       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7e58acbe-c20a-520a-bb35-1227947166e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -عقد -إجارة من الباطن -استراد ثمن اجرة لعدم حتقق شرط يف العقد -دفع املدعى عليه باالنتفاع مدة من العقد -تقدير اجرة املثل من قسم اخلبراء -ثبوت بطان العقد لعدم موافقة املؤجر األصلي -إلزام املدعى عليه بإعادة الثمن املسلم وإفهامه بأن له املطالبة بأجرة املثل خال فترة انتفاعه بدعوى مستقلة.","document_number":"33415126","case_number":"3441","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/18","year":"1434","subject":"إجارة -عقد -إجارة من الباطن -استراد ثمن اجرة لعدم حتقق شرط يف العقد -دفع املدعى عليه باالنتفاع مدة من العقد -تقدير اجرة املثل من قسم اخلبراء -ثبوت بطان العقد لعدم موافقة املؤجر األصلي -إلزام املدعى عليه بإعادة الثمن املسلم وإفهامه بأن له املطالبة بأجرة املثل خال فترة انتفاعه بدعوى مستقلة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/18:‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪33415126 :‬‬\n                       ‫َر ْق ُم الدعوى‪3441:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‬\n         ‫‪ 34191043:‬تاريخه‪1434/4/17 :‬هـ‬\n\n\n‫إجــارة ‪ -‬عقــد ‪ -‬إجــارة مــن الباطــن ‪ -‬اســتراد ثمــن اجــرة لعــدم حتقــق‬\n‫شــرط يف العقــد ‪ -‬دفــع املدعــى عليــه باالنتفــاع مــدة مــن العقد ‪ -‬تقدير‬\n‫اجــرة املثــل مــن قســم اخلبــراء ‪ -‬ثبــوت بطــان العقــد لعــدم موافقــة‬\n‫املؤجــر األصلــي ‪ -‬إلــزام املدعــى عليــه بإعــادة الثمــن املســلم وإفهامــه‬\n‫بــأن لــه املطالبــة بأجــرة املثــل خــال فتــرة انتفاعــه بدعــوى مســتقلة‪.‬‬\n\n\n\n\n‫‪ -1‬قــول شــيخ اإلســام ابــن تيميــة أن األصــل يف العقــود والشــروط‬\n‫اجلــواز والصحــة وال يحــرم منهــا ويبطــل إال مــا دل الشــرع علــى‬\n‫حترميــه وإبطالــه نص ـ ًا أو قياســا عنــد مــن يقــول بــه وقــال مانصــه‬\n‫«وأصــول أحمــد املنصوصــة عنــه أكثرهــا يجــري علــى هــذا القــول ‪،‬‬\n‫ومالــك قريــب منــه‪ ،‬لكــن أحمــد أكثــر تصحيح ـ ًا للشــروط ‪ ،‬فليــس‬\n‫يف الفقهــاء األربعــة أكثــر تصحيحـ ًا للشــروط منــه ‪.»...‬ا‪.‬ه ـ مجمــوع‬\n                                                ‫الفتــاوى(‪)132-126/29‬‬\n‫‪ -2‬قــول ابــن قدامــة يف الشــرح‪(:‬فإذا عــاد أحدهمــا فبــذل اليمــن ‪ ،‬لــم‬\n‫يســمعها يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا يف‬\n‫مجلــس آخــر فــإذا اســتأنف الدعــوى أعيــد احلكــم بينهمــا كاألول)‬\n                          ‫الشــرح الكبيــر مــع اإلنصــاف (‪ 436/28‬و ‪.)437‬‬\n\n\n\n                                                                                  ‫‪54‬‬\n\f     ‫ادعــت املدعيــة «الشــركة» ضــد املدعــى عليها»شــركة أخــرى» بدعــوى‬\n     ‫بأنهــا اســتأجرت منهــا مجموعــة مســتودعات بثمــن محــدد واشــترطت‬\n     ‫بــأن تســتخرج لهــا تراخيــص وســلمت الدفعــة األولــى وبقيــت فيــه فتــرة ‪-‬‬\n     ‫عليــه ولعــدم قيامهــا باســتخراج التراخيــص الالزمــة وملــا جــاء يف منطــوق‬\n     ‫وثيقــة العقــد مــن اعتبــار العقــد الغيــا وإلتــزام املدعــى عليهــا بإعــادة مــا‬\n     ‫ســلم مــن ثمــن لــذا فقــد طلبــت إلــزام املدعــى عليهــا بإعــادة الثمــن املســلم‬\n     ‫‪ -‬أقــر وكيــل املدعــى عليهــا بالدعــوى جملــة وتفصيــا لــذا فــإن العقــد‬\n     ‫يعتبــر الغيــا ودفــع بــأن املدعيــة اســتفادت مــن العقــار قرابــة الســنة لــذا‬\n     ‫فهــي غيــر مســتعدة بإعــادة مــا تطالــب بــه ‪ -‬متســك وكيــل املدعــن مبــا‬\n     ‫ورد يف منطــوق اخلطــاب املوجــه مــن املدعــى عليهــا للمدعيــة بإلتزامهــا‬\n     ‫باســتخراج الترخيــص وإال فيعــد العقــد الغيــا وتلتــزم بإعــادة املبلــغ لهــا‬\n     ‫‪ -‬طلبــت احملكمــة مــن املدعــى عليهــا مســتند متلكهــا فأبــرزت وثيقــة‬\n     ‫العقــد املبرمــة بينهــا وبــن املؤجــر وقــد تضمــن يف أحــد بنــوده إلتزامهــا‬\n     ‫بتوثيــق أي عقــد أجــرة تبرمــه يف الباطــن لديه وقرر وكيل املدعى عليها‬\n     ‫بــأن موكلتــه لــم تقــم بهــذا اإلجــراء ‪ -‬عليــه وألن املدعــى عليهــا صادقــت‬\n     ‫علــى دعــوى املدعيــة وأقــرت بعــدم اســتخراج رخصــة مــن البلديــة اخلاصــة‬\n     ‫باملســتودعات محــل الدعــوى يف املوعــد الــذي تشــارطا عليــه كمــا‬\n     ‫أقــرت أنــه يف حــال عــدم القــدرة علــى اســتخراجه يف التاريــخ املنــوه عنــه‬\n     ‫فــإن العقــد يعتبــر الغي ـ ًا وملــا جــاء يف إجابــة املدعــى عليــه مــن أن أصــل‬\n     ‫العقــار مســتأجر مــن املؤسســة ‪ ...‬عليــه وألن مذهــب جمهــور العلمــاء‬\n     ‫مــن املالكيــة والشــافعية واملذهــب عنــد احلنابلــة واحلنفيــة علــى تفصيــل‬\n\n‫‪55‬‬\n\f‫عندهــم وقــول ابــن حــزم واختيــار شــيخ اإلســام ابــن تيميــة علــى جــواز‬\n‫إجــارة العــن املســتأجرة بعــد قبضهــا وال يشــترط إذن املؤجــر ومــا ذكــر‬\n‫يف العقــد بــن املؤجــر األول واملؤجــر الثانــي مــن اشــتراط عــدم جــواز‬\n‫التأجيــر مــن الباطــن إال بعــد توثيــق اإلجــراء لــدى املؤجــر األول علــى‬\n‫التفصيــل املذكــور فــإن الصحيــح مــن مذاهــب العلمــاء جــواز مثــل هــذه‬\n‫الشــروط التــي تعــود علــى املؤجــر األول بنفــع مقصــود ولــه فيهــا مصلحــة‬\n‫و أن األصــل يف العقــود والشــروط اجلــواز والصحــة وال يحــرم منها ويبطل‬\n‫إال مــا دل الشــرع علــى ت ـ ــحرميه وإبطالــه ‪ ،‬نص ـ ًا ‪ ،‬أو قياس ـ ًا عنــد مــن‬\n‫يقــول بــه وملصادقــة الطرفــن علــى عــدم توثيــق العقــد لــدى املؤجــر األول‬\n‫فعلــى هــذا فــإن العقــد الثانــي لــم يــن علــى عقــد إيجــار صحيــح ومبــا أن‬\n‫املدعــي وكالــة يطالــب بإعــادة األجــرة املدفوعــة للســنة األولــى وقدرهــا‬\n‫خمســمائة وســبعة وســتون ألــف ريــال ولعــدم طلــب أحــد منهمــا تقديــر‬\n‫أجــرة املثــل وألن األصــل يف مثــل هــذا أن يطالــب بتقديــر أجــرة املثــل‬\n‫يف دعــوى مســتقلة‪ ،‬لــذا فقــد ثبــت لــدى احملكمــة أن بذمــة الشــركة‬\n‫املدعــى عليهــا خمســمائة وســبعة وســتني ألــف ريــال تدفعهــا للمدعيــة‬\n‫لعــدم صحــة العقــد الثانــي مــن الباطــن بــن املؤجــر الثانــي واملســتأجر‬\n‫الثالــث وافهــم وكيــل املدعــى عليهــا بــأن لــه مطالبــة الشــركة املدعيــة‬\n‫بأجــرة املثــل ‪ -‬وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة القناعــة‬\n‫وقــرر املدعــى عليــه وكالــة عــدم القناعــة فأفهــم بالتعليمــات ‪ -‬عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبلحوظــة بــأن وكيــل املدعــى عليهــا‬\n‫طالــب بأجــرة املثــل فأجابــت احملكمــة بــأن وكيــل املدعــى عليهــا ذكر‬\n‫يف الئحتــه باعتراضــه علــى بطــان العقــد ثــم طالــب بأجــرة املثــل وال‬\n‫ميكــن النظــر يف طلبــه واحلــال هــذه إال بعــد اكتســاب احلكــم بثبــوت‬\n\n\n                                                                                      ‫‪56‬‬\n\f     ‫بطــان العقــد لكونــه فــرع عنهــا كمــا أن مطالبتــه بأجــرة املثــل لــم‬\n     ‫تــرد إال بعــد النطــق باحلكــم وال تقبــل الطلبــات بعــد قفــل بــاب املرافعــة‬\n     ‫وأكــدت علــى مــا قررتــه ســابقا بــأن لهــا إقامــة دعــوى مســتقلة بذلــك‬\n     ‫ونظيــر هــذا مــا جــاء يف الشــرح الكبيــر إذا نــكل مــن توجهــت اليمــن‬\n     ‫يف حقــه قــال ‪ -‬رحمــه اهلل ‪ -‬مــا نصه‪(:‬فــإذا عــاد أحدهمــا فبــذل اليمــن‬\n     ‫‪ -‬لــم يســمعها يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا‬\n     ‫يف مجلــس آخــر فــإذا اســتأنف الدعــوى أعيــد احلكــم بينهمــا كاألول)‬\n     ‫الشــرح الكبيــر مــع اإلنصــاف (‪ - )437.436/28‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد  لــدي أنــا ‪ .................‬القاضــي باحملكمــة العامــة‬\n     ‫ـاء علــى األوراق الــواردة لنــا مــن فضيلــة رئيــس محاكــم‬          ‫بالدمــام بنـ ً‬\n     ‫املنطقــة الشــرقية علــى خطــاب مديــر شــرطة الدمــام رقــم‬\n     ‫‪2/30625‬يف‪1430/8/27‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n     ‫‪2912973‬يف ‪1429/5/19‬ه ـ حضــر‪ .............. /‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬بالوكالــة عــن ‪ .................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــده‬\n     ‫برقــم ‪31290‬يف ‪1429/3/22‬ه ـ جلــد ‪ 7048‬بصفتــه وكيــا  عــن‬\n     ‫‪ ...................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫شــمال محافظــة جــدة برقــم ‪ 96970‬يف ‪1428/11/24‬ه ـ جلــد ‪6646‬‬\n     ‫بصفتــه شــريك ومديــر شــركة ‪ ......................‬مبوجــب عقــد التأســيس‬\n     ‫الصــادر مــن كاتــب عــدل الغرفــة التجاريــة بجــدة برقــم ‪19‬يف‬\n‫‪57‬‬\n\f‫‪1423/11/2‬ه ـ ومبوجــب الســجل التجــاري رقــم ‪ 4030141450‬يف‬\n‫‪1423/11/17‬ه ـ الصــادر مــن جــدة وحضــر حلضــوره ‪...................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم …………‪ ..‬بالوكالــة‬\n‫عــن م‪ .....................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمام‬\n‫الثانيــة برقــم ‪ 48966‬يف ‪1430/10/7‬ه ـ جلــد ‪ 8343‬وبالوكالــة عــن‬\n‫‪ ...................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n‫الثانيــة برقــم ‪56849‬يف ‪1430/11/15‬ه ـ جلــد ‪ 8422‬وهمــا أصحــاب‬\n‫شــركة ‪.......................‬مبوجــب عقــد التأســيس املثبــت لــدى كاتــب‬\n‫العــدل املكلــف بالعمــل بالغرفــة التجاريــة الصناعيــة باملنطقــة الشــرقية‬\n‫برقــم ‪132‬جلــد ‪ 60‬لعــام ‪1426‬ه ـ ومبوجــب الســجل التجــاري  الصــادر‬\n‫مــن الدمــام برقــم …………‪..‬يف ‪1422‬هــ  وادعــى األول بقولــه‪ :‬لقــد‬\n‫اســتأجرت شــركة ‪ ...........................‬مــن شــركة ‪ ...............‬تســعة‬\n‫مســتودعات مبنطقــة ‪ ................‬وذلــك بتاريــخ ‪2006/7/5‬م ملــدة خمــس‬\n‫ســنوات اعتبــار ًا مــن ‪2006/12/5‬م حتــى ‪2011/12/4‬م بأجــرة ســنوية‬\n‫قدرهــا خمســمائة وســبعة وســتون ألــف ريــال لكامــل املســتودعات‬\n‫وتســدد أجــرة كل ســنة دفعــة واحــدة يف بدايــة كل ســنة مبوجــب العقــد‬\n‫احملــرر بينهمــا واملشــتمل علــى عشــرة مــواد وقــد قامــت الشــركة‬\n‫موكلتــي بتســليم أجــرة الســنه االولــى وقدرهــا خمســمائة وســبعة‬\n‫وســتون ألــف  ريــال للشــركة املدعــي عليهــا مبوجــب شــيك مســحوب‬\n‫علــى البنــك ‪ .....‬برقــم ‪ 4171‬يف‪2006/7/5‬م وبتاريــخ ‪2006/7/11‬م‬\n‫تعهــدت الشــركة املؤجــرة بتجهيــز رخــص البلديــة اخلاصة باملســتودعات‬\n‫التســعة وتســليمها للشــركة موكلتــي وإذا لــم تقــم بتجهيــز الرخــص‬\n‫املذكــورة يف موعــد أقصــاه نهايــة شــهر ‪2006/9‬م فإنهــا ملتزمــة بإعــادة‬\n\n\n                                                                                    ‫‪58‬‬\n\f       ‫كامــل أجــرة الســنة األولــى ويعتبــر العقــد الغي ـ ًا إال أنهــا لــم تــف مبــا‬\n       ‫تعهــدت بــه ثــم قامــت بتســليم املســتودعات التســعه للشــركة موكلتــي‬\n       ‫بتاريــخ ‪2006/10/12‬م وقــد اســتمرت الشــركه موكلتــي يف‬\n       ‫املســتودعات حتــى ‪2007/9/26‬م وكانــت خاللهــا تطالــب بالرخــص‬\n       ‫دون جــدوى ثــم قامــت بإعــادة املســتودعات للشــركة املؤجــرة لــذا أطلــب‬\n       ‫إلــزام شــركة ‪ ...................‬بإعــادة أجــرة الســنة األولــى وقدرهــا‬\n       ‫خمســمائة وســبعة وســتون ألــف ريــال للشــركة موكلتــي هــذه دعــواي‬\n       ‫وبســؤال املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬ماذكــره املدعــي وكالــة‬\n       ‫ا والشــركة موكلتــي لــم‬               ‫يف دعــواه كلــه صحيــح جملــة وتفصي ـ ً‬\n     ‫تســتطع جتهيــز رخــص البلديــه  اخلاصــة باملســتودعات التســعه املؤجــرة  ‬\n       ‫علــى الشــركة موكلــة املدعــى يف املوعــد الــذي التزمــت فيــه وهــو نهايــة‬\n       ‫ـاء علــى هــذا فــإن العقــد الــذي بينهمــا يعتبــر الغي ـ ًا‬   ‫شــهر ‪2006/9‬م وبنـ ً‬\n       ‫إال أن الشــركة املدعيــة اســتلمت املســتودعات التســعة بتاريــخ‬\n       ‫‪2006/10/12‬م واســتمرت بهــا وانتفعــت منهــا  حتــى إرجاعها للشــركة‬\n       ‫موكلتــي بتاريــخ ‪2007/9/26‬م أي مايقــارب ســنة الشــركة موكلتــي‬\n       ‫ليســت مســتعدة مبــا طلبــه املدعــي وكالــة ألن مــا دفعتــه الشــركة‬\n       ‫املدعيــة هــو مقابــل انتفاعهــا ملــدة بقائهــا يف املســتودعات هكــذا أجــاب‬\n       ‫ثــم يف جلســة أخــرى  حضــر ‪ ...................‬ســعودي اجلنســيه مبوجــب‬\n       ‫الســجل املدنــي رقــم ‪ ....................‬بالوكالــة عــن ‪ ......................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة  ‬\n       ‫برقــم ‪ 29746‬يف ‪1431/29‬ه ـ جلــد ‪ 9444‬باألصالــة عــن نفســه وبصفتــه‬\n       ‫ا عــن كل مــن ‪ .................... .................‬و‪....................‬‬        ‫وكي ـ ً‬\n       ‫و‪ .....................‬و‪ ...................‬بصفتهــم الشــركاء يف شــركة‬\n\n\n‫‪59‬‬\n\f‫‪ ...................‬مبوجــب عقــد التأســيس املوثــق   لــدى كاتــب العــدل‬\n‫بالغرفــة التجاريــة الصناعيــة بجــدة رقــم ‪19‬صحيفــة ‪/42/23/22‬جلــد‬\n‫‪/9‬ش‪4/‬يف ‪1423/11/2‬ه ـ والســجل التجــاري رقــم ‪/4030/4/450‬يف‬\n‫‪1423/11/17‬ه ـ الصــادر مــن جــدة مبوجــب الوكالــة الصــادرة  مــن‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 27578‬يف‬\n‫‪1431/3/22‬ه ـ جلــد ‪ 9412‬املخــول للوكيــل فيهــا حــق املطالبــة بحقــوق‬\n‫الشــركة وإقامــة وســماع الدعــاوي والــرد عليهــا واملرافعــة والصلــح‬\n‫والتنــازل واإلقــرار واإلنــكار واإلجابــة ويف يــوم الســبت املوافــق‬\n‫‪1431/3/20‬ه ـ الســاعة العاشــرة صباحـ ًا فتحــت اجللســة وفيهــا حضــر‬\n‫املدعي وكاله ‪ ...‬وحضر حلضوره ‪ .................‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ‪ ..................‬بالوكالــة عــن ‪ ......................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابة عدل الدمام الثانية برقم ‪1429/6/21‬هـ‬\n‫ا عــن ‪........................‬‬\n                              ‫ا عــن نفســه ووكي ـ ً‬    ‫جلــد ‪ 7523‬بصفتــه أص ـ ً‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم‬\n‫‪ 29973‬يف ‪1426/7/8‬هـ جلد ‪ 4699‬بصفتها أصحاب ……………‪..‬‬\n‫مبوجــب عقــد التأســيس املوثــق مــن كاتــب عــدل الدمــام برقــم ‪ 45‬عــدد‬\n‫‪ 48‬مــن جلــد ‪3‬العــام ‪1422‬ه ـ وملحــق التعديــل املوثــق مــن كاتــب العــدل‬\n‫املكلــف بالعمــل بالغرفــة التجاريــة الصناعيــة باملنطقــة الشــرقية‬\n‫بالصحيفــة ‪144‬عــدد‪ 132‬جلــد ‪6‬يف ‪1426/3/15‬ه ـ وألن وكالــة‬\n‫املدعــي املشــار إليهــا آنف ـ ًا قــد  نصــت علــى أن للوكيــل مراجعــة جميــع‬\n‫اجلهــات والدوائــر احلكوميــة واخلاصــة والهيئــات واحملاكــم ومطالبــه‬\n‫كل مــن شــركة ‪ ..................‬و‪ .....................‬بقيمــة اإليجــار املدفــوع‬\n‫لهــم مقابــل املســتودعات  مبدينــة ‪ ................‬وتقــدمي الدعــاوي واالنهاءات‬\n\n\n                                                                                           ‫‪60‬‬\n\f     ‫واســتالم م كافــة احلقــوق باســم الشــركة مبوجــب شــيكات واملرافعــه‬\n     ‫عــن الشــركة لــدى جميــع مواصلــة الســير يف الدعــوى الفتقارهــا إلــى‬\n     ‫حــق االقرارواحضــار لســياق وطلــب اليمــن والقناعــه باحلكــم‬\n     ‫واالعتــراض عليــه ونحــو ذلــك لــذا فقــد أفهمــت املدعــي وكالــة بذلــك‬\n     ‫فقــال أطلــب إمهالــي إلحضــار وكالــة حتولنــي جميــع ماتقتضيــه‬\n     ‫الدعــوى هكــذا قــرر فأجــاب لطلبــه ورفعــت اجللســه لذلــك بعــد‬\n     ‫إعالمهمــا باحلضــور يــوم الســبت املوافق‪1431/5/17‬هـ واجلرح والتعديل‬\n     ‫واملنــع مــن الســفر وتوريــد الشــهود والبينــات واالعتــراض وتن ـ ــفيذ‬\n     ‫األحــكام واالســتئناف واإلجابــة وطلــب اليمــن وســماع وطلــب احلكــم‬\n     ‫وقبولــه ونفيــه واالعتــراض عليــه وطلــب متييــزه والفســخ واإلبــراء‬\n     ‫واملخالصــه واســتالم الصكــوك واالعتــراض عليهــا إلى أخــر ماوردفيها‬\n     ‫وحضــر حلضــوره املدعــى عليــه وكالــه …………………‪ .‬وبعــرض‬\n     ‫إجابــة املدعــى عليــه وكالــة ‪ ...............‬علــى املدعــي وكالــة قــال‬\n     ‫ماذكــره املدعــى عليــه وكالــة مــن أن الشــركة موكلتــه لــم تســتطع‬\n     ‫جتهيــز رخــص البلديــة للمســتودعات التســعة يف املدة احملــددة وأن العقد‬\n     ‫ـاء علــى هــذا يعتبــر ال غياًفهــو صحيــح حيــث ســبق أن بعثــت شــركة‬        ‫بنـ ً‬\n     ‫‪ ...............‬لشــركة ‪ ...........‬خطاب ـ ًا بتاريــخ ‪2006/7/11‬م تتعهــد فيــه‬\n     ‫بتجهيــز الرخــص  يف مــدة أقصاهــا نهايــة  الشــهر التاســع عــام ‪2006‬م‬\n     ‫وإذا لــم يتــم جتهيــز الرخــص فــإن شــركة  ‪ ........‬ملتزمــه بــإ عــادة املبلــغ‬\n     ‫ا ويعتبــر العقــد الغي ـ ًا‬ ‫الــذي اســتلمته مــن الشــركة موكلتــي كام ـ ً‬\n     ‫وقــد وافقــت الشــركة موكلتــي علــى مــاورد يف خطــاب الشــركة‬\n     ‫موكلــة املدعــى عليــه وأصبــح إتفاق ـ َا بينهمــا هكــذا قــرر ثــم أبــرز‬\n     ‫املدعــي وكالــة عقــد االتفــاق الصــادر مــن شــركة ‪ ...........‬بتاريــخ‬\n\n\n‫‪61‬‬\n\f‫‪2006/7/5‬م وباالطــاع عليــه وجــد أنــه يتضمن قيام شــركة ‪...............‬‬\n‫بتأجيــر تســعة مســتودعات مبنطقــة اخلالديــة علــى شــركة ‪.................‬‬\n‫ملــدة خمــس ســنوات تبــدأ مــن ‪2006/12/5‬م وتنتهــي يف ‪2011/12/4‬م‬\n‫بأجــرة ســنوية قدرهــا خمســمائة وســبعة وســتون ألــف ريــال تدفــع دفعــة‬\n‫واحــدة وهــذا العقــد وفــق خمســة عشــر بنــد ومذيــل بتوقيــع كل مــن‬\n‫شــركة ‪ .............‬وشــركة ‪ ...................‬كمــا أبــرز املدعــي وكالــة‬\n‫خطاب ـ ًا صــادر ًا مــن شــركة ‪ ...‬وموجه ـ ًا لشــركة ‪ ..................‬بتاريــخ‬\n‫‪2006/7/11‬م يتضمــن مانصــه ‪ :‬املوضــوع ‪ :‬تعهــد والتــزام بتجهيــز‬\n‫رخصــة بلديــة بخطابنــا هــذا نتعهــد لكــم نحــن شــركة ‪...............‬‬\n‫بتجهيــز رخصــة بلديــة لعــدد واحــد مســتودع تخزيــن املــواد الغذائيــة‬\n‫وجتهيــز أيض ـ ًا رخصــة بلديــة أخــرى لعــدد ثمانيــة مســتودعات تخزيــن‬\n‫أدوات كهربائيــة متنوعــه وذلــك يف منطقــة ‪ ...‬بالدمــام وإذا لــم يتــم‬\n‫جتهيــز رخــص البلديــة املطلوبــة وذلــك حتــى نهايــة شــهر ســبتمبر ‪2006‬م‬\n‫ا ويعتبــر العقــد ال غيـ ًا ‪ .‬أه ـ ‪ .‬ومذيــل‬\n                                            ‫نتعهــد ونلتــزم  بإعــادة املبلــغ كامـ ً‬\n‫هــذا اخلطــاب بتوقيــع املديــر العــام ومختــوم بختــم شــركة ‪ ...‬وبعــرض‬\n‫العقــد واخلطــاب املشــار إليهمــا بعاليــه علــى املدعــى عليــه وكالــة صــادق‬\n‫عليهمــا ثــم ســألت الطرفــن هــل حصــل اتفــاق جديــد بــن شــركة‬\n‫‪ .............‬وشــركة ‪ ......................‬بعــد إلغــاء العقــد املبــرم بينهمــا وقبــل‬\n‫اســتالم شــركة ‪ ..................‬للمســتودعات بتاريــخ ‪2006/10/12‬م‬\n‫فقــاال لــم يحصــل أي إتفــاق جديــد علــى التأجيــر مكتوبـ َا وال مشــافهة‬\n‫هكــذا قــرر ثــم ســألت املدعــى عليــه وكالــة عــن مســتند ملكيــة‬\n‫شــركة ‪ ..............‬للمســتودعات فقــال إن موقــع املســتودعات مؤجــر‬\n‫علــى الشــركة موكلتــي مــن قبــل ‪ ...‬هكــذا قــرر فســألته عــن عقــد‬\n\n\n                                                                                              ‫‪62‬‬\n\f       ‫اإليجــار فقــال أطلــب إمهالــي إلحضــاره لكــم هكــذا قــرر فأجيــب‬\n       ‫لطلبــه ثــم يف جلســة أخــرى  حضــر الطرفــان كل مــن املدعــي  وكالــة‬\n       ‫‪ ...‬واملدعــى عليــه وكالــة ‪ ...‬وأبــرز املدعــي وكالــة ‪ ...‬صــك الوكالــة‬\n       ‫الصــادر مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 9827‬يف‬\n       ‫ا عــن‬    ‫‪1431/2/2‬ه ـ تتضمــن أن ‪ .....................‬بصفتــه وكي ـ ً‬\n       ‫‪ ........................‬بصفتــه شــريك ومديــر شــركة ‪ .......................‬مبوجــب‬\n       ‫عقــد التأســيس رقــم ‪ 19‬يف ‪1432/11/2‬ه ـ صحيفــة رقــم ‪24/23/22‬‬\n     ‫مجلــد ‪/9‬ش‪/‬ع الصــادر مــن كتــاب عــدل الغــرف التجاريــة بجــده  ‬\n       ‫مبوجب السجل التجاري رقم ‪ 4030141450‬يف تاريخ ‪1423/11/17‬هـ‬\n       ‫ســجل جــدة بالوكالــة الصــادرة مــن كتابــة عــدل جــدة الثانيــة شــمال‬\n       ‫محافظــة جــدة برقــم ‪ 96970‬يف ‪1428/11/24‬ه ـ جلــد ‪ 6646‬قــد أقامــا‬\n       ‫‪ ...................‬وكيــا  ينــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وإقامــة‬\n       ‫الدعــوى ضــد شــركة ‪ .............‬أو ‪ .................‬وابنــه ‪.....................‬‬\n       ‫للمطالبــة بإعــادة قيمــة املبالــغ املدفوعــة لهــم مقابــل عقــد اســتئجار‬\n       ‫مســتودعات يف ‪ ...‬ولــه حــق اإلقــرار عــن الشــركة واســتالم الصكــوك‬\n       ‫واالعتــراض عليهــا وإنهــاء مايلــزم حضــوره إلــى اخــر مــاورد فيهــا ثــم أبــرز‬\n       ‫املدعــى عليــه وكالــة ‪ ....‬أصــل العقــد الصــادر مــن املؤسســة … برقــم‬\n       ‫‪ 2631‬يف ‪1426/11/19‬ه ـ وباالطــاع عليــه وجدتــه يتضمــن تأجيــر‬\n       ‫املؤسســة … لقطعــة األرض  رقــم ‪ 3/46‬يف ‪ ...‬علــى شــركة ‪..................‬‬\n       ‫ملــدة تســع ســنوات تنتهــي يف ‪1435/12/29‬ه ـ بأجــرة ســنوية قدرهــا‬\n       ‫مائــة وســتة وثالثــون ألف ـ ًا وأربعمائــة وثــا ثــون ريــا ًأل وهــذا العقــد وفــق‬\n       ‫ثالثــة وعشــرين مــادة ومذيــل بتوقيــع كل مــن الطــرف األول املؤسســة ‪...‬‬\n       ‫والطــرف الثانــي شــركة ‪ ......................‬وقــد تضمنــت املــادة احلاديــة‬\n\n\n‫‪63‬‬\n\f ‫عشــر علــى أنــه ال يجــوز للطــرف الثانــي تأجيــر األرض موضــوع العقــد‬\n ‫املنشــآت املقامــة عليهــا كليـ ًا أو جزئيــا للغيــر إال بشــرط أن يوثــق هــذا‬\n ‫اإلجــراء لــدى الطــرف األول وعلــى النمــوذج املخصــص لهــذا الغــرض‬\n ‫خــال شــهر مــن تاريــخ  التأجيــر مــن الباطــن علــى أن ال تتجــاوز مــدة‬\n‫التاجيــر مــن الباطــن مــدة هــذا العقــد هكذا تضمنت وبســؤال الطرفني ‬\n ‫هــل قامــا بتوثيــق عقــد اإليجــار الــذي بينهمــا علــى الصفــة الــواردة يف‬\n ‫املــادة احلاديــة عشــر املشــار إليهــا بعاليــه فقــاال‪ :‬لــم يتــم توثيقــه علــى‬\n ‫الصفــة املذكــورة هكــذا قــررا وحيــث األمــر ماذكــر وألن عقــد‬\n ‫اإليجــار املبــرم بــن الشــركتني  قــد مت إلغــاؤه بإقــرار الطرفــن وألن‬\n ‫اســتالم الشــركة املدعيــة للمســتودعات التســعة وإنتفاعهــا بهــا للفتــرة‬\n ‫مــن ‪2006/10/12‬م حتــى ‪2007/9/26‬م لــم يبنــى علــى عقــد إيجــار‬\n ‫صحيــح لــذا فقــد رأيــت الكتابــة لهيئــة النظــر لتقديــر أجــرة املثــل‬\n ‫للمستودعات التسعة املذكورة يف الدعوى اعتبار ًأ من ‪2006/10/12‬م‬\n ‫حتــى ‪2007/9/26‬م واإلفــادة ثــم يف جلســة أخــرى فلــدي أنــا ‪ ...‬القاضــي‬\n ‫باحملكمــة العامــة بالدمــام حضــر الطرفــان كل مــن املدعــي وكالــة‬\n ‫‪ .......................‬واملدعــى عليــه ‪ .......................‬ســعودي اجلنســية مبوجــب‬\n ‫الســجل املدنــي رقــم ‪    .......................‬الوكيــل عــن ‪.......................‬‬\n ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالدمــام برقــم‬\n ‫‪ 3384196‬وتاريــخ ‪1433/5/23‬ه ـ بصفتــه الوكيــل عــن‬\n ‫‪ ............................‬واملخــول لــه فيهــا املطالبــة وإقامــة الدعــاوي واملرافعــة‬\n ‫واملدافعــة وســماع الدعــاوي والــرد عليهــا وطلــب اليمــن ورده واالمتنــاع‬\n ‫عنــه وطلــب تطبيــق املــادة ‪ 230‬مــن نظــام املرافعــات الشــرعية واملطالبــة‬\n ‫بتنفيــذ االحــكام وقبــول االحــكام ونفيهــا واالعتــراض علــى االحكام‬\n\n\n                                                                                                ‫‪64‬‬\n\f     ‫وطلــب االســتئناف واســتالم املبالــغ بشــيك لــدى احملاكــم الشــرعية ويف‬\n     ‫هــذه اجللســة جــرى تــاوة مــا ســبق ضبطــه مــن الدعــوى واإلجابــة ومــا مت‬\n     ‫بعــد ذلــك فســألت املتداعيــن عــن ذلــك فصادقــا عليــه وطلبا  االســتمرار‬\n     ‫يف الدعــوى والنظــر علــى ضــوء مــا ســبق ضبطــه وطلبــا الفصــل يف‬\n     ‫القضيــة  ثــم يف جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره‬\n     ‫املدعــى عليــه أصالــة   ‪ ...........................‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪  ....................‬وبالرجــوع إلــى أوراق املعاملــة وجــد‬\n     ‫قــرار هيئــة اخلبــراء برقــم ‪ 163‬وتاريــخ ‪1432/4/28‬ه ـ واملتضمــن مــا‬\n     ‫نصــه ‪ ( :‬بنــاء علــى آمــر صاحــب الفضيلــة الشــيخ ‪ ..................... /‬رقــم‬\n     ‫‪ 31/19687‬يف ‪1431/12/2‬هـ املتعلقة بدعوى ‪ .....................‬بالوكالة‬\n     ‫عــن شــركة ‪ ...................‬ضــد ‪ .................‬أجــرة املســتودعات املنــوه‬\n     ‫عنهــا بحضــور أطــراف القضيــة ومــن ثــم تقديــر أجــرة املثــل لهــذه‬\n     ‫املســتودعات اعتبــار ًا مــن ‪2006/10/12‬م حتــى ‪2007/9/26‬م مــع‬\n     ‫االســتعانة بأهــل اخلبــرة يف ذلــك عليــه جــرى املكاتبــة ملكتــب كل مــن‬\n     ‫شــركة ‪ .....................‬وشــركاه ‪ ...‬ومكتــب شــركة ‪ .............‬املرفقــة‬\n     ‫باملعاملــة مكتــب ‪ ..........‬يذكــر ان األجــرة يف تلــك الفتــرة مــا بــن ‪90‬‬\n     ‫إلــى ‪ 120‬للمتــر املربــع ومكتــب ‪ ...‬يذكــر أن األجــرة يف تلــك الفتــرة مــا‬\n     ‫بــن ‪ 100‬إلــى ‪ 110‬ريــال للمتــر املربــع يف حــال املبنــى جديــد غير مرخص‬\n     ‫مــن اجلهــات الرســمية لــذا تــرى هيئــة النظــر أن االجــرة املتوســطة بــن‬\n     ‫التقديريــن أجــرة وقدرهــا ‪ 95‬ريــال للمتــر املربــع وهــذه أجــرة معتدلــة مــن‬\n     ‫تاريــخ ‪2006/10/12‬م إلــى ‪2007/9/26‬م هــذا مــا جــرى وباهلل التوفيق‬\n     ‫عضــو هيئــة النظــر ‪ .................‬وعضــو هيئــة النظــر ‪ ............‬وعضــو هيئــة‬\n     ‫النظــر ‪ )......................‬وبعرضــه علــى املتداعيــن طلبــا إمهالهمــا للجواب‬\n\n\n‫‪65‬‬\n\f‫علــى قــرار هيئــة النظــر ثــم يف جلســة أخــرى  حضــر الطرفــان وقــد مت‬\n‫تأمــل مــا ســبق ضبطــه فبــدا لــي عــدم وجاهــة إجــراء فضيلــة القاضــي‬\n‫الســلف مــن جهــة إحالــة تقديــر أجــرة املثــل لهيئــة النظــر  ويف هــذه اجللســة‬\n‫ـاء علــى مــا تقــدم‬\n                  ‫جــرى عــرض الصلــح علــى الطرفــن فلــم يوفقــا إليــه فبنـ ً‬\n‫مــن الدعــوى واإلجابــة وإقرارهمــا علــى مــا مت ضبطــه ومبــا أن املدعــى‬\n‫عليــه صــادق علــى دعــوى املدعــي وأقــر بعــدم اســتخراج رخصــة مــن‬\n‫البلديــة اخلاصــة باملســتودعات محــل الدعــوى  يف املوعــد الــذي تشــارطا‬\n‫عليــه كمــا أقــر أنــه يف حــال عــدم القــدرة علــى اســتخراجه يف التاريــخ‬\n‫املنــوه عنــه فــإن العقــد يعتبــر الغيـ ًا ومــا جــاء يف تضاعيــف إجابــة املدعــى‬\n‫عليــه مــن أن أصــل العقــار مســتأجر مــن ‪ ...‬فــإن مذهــب جمهــور العلمــاء‬\n‫مــن املالكيــة والشــافعية واملذهــب عنــد حلنابلــة واحلنفيــة علــى تفصيــل‬\n‫عندهــم وقــول ابــن حــزم واختيــار شــيخ االســام ابــن تيميــة علــى جــواز‬\n‫إجــارة العــن املســتأجرة بعــد قبضهــا وال يشــترط إذن املؤجــر ومــا ذكــر‬\n‫يف العقــد بــن املؤجــر  األول واملؤجــر الثانــي مــن اشــتراط عــدم جــواز‬\n‫التأجيــر مــن الباطــن إال بعــد توثيــق اإلجــراء لــدى املؤجــر األول علــى‬\n‫التفصيــل املذكــور فــإن الصحيــح مــن مذاهــب العلمــاء جــواز مثــل هــذه‬\n‫الشــروط التــي تعــود علــى املؤجــر األول بنفــع  مقصــود ولــه فيهــا مصلحــة‬\n‫وهــذا هــو مذهــب احلنابلــة والظاهــر مــن مذهــب املالكيــة  وذكــر شــيخ‬\n‫اإلســام ابــن تيميــة أن األصــل يف العقــود والشــروط اجلــواز والصحــة وال‬\n‫يحــرم منهــا ويبطــل إال مــا دل الشــرع علــى ت ـ ــحرميه وإبطالــه ‪ ،‬نصـ ًا ‪ ،‬أو‬\n‫قياسـ ًا عنــد مــن يقــول بــه وقــال مــا نصــه  ‪ ( :‬وأصــول أحمــد املنصوصــة‬\n‫عنــه أكثرهــا يجــري علــى هــذا القــول ‪ ،‬ومالــك قريــب منــه ‪ ،‬لكــن‬\n‫أحمــد أكثــر تصحيح ـ ًا للشــروط ‪ ،‬فليــس يف الفقهــاء األربعــة أكثــر‬\n\n\n                                                                                         ‫‪66‬‬\n\f     ‫تصحيح ـ ًا للشــروط منــه ‪ ) ...‬اه ـ مجمــوع الفتــاوى ‪. )132-126/29( :‬‬\n     ‫وحيــث صــادق الطرفــان علــى عــدم توثيــق العقــد لــدى املؤجــر األول‬\n     ‫فعلــى هــذا  فــإن العقــد الثانــي لــم يبنــى علــى عقــد إيجــار صحيــح  ومبــا‬\n     ‫أن املدعــي وكالــة يطالــب بإعــادة األجــرة املدفوعــة للســنة األولــى والتــي‬\n     ‫قدرهــا خمســمائة وســبعة وســتون ألــف ريــال ومبــا أن املتداعيــن لــم‬\n     ‫يطلــب أحــد منهمــا تقديــر أجــرة املثــل واألصــل يف مثــل هــذا أن يطالــب‬\n     ‫بتقديــر أجــرة املثــل يف دعــوى مســتقلة لــذا فقــد ثبــت لــدي أن بذمــة‬\n     ‫شــركة ‪ ................‬مبلغ ـ ًا قــدره خمســمائة وســبعة وســتون ألــف ريــال‬\n     ‫تدفعهــا لشــركة ‪ ...............................‬وذلــك لعــدم صحــة العقــد الثانــي‬\n     ‫مــن الباطــن بــن املؤجــر الثانــي واملســتأجر الثالــث وبــه حكمــت‬\n     ‫وأفهمــت وكيــل شــركة ‪ ...............‬بــأن للشــركة مطالبــة الشــركة‬\n     ‫املدعيــة بأجــرة املثــل وبذلــك حكمــت وبعرضــه علــى الطرفــن قــرر‬\n     ‫املدعــي وكالــة القناعــة وقــرر املدعــى عليــه وكالــة عــدم القناعــة‬\n     ‫وطلــب االســتئناف فأفهــم أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ بعــد‬\n     ‫مهلــة تنظيــم الصــك خمســة أيــام إذا مضــت املــدة ولــم يقــدم الئحــة‬\n     ‫اعتراضيــة ســقط حقــه يف طلــب االســتئناف ولــه املراجعــة خــال املهلــة‬\n     ‫واملــدة النظاميــة الســتالم نســخة احلكــم لالعتــراض عليــه وبــاهلل‬\n     ‫التوفيــق وختمــت اجللســة يف متــام الســاعة الثانيــة عشــر  ‪ ،‬وصلــى اهلل‬\n        ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف  ‪1433/08/18‬هـ‬\n     ‫احلمــد هلل وحــده   ففــي يــوم  األحــد املوافــق‪ 1434/06/11‬ه ـ الســاعة‬\n     ‫الثامنــة انعقــدت اجللســة بعــد انتهــاء انتدابنــا مــن املجلــس األعلــى للقضاء‬\n     ‫وقــد وردنــا كتــاب فضيلــة رئيــس االســتئناف باملنطقــة الشــرقية رقــم‬\n     ‫‪ 34620259‬وتاريــخ ‪1434/4/22‬ه ـ واملرفــق بها قرار املالحظة الصادر‬\n\n\n‫‪67‬‬\n\f‫مــن الدائــرة األولــى‪ -‬ق‪ 1/‬رقــم ‪ 34191042‬وتاريــخ ‪1434/4/17‬ه ـ‬\n‫ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لوحــظ أن املدعــى عليــه وكالــة طالــب يف‬\n‫الئحتــه االعتراضيــة بأجــرة املثــل وهــذا مــن حقــه يف هــذه الدعــوى ‪،‬‬\n‫فعلــى فضيلتــه مالحظــة ذلــك وإكمــال الــازم حســب الوجــة الشــرعي‬\n‫والتعليمــات) ‪ .‬اه ـ ‪ .‬وأجيــب أصحــاب الفضيلــة الكــرام أن الالئحــة‬\n‫االعتراضيــة تضمنــت االعتــراض علــى احلكــم ببطــان العقــد صراحــة‬\n‫يف مواضــع غيــر مــا دون يف الضبــط ‪ ،‬ثــم يف آخــر الالئحــة أشــار إلــى‬\n‫أجــرة املثــل ومبــا أن مطالبتــه هــذه تتضمــن املوافقة علــى احلكم ببطالن‬\n‫العقــد ‪ ،‬ويظهــر بهــذا عــدم حتريرهــا ‪ ،‬واألصــل أن املطالبــة بأجــرة املثل‬\n‫فــرع عــن بطــان العقــد أو انفســاخه ‪ ،‬ومبــا أنــه غيــر مقتنــع باحلكــم‬\n‫فــا ميكــن النظــر يف مطالبتــه أجــرة املثــل حتــى يكتســب احلكــم‬\n‫القطعيــة علــى مــا جــاء يف النظــام ‪ ،‬ثــم إن مطالبتــه أجــرة املثــل جــاءت‬\n‫بعــد احلكــم ‪ ،‬وتعديــل الدعــوى بعــد صــدور احلكــم الــذي جــاء مبني ـ ًا‬\n‫علــى مطالبتــه الســابقة يف دعــواه غيــر مقبــول ؛ ألن صــدور احلكــم مــن‬\n‫القاضــي يف القضيــة بعــد انتهــاء املرافعــة قفــل لبابهــا‪ ،‬ولــه رفــع دعــوى‬\n‫مســتقلة كمــا ُأ ْوضــح ذلــك يف تســبيب احلكــم‪ ،‬ونظيــر هــذا مــا جــاء يف‬\n‫الشــرح الكبيــر إذا نــكل مــن توجهــت اليمــن يف حقــه قــال ابــن قدامــه‬\n‫رحمــه اهلل ‪ -‬مــا نصــه ‪ ( :‬فــإذا عــاد أحدهمــا فبــذل اليمــن ‪ ،‬لــم يســمعها‬\n‫يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا يف مجلــس‬\n‫آخــر فــإذا اســتأنف الدعــوى ؛ أعيــد احلكــم بينهمــا كاألول ) الشــرح‬\n‫الكبيــر مــع اإلنصــاف ‪ ، )437.436/28( :‬وســيجري رفــع املعاملــة‬\n‫حملكمــة االســتئناف للتدقيــق وبــاهلل التوفيــق وختمــت اجللســة يف متــام‬\n\n\n                                                                                    ‫‪68‬‬\n\f     ‫الســاعة الثامنــة وعشــر دقائــق وصلــى اهلل وســلم علــى نبينــا محمد وعلى‬\n     ‫آلــه وصحبــه حــرر يف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/11‬ه ـ احلمــد هلل وحــده‬\n     ‫والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه أمــا بعــد ‪ ...‬فقــد‬\n     ‫اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبدينــة الدمــام برقــم ‪ 34/1017287‬وتاريــخ ‪1434/6/18‬ه ـ‬\n     ‫واملقيــدة لــدى احملكمــة برقــم ‪ 34/1531166‬وتاريــخ ‪1434/6/25‬ه ـ‬\n     ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪ ....................... /‬املســجل‬\n     ‫برقــم ‪ 33415126‬وتاريــخ ‪1433/9/18‬ه ـ اخلــاص بدعــوى‪ /‬شــركة‬\n     ‫‪ ................‬ضــد‪ /‬شــركة ‪ ................‬يف قضيــة حقوقيــة وقــد تضمــن‬\n     ‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n     ‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه وأوراق‬\n     ‫ـاء علــى قرارنــا رقــم ‪ 34191042‬وتاريــخ ‪1434/4/17‬ه ـ فقــد‬         ‫املعاملــة بنـ ً‬\n     ‫قررنــا املصادقــة علــى احلكــم‪ ،‬ولبيانــه حــرر يف ‪1434/7/30‬ه ـ ‪ ،‬واهلل‬          ‫ّ‬\n                                                                        ‫ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":54,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8553645c5b52d2fb2a5a8d8072605d0a93c7540a85feb41ebeb16bf145765971","normalized_text_hash":"bd60c0e4323239da05a317fe6a3cf703f2db2272e29a980cfeadb6caff06a525","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p54-33415126"},{"id":"be45e6da-3601-5059-a89c-022656079ff8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بإخاء العقار أو مضاعفة األجرة ملخالفة بنود العقد -ثبوت سريان مدة العقد وعدم تغيير النشاط املتفق عليه- مصادقة الطرفن على مدة العقد والنشاط -صرف النظر عن","document_number":"33469025","case_number":"4958","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/29","year":"1434","subject":"إجارة -مطالبة بإخاء العقار أو مضاعفة األجرة ملخالفة بنود العقد -ثبوت سريان مدة العقد وعدم تغيير النشاط املتفق عليه- مصادقة الطرفن على مدة العقد والنشاط -صرف النظر عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/29 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33469025 :‬‬\n                        ‫َر ْق ُم الدعوى‪4958 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3437543‬تاريخه ‪1434/2/16‬هـ‬\n\n\n ‫إجــارة‪ -‬مطالبــة بإخــاء العقــار أو مضاعفــة األجــرة ملخالفــة بنــود‬\n ‫العقــد‪ -‬ثبــوت ســريان مــدة العقــد وعــدم تغييــر النشــاط املتفــق عليــه‪-‬‬\n ‫مصادقــة الطرفــن علــى مــدة العقــد والنشــاط‪ -‬صــرف النظــر عــن‬\n                                                                    ‫الدعــوى ‪.‬‬\n\n\n\n\n                   ‫ما أشار له القاضي من مبادئ وقواعد يف تسبيب حكمه‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي بقولــه أنــه أبــرم عقــد إيجــار عقــار ‪ ..‬ميلكــه للشــركة‬\n ‫املدعــى عليهــا ملــدة وأجــرة محددتــن ‪ ،‬قامــت الشــركة املدعــى عليهــا‬\n ‫مبخالفــة بنــود العقــد وذلــك بقيامهــا بتغييــر النشــاط املتفــق عليــه يف‬\n ‫العقــد‪ ،‬طالــب املدعــي بإخــاء املبنــى ومضاعفــة األجــرة‪ ،‬أنكــرت‬\n ‫املدعــى عليهــا دعــوى املدعــي ورفضــت اإلخــاء ومتســكت مبــدة العقد‪،‬‬\n ‫صــادق الطرفــان علــى ســريان مفعــول مــدة العقــد وعــدم تغييــر النشــاط‬\n ‫املتفــق عليــه ولــم يثبــت لــدى القاضــي خــاف ذلــك‪ ،‬وملــا كان فســخ‬\n ‫العقــد ال يكــون إال بإنتهــاء املــدة وتراضــي الطرفــن لــذا حكمــت‬\n ‫احملكمــة بصــرف النظــر عــن الدعــوى ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                          ‫اإلســتئناف ‪.‬‬\n\n                                                                                  ‫‪70‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n     ‫العامــة بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة بالدمــام برقــم ‪ 4958‬وتاريــخ ‪1431/07/03‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3119812‬وتاريــخ  ‪1431/7/3‬ه ففــي يــوم‬\n     ‫الســبت املوافق‪1432/06/18‬ه ـ حضــر ‪..................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .........................‬الوكيــل الشــرعي عــن‬\n     ‫‪ .....................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n     ‫برقــم ‪ 39925‬وتاريــخ ‪1432/10/12‬ه ـ جلــد ‪ 1885‬وحضــر حلضــوره‬\n     ‫‪ .......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..............‬‬\n     ‫الوكيــل الشــرعي عــن ‪ ...................‬بصفتــه رئيــس ‪ .................‬مبوجــب‬\n     ‫الوكالــة الصــادة مــن كاتــب العــدل املكلــف بوزارة التجــارة والصناعة‬\n     ‫ا يف دعــواه‪ :‬لقــد أجــر موكلــي علــى الشــركة ‪ ..................‬كامــل‬     ‫قائـ ً‬\n     ‫املبنــى املكــون مــن دوريــن وملحــق ومواقــف املقــام علــى القطعتــن‬\n     ‫رقــم ‪ 5‬و ‪ 6‬مــن مخطــط رقــم ‪ 1/791‬بحــي املنــار مبدينــة الدمــام ملــدة‬\n     ‫عشــر ســنوات إعتبــار ًا مــن تاريــخ تســليمه حســب العقــد املبــرم يف‬\n     ‫‪1432/11/5‬ه ـ بأجــرة قدرهــا ثالثمائــة وخمســن ألــف ريــال للســنة ويف‬\n     ‫عــام ‪1430‬ه ـ أخــل املدعــى عليــه بالعقــد حيــث كان العقــد علــى معهــد‬\n     ‫لتدريــب البنــن فقســم املدعــى عليــه املبنــى الــى قســمني وقــام بتشــغيل‬\n     ‫معهــد لتدريــب البنــات مــن غيــر رجــوع الــى موكلــي ويف هــذا مخالفــة‬\n     ‫للبنــد الســادس مــن العقــد لــذا أنذرتهــم لقــاء إخاللهــم بالعقــد وطلبــت‬\n     ‫منهــم إخــاء املبنــى أو مضاعفــة األجــرة لتصبــح ســبعمائة ألــف لــذا‬\n\n‫‪71‬‬\n\f‫أطلــب إلزامهــم بإخــاء العــن املؤجــرة ودفــع مبلــغ ســبعمائة ألــف عــن‬\n‫الســنتني األخيرتــن وبعــرض الدعــوى علــى املدعــى عليــه قــال أطلــب‬\n‫مهلــة للرجــوع إلــى موكلــي وإعــداد جــواب فطلبــت مــن املدعــي أصــل‬\n‫صــك امللكيــة وحتديــد بدايــة املــدة املطالــب فيهــا مبضاعفــة األجــرة‬\n                                      ‫وبيــان مجمــوع الواصــل فأســتعد بذلــك‬\n‫ويف جلســة ‪1432/09/10‬ه ـ حضــر الطرفــان وســألت املدعــي عــن صك‬\n‫امللكيــة فأبــرز الصــك الصــادر مــن كتابــة العــدل بالدمــام األولــى برقــم‬\n‫‪ 2/64/6000‬يف ‪1432/10/13‬ه ـ ويتضمــن ملكيــة مــوكل املدعــي‬\n‫لقطعتــي األرض ‪ 5‬و ‪ 6‬مــن مخطــط رقــم ‪ 791/1‬يف حــي املنــار بالدمــام‬\n‫وأمــرت بإيــداع صــورة مصدقــة منــا باملعاملــة كمــا ســألته عــن بدايــة‬\n‫املــدة املطالــب فيهــا مبضاعفــة االجــرة ومقــدار الواصــل فقــال لســت‬\n                            ‫متأكــد ًا وأطلــب مهلــة للرجــوع إلــى احلســابات‬\n‫ويف جلســة ‪1433/02/24‬هـ حضر الطرفان وســألت املدعي عن مقدار‬\n‫الواصــل فقــال مبلــغ مليونــن وثمامنائــة ريــال وســألته عــن بدايــة املــدة‬\n‫املطالــب فيهــا مبضاعفــة األجــرة فقــال تاريــخ ‪1431/04/04‬ه ـ فســألته‬\n‫عــن املبلــغ الــذي يطالــب بــه عــن الســنتني االخيرتــن مــا صفتــه فقــال‬\n‫صفتــه مبلــغ مضاعــف علــى االجــرة املنصــوص عليهــا يف العقــد وامــا‬\n‫حســب العقــد فــا يوجــد مبلــغ متخلــف وبعــرض الدعــوى ومــا أضيــف‬\n‫إليهــا علــى املدعــى عليــه قــال صحيــح اســتأجرت الشــركة موكلتــي‬\n‫املبنــى املذكــور مــن مــوكل املدعــي باألجــرة الســنوية املذكــورة واملــدة‬\n‫املذكــورة ولكــن لــم نخــل بالعقــد وال نقــر مبضاعفــة األجــرة وال يوجــد‬\n‫مبلــغ متخلــف مــن األجــرة وغيــر مســتعدين بإخــاء العــن املؤجــرة ألن‬\n‫العقــد ســاري املفعــول فطلبــت مــن املدعــي أصــل العقــد فأبــرزه ووقــع‬\n\n\n                                                                                   ‫‪72‬‬\n\f                             ‫الطرفــان علــى صــورة منــه وأمــرت بإرفاقــه باملعاملــة ‪.‬‬\n       ‫ويف جلســة ‪1433/10/28‬ه ـ حضــر الطرفــان وخلــص املدعــى عليــه‬\n       ‫مذكرتــه اجلوابيــة بقولــه تضمــن عقــد اإليجــار بعــض الشــروط‬\n       ‫اجلوهريــة  منهــا أن للمســتأجر حــق االنتفــاع منــه واالســتفادة بــكل‬\n       ‫الطــرق املشــروعة ومنهــا أن مــدة اإليجــار عشــر ســنوات حســب البنــد‬\n       ‫ثالثــة مــن الفقــرة ثانيـاً  ومنهــا أنــه ال يحــق ألحــد الطرفــن فســخ العقــد‬\n       ‫أال بانتهــاء املــدة أو تراضــي الطرفــن حســب البنــد الســابع ومنهــا أن‬\n     ‫علــى املســتأجر تســليم املبنــى املؤجــر للطــرف األول عنــد االســتغناء عنــه  ‬\n       ‫كمــا اســتلمه عنــد بدايــة العقــد وعليــه إصــاح مــا اتلــف أو دفــع كامــل‬\n       ‫التكاليــف كمــا يف البنــد الثامــن وأحلــق علــى العقــد يف ‪1424/9/6‬ه‬\n       ‫بزيــادة اإليجــار خمســن ألــف ريــال علــى نفــس مــدة العقــد وأؤكــد علــى‬\n       ‫أن عقــد اإليجــار خــا مــن أي عبــارة أو إشــارة بــأن املعهــد يخــص الرجــال‬\n       ‫أو النســاء أو كالهمــا ونســتند علــى البنــد األول مــن أو ًال وفيــه أن يقــوم‬\n       ‫الطــرف األول بتجهيــز مقــر العامليــة يف الدمــام ويف البنــد األول مــن ثانيـ ًا‬\n       ‫وللمســتأجر حــق االنتفــاع منــه واالســتفادة بــكل الطــرق املشــروعة‬\n       ‫وهــذا نــص يف العقــد وال اجتهــاد مــع النــص وموكلتــي مرخــص لهــا‬\n       ‫ممارســة نشــاط التدريــب ســواء للنســاء او الرجــال وممارســة هــذا‬\n       ‫النشــاط اســتفادة مشــروعة ال تتعــارض مــع النظــام او مــع عقــد اإليجــار‬\n       ‫ولــم تخالــف موكلتــي البنــد الســادس مــن عقــد اإليجــار ومــا قامــت‬\n       ‫بــه هــو فصــل قســم النســاء عــن قســم الرجــال مــن خــال عمــل فواصــل‬\n       ‫ميكــن إزالتهــا يف أي وقــت دون املســاس باملبنــى وال تعتبــر تعديــات‬\n       ‫مــن شــأنها اإلضــرار باملبنــى وال تنــدرج حتــت نــص املــادة السادســة ولــو‬\n       ‫اندرجــت فــإن ذات املــادة لــم تعــط احلــق للمؤجــر يف فســخ العقــد علــى‬\n\n\n‫‪73‬‬\n\f‫افتــراض وجــود املخالفــة مــع أنهــا لــم توجــد والفصــل بــن معهــد الرجــال‬\n‫والنســاء مطلــب شــرعي ونظامــي واملــادة الثامنــة مــن العقــد ألزمــت‬\n‫موكلتــي بتســليم املبنــى إلــى الطــرف األول كمــا اســتلمته وعليهــا‬\n‫إصــاح مــا تلــف أو التعويــض عنــه وهــذا اكبــر ضمــان للمدعــي ضــد‬\n‫أي تغييــر أو تعديــل أمــا مطالبــة املدعــي بإخــاء املبنــى فــور ًا فــان فيــه‬\n‫مخالفــة صريحــة لبنــود العقــد فــا يحــق ألحــد الطرفــن فســخ العقــد إال‬\n‫بانتهــاء املــدة والتراضــي ومطالبتــه مبضاعفــة قيمــة اإليجــار يكشــف‬\n‫هدفــه فهــذا الطلــب ينــايف جميــع مــا أورده يف دعــواه ويتعــارض مــع باقــي‬\n‫الطلبــات فكيــف يطالــب باإلخــاء للمخالفــة ثــم يخيرهــا أو يســاومها‬\n‫بــن ذلــك وبــن مضاعفــة اإليجــار فهــل يســتقيم أن يطالــب بفســخ العقــد‬\n‫لوجــود مخالفــات ثــم يف الوقــت نفســه يطالــب مبضاعفــة اإليجــار علمـ ًا‬\n‫بــأن اإليجــار مغالــى فيــه نســبه للمــكان والزمــان الــذي جــرى فيــه‬\n‫االتفــاق وقبلــت موكلتــي بذلــك تطبيقــا لسياســة طويلــة األجــل إلثبــات‬\n‫مصداقيتهــا عنــد عمالئهــا وباالطــاع علــى العقــد وجــد انــه مــؤرخ يف‬\n‫‪1423/11/05‬ه ـ ويف الفصــل أو ًال البنــد األول يقــوم الطــرف األول‬\n                                                   ‫بتجهيــز مقــر ‪ .......‬يف الدمــام‬\n‫ويف الفصــل الثانــي يف البنــد األول منــه ما نصه وللمســتأجر حق االنتفاع‬\n‫منــه واالســتفادة بــكل الطــرق املشــروعة ويف البنــد الثالــث مــا نصــه إن‬\n‫هــذا اإليجــار معقــود ملــدة عشــر ســنوات ميالديــة ويف البنــد الســادس ال‬\n‫يحــق للطــرف الثانــي أي تغييــر يف املوقــع املؤجــر لــه إال بعــد أخــذ املوافقة‬\n‫اخلطيــة مــن الطــرف األول املالــك ويتــم التنفيــذ حســب شــروط الطــرف‬\n‫األول ويف البنــد الســابع ال يحــق ألحــد الطرفــن فســخ العقــد إال بانتهــاء‬\n‫املــدة أو تراضــي الطرفــن ويف البنــد الثامــن علــى الطــرف الثانــي تســليم‬\n\n\n                                                                                        ‫‪74‬‬\n\f     ‫املبنــى املؤجــر ‪ ......‬كمــا اســتلمه وقــد أحلــق عليــه يف ‪1424/09/06‬‬\n     ‫إضافــات وتعديــات مــن ضمنهــا إضافــة وحدتــن ســكنيتني يف مقدمــة‬\n                          ‫البنــاء يف الــدور الثالــث لتكــون مكاتــب إلدارة املعهــد‬\n     ‫وتعديــل مبلــغ اإليجــار بزيــادة خمســن ألــف ريــال ســنوي ًا طــوال فتــرة‬\n     ‫العقــد بعــرض العقــد علــى الطرفــن صادقــا علــى مــا فيــه وانــه مــؤرخ يف‬\n     ‫‪1423/11/05‬ه ـ املوافــق ‪2003/01/08‬م ويف جلســة ‪1433/11/27‬ه ـ‬\n     ‫حضــر الطرفــان وســألت املدعــي هــل العقــد ال يــزال ســاري املفعــول‬\n     ‫فقــال نعــم ولــن ينتهــي إال يف ‪2014/03/01‬م أي بعــد ســتة أشــهر تقريبـ ًا‬\n     ‫وســألته مــا هــو وجــه انتفــاع املدعــى عليــه مــن العــن املؤجــرة فقــال‬\n     ‫التدريــب علــى احلاســب اآللــي ولــم يغيــر نشــاطه وبعرضــه علــى املدعــى‬\n     ‫عليــه صــادق علــى ذلــك إال أنــه ذكــر أن انتهــاء العقــد يف ‪2014/7/1‬م‬\n     ‫فســألته لــدى موكلتــه ترخيــص لتدريــب النســاء فقــال نعــم وأبــرز‬\n     ‫رخصــة تدريــب نســاء باســم ‪ .....................‬النســائي للتدريــب برقــم‬\n     ‫‪135927/1/8‬وتاريــخ ‪1433/06/30‬ه ـ وهــو صــادر مــن اإلدارة العامــة‬\n     ‫للتدريــب ‪ ...‬يف املؤسســة العامــة للتدريــب التقنــي واملهنــي وأمــرت بإيــداع‬\n     ‫صــورة مصدقــة منهــا باملعاملــة وبعرضهــا علــى املدعــي صــادق عليهــا‬\n     ‫فســألت الطرفــن ألديهمــا زيــادة يريــدان إضافتهــا فقــاال ال زيــادة لدينــا‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيث تصــادق الطرفان على‬       ‫فبنـ ً‬\n     ‫أن العقــد ال يــزال ســاري املفعــول وان املدعــى عليــه انتفــع بالعــن املؤجــرة‬\n     ‫يف التدريــب علــى احلاســب اآللــي ولــم يغيــر نشــاطه ومبــا أن النشــاط‬\n     ‫الــذي متارســه املدعــى عليهــا مرخــص بــه مــن اجلهــة املختصــة وألن مســتند‬\n     ‫املدعــي يف طلبــه مــن املدعــى عليــه اإلخــاء أو مضاعفــة األجــرة هــو‬\n     ‫البنــد الســادس وألن البنــد الســادس ال يجيــز فســخ العقــد وال مضاعفــة‬\n\n\n‫‪75‬‬\n\f‫األجــرة وألن البنــد األول مــن العقــد يجيــز للمدعــى عليــه االنتفــاع بالعــن‬\n‫املؤجــرة واالســتفادة بــكل الطــرق املشــروعة وألن البنــد الســابع مينــع‬\n‫فســخ العقــد إال بعــد انتهــاء املــدة أو تراضــي الطرفــن وحيــث لــم أجــد‬\n‫يف العقــد مــا يبــرر للمدعــي طلبــه لــذا كلــه صرفــت النظــر عــن دعــوى‬\n‫املدعــي ولــم يثبــت لــدي اســتحقاقه ملــا يدعيــه وبذلــك حكمــت وبعــرض‬\n‫احلكــم علــى الطرفــن قنــع بــه املدعــى عليــه ولــم يقنــع بــه املدعــي وطلــب‬\n‫متييــزه فأجبتــه لطلبــه‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/27‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد بشــأن دعوى ……………‪  /..‬ضد ‪  /‬الشــركة‬\n‫‪ .................‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية وبرفقهــا قرارهــا رقــم ‪ 3437543‬وتاريــخ ‪1434/02/16‬ه ـ‬\n‫املتضمــن مــا نصــه ( بدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ) رئيــس‬\n‫الدائــرة الشــيخ ‪ .................‬توقيعــه بقلمــه وختمــه ‪ ،‬وقاضــي اســتئناف‬\n‫الشــيخ ‪ .................‬توقيعــه بقلمــه وختمــه ‪ ،‬وقاضــي اســتئناف الشــيخ‬\n‫‪ ........................‬توقيعــه بقلمــه وختمــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1434/3/22‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام املســاعد برقــم‬\n‫‪ 3119812‬وتاريــخ ‪ 1434/1/14‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34193124‬وتاريــخ ‪1434/1/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ........................./‬املســجل برقــم‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫‪ 33469025‬وتاريــخ ‪1433/11/29‬ه ـ اخلــاص بدعــوى‪................../‬‬\n     ‫ضد‪/‬الشــركة ‪ ......................‬يف قضيــة حقوقيــة وقــد تضمــن الصــك‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n     ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                      ‫حــرر يف ‪1434/2/16‬ه ـ ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":70,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"705d1697f2a7933f2d25f7adf8308b140ebf988d197ec38ce5901450902e5de3","normalized_text_hash":"6616d9f43ed4f7db3bb4e6ac8e769eb4c8d71b37adae3dc3117268be04570fd7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p70-33469025"},{"id":"75941498-0fb4-5449-8bbd-570c0e463844","document_type":"judgment","category":"judicial","subcategory":"general","title":"اجارة -عقد -اجاره سيارة -مطالبة باجرة سيارة -تخلف املدعى عليه عن احلضور رغم تبلغه -االستعانه باهل اخلبره يف مضاهاة اخلط -إحضار البينة بأن السيارة كانت بحوزة املدعى عليه وقت القبض ،حتليف اليمن -إلزام املدعى عليه بدفع باقي األجرة - الغائب على حجته متى حضر.","document_number":"34254640","case_number":"15788","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة واحملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/28","year":"1434","subject":"اجارة -عقد -اجاره سيارة -مطالبة باجرة سيارة -تخلف املدعى عليه عن احلضور رغم تبلغه -االستعانه باهل اخلبره يف مضاهاة اخلط -إحضار البينة بأن السيارة كانت بحوزة املدعى عليه وقت القبض ،حتليف اليمن -إلزام املدعى عليه بدفع باقي األجرة - الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/28:‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪34254640 :‬‬\n                     ‫َر ْق ُم الدعوى‪15788:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‬\n         ‫‪  34346223:‬تاريخه‪1434/11/2:‬هـ‬\n\n\n‫اجــارة ‪ -‬عقــد ‪ -‬اجــاره ســيارة ‪ -‬مطالبــة باجــرة ســيارة ‪-‬تخلــف املدعــى‬\n‫عليــه عــن احلضــور رغــم تبلغــه ‪ -‬االســتعانه باهــل اخلبــره يف مضاهــاة‬\n‫اخلــط ‪ -‬إحضــار البينــة بــأن الســيارة كانــت بحــوزة املدعــى عليــه وقــت‬\n‫القبــض ‪ ،‬حتليــف اليمــن ‪ -‬إلــزام املدعــى عليــه بدفــع باقــي األجــرة ‪-‬‬\n                                          ‫الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه غيابيــا بأنــه اســتأجر منــه‬\n‫ســيارة ملــدة ســبعة وعشــرين يومــا مبائــة وعشــرة ريــاالت يوميــا ثــم‬\n‫اســتبدلها بســيارة أخــرى وبنفــس األجــرة إال أنــه لــم يســلم الســيارة‬\n‫إال بعــد املــدة وابــاغ اجلهــات الرســمية والتعميــم عنــه والقبــض عليــه‪،‬‬\n‫عليــه وألن الســيارة بقيــت عنــده أربعمائــة وأحــد عشــر يومــا فقــد طلــب‬\n‫إلزامــه بدفــع أربعــة وثالثــن ألفــا وأربعمائــة ريــال بعــد حســم مــا ســلمه‪،‬‬\n‫جــرى تبليــغ ابنــه بجلســتني إال أنــه لــم يحضــر كمــا وردت إفــادة بأنــه‬\n‫جــرى تبليغــه هاتفيــا فاعتــذر عــن عــدم احلضــور ‪ ،‬طلــب مــن املدعــي‬\n                                                                                      ‫‪92‬‬\n\f     ‫البينــة فأحضــر رجلــي  األمــن اللذيــن قبضــا علــى املدعــى عليــه وشــهدا‬\n     ‫بالقبــض عليــه وضبــط الســيارة معــه وال يذكــران أكثــر مــن ذلــك ‪-‬‬\n     ‫وردت إفــادة الشــرطة بأنــه جــرى التعميــم عليــه وإدراجــه ضمــن قائمــة‬\n     ‫إيقــاف اخلدمــات ‪ -‬جــرى االطــاع علــى إقــرار خطــي منســوب للمدعــى‬\n     ‫عليــه يقــر فيــه باملبلــغ املدعــى بــه وموجبــه فطلــب مــن املدعــي احضــاره‬\n     ‫وإحضــار أصــل وثيقــة عقــد األجــرة إلجــراء املضاهــاة لــدى األدلــة‬\n     ‫اجلنائيــة ‪ -‬طلبــت األدلــة اجلنائيــة أوراقــا محــررة يف أحــوال عاديــة مــن‬\n     ‫املدعــى عليــه فــردت اإلفــادة بتعــذر ذلــك لعــدم حضــور املدعــى عليــه‬\n     ‫وطلــب اإلفــادة هــل التوقيــع علــى وثيقــة العقــد متفقــة مــع اإلقــرار باحملرر‬\n     ‫فعــادت اإلفــادة بأنهمــا متفقــان ‪ -‬طلــب مــن املدعــي اليمــن علــى صحــة‬\n     ‫دعــواه تقويــة جلانبــه فحلــف اليمــن املطلوبــة ‪ -‬بنــاء علــي مــا تقــدم مــن‬\n     ‫الدعــوي واالجابــة وبنــاء علــي مــا جــاء بعقــد االيجــار ومــا جــاء باالقــرار‬\n     ‫املذكــور وبنــاء علــي ماجــاء بتقريــر األدلــة اجلنائيــة وحيــث أدى املدعــي‬\n     ‫اليمــن الشــرعية تقويــة جلانبــه وعلــى عــدم اســتالمه املبلــغ املذكــور‬\n     ‫فقــد صــدر احلكــم علــي املدعــي عليــه الغائــب  بدفــع أربعــة وثالثــن‬\n     ‫الف ـ ًا وأربعمئــة ريــال للمدعــي وتقــرر بعــث صــورة مــن صــك احلكــم‬\n     ‫للمدعــى عليــه ‪ -‬تعــذر ابالغــه فرفعــت لالســتئناف ‪ -‬صــدق احلكــم مــن‬\n     ‫محكمــة االســتئناف وأضافــت بــأن الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــي مــن النبــي بعــده وبعــد لــدي‬\n     ‫أنــا د‪ .................. /‬القاضــي باحملكمــة العامــة باملدينــة املنــورة واحملالــة‬\n     ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــه برقــم ‪30/60155‬يف‬\n‫‪93‬‬\n\f‫‪1430/11/14‬ه ـ واملقيــدة بأســاس احملكمــة برقــم ‪ 15788‬يف‬\n‫‪1430/11/14‬ه ـ ففــي يــوم الســبت املوافــق ‪1431/10/23‬ه ـ حضــر‪/‬‬\n‫‪....................‬بالســجل املدنــي رقــم ‪ .................‬املدينــة وادعــي علــي‬\n‫الغائــب عــن مجلــس احلكــم ‪ ........... /‬ســعودي اجلنســية   بالســجل‬\n‫املدنــي رقــم ‪ .............‬بقولــه أننــي أجــرت املدعــي عليــه ســيارة ‪ ...‬رقــم‬\n‫اللوحــة (‪ ).............‬لــون ‪ ...‬مــدة ســبعة وعشــرين يومــا بأجــرة يوميــة‬\n‫قدرهــا مائــة وعشــرة ريــاالت اعتبارمــن ‪1429/9/9‬ه ـ ثــم يف يــوم األثــن‬\n‫‪1429/9/22‬ه ـ حضــر واســتبدل الســيارة بســيارة أخــرى مــن نــوع ‪...‬‬\n‫وبنفــس االجــرة وبنفــس املــدة ولكنــه لــم يســلم الســيارة بعــد نهايــة املــدة‬\n‫املذكــورة فأبلغــت اجلهــات الرســمية عنــه ومت التعميــم عنــه ومت القبــض‬\n‫علــى الســيارة يف ‪1430/11/6‬ه ـ وبذلــك فقــد بقيــت الســيارة لديــه‬\n‫أربعمائــة واحــد عشــر يومــا بلغــت أجرتهــا واحــد وأربعون ألفــا ومائة ريال‬\n‫وقــد ســلمني خمســة آالف ومائتــي ريــال وبقــي عليــه خمســة وثالثــون الفا‬\n‫وتســعمائة ريــال وقــد كتــب لــي إقــرار ًا بذلــك بتاريــخ ‪1430/11/6‬ه ـ‬\n‫وهــذا مانصــه أقــر أنــا ‪ ...................‬بأننــي اســتأجرت ســيارة ‪ ...‬رقــم(‬\n‫‪)...........‬مبوجــب العقــد رقــم ‪ 407‬يف ‪1429/9/9‬ه ـ ملــدة ‪ 27‬يومــا ثــم‬\n‫تغيــب حتــي عمــم عــن الســيارة وقبضــت مــن قبــل البحــث اجلنائــي يف يــوم‬\n‫االحــد ‪1430/11/6‬ه ـ وحســبت املــدة التــي بقيــت وهــي أربعمائــة وأحــد‬\n‫عشــر يومـاً  بأجــرة يوميــة قدرهــا مائــة ريــال بعــد اخلصــم ليصبــح املبلــغ‬\n‫قــدره واحــد واربعــون الفـ ًا ومائــة ريــال دفعــت منهــا خمســة آالف ومئتــي‬\n‫ريــال ومبوجــب العقــد علــى دفعــات وتبقــى لــدى مبلــغ قــدره خمســة‬\n‫وثالثــون الف ـ ًا وتســعمائة ريــال وهــو يف ذمتــي وســوف اســدده يف مــدة‬\n‫عشــرة أيــام بــدون تأخيــر وعلــي ذلــك قــررت بذلــك وأشــهد علــي نفســي‬\n\n\n                                                                                        ‫‪94‬‬\n\f     ‫واهلل خيــر الشــاهدين املقرمبــا فيــه ‪ ..............‬توقيعــه يف ‪1430/11/6‬ه ـ‬\n     ‫أ‪ .‬هــ  وبعــد ذلــك ســلمنى الــف وخمســمائة ريــال فقــط وبقــي عليــه أربعــه‬\n     ‫وثالثــون الفــا وأربعمائــة ريــال  أه ـ ‪ .‬وملــا أنتهــت املهلــة بحثــت عنــه فلــم‬\n     ‫أجــده وتقدمــت ضــده بهــذه الدعــوي ولــذا فأطلــب احلكــم عليــه بدفــع‬\n     ‫املبلــغ املذكــور وقــدره أربعــة وثالثــون الف ـ ًا وأربعمائــة ريــال هكــذا‬\n     ‫قــرر دعــواه هــذا وقــد جــري االطــاع علــى عقــد التأجيــر الصــادر مــن‬\n     ‫مؤسســة ‪ ...............‬لتأجيــر الســيارات برقــم ‪ ...‬املتضمــن اســتئجار‬\n     ‫املدعــو‪ ......................... /‬للســيارة املذكــورة باألجــرة املذكــورة املــدة‬\n     ‫املذكــورة واملشــروح عليــه بــأن املذكــور اســتبدل الســيارة ‪ ...‬بســيارة ‪...‬‬\n     ‫برقــم ‪ ...............‬هــذا وقــد جــري طلــب املذكوربحضــور جلســة الثالثــاء‬\n     ‫‪1430/11/29‬هـ حيث تبلغ ابنه ‪ ...‬من قبل محضر اخلصوم ‪  ...‬ولكنه‬\n     ‫لــم يحضــر كمــا جــرى طلبــه حلضــور جلســة الســبت ‪1431/1/23‬ه ـ‬\n     ‫فوردنــا خطــاب قســم احملضريــن املتضمــن انــه مت الذهــاب الــي املنــزل‬\n     ‫عــدة مــرات وبعــد االتصــال باملدعــى عليــه أفــاد بأنــه يف املستشــفي يف‬\n     ‫الريــاض مــن قبــل احلــج إلجــراء عمليــه جراحيــة يف قلبــه وال يعلــم متــى‬\n     ‫يخــرج علم ـ ًا بأنــه تبلــغ مبوعــد اجللســة هاتفي ـ ًا كمــا مت حتديــد جلســة‬\n     ‫الســبت ‪1431/3/13‬ه ـ فأفــاد احملضــر أنــه مت الذهــاب للمنــزل عــدة‬\n     ‫مــرات ولــم جنــده وافــاد احلــارس بأنــه يف الريــاض إلجــراء عمليــه ثــم مت‬\n     ‫حتديــد جلســة يف يــوم الســبت ‪1431/4/25‬ه ـ فعــاد اخلطــاب بواســطة‬\n     ‫محضــر اخلصــوم ‪ ...‬أنــه مت الذهــاب ملنــزل املذكــور عــدة مــرات واليوجد‬\n     ‫مــن يتــم تبليغــه وقــد ســلمت صــورة اخلطــاب الــي عمــدة احلــي كمــا جــرى‬\n     ‫ارســال خطــاب مســجل برقــم ‪ 495‬يف ‪1431/3/20‬ه ـ كمــا مت حتديــد‬\n     ‫جلســة يف يــوم الثالثــاء ‪1431/8/15‬ه ـ ومت ابــاغ ابنــه املدعــو‪......... /‬‬\n\n\n‫‪95‬‬\n\f‫الــذي أفــاد أن أبــاه مــا يــزال يف املستشــفي حســب كالمــه مــن قبــل‬\n‫احملضــر ‪ .............‬وحيــث احلــال مــا ذكــر فقــد قــررت النظــر يف القضيــة‬\n‫غيابي ـ ًا وطلبــت مــن املدعــي البينــة فقــال لــدي شــاهدان مــن البحــث‬\n‫اجلنائــي شــهدا علــى اإلقــرار املذكــور ومســتعد بإحضارهمــا ثــم رفعــت‬\n‫اجللســة لذلــك وعليــه حصــل التوقيــع ‪ .‬ويف يــوم األحــد ‪1431/12/1‬ه ـ‬\n‫حضــر املدعــي كمــا حضــر معــه كل مــن ‪ .................‬بالســجل املدنــي‬\n‫رقــم ‪ ...............‬املدينــة و‪ ........................‬بالســجل املدنــي رقــم ‪..............‬‬\n‫املدينــة وبســؤالهما عمــا لديهمــا مــن شــهادة قــاال أننــا أســتلمنا املدعــو‪/‬‬\n‫‪ ....................‬مــن الدوريــات األمنيــة وقــد حضــر عندنــا وكان قــد‬\n‫ســبق التعميــم عنــه كمــا اســتلمنا منــه الســيارة العائــدة للمدعــي هــذا‬\n‫احلاضــر حيــث إنهــا كانــت ســيارة تأجيــر وســلمناها لهــذا احلاضــر‬\n‫‪ ...................‬ووقــع بإســتالمها وبعــد ذلــك أوقفنــا البحــث عــن املذكــور‬\n‫وانتهــى دورنــا بذلــك وال نذكــر اكثــر مــن ذلــك هكــذا شــهدا هــذا‬\n‫وقــد ســبق أن وردنــا خطــاب مديــر شــرطة املدينــة برقــم ‪ 5/5/2/22‬يف‬\n‫‪1432/1/1‬ه ـ املتضمــن إدراج اســم ‪ ................‬علــى قائمــة املطلوبــن‬\n‫إجــراء (إيقــاف خدمــات) وحيــث أنــه لــم يراجعنــا املدعــي عليــه طيلــة‬\n‫تلــك املــدة فقــد جــرى ســؤال املدعــي عــن اإلقــرار األساســي املنســوب‬\n‫للمدعــى عليــه فقــال إنــه موجــود لــدي فطلبــت منــه إحضــار العقــد‬\n‫لتأجيــر الســيارة وإحضــار اإلقــرار األســاس للمدعــى عليــه ملضاهــات‬\n‫التوقيعــن العائديــن للمدعــى عليــه مــع بعضهمــا مــن قبــل األدلــة اجلنائيــة‬\n‫فإســتعد بذلــك ورفعــت اجللســة ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/3/4‬ه ـ‬\n‫وفيهــا حضــر املدعــي وقــد عــادت املعاملــة مــن األدلــة اجلنائيــة برقــم‬\n‫‪ 117/5320‬يف ‪1433/5/22‬ه ـ والــذي جــاء فيــه بشــأن مضاهــاة توقيــع‬\n\n\n                                                                                                   ‫‪96‬‬\n\f     ‫‪ ...................‬علــي أقــرار وعقــد تأجيــر ســيارة منســوبة إليــه (موضوعــي‬\n     ‫الفحــص) وباطــاع املختصــن لدينــا تبــن أنــه يلــزم إلكمــال الفحــص‬\n     ‫حتقيــق األتــي ‪1 -:‬ـ  تزويدنــا بــأوراق محــرره بظــروف طبيعيــة وفيــرة‬\n     ‫العــدد حتتــوي علــي توقيــع املدعــو‪................ /‬علــى أن تكــون أساس ـ ًا‬\n     ‫ولديــه صــور ًا ومــن واقــع تعامالتــه الرســمية ‪ -2 ،‬تكليــف ‪..............‬‬\n     ‫باحلضــور لشــعبة التزويــف والتزويــر طرفنــا ليتــم اســتكتابة مــن قبــل‬\n     ‫املختصــن لدينــا ‪ .‬لــذا نعيــد لكــم أوراق القضيــة ويف حالــة اســتكمال‬\n     ‫املطلــوب إعادتهــا لنــا ‪ .‬وحيــث إن املدعــى عليــه متهــرب عــن القضيــة‬\n     ‫منــذ مــا يزيــد عــن حوالــي ثــاث ســنوات وحيــث مت إيقــاف خدماتــه منــذ‬\n     ‫مــا يزيــد عــن ســنتني ولــم يتــم حضــوره إلــى تاريخــه وحيــث أن ورقــة‬\n     ‫عقــد اإليجــار ورقــة أســاس واقــراره باملبلــغ علــي ورقــة أســاس وكال‬\n     ‫التوقيعــن توقعــن اساســيني فقــد قــررت اعــادة املعاملــة لإلدلــة اجلنائيــة‬\n     ‫ملضاهــات التوقيعــن املذكوريــن علــي حالهــا حيــث أن املذكــور‬\n     ‫متهــرب ولــم نتمكــن مــن احضــاره ولــو حضــر لدينــا ملــا احتجنــا الــي‬\n     ‫مخاطبتهــم ورفعــت اجللســة‪ .‬ثــم جــرت اعــادة املعاملــة مــرة آخــرى لالدلــة‬\n     ‫اجلنائيــة ملضاهــات التوقيــع املوجــود علــى االقــرار مــع التوقيــع علــي عقــد‬\n     ‫االيجــار فقــط ثــم عــادت مــن األدلــة اجلنائيــة برقــم ‪ 1/7/3386/22‬يف‬\n     ‫‪1434/4/3‬ه ـ والــذي جــاء فيــه تقريــر فنــى رقــم ‪ 50‬مــادة الفحــص (‪)1‬‬\n     ‫عقد ســيارة (‪ )2‬اقرارواملطلوب املضاهات بني توقيع ‪ .........‬املنســوب له‬\n     ‫علــى االقــرار والتوقيــع املثبــت علــي عقــد إيجــار ســيارة مــن فــرع مؤسســة‬\n     ‫‪ ...‬الفحــص والنتيجــة باملضاهــات بعــد النتيجــة‪ -:‬باملضاهــات بــن‬\n     ‫التوقيعــن موضــوع الفحــص (‪ )1‬و(‪)2‬ومقارنتهمــا وجــد أنهما يتفقان أي‬\n     ‫محــرره شــخص واحــد‪ .‬انتهــى الفاحصــون رقيــب ‪  ..................../‬رئيــس‬\n\n\n‫‪97‬‬\n\f  ‫شــعبة الفحــوص الفنيــة ‪ ..............‬أه ـ وحيــث احلــال ماذكــر فقــد أفهمت‬\n  ‫املدعــي بــأن عليــه اليمــن تقويــة جلانبــه واليمــن علــى أنــه لــم يســتلم املبلــغ‬\n  ‫ا واهلل العظيــم الــذي ال‬      ‫املذكــور فاســتعد بــأداء اليمــن ثــم حلــف قائ ـ ً‬\n  ‫الــه إال هــو عالــم الغيــب والشــهادة أنــه بقــي لــي بذمــة املدعــي عليــه مــن‬\n  ‫الســند الــذي حــرره لــي أربعــة وثالثــون ألف ـ ًا وأربعمائــة ريــال وأربعمائــة‬\n  ‫ريــال وواهلل العظيــم أننــي لــم أســتلم منــه شــيئا إلــى تاريخــه هكــذا‬\n  ‫حلــف فبنــاء علــي مــا تقــدم مــن الدعــوي واإلجابــة وبنــاء علــي مــا جــاء‬\n  ‫بعقــد اإليجــار وماجــاء باإلقــرار املذكــور وبنــاء علــي ماجــاء بتقريــر‬\n  ‫األدلــة اجلنائيــة وحيــث أدى املدعــي اليمــن الشــرعية تقويــة جلانبــه وعلــى‬\n  ‫عــدم اســتالمه املبلــغ املذكــور فقــد حكمــت علــي املدعــي عليــه الغائب‬\n  ‫‪  .............‬بدفــع املبلــغ املدعــي بــه وقــدره أربعــة وثالثــون ألف ـ ًا وأربعمائــة‬\n  ‫ريــال للمدعــي هــذا مــا حكمــت بــه فليعلــم وقــررت بعــث صــورة مــن‬\n  ‫احلكــم للمدعــي عليــه إلبــداء قناعتــه باحلكــم مــن عدمهــا حســب‬\n  ‫املتبــع  وضبــط يف الضبــط املفتــوح جلــد ‪ 10/52‬لعــام ‪1431‬ه ـ صفحــة‬\n              ‫‪121‬وصلــي اهلل علــي نبينــا محمــد وعلــي آلــه وصحبــه وسـ ـ ـ ــلم‬\n  ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد  املوافــق ‪ 1434/11/23‬ه ـ فقــد‬\n  ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة باخلطــاب‬\n  ‫رقــم‪ 34872890‬يف‪ 1434/11/06‬ه ـ وبرفقهــا الصــك الصــادر منــا‬\n  ‫برقــم ‪ 34293027‬يف ‪ 1434/08/09‬ه ـ ومظهــر عليــه بالقــرار رقــم‬\n  ‫‪ 34346223‬يف ‪ 1434/11/02‬ه ـ الصــادر مــن الدائــرة احلقوقيــة‬\n  ‫اخلامســة  املتضمــن املوافقــة علــى احلكــم واهلل املوفــق‪ .‬قاضــي اســتئناف‬\n‫‪ .....................‬ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ‪  ...........................‬‬\n  ‫ختمــه وتوقيعــه  ‪ ،‬رئيــس الدائــرة ‪  .....................‬ختمــه وتوقيعــه ‪ .‬وصلــى‬\n\n\n                                                                                                ‫‪98‬‬\n\f                         ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ‬\n     ‫فقــد جــرى م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة‬\n     ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى‬\n     ‫هــذا احلكــم الصــادر مــن فضيلــة الشــيخ ‪   ................... /‬القاضــي‬\n     ‫يف احملكمــة العامــة باملدينــة املنــورة   املســجل بعــدد ‪34254640‬‬\n     ‫وتاريخ‪1434/6/28‬ه ـ املتضمــن دعــوى ‪ ................... /‬ضــد ‪..................‬‬\n     ‫الغائــب عــن مجلــس احلكــم ‪ ،‬احملكــوم في ــه مبــا دون باطــن الصــك ‪،‬‬\n     ‫وبدراســة احلكــم وص ــورة ضبط ــه تقــرر املوافقــة علــى احلكــم والغائــب‬\n     ‫علــى حجتــه إذا حضــر ‪ .‬وبــاهلل التوفيــق‪  ،‬وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                              ‫وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":92,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2967fd2523fefdf7fb6df0bfd582b73a3a49d78067ac627fc699d3081a3ea8f4","normalized_text_hash":"9a6dd15b652fcafbe24159c80827495b05b01b2ba39674bfef19c3e50820b73f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p92-34254640"},{"id":"3aee44c8-8073-54f2-90b9-ad4a35cbff62","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -عقد -مطالبة بفسخ العقد وإخاء العقار لعدم إلتزام املستأجر بشروط العقد -إقرار املدعى عليه بعدم دفع األجرة املستحقة يف موعدها -والدفع بالقيام بإصالحات بإذن املؤجر واملطالبة بحسمها من األجرة املستحقة -إلزام املدعى عليه باإلخاء وصرف النظر عن طلبه احلسم لعدم ثبوت إذن املؤجر","document_number":"33286548","case_number":"17043","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/8","year":"1434","subject":"إجارة -عقد -مطالبة بفسخ العقد وإخاء العقار لعدم إلتزام املستأجر بشروط العقد -إقرار املدعى عليه بعدم دفع األجرة املستحقة يف موعدها -والدفع بالقيام بإصالحات بإذن املؤجر واملطالبة بحسمها من األجرة املستحقة -إلزام املدعى عليه باإلخاء وصرف النظر عن طلبه احلسم لعدم ثبوت إذن املؤجر","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/8:‬هـ   ‬\n                   ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33286548 :‬‬\n                        ‫َر ْق ُم الدعوى‪17043 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 3430181‬تاريخه‪1434/2/5:‬هـ‬\n\n\n‫إجــارة ‪ -‬عقــد‪ -‬مطالبــة بفســخ العقــد وإخــاء العقــار لعــدم إلتــزام‬\n‫املســتأجر بشــروط العقــد ‪ -‬إقــرار املدعــى عليــه بعــدم دفــع األجــرة‬\n‫املســتحقة يف موعدهــا ‪ -‬والدفــع بالقيــام بإصالحــات بــإذن املؤجــر‬\n‫واملطالبــة بحســمها مــن األجــرة املســتحقة ‪ -‬إلــزام املدعــى عليــه‬\n‫باإلخــاء وصــرف النظــر عــن طلبــه احلســم لعــدم ثبــوت إذن املؤجــر‬\n                                                           ‫علــى احلســم‪.‬‬\n\n\n\n\n‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه اســتأجر منهــا دورا ملــدة ثــاث‬\n‫ســنوات بأجــرة معلومــة وقــد ســدد املبلــغ احلــال إال أنهــا تطالبــه بإخــاء‬\n‫الــدور لعــدم قيامــه بســحب البيــارة وعــدم قيامــه بعمــل الســراميك وعــدم‬\n‫انتظامــه بدفــع األجــرة يف وقتهــا احملــدد واقتنائــه احلمــام والدجــاج يف‬\n‫ســطح الــدور وقــد تــأذت منــه وإلزالتــه احلاجــز املوضــوع علــى النافــذة‬\n‫املطلــة علــى فنــاء موكلتــه ‪ -‬أقــر املدعــى عليــه بالعقــد وأنكــر كل‬\n\n                                                                                    ‫‪100‬‬\n\f      ‫موجبــات اإلخــاء وأن الطيــور يف ســطحه ال أذى لهــا عليهــا وأنــه لــم‬\n      ‫يتفــق معهــا علــى وضــع الســراميك لكامــل الــدور ‪ -‬قــرر وكيــل املدعية‬\n      ‫بأنــه لــم يعــد احلاجــز كمــا كان وأن الســراميك كان لكامــل الــدور‬\n      ‫وهــو لــم يقــم إال ببعضــه ‪ -‬قــرر وكيــل املدعــى عليــه بــأن خســر مــا‬\n      ‫يقــارب الثالثــن ألــف ريــال مقابــل اصالحــات ويطالــب بحســمها مــن‬\n      ‫األجــرة ‪ -‬قــرر وكيــل املدعيــة بــأن هــذه االصالحــات لــم تكــن بــإذن‬\n      ‫موكلتــه عــدا الســراميك فقــد حســم لــه مــن األجــرة ألجلهــا ‪ -‬أحضــر‬\n      ‫املدعــي وكالــة شــاهدا شــهد بأنــه الــدور اســتؤجر عــن طريقــه وقــد‬\n      ‫جــرى تخفيــض األجــرة مقابــل قيــام املدعــى عليــه بعمــل الســراميك‬\n      ‫والتعتيــق ويكــون للمؤجــر حــق الفســخ إذا تأخــر عــن دفــع األجــرة ‪ -‬لــم‬\n      ‫يطعــن املدعــى عليــه بشــهادة الشــاهد بشــيء ‪ -‬أحضــر املدعــي وكالــة‬\n      ‫البينــة علــى عدالــة شــاهده ‪ -‬جــرى ســؤال وكيــل املدعــى عليــه البينــة‬\n      ‫علــى دفعــه بــأن االصالحــات كانــت بــإذن املدعيــة فقــرر بــأال بينــة لديــه‬\n      ‫فأفهمــه بــأن ملوكلــه طلــب ميــن املدعيــة إال أن وكالتــه ال تخولــه تقريــر‬\n      ‫طلبهــا مــن عدمــه وأن علــى موكلــه احلضــور أو احضــار وكالــة تخولــه‬\n      ‫طلبهــا ‪ -‬جــرى االطــاع علــى وثيقــة العقــد وقــد ظهــر فيهــا أن للمدعيــة‬\n      ‫خيــار الفســخ إذا تأخــر املســتأجر عــن الســداد أو ازعــاج اجليــران ويف‬\n      ‫اجلانــب األميــن مــن العقــد دون بأنــه جــرى تخفيــض األجــرة مقابــل‬\n      ‫تركيــب الســراميك ‪ -‬أقــر وكيــل املدعــى عليــه بــأن موكلــه تأخــر‬\n      ‫يف ســداد األجــرة ‪ -‬فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ومبــا أن‬\n      ‫عقــد اإليجــار نــص علــى فســخ العقــد يف حالــة التأخــر يف تســديد األجــرة‬\n      ‫وأذى اجليــران ومبــا أن املدعــى عليــه وكالــة أقــر بتوقفــه عــن دفع األجرة‬\n      ‫وهــو مخــول باإلقــرار يف الوكالــة وألن املدعــى عليــه وكالــة يشــغل‬\n\n\n‫‪101‬‬\n\f‫العقــار حتــى اآلن وذكــر املدعــى عليــه أن عقــد اإليجــار ســا ٍر ومبــا أن‬\n‫املدعــى عليــه طالــب بخصــم اإلصالحــات مــن ثمــن األجــرة وألنــه ذكــر‬\n‫يف العقــد أنــه جــرى تخفيــض األجــرة مقابــل تركيــب الســيراميك وألن‬\n‫املدعــي وكالــة أنكــر موافقــة موكلتــه علــى قيــام املدعــى عليــه أصالــة‬\n‫باإلصالحــات وألن املدعــى عليــه لــم يحضــر بينــة ولــم يخــول وكيلــه‬\n‫طلــب اليمــن ولــم يحضــر ليقــرر هــل يطلــب اليمــن أم ال وملصادقــة‬\n‫املدعــى عليــه علــى عقــد اإليجــار لــذا فقــد صــدر احلكــم بإلــزام املدعــى‬\n‫عليــه أصالــة بإخــاء العقــار املســتأجر وتســليمه للمدعيــة أصالــة عــن‬\n‫طريــق احلقــوق املدنيــة وصــرف النظــر عــن طلبــه خصــم اإلصالحــات‬\n‫التــي ذكرهــا مــن قيمــة اإليجــار ‪ -‬بعــرض احلكــم علــى املدعــى عليــه‬\n‫وكالــة قــرر عــدم القناعــة فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 17043‬وتاريــخ ‪1431/04/05‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3156358‬وتاريــخ ‪1431/04/01‬ه ـ ففــي يــوم الثالثاء‬\n‫املوافق‪1431/08/29‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 57‬وفيهــا حضــر‬\n‫‪ ...............‬ســجل رقــم ‪ ....................‬بالوكالــة عــن  ‪ .................‬مبوجــب‬\n‫الوكالــة رقــم ‪ 9861‬يف ‪ 1428/02/15‬ه ـ الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بجنــوب الريــاض وحضــر حلضــوره ‪ ................‬ســجل رقــم‬\n‫‪ .......................‬وادعــى األول بقولــه لقــد اســتأجر املدعــى عليــه مــن‬\n                                                                                              ‫‪102‬‬\n\f      ‫موكلتــي دورا علويــا يف الفلــة الواقعــة بحــي ‪ ...............‬بالقــرب مــن‬\n      ‫شــارع ‪ ........‬بتاريــخ ‪ 1430/06/01‬ه ـ ملــدة ثــاث ســنوات بأجــرة ســنوية‬\n      ‫قدرهــا واحــد وعشــرون ألــف ريــال وقــد ســدد املبلــغ احلــال وموكلتــي‬\n      ‫تطلــب إلزامــه بفســخ العقــد وإخــاء العقــار وذلــك إلخاللــه بشــروط‬\n      ‫العقــد التاليــة ‪ -1 :‬عــدم ســحب البيــارة ‪ -2‬عــدم قيامــه بعمــل ســيراميك‬\n      ‫لكامــل الــدور كمــا هــو متفــق عليــه  ‪ -3‬عــدم ســداده االيجــار يف وقتــه‬\n      ‫‪ -4‬وجــود حمــام ودجــاج يف ســطح الفلــة وقــد تــأذت منــه موكلتــي ‪-5‬‬\n      ‫كمــا أنــه قــام بإزالــة احلاجــز املوضــوع علــى النافــذة التــي تطــل علــى فنــاء‬\n      ‫تابــع ملوكلتــي هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه كلــه غيــر صحيــح‬\n      ‫مــا عــدا وجــود احلمــام والدجــاج ولكــن ليــس فيــه أذى علــى موكلتــه‬\n      ‫أمــا ســحب البيــارة فقــد قمــت بذلــك مرتــن أو ثــاث وأمــا الســيراميك‬\n      ‫فاملتفــق عليــه كان علــى الصالــة وقــد عملــت وأمــا احلاجــز فقــد كســر‬\n      ‫بســبب لعــب األوالد وقــد أعدتــه كمــا كان وأنــا غيــر مســتعد بإخــاء‬\n      ‫العقــار وبعــرض ذلــك علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه‬\n      ‫مــن أنــه أعــاد احلاجــز فصحيــح ولكنــه لــم يعــده كمــا كان ومــا ذكــره‬\n      ‫مــن أن االتفــاق علــى الســيراميك علــى الصالــة فقــط فغيــر صحيــح‬\n      ‫والصحيــح أن املتفــق عليــه للــدور كامــا وهــو منصــوص عليــه يف العقــد‬\n      ‫فجــرى ســؤال املدعــى عليــه هــل لديــه بينــة علــى أن املتفــق عليــه هــو‬\n      ‫عمــل الســيراميك للصالــة فقــط فقــال نعــم وســوف أحضرهــا يف اجللســة‬\n      ‫القادمــة وعليــه رفعــت اجللســة وحــدد لهــا موعــد يــوم الثالثــاء املوافــق‬\n      ‫‪ 1431/11/04‬ه ـ الســاعة ‪ 09,30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1431/08/29‬ه ـ احلمــد هلل‬\n\n\n‫‪103‬‬\n\f  ‫وحــده وبعــد ففــي يــوم الثالثــاء  املوافــق ‪1431/11/4‬ه ـ أفتتحــت اجللســة‬\n  ‫الســاعة ‪  09 : 52‬وفيهــا حضــر املتداعيــان ويف هــذه اجللســة قــال املدعــى‬\n  ‫عليــه بــأن الــدور مت عمــل ســراميك لــه وأطلــب خــروج جلنــه عليــه وعليــه‬\n  ‫فقــد رفعــت اجللســة للكتابــة لهيئــة النظــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1431/11/4‬ه ـ‬\n  ‫احلمد هلل وحده وبعد ففي يوم االربعاء املوافق ‪1432/9/10‬هـ أفتتحت‬\n  ‫اجللســة الســاعة ‪  01 : 15‬وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره‬\n  ‫ا عــن ‪..........................‬‬\n                                  ‫‪ ...................‬ســجل رقــم ‪ ....................‬وكي ـ ً‬\n  ‫مبوجــب الوكالــة رقــم ‪ 76581‬يف ‪1432/9/8‬ه ـ الصــادرة مــن كتابــة‬\n  ‫العــدل الثانيــة بجنــوب الريــاض وفيهــا وردنــا قــرار هيئــة اخلبــراء رقــم‬\n  ‫‪ 1/633‬وتاريــخ ‪1432/5/2‬ه ـ واملتضمــن فقــد مت الوقــوف علــى محــل‬\n  ‫النــزاع بحضــور الطرفــن وهــو عبــارة عــن دور ثانــي يف فلــة املدعيــة‬\n  ‫وقــد قــام املدعــى عليــه بوضــع بــاط ســيراميك لكامــل الــدور ماعــدا‬\n  ‫غرفتــن وممــر بينهمــا حيــث أن بهــا فرشــة أرضيــة ونقــدر أن الــذي وضــع‬\n‫الســيراميك فيــه يعــادل ثالثــة أربــاع مســاحة الــدور هــذا مالدينــا أ ‪ .‬هــ  ‬\n  ‫ويف هــذه اجللســة قــال املدعــى عليــه وكالــة إن التهميــش املوضــوع علــى‬\n  ‫عقــد اإليجــار واخلــاص بالســيراميك لــم يكــن مبوافقــة موكلــي كمــا‬\n  ‫أن موكلــي قــد عمــل إصالحــات يف الــدور كلفــت ثالثــن ألــف يطلــب‬\n  ‫خصمهــا مــن اإليجــار فجــرى ســؤاله عــن نــوع اإلصالحــات وهــل كانــت‬\n  ‫بإتفــاق مــع املدعــي فقــال ســوف أســأل موكلــي ورفعــت اجللســة وحــدد‬\n  ‫لهــا موعــد يــوم االثنــن املوافــق ‪1432/11/19‬ه ـ الســاعة ‪ 9.30‬وبــاهلل‬\n  ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                               ‫حــرر يف ‪1432/9/10‬ه ـ‬\n\n\n                                                                                                 ‫‪104‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1432/11/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 35‬وفيهــا حضــر املتداعيــان ويف هــذه‬\n      ‫اجللســة جــرى ســؤال املدعــى عليــه وكالــة عمــا طلــب فيــه اإلمهــال‬\n      ‫فقــدم مذكــرة هــذا نصهــا إشــارة إلــي طلــب فضيلتكــم باجللســة‬\n      ‫الســابقة حتديــد أعمــال اإلصالحــات التــي قــام بهــا موكلنــا املدعــى‬\n      ‫عليــه ‪ ................. /‬بعقــار املدعيــة ‪ .................. /‬ويطلــب إلــزام املدعيــة‬\n      ‫بتكاليــف تلــك األعمــال فقــد أفادنــي موكلــي أن تلــك األعمــال هــي‬\n      ‫كاآلتــي ‪ :‬إصالحــات احلمــام اخلــاص بالقســم الصغيــر بتكلفــة ‪350‬‬\n      ‫ريــال وفتــح بــاب خارجــي مــع شــراء البــاب وتركيبــه بتكلفــة ‪500‬‬\n      ‫ريــال وبــاب قاطــع للقســم اخلــاص بالنســاء ‪ 220‬ريــال وبــاب عــازل‬\n      ‫لغــرف النــوم ‪ 220‬ريــال وأجــرة تركيــب األبــواب املشــار إليهــا وإصــاح‬\n      ‫تلفيــات األبــواب القدميــة بتكلفــة ‪ 400‬ريــال وتركيــب مجلــى إيطالــي‬\n      ‫‪ 370‬ريــال وتعتيــق الســيب املوصــل بــن قســم الرجــال والنســاء ســعر‬\n      ‫املتــر ‪ 10‬ريــال الكميــة وتعتيــق مقلــط الرجــال مــع بويــة الســقف ســعر‬\n      ‫املتــر ‪ 10‬ريــال بتكلفــة إجماليــة وشــراء ســيراميك ســعر املتــر ‪ 14‬ريــال‬\n      ‫إجمالــي وتركيــب الســيراميك ســعر تركيــب املتــر ‪ 10‬ريــال إجمالــي‬\n      ‫وعــدد متــر نعلــه ســعر املتــر ‪ 5‬ريــال ‪ +‬تركيــب ‪ 2‬ريــال للمتــر ليكــون‬\n      ‫إجمالــي مــا تكلفــه موكلــي ويطلــب إلــزام املدعيــة بــه مــا تقــرره اللجنــة‬\n      ‫املختصــة إضافــة إلــى ذلــك تقديــر أجــرة الســيارة تقديــر أجــرة ملوكلــي‬\n      ‫عــن قيامــه بتلــك األعمــال و وقوفــه مــع العمــال وإحضــار األغــراض علمـ ًا‬\n      ‫أن جميــع تلــك اإلصالحــات متــت مبعرفــة املدعيــة يثبــت ذلــك العقــد‬\n      ‫املوقــع مــن الطرفــن نطلــب مــن فضيلتكــم إحالتهــا إلــي هيئــة اخلبــراء‬\n      ‫لتقديــر اإلصالحــات ا‪.‬ه ـ وبعرضهــا علــى املدعــي وكالــة قــال مــا‬\n\n\n‫‪105‬‬\n\f‫ذكــره املدعــى عليــه مــن إصــاح احلمــام وتلفيــات األبــواب القدميــة فأنــا‬\n‫مــن قــام بذلــك وأمــا بخصــوص فتــح البــاب اخلارجــي وبــاب قاطــع لقســم‬\n‫النســاء وبــاب عــازل لغــرف النــوم وأجــرة تركيبهــا واملجلــى فجميعهــا‬\n‫لــم نــأذن لــه فيهــا وأمــا بخصــوص التعتيــق والســيراميك فقــد اســتعد‬\n‫هــو بذلــك عنــد اســتئجاره للــدور وقــد أنقــص يف أجــرة الــدور مقابــل‬\n‫ذلــك هكــذا ذكــر وبعرضــه علــى املدعــى عليــه وكالــة قــال الصحيــح‬\n‫مــا ذكرتــه ولــدي البينــة عليــه وســوف أحضرهــا يف اجللســة القادمــة‬\n‫وبســؤال املدعــي هــل لديــه بينــة علــى دفعــه قــال نعــم وســوف أحضرهــا‬\n‫يف اجللســة القادمــة وعليــه رفعــت اجللســة وحــدد لهــا موعــد يــوم االربعــاء‬\n‫‪1432/1/19‬ه ـ وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/11/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء  املوافــق ‪ 1433/01/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪  08 : 40‬وفيهــا حضــر املتداعيــان وفيهــا‬\n‫أحضــر املدعــي وكالــة شــاهدا هــو ‪ .................‬ســجل رقــم ‪..................‬‬\n‫واملولــود يف ‪1383‬ه ـ ويســكن الريــاض وال يوجــد صلــة قرابــة والــذي‬\n‫شــهد بقولــه إننــي صاحــب املكتــب العقــاري الــذي مت اســتئجار الــدور‬\n‫عــن طريقــه وقــد حصــل االتفــاق بينهــم عنــد االســتئجار بأن يتــم تخفيض‬\n‫مقــدار األجــرة إلــى واحــد وعشــرين ألــف ريــال ســنويا ملــدة ثــاث ســنوات‬\n‫مقابــل قيــام املســتأجر بأعمــال الســيراميك والتعتيــق ويكــون للمؤجــر‬\n‫حــق فســخ العقــد عنــد تأخــر املســتأجر يف دفــع األجــرة هكــذا شــهد‬\n‫وبســؤال املدعــي هــل لديــه زيــادة بينــة قــال ال يوجــد لــدي بينــة هكــذا‬\n‫ذكــر فجــرى عــرض الشــاهد علــى املدعــى عليــه وكالــة فقــال ال أقــول‬\n‫فيــه شــيئا فطلبــت مــن املدعــي تزكيــة شــاهدة فاســتعد بذلــك ورفعــت‬\n\n\n                                                                                        ‫‪106‬‬\n\f      ‫اجللســة وحــدد لهــا موعــد يف يــوم األربعــاء ‪1433/3/9‬ه ـ الســاعة ‪09.15‬‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف  ‪ 1433/01/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪ 1433/03/09‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪  09 : 50‬وفيهــا حضــر املتداعيــان وأحضــر‬\n      ‫املدعــي وكالــة تزكيــة لشــاهده وهمــا ‪ ...................‬مصــري اجلنســية‬\n      ‫يحمــل إقامــة رقــم …………… و ‪ ...............‬مصــري اجلنســية يحمــل‬\n      ‫إقامــة رقــم ‪ .................‬وقــد شــهدا بعدالــة الشــاهد وبســؤال املتداعيــن‬\n      ‫هــل لديهمــا مــا يرغبــان يف إضافتــه قــال املدعــى عليــه وكالــة ال وقــال‬\n      ‫املدعــي وكالــة نعــم أرغــب إفهــام املدعــى عليــه وكالــة بــأن موكلتــي ال‬\n      ‫ترغــب يف جتديــد العقــد الــذي ينتهــي يف ‪ 1433/05/30‬ه ـ مــع مطالبتنا‬\n      ‫باإلخــاء قبــل هــذه املــدة فجــرى إفهــام املدعــى عليــه وكالــة بذلــك‬\n      ‫إلبــاغ موكلــه بــه عنــد ذلــك جــرى إفهــام املتداعيــن بأنــه قــد مت إقفــال‬\n      ‫بــاب املرافعــة ورفعــت اجللســة لذلــك وحــدد لهــا موعــد يــوم األربعــاء‬\n      ‫املوافــق ‪1433/3/30‬ه ـ الســاعة ‪ 09.15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/03/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم  األربعــاء املوافــق ‪ 1433/03/30‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪  09 : 17‬وفيهــا حضــر املتداعيــان وكالــة‬\n      ‫ويف هــذه اجللســة جــرى ســؤال املدعــى عليــه وكالــة هــل لــدى موكلــه‬\n      ‫بينــة علــى أن اإلصالحــات كانــت بــإذن مــن املدعيــة فقــال ال يوجــد‬\n      ‫بينــة ســوى التذييــل الــذي علــى عقــد اإليجــار والــذي ســبق أن ذكــره‬\n      ‫املدعــي وكالــة عنــد ذلــك أفهمتــه أن ملوكلــه ميــن املدعيــة وباالطــاع‬\n      ‫علــى وكالتــه وجدتهــا ال تخولــه اجلــواب عــن ذلــك فأفهمتــه بأنــه البــد‬\n\n\n‫‪107‬‬\n\f‫مــن إضافــة طلــب اليمــن و ردهــا يف الوكالــة أو حضــور موكلــه وعليــه‬\n‫رفعــت اجللســة وحــدد لهــا موعــد يــوم األربعــاء املوافــق ‪ 1433/06/04‬ه ـ‬\n‫الســاعة ‪ 09.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1433/03/30‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ...................‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض خلــف الشــيخ ‪ ..................‬وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪17043‬‬\n‫وتاريــخ ‪ 1431/04/05‬هــ  املقيــدة باحملكمــة برقــم ‪ 3156358‬وتاريــخ‬\n‫‪ 1431/04/01‬هــ  ففــي يــوم  األربعــاء املوافق‪ 1433/06/04‬هـ افتتحت‬\n‫اجللســة الســاعة ‪  09 : 44‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وكالــة ‪ ....................‬املذكوريــن أعــاه وبســؤال املدعــى عليــه وكالــة‬\n‫عمــا طلــب منــه يف اجللســة املاضيــة قــال إن موكلــي غيــر موجــود يف‬\n‫الريــاض وهــو مجــاز مــن عملــه وقــد أخبرنــي بأنــه يطلــب منكــم احلكــم‬\n‫يف القضيــة أو حتديــد جلســة أخــرى ليحضــر فيهــا ويقــرر مــا لديــه وقــد‬\n‫أبــرز املدعــي وكالــة نســخة كربونيــة لعقــد إيجــار صــادر مــن مكتــب‬\n‫‪ ...‬للعقــارات برقــم ‪ 144‬يف ‪1430/6/1‬ه ـ اســتئجار املدعــى عليــه أصالــة‬\n‫دور علوي عوائل يقع يف حي ‪ ............‬الغربي بأجرة سنوية قدرها واحد‬\n‫وعشــرون ألــف ريــال ملــدة ثــاث ســنوات طريقــة الدفــع دفعــة كل ســتة‬\n‫أشــهر وقدرهــا عشــرة آالف وخمســمائة ريــال ثــم ذكــرت شــروط العقــد‬\n‫و جــاء يف فقــرة املالحظــة مــا نصــه يحــق للمالــك فســخ العقــد وخــروج‬\n‫املســتأجر يف حالــة التأخيــر عــن تســديد اإليجــار أو إزعــاج اجليــران ويف‬\n‫اجلانــب األميــن مــن العقــد كتــب مــا نصــه مت تنزيــل اإليجــار مببلــغ قــدره‬\n‫واحــد وعشــرون ألــف ريــال ســنوي مقابــل تركيــب الســيراميك للــدور‬\n\n\n                                                                                         ‫‪108‬‬\n\f        ‫العلــوي ويف اجلانــب األيســر منــه عبــارة نصها ســباكة احلمامات واملطبخ‬\n        ‫والكهربــاء علــى املالــك كذلــك جــاء يف الفقــرة العاشــرة مــن الشــروط‬\n        ‫يف حالــة تأخــر املســتأجر عــن دفــع الدفعــة املســتحقة يحــق للمالــك فســخ‬\n        ‫العقــد وخروجــه عــن طريــق اجلهــات املختصــة ثــم يف أســفل العقــد توقيــع‬\n        ‫منســوب للطــرف األول ‪ ..............‬والطــرف الثانــي ‪ ................‬عنــه ابنــه‬\n        ‫‪ ..............‬وختــم املكتــب‪ .‬وبعــرض هــذا العقــد علــى املدعى عليه وكالة‬\n        ‫قــال هــذا هــو العقــد بــن موكلــي واملدعــي أصالــة وقــال املدعــي وكالــة‬\n        ‫إن املدعــى عليــه أصالــة لــم يســدد اإليجــار مــن ‪1431/12/1‬ه ـ حتــى‬\n        ‫اآلن وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال نعــم إن موكلــي لــم‬\n      ‫يدفــع األجــرة مــن ‪1431/12/1‬ه ـ علمــا أن موكلــي الزال يشــغل العقــار  ‬\n        ‫وعقــد اإليجــار كان ســاريا فبنــاءا علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n        ‫ومبــا أن عقــد اإليجــار املشــار إليــه أعــاه نــص علــى فســخ العقــد يف حالــة‬\n        ‫التأخــر يف تســديد األجــرة و أذى اجليــران ومبــا أن املدعــى عليــه وكالــة‬\n        ‫أقــر بعــدم دفــع موكلــه األجــرة مــن تاريــخ ‪1431/12/1‬ه ـ وهــو مخــول‬\n        ‫باإلقــرار يف الوكالــة ومبــا أن املدعــى عليــه وكالــة يشــغل العقــار‬\n        ‫حتــى اآلن وذكــر املدعــى عليــه أن عقــد اإليجــار ســا ٍر ومبــا أن املدعــى‬\n        ‫عليــه طالــب بخصــم اإلصالحــات مــن قيمــة األجــرة ومبــا أنــه ذكــر يف‬\n        ‫العقــد أنــه جــرى تخفيــض األجــرة مقابــل تركيــب الســيراميك ومبــا أن‬\n        ‫املدعــي وكالــة أنكــر موافقــة موكلتــه علــى قيــام املدعــى عليــه أصالــة‬\n        ‫باإلصالحــات ومبــا أن املدعــى عليــه لــم يحضــر بينــة ولــم يخــول وكيلــه‬\n        ‫طلــب اليمــن ولــم يحضــر ليقرر هل يطلب اليمني أم ال وملصادقة املدعى‬\n        ‫عليــه علــى عقــد اإليجــار لــذا فقــد ألزمــت املدعــى عليــه أصالــة بإخــاء‬\n        ‫العقــار املســتأجر وتســليمه للمدعيــة أصالــة عــن طريــق احلقــوق املدنيــة‬\n\n\n‫‪109‬‬\n\f‫وصرفــت النظــر عــن طلبــه خصــم اإلصالحــات التــي ذكرهــا مــن قيمــة‬\n‫اإليجــار وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب‬\n‫االســتئناف بالئحــة اعتراضيــة فجــرى إفهامــه مبراجعــة احملكمــة يــوم‬\n‫األحــد ‪1433/6/8‬ه ـ الســتالم نســخة مــن احلكــم وتقــدمي اعتراضــه‬\n‫عليــه خــال ثالثــن يومــا مــن تاريــخ اســتالمها وأنــه إذا انتهــت املــدة ولــم‬\n‫يقــدم اعتراضــه خاللهــا  ســقط حقــه يف االســتئناف واكتســب احلكــم‬\n‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1433/06/04‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/3/25‬ه ـ‬\n‫فتحــت اجللســة وفيهــا حضــر املدعــي وكالــة وقــد وردت املعاملــة‬\n‫مــن محكمــة االســتئناف مرفقــا بهــا القــرار رقــم ‪ 3430181‬يف‬\n‫‪1434/2/5‬ه ـ املــدون علــى ظهــر الصــك املتضمــن أنــه لــم يظهــر مــا‬\n‫يوجــب االعتــراض علــى احلكــم مــع تنبيــه فضيلتــه بإفهــام املدعــي بــأن‬\n‫لــه حــق املطالبــة فيمــا ورد يف الئحتــه االعتراضيــة زائــدا علــى اإلخــاء‬\n‫واهلل املوفــق وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/03/25‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n‫‪ 3156358‬وتاريــخ ‪1433/12/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــه القاضــي باحملكمــة الشــيخ‪ ...................../‬املســجل برقــم‬\n‫‪ 33286548‬وتاريــخ ‪1433/6/8‬ه ـ اخلــاص بدعــوى‪.................../‬‬\n‫وكالــة ضــد‪ ............../‬بشــأن خــاف يف عقــار علــى الصفــة املوضحــة‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫بالصــك واملتضمــن حكــم فضيلتــه كمــا هــو موضــح يف الصــك‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫لــم يظهــر مايوجــب االعتــراض علــى احلكــم مــع تنبيــه فضيلتــه بــا فهــام‬\n      ‫املدعــي بــأن لــه حــق املطالبــة فيمــا ورد يف الئحتــه االعتراضيــة زائــدا‬\n      ‫علــى اإلخــاء‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                              ‫وســلم‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":100,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d1e473a5d29df886f526a9e657266945139ea38d5cd4023dab89dc00427aae20","normalized_text_hash":"6a689ece6153479841b1e61168027cec89a79cfb14c8d14bbfa1996a69d01422","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p100-33286548"},{"id":"609cf8b1-4a23-5881-8e50-9d8bfb4099b4","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -صيانة -استئجار املدعي عدة شاليهات من الشركة املدعى عليها ملدة معينة -االتفاق على قيام الشركة بأعمال الصيانة للشاليهات ودفع املدعي مقابل الصيانة -مطالبة الشركة بفسخ العقد قبل نهاية املدة -موافقة املدعي على الفسخ واإلخاء مقابل رد املبالغ التي أنفقها والتعويض عن األرباح املتوقعة باقي مدة العقد -دفع املدعي بوجود مخالصة ببراءة ذمته جتاه الشركة املدعى عليها -قيام القرينة على إقرار املدعي باملخالصة -صرف","document_number":"3416698","case_number":"3311858","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/19","year":"1434","subject":"إجارة -صيانة -استئجار املدعي عدة شاليهات من الشركة املدعى عليها ملدة معينة -االتفاق على قيام الشركة بأعمال الصيانة للشاليهات ودفع املدعي مقابل الصيانة -مطالبة الشركة بفسخ العقد قبل نهاية املدة -موافقة املدعي على الفسخ واإلخاء مقابل رد املبالغ التي أنفقها والتعويض عن األرباح املتوقعة باقي مدة العقد -دفع املدعي بوجود مخالصة ببراءة ذمته جتاه الشركة املدعى عليها -قيام القرينة على إقرار املدعي باملخالصة -صرف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/19 :‬هـ   ‬\n                         ‫ُ‬               ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3416698:‬‬\n                           ‫َر ْق ُم الدعوى‪3311858 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‬\n                 ‫‪  34324644:‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬صيانــة‪ -‬اســتئجار املدعــي عــدة شــاليهات مــن الشــركة املدعــى‬\n      ‫عليهــا ملــدة معينــة‪ -‬االتفــاق علــى قيــام الشــركة بأعمــال الصيانــة‬\n      ‫للشــاليهات ودفــع املدعــي مقابــل الصيانــة‪ -‬مطالبــة الشــركة بفســخ‬\n      ‫العقــد قبــل نهايــة املــدة‪ -‬موافقــة املدعــي علــى الفســخ واإلخــاء مقابــل‬\n      ‫رد املبالــغ التــي أنفقهــا والتعويــض عــن األربــاح املتوقعــة باقــي مــدة‬\n      ‫العقــد‪ -‬دفــع املدعــي بوجــود مخالصــة ببــراءة ذمتــه جتــاه الشــركة‬\n      ‫املدعــى عليهــا‪ -‬قيــام القرينــة علــى إقــرار املدعــي باملخالصــة‪ -‬صــرف‬\n                                                     ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول ابــن رجــب احلنبلــي رحمــه اهلل يف جامــع العلــوم واحلكــم ص‬\n      ‫‪»:316‬وقــد كان شــريح وإيــاس بــن معاويــة يحكمــان يف األمــوال املتنــازع‬\n      ‫فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعيــن ‪ ..‬وكان‬\n      ‫يقضــي بنحــو ذلــك أبوبكــر الشــامي مــن الشــافعية ورجــح قولــه ابــن‬\n                                                                   ‫عقيــل مــن أصحابنــا»‪.‬‬\n      ‫‪ -2‬املــادة (‪ )155‬مــن نظــام املرافعــات الشــرعية ونصها‪»:‬يجــوز للقاضــي‬\n      ‫أن يســتنتج قرينــة‪ ،‬أوأكثــر مــن وقائــع الدعــوى‪ ،‬أو ُمناقشــة اخلصــوم‬\n      ‫ا ناقص ـ ًا ثبــت‬‫ليكمِ ــل ِبهــا دلي ـ ً‬\n                                             ‫حلكمِ ــه أو ُ‬\n                                                         ‫أو الشــهود؛ لتكــون ُمســتند ًا ُ‬\n              ‫احلكــم»‪.‬‬\n                     ‫لديــه ليك ـ ِّون بهمــا مع ـ ًا اقتناعــه بثبــوت احلــق إلصــدار ُ‬\n\n‫‪125‬‬\n\f‫أقــام املدعــي دعــواه ضــد الشــركة املدعــى عليهــا بأنــه اســتأجر منهــا‬\n‫عــدة شــاليهات ملــدة عشــر ســنوات علــى مبلــغ معلــوم لديهمــا‪ ،‬كمــا‬\n‫اتفقــا علــى قيــام الشــركة بعمــل صيانــة لهــذه الشــاليهات مقابــل دفــع‬\n‫املدعــي مبلــغ معــن إال أن الشــركة لــم تقــم بالعمــل املطلــوب كمــا‬\n‫أنهــا وقبــل نهايــة الســنة األولــى مبــا لهــا مــن حــق خيــار الفســخ املثبــت‬\n‫بأحــد بنــود العقــد طلبــت فســخ العقــد‪ ،‬وافــق املدعــي علــى الفســخ‬\n‫وإخــاء الشــاليهات شــريطة إعــادة املبالــغ التــي أنفقهــا (أجــرة وصيانــة‬\n‫وجتهيــزات إضافيــة) والتعويــض عــن األربــاح املتوقعــة باقــي مــدة العقــد‪،‬‬\n‫اتفــق الطرفــان ودي ـ ًا علــى فســخ العقــد واإلخــاء‪ ،‬قامــت الشــركة‬\n‫مبطالبــة املدعــي بســداد مبلــغ ‪ .....‬قيمــة تكاليــف الكهربــاء واملــاء‬\n‫واملفقــودات‪ ،‬أنكــر املدعــي مديونيتــه للشــركة بهــذه املبالــغ عــدا مبلــغ‬\n‫خمســن ألــف ريــال فقــط وقــدم لذلــك «مخالصــة نهائيــة» مطبوعــة علــى‬\n                                ‫ورق الشــركة املدعــى عليهــا تؤكــد قولــه ‪.‬‬\n‫ـاء علــى مــا تقــدم وملــا كان االتفــاق كل ال يتجــزأ‪ ،‬ويف حالــة‬         ‫وبنـ ً‬\n‫عــدم اهتــداء القاضــي للدليــل اليقينــي للحكــم يف الدعــوى يجــوز لــه‬\n‫اســتنتاج قرينــة أو أكثــر مــن وقائــع الدعــوى أو مناقشــة اخلصــوم أو‬\n‫الشــهود لتكــون مســتند ًا حلكمــه أو تكملــة لدليــل ناقــص ثبــت لديــه‬\n‫ليكــون بهمــا معـ ًا اقتناعــه بثبــوت احلــق‪ ،‬كمــا أنــه يحكــم يف األمــوال‬\n‫املتنــازع فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعــن‪،‬‬\n‫وبإعمــال ذلــك علــى الدعــوى املاثلــة ومبــا أنــه لــم يثبــت لــدى احملكمــة‬\n‫أن يف ذمــة الشــركة املدعــى عليهــا حــق مالــي لــذا صرفــت النظــر عــن‬\n\n                                                                                       ‫‪126‬‬\n\f      ‫مطالبــة املدعــي لعــدم اســتحقاقه‪ ،‬وإلــزام املدعــي بســداد مبلــغ خمســن‬\n      ‫ألــف ريــال للشــركة لثبوتهــا لديــه ‪ -‬قــرر املدعــي عــدم القناعــة فأفهــم‬\n                     ‫بالتعليمــات‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ......................‬القاضــي باحملكمــة‬\n      ‫العامــة بالدمــام بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس‬\n      ‫برقــم ‪ 9514‬يف ‪1420/10/22‬ه ـ حضــر ‪ .................‬احلامــل للبطاقــة‬\n      ‫رقــم ‪ ................‬رقــم احلفيظــة ‪ ........‬يف ‪ ......‬الصــادرة مــن ‪ .....‬وحضــر‬\n      ‫حلضــوره ‪ .......................‬احلامــل للبطاقــة رقــم ‪ .................‬رقــم احلفيظــة‬\n      ‫‪ ........‬يف   ‪1403/4/1‬ه ـ الصــادرة مــن الريــاض بالوكالــة عــن‬\n      ‫‪ ........................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‪ .......‬برقــم‬\n      ‫‪ .....‬يف ‪ ......‬اجللد ‪ ......‬وبالوكالة عن ‪ ...............‬و‪ .......................‬مبوجب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل ‪  ......‬برقــم ‪ .....‬يف ‪ .....‬اجللــد ‪.....‬‬\n      ‫وبالوكالــة عــن ‪......................‬و‪ ..................‬و ‪ ....................‬بالوكالــة‬\n      ‫عــن ‪.......................‬و‪ .....................‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل ‪ .....‬برقــم ‪ .....‬يف ‪ .......‬اجللــد ‪ ...‬املخولــة لــه يف املرافعــة‬\n      ‫واملدافعــة واالعتــراض كمــا حضــر ‪ ....................‬احلامــل للبطاقــة رقــم‬\n      ‫……………‪ ..‬رقــم احلفيظــة ‪ 120040‬الصــادرة مــن الريــاض يف‬\n      ‫‪1395/6/19‬ه ـ ومــوكل املدعــى عليــه واحلاضــر ‪......................‬‬\n      ‫واملذكــورون هــم أعضــاء إدارة مجلــس ‪ .............................‬مبوجــب‬\n      ‫محضــر جمعيــة الشــركاء الســابعة عشــر وقــد جــاء يف املــادة ‪ 1/14‬ميثــل‬\n      ‫مجلــس إدارة الشــركة يف عالقاتهــا لــدى الدوائــر احلكوميــة‬\n‫‪127‬‬\n\f‫والشــركات واألفــراد يف املرافعــة واملدافعــة واملخاصمــة واملراجعــة‬\n‫واالعتــراض ‪ ...‬الــخ‪ ،‬وادعــى األول قائــا‪ :‬بأننــي اســتأجرت مــن‬\n‫الشــركة املذكــورة ‪ 60‬وحــدة شــاليه املســماة بشــاليهات ‪.................‬‬\n‫ملــدة عشــر ســنوات بأجــرة ســنوية قدرهــا مليــون ريــال اعتبــارا مــن‬\n‫‪1418/5/30‬ه ـ املوافــق ‪1997/10/1‬م وبعــد اســتئجاري بــدأت‬\n‫الشــركة مبضايقتــي واختــاق األعــذار والزعــم أني مقصــر يف الصيانة‬\n‫وقــد اتفقــت معهــم علــى أن يقومــوا بالصيانــة مقابــل مبلــغ ألفــن ريــال يف‬\n‫الشــهر إال أنهــم لــم يقومــوا بالصيانــة وقصــروا معــي وقبــل نهايــة الســنة‬\n‫األولــى طلبــوا منــي اإلخــاء حيــث طلبــوا منــي ذلــك بشــهرين وبنــاء علــى‬\n‫ذلــك قــد أخليــت الشــاليهات وســلمتها لهــم‪ ،‬وبنــاء علــى ذلــك فإننــي‬\n‫أطالبهــم بإعــادة اإليجــار للســنة األولــى وقــدره مليــون ريــال‪ ،‬وإعــادة‬\n‫قيمــة الصيانــة وقدرهــا اثنــان وعشــرون ألــف وســبعمائة وأربعــة وســبعون‬\n‫ريــال‪ ،‬ثالثــا مطالبتهــم مببلــغ وقــدره تســعة وتســعون ألــف وثمامنائــة‬\n‫وخمســة عشــر ريــال وتفصيلهــا كمــا يلــي‪ :‬ســتة عشــر ألــف وثالثمائــة‬\n‫وتســعة وتســعون ريــال قيمــة جتهيــزات إضافيــة‪ ،‬وثالثــة عشــر ألــف‬\n‫وســبعة وعشــرون ريــال قيمــة دعايــة وإعــان‪ ،‬واثنــا عشــر ألــف نســبة‬\n‫تكلفــة الهواتــف‪ ،‬وأربعــة وأربعــون ألــف وخمســمائة ريــال إيجــار‬\n‫الشــاليه رقــم ‪ ،6‬وثمامنائــة وتســعة وثمانــون ريــال أربــاح التأمــن التعاونــي‬\n‫لعــام ‪97‬و ‪ ،98‬وألــف وســبعمائة ريــال إصــاح الزجــاج‪ ،‬وإحــدى عشــر‬\n‫ألــف وثالثمائــة ريــال إصــاح معــدات البركــة‪ ،‬وكذلــك تعويضــي عــن‬\n‫األربــاح املتوقعــة عــن تســع ســنوات الباقيــة مــن العقــد هــذه دعــواي‪،‬‬\n‫أطلــب احلكــم عليهــم بذلــك‪ ،‬وباســتجواب املدعــى عليــه أجــاب قائــا‪:‬‬\n‫إن الشــركة قامــت بإنشــاء شــاليهات ذات مســتوى جيــد‪ ،‬ونظــرا لعــدم‬\n\n\n                                                                                      ‫‪128‬‬\n\f      ‫تخصص الشــركة يف اإليواء فقد رأت تأجير الشــاليهات على شــخص‬\n      ‫متخصــص‪ ،‬وقــد تقــدم املدعــي بطلــب االســتئجار ومت االتفــاق معــه علــى‬\n      ‫تأجيــره الشــاليهات عشــر ســنوات بأجــرة قدرهــا مليــون ريــال للســنة‬\n      ‫مبوجــب العقــد املــؤرخ يف ‪1418/3/28‬ه املوافــق ‪1997/8/1‬م ويشــتمل‬\n      ‫علــى ‪ 31‬بنــد‪ ،‬وقــد جــاء يف البنــد الثالــث أنــه يلتــزم الطــرف الثانــي‬\n      ‫باحملافظــة علــى الشــاليهات‪ ،‬واملــادة الثامنــة بســداد قيمــة فواتيــر‬\n      ‫الهاتــف والكهربــاء وامليــاه‪ ،‬واملــادة العاشــرة أن تكــون الصيانــة علــى‬\n      ‫عاتــق املســتثمر بنفــس مســتوى اإلنشــاءات مــع االلتــزام بجــدول الصيانــة‬\n      ‫الوقائيــة املرفــق بالعقــد‪ ،‬وجــاء يف املــادة الثالثــة والعشــرين أنــه يحــق‬\n      ‫للطــرف األول فســخ العقــد يف إحــدى احلــاالت ومنهــا عــدم القيــام‬\n      ‫بالصيانــة علــى الوجــه املطلــوب بعــد إشــعاره مرتــن متتاليتــن الــخ‪،‬‬\n      ‫ونظــرا لعــدم قيــام املدعــي بالصيانــة علــى الدرجــة املطلوبــة وكــون‬\n      ‫العمالــة التــي تديــر املشــروع ال يتجــاوز عددهــم أصابــع اليــد الواحــدة ومت‬\n      ‫االجتمــاع معــه عــدة مــرات ومت االتفــاق علــى إنهــاء العقــد وديــا ومت‬\n      ‫اإلخــاء مــن املدعــي‪ ،‬وأمــا الصيانــة التــي ذكــر فهــي صيانــة للحدائــق‬\n      ‫فقــط دون املبانــي ومــا يتبعهــا‪ ،‬ومــا ذكــره مــن مطالبتــه بقيمــة‬\n      ‫جتهيــزات‪ ،‬فــا أعلــم مــا هــي التجهيــزات‪ ،‬وأمــا بالنســبة للدعايــة‬\n      ‫واإلعــان فهــو مســئول عنهــا حســب العقــد‪ ،‬وأمــا بالنســبة للهواتــف فــإن‬\n      ‫العقــد قــد نــص علــى تأمــن ثــاث هواتــف جــوال اســتقبال فقــط ومت‬\n      ‫تأمينهــا‪ ،‬وأمــا بالنســبة إليجــار الشــاليه رقــم ‪ 6‬فهــو مؤجــر قبــل أن‬\n      ‫يســتأجر املدعــي ملــدة ســنة وقــد نصــت املــادة ‪ 14‬مــن العقــد بــأن علــى‬\n      ‫الطــرف الثانــي قبــول العقــود املوقعــة مــع املســتأجرين قبــل بدايــة هــذا‬\n      ‫العقــد‪ ،‬وأربــاح التأمــن لــم تســتلم منهــا شــيء‪ ،‬وأمــا إصــاح الزجــاج‬\n\n\n‫‪129‬‬\n\f‫وإصــاح معــدات البركــة فهــو املســئول عنهــا حســب بنــد الصيانــة‪،‬‬\n‫كمــا أضــاف املدعــى عليــه‪ :‬إذا كان املدعــي لديــه القــدرة علــى تشــغيل‬\n‫الشــاليهات فــا مانــع لدينــا مــن تســليمها لــه مبوجــب شــروط العقــد‬\n‫ونخفــض لــه مــن األجــرة مئــة ألــف ريــال‪ ،‬وبعــرض مــا ذكــره املدعــى‬\n‫عليــه علــى املدعــي مــن أنــه مت اإلخــاء مبوجــب اتفــاق أجــاب قائــا‪ :‬بأنــه‬\n‫قــد ورد لـ ّـي خطــاب مــن املدعــى عليــه بطلــب اإلخــاء حســب املــاده ‪23‬‬\n‫مــن بنــد العقــد وقــد قمــت باإلخالء بنــاء على طلبهم املشــروع‪ ،‬والهواتف‬\n‫مت التفاهــم مــع رئيــس مجلــس اإلدارة واملديــر الســابق ‪ ...‬علــى أنــه مت‬\n‫تامــن هواتــف ّأيــن كانــت وعليهــم حتمــل ‪% 75‬مــن التكلفــة‪ ،‬وأمــا‬\n‫الشــاليه رقــم ‪ 6‬فقــد مت تســليمي كشــف حســاب يفيــد بــأن لــي بذمتهــم‬\n‫مبلــغ أربعــه وأربعــون ألــف وخمســمائة ريــال قيمــه الشــالية‪ ،‬وأربــاح‬\n‫التأمــن اســتلموا مــا يخــص عــام ‪97‬م‪ ،‬وإصــاح الزجــاج والبركــة هــم‬\n‫املســؤولني عنهــا؛ ألنهــا مــن الصيانــة‪ ،‬وأمــا مــا ذكــر ه مــن العــرض علـ ّـي‬\n‫بالعــودة للمشــروع مببلــغ تســعمائة ألــف ريــال فــا أرغــب بذلــك بســبب‬\n‫معاملتهــم لــي ولتقــادم املــدة حيــث ذهــب وعمالــي‪ ،‬وطلبــت مــن الطرفــن‬\n‫البينــة منهمــا بــكل مــا يدعيــاه‪ ،‬فاســتعدا بذلــك‪ ،‬ويف جلســة أخــرى‬\n‫حضــر الطرفــان وبطلــب البينــة منهمــا أبــرز املدعــى عليــه عقــد صيانــة‬\n‫مشــروع شــاليهات الترفيــة واملــؤرخ يف ‪1418/6/19‬ه ـ املوافــق‬\n‫‪1997/10/20‬م املتضمــن إتفــاق الشــركة ‪ ................‬ثانيا‪/‬الســيد‬\n‫‪ ..................‬ويشــار إليــه الطــرف الثانــي قــد جــاء يف العقــد الفقــرة الثانية‬\n‫مــا نصــه‪( :‬يقــوم الطــرف األول بتقــدمي خدمــات الصيانــة بواســطة فريــق‬\n‫الصيانــة اخلــاص بــه حــن احلاجــة مقابــل مبلــغ شــهري قــدرة ألفــان ريــال‬\n‫بــدون قطــع الغيــار التــي يتحملهــا الطــرف الثانــي ويقــوم بتوريدهــا حــال‬\n\n\n                                                                                            ‫‪130‬‬\n\f      ‫طلبهــا مــن الطــرف األول لتــايف أي أضــرار تلحــق بالعمــل أو املشــروع أو‬\n      ‫يقــوم الطــرف األول بتوفيرهــا وتقــدمي الفواتيــر للطــرف الثانــي للدفــع)‬\n      ‫أ‪.‬هــ‪ ،‬وبعــرض العقــد علــى املدعــي أجــاب قائــا‪ :‬إن هــذا العقــد صحيــح‬\n      ‫وهــو عقــد صيانــة لكامــل املشــروع وليــس مخصــص للزراعــة‪ ،‬كمــا‬\n      ‫ذكــر املدعــى عليــه وســمع ذلــك املدعــى عليــه وقــال‪ :‬نعــم إن الصيانــة‬\n      ‫هــي ملشــروع شــاليهات الترفيــة كاملــة‪ ،‬وبطلــب البينــة مــن املدعــي علــى‬\n      ‫الهواتــف أبــرز وثيقــة معنونــة لشــركة ‪ .................‬وهــذا نصهــا‪( :‬محضر‬\n      ‫اجتمــاع يف يــوم األربعــاء ‪1997/9/3‬م ومبكاتــب الشــركة اجتمــع‬\n      ‫كل مــن رئيــس مجلــس إدارة الشــركة ‪ ..........‬وبحضــور مديــر عــام‬\n      ‫الشــركة واألســتاذ ‪ ...........‬مســتثمر شــاليهات الترفيــه وذلــك حــول‬\n      ‫اســتالم املســتثمر للشــاليهات وقــد مت االتفــاق علــى مــا يلــي‪ )1 :‬يبــدأ‬\n      ‫ســريان عقــد االســتثمار يــوم ‪1997/10/1‬م‪ )2 .‬تتكفــل الشــركة‬\n      ‫‪ ...................‬مبــا قيمتــه ‪ % 75‬مــن تكلفــة تأســيس هاتــف مشــروع‬\n      ‫شــاليهات الترفيــه ‪ % 25‬يتحملهــا املســتثمر ‪ .............‬علــى أن يــؤول جميع‬\n      ‫ذلــك فيمــا بعــد إلــى الشــركة ‪ )3 ..................‬متــت مناقشــة جميــع‬\n      ‫مالحظــات املســتثمر الــواردة يف خطابــه بتاريــخ ‪1997/8/31‬م ومت‬\n      ‫االتفــاق علــى املعاجلــة اخلاصــة بهــا‪ .‬الشــركة ‪ .................. ..........‬املديــر‬\n      ‫العــام التوقيــع املســتثمر ‪ ..................‬التوقيــع كذلــك ختــم الشــركة‬\n      ‫‪ ................‬حتــت توقيــع املديــر العــام لشــركة ‪ ).............‬وبعرضهــا علــى‬\n      ‫املدعــى عليــه أجــاب قائــا‪ :‬هــذا االتفــاق صحيــح ولكــن املقصــود فيــه‬\n      ‫هــو إيصــال الهاتــف عــن طريــق شــركة ‪ .....‬حتــى اآلن لــم يصــل املنطقة‪،‬‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وجــرى عــرض مــا أجــاب بــه املدعــى‬\n      ‫عليــه علــى املدعــي مــن أن املقصــود بالهاتــف هــو إيصــال الهاتــف عــن‬\n\n\n‫‪131‬‬\n\f‫طريــق شــركة ‪ .......‬فأجــاب املدعــي قائــا‪ :‬إن االتفــاق إيصــال الهاتــف‬\n‫أي كان نوعــه ولــم يحــدد‪ ،‬وجــرى ســؤاله ألديــه البينــة علــى مــا ذكــر‬\n‫فأجــاب قائــا‪ :‬بينتــي هــي محضــر االتفــاق املــدون آنفــا‪ ،‬كمــا أضــاف‬\n‫املدعــي قائــا أنــه بعــد اســتالمي للمشــروع بأســبوع تعطلــت معــدات‬\n‫بركــة الســباحة وقمــت بإصالحهــا مــع قطــع غيــار بإحــدى عشــر ألــف‬\n‫وثالثمائــة ريــال‪ ،‬كمــا أن الشــركة اســتلمت منــي ألــف وثمامنائــة ريــال‬\n‫قيمــة إصــاح الزجــاج وقيمــة الزجــاج فقــط مائــة ريــال والتركيــب علــى‬\n‫الشــركة؛ ألنــه مــن الصيانــة‪ ،‬كمــا أبــرز املدعــي كشــف حســاب رقــم‬\n‫‪ 4‬واملرســل بالفاكــس للعميــل الســيد ‪ ....................‬املــؤرخ يف‬\n‫‪1998/7/1‬م صــادر مــن الشــركة ‪...................‬وقــد جــاء فيــه املســتحق‬\n‫لكــم عــن قيمــة تأجيــر شــاليه رقــم( ‪ 39500  )6‬ريــال‪ ،‬وســمع ذلــك‬\n‫املدعــى عليــه وأجــاب قائــا‪ :‬إن الزجــاج مت تركيبــه مبوجــب فاتــورة‬\n‫وأطلــب إمهالــي إلحضارهــا‪ ،‬ومــا ذكــره املدعــي مــن أنــه مت إصــاح‬\n‫البركــة بعــد أســبوع فقــط أطلــب منــه إثبــات ذلــك‪ ،‬كمــا جــرى  ســؤال‬\n‫املدعــى عليــه عمــا ذكــره يف إجابتــه ســابقا أن الدعايــة واإلعــان علــى‬\n‫املدعــي فأجــاب قائــا‪ :‬بــأن العقــد قــد نــص باملــادة الثامنــة منــه بأنــه‬\n‫يلتــزم الطــرف الثانــي بســداد رســوم البلديــة اخلاصــة باللوحــات اإلعالنية‬\n‫اخلاصــة بشــاليهات الترفيــه وعددهــا أربعــة أوجــه إعالنيــة مبســاحة‬\n‫ســبعة وتســعني متــر‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬إن ذلــك خــاص بالالفتة‬\n‫التــي علــى الشــاليهات نفســها‪ ،‬أمــا مــا جــاء يف دعــواي فهــو املقصــود‬\n‫الدعايــة واإلعــان يف وســائل اإلعــام وقــد اتفقــت مــع املديــر الســابق‬\n‫‪ ..................‬ورئيــس مجلــس اإلدارة الســابق ‪ ..................‬حيــث اتفقــت‬\n‫معهمــا علــى أن يدفــع خمســة وعشــرين باملائــة مــن قيمــة  الدعايــة ال أننــي‬\n\n\n                                                                                      ‫‪132‬‬\n\f      ‫ســوف أضمــن الدعايــة‪ ،‬وإن الشــاليهات تقــع بجــوار مدينــة ‪......‬‬\n      ‫الترفيهيــة‪ ،‬وســمع ذلــك املدعــى عليــه وأجــاب قائــا‪ :‬إن مــا ذكــره‬\n      ‫املدعــي مــن أنــه اتفــق مــع املديــر الســابق ورئيــس مجلــس اإلدارة فــا ‬\n      ‫أعلــم عنــه‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬إنــه مت االتفــاق معهمــا مشــافهة‬\n      ‫وعندمــا طلبــت منهمــا كتابــة ذلــك وإضافتــه مبحضــر الهاتــف قــال لــي‬\n      ‫‪ ..............‬نحــن موجوديــن ونتعامــل بثقــة‪ ،‬ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان وبســؤال املدعــى عليــه عــن فاتــورة الزجــاج التــي وعــد‬\n      ‫بإحضارهــا أجــاب قائــا‪ :‬بأننــي لــم أمتكــن مــن إحضارهــا‪ ،‬وجــرى‬\n      ‫ســؤال املدعــي عــن إثبــات فواتيــر بركــة الســباحة‪ ،‬أبــرز وثيقــة هــذا‬\n      ‫نصهــا‪(  :‬بســم اهلل الرحمــن الرحيــم التاريــخ ‪1418/6/22‬ه ـ املكــرم‬\n      ‫مديــر شــاليهات ‪ ...........‬احملتــرم الســام عليكــم ورحمــة اهلل وبركاتــه‬\n      ‫وبعــد‪ :‬نحيطكــم علمــا بتقريــر مفصــل بعــد زيــارة بركــة الســباحة‬\n      ‫املتعطلــة الكائنــة بشــاليهات ‪ ......‬حيــث وجــد مــا يلــي‪/1 :‬هنــاك كســر‬\n      ‫وانفجــار بالفلتــر نتيجــة عيــب فنــي يف التوصيــات اخلاصــة بالفلتــر‬\n      ‫واملضخــة متمثــل يف وضــع قطــع توصيــات ال تتناســب مــع كميــة‬\n      ‫الضغــط الناشــئ مــن ســحب املضخــة كذلــك وضــع مواســير ‪ 40‬بــدال‬\n      ‫مــن ‪ 80‬الالزمــة لهــذه احلالــة‪/2 .‬عــدم وضــع املضخــات علــى قواعــد‬\n      ‫حلمايتهــا مــن امليــاه املتواجــدة بأرضيــة غرفــة املعــدات ممــا أدى إلــى تلــف‬\n      ‫إحــدى املضخــات والتــي يلــزم اســتبدالها إلــى جانــب الفلتــر املنفجــر‪/3 .‬‬\n      ‫عــدم وجــود غرفــة تفتيــش بداخــل غرفــة املعــدات الالزمــة لتجميــع امليــاه‬\n      ‫داخــل غرفــة املعــدات يف حالــة وجــود أي تســرب داخلهــا كذلــك يلــزم‬\n      ‫وجــود مضخــة داخــل غرفــة التفتيــش لدفــع امليــاه إلــى اخلــارج‪/4 .‬قلــة‬\n      ‫عــدد فتحــات الرجــوع حيــث املوجــودة ســتة فقــط بينمــا الالزمــة عشــرة‬\n\n\n‫‪133‬‬\n\f‫ممــا يــؤدي إلــى قلــة كميــة امليــاه املرجتعــة خــال اإلســلميرات اخلمســة‬\n‫بالبركــة ‪ ............‬مديــر املشــاريع توقيعــه) أ‪.‬هــ‪ .‬كمــا أبــرز أيضــا وثيقــة‬\n‫هــذا نصهــا‪( :‬بســم اهلل الرحمــن الرحيــم التاريــخ ‪1418/6/21‬ه ـ‬\n‫املكــرم مديــر شــاليهات ‪ ............‬احملتــرم الســام عليكــم ورحمــة اهلل‬\n‫وبركاتــه وبعــد‪ :‬بنــاء علــى تعميدكــم لنــا مبعاينــة معــدات بركــة‬\n‫الســباحة املتعطلــة واخلاصــة بشــاليهات الترفيــه وطلبكــم تقــدمي التقريــر‬\n‫الــازم والتســعيرة املتعلقــة بهــذا اإلصــاح عليــه نحيطكــم أن فريــق‬\n‫العمــل املكــون مــن املهنــدس والفنيــن قــد عاينــوا املعــدات فوجــدوا أن‬\n‫العطــل احلاصــل ســببه ضغــط زائــد علــى الفلتــر ممــا أدى إلــى انفجــار‬\n‫الفلتــر كذلــك تســرب امليــاه داخــل املضخــة ممــا أدى إلــى احتراقهــا‪،‬‬\n‫وعلــى هــذا فــا بــد مــن إعــادة تركيــب فلتــر ومضخــة جديــدان مــن‬\n‫نفــس النوعيــة وكذلــك إعــادة تركيــب توصيــات جديــدة بــدال مــن‬\n‫القائمــة حاليــا القيمــة اإلجماليــة لألعمــال أعــاه ‪11800‬ريــال ال غيــر‬\n‫املهنــدس ‪ ..............‬مديــر املشــاريع توقيعــه) أ‪.‬ه ـ ‪ .‬وأبــرز ســند قبــض‬\n‫معنــون مؤسســة ‪ ...............‬للتجــارة واملقــاوالت ســند قبــض رقــم ‪ 258‬يف‬\n‫‪1997/11/2‬م املوافــق ‪1418/7/2‬ه ـ اســتلمنا مــن األســتاذ املكــرم‬\n‫‪ ......................‬شــاليهات ‪ ........‬فقــط خمســة آالف وســبعمائة ريــال ال‬\n‫غيــر وذلــك عــن دفعــة أخيــرة مــن عمليــة تركيــب معــدات املســبح وذلــك‬\n‫بعــد خصــم مبلــغ خمســمائة ريــال ليصبــح إجمالــي مــا وصلنــا أحــد عشــر‬\n‫ألــف وثالثمائــة ريــال‪ ،‬وأبــرز ســند آخــر برقــم ‪ 256‬مببلــغ خمســة آالف‬\n‫وســتمائة ريــال وكتبــت البيانــات باللغــة اإلجنليزيــة‪ ،‬وبعــرض ذلــك على‬\n‫املدعــى عليــه أجــاب قائــا‪ :‬إن املدعــي ملــا عــرض علــى الشــركة عطــل‬\n‫املســبح مت عرضــه علــى الشــركة املنفــذة وأصــدرت تقريــر بأنــه مــن‬\n\n\n                                                                                        ‫‪134‬‬\n\f      ‫ســوء االســتخدام‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬ال يوجــد أي خطــاب‪،‬‬\n      ‫واســتعد املدعــى عليــه بإحضــاره وإحضــار فاتــورة الزجــاج‪ ،‬ويف جلســة‬\n      ‫أخــرى حضــر املدعــي وحضــر حلضــوره ‪ ........‬احلامــل للبطاقــة رقــم‬\n      ‫‪ ................‬رقــم احلفيظــة ‪ .........‬يف ‪ ........‬الصــادرة مــن ‪ .......‬بالوكالــة‬\n      ‫عــن ‪............‬حــال كونــه وكيــا  عــن ‪ ...............‬و‪........................‬‬\n      ‫و‪ ................‬و‪ ..............‬و‪ .................‬و‪ .......................‬و‪....................‬‬\n      ‫وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل ‪ .....‬برقــم ‪ ......‬يف‬\n      ‫‪ ......‬واملخولــة لــه ينــوب عــن موكله فيما يخصهم يف الشــركة واملرافعة‬\n      ‫واملدافعــة وبالوكالــة عــن ‪ .....................‬مبوجــب وكالتــه عــن‬\n      ‫‪ ...................‬واملخولــة لــه املرافعــة واملدافعــة واملطالبــة وذلــك فيما يخص‬\n      ‫موكليــه مــن الشــركة ‪ .................‬وبالوكالــة عــن ‪...................‬مبوجب‬\n      ‫الوكالــة الصــادرة مــن ‪ .....‬برقــم ‪ .....‬يف ‪ ......‬اجللــد ‪ ......‬واملخولــة لــه‬\n      ‫مبطالبــة ومداعــاة ‪ .....................‬وذلــك بخصــوص الشــاليهات املؤجــرة‬\n      ‫عليــه لــه حــق الدعــوى واإلجابــة والصلــح واالســتالم‪ ،‬وأضــاف املدعــى‬\n      ‫عليــه‪ :‬إن موكلينــي هــم أعضــاء مجلــس إدارة مراكــز ‪..............‬‬\n      ‫واملخــول لــه مــن مجلــس إدارة الشــركة حســب املــادة ‪ 1/14‬متثيــل‬\n      ‫الشــركة لــدى الغيــر باملرافعــة واملدافعــة واملخاصمــة ‪...‬الــخ وطلــب منــه‬\n      ‫مــا يثبــت أن موكليــه هــم أعضــاء مجلــس إدارة الشــركة واســتعد‬\n      ‫بذلــك‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبطلــب مــا طلــب إمهالــه مــن‬\n      ‫املدعــى عليــه أبــرز خطــاب مــن مؤسســة ‪ .........‬التجاريــة املــؤرخ يف‬\n      ‫‪1997/10/28‬م وهــذا نصــه‪( :‬بســم اهلل الرحمــن الرحيــم الســادة‬\n      ‫الشــركة ‪ ...............‬احملترمــن الســام عليكــم ورحمــة اهلل وبركاتــه‬\n      ‫إشــارة إلــى طلــب الســادة‪ /‬مؤسســة ‪ ..............‬للمقــاوالت ملعاينــة بركــة‬\n\n\n‫‪135‬‬\n\f‫الســباحة املنفــذة مــن قبلكــم يف موقــع شــاليهات ‪ .............‬وبنــاء علــى‬\n‫طلبكــم تقريــر حــول حادثــة الفلتــر بالبركــة املذكــورة‪ ،‬فقــد قمنــا‬\n‫يــوم ‪1997/10/27‬م  مبعاينــة املوقــع برفقــة مندوبكــم وقــد تبــن اآلتي‪:‬‬\n‫أوال‪/‬أن جميــع توصيــات املواســير والتجهيــزات يف غرفــة املعــدات‬\n‫صحيحــة وحســب املواصفــات املعمــول بهــا‪ .‬ثانيــا‪/‬أن عطــا كهــذا‬\n‫(وبعــد تشــغيل ألكثــر مــن شــهر مضــى) ال يحــدث إال نتيجــة خطــأ يف‬\n‫التشــغيل‪ ،‬أو تســكر أحــد احملابــس الراجعــة للبركــة وبالتالــي نحــن‬\n‫مطمئنــون إلــى أن تنفيــذ العمــل صحيــح وال تبعــة علــى املقــاول مــن أي نوع‬\n‫خاصــة وأن الفلتــر الثانــي يعمــل بشــكل صحيــح وســليم ولكــم حتياتنــا‬\n‫املشــرف الفنــي ‪ ..............‬توقيعــه) أ‪.‬هــ‪ ،‬كمــا أبــرز فاتــورة معنونــة مــن‬\n‫مجمــع ‪ ........ ........‬رقــم ‪ 2488‬يف ‪1998/8/30‬م واملكتــوب مــن الســيد‬\n‫الشــركة ‪ ......................‬ســتمائة وثالثــون ريــال خصــم ثالثــون ريــال‬\n‫املجمــوع ســتمائة زجــاج ســترميلي ســادة ســولورين ضــد الكســر‪،‬‬\n‫وبعرضهــا علــى املدعــي أصالــة أجــاب قائــا‪ :‬أن التقريــر يحتــاج إلــى‬\n‫الرجــوع إلــى التواريــخ حتــى أمتكــن مــن اإلجابــة‪ .‬ثانيا‪/‬التوقيــع علــى‬\n‫الفاتــورة ليــس توقيعــي وال أعلــم مــن هــو توقيعــه وهــو التوقيــع املــدون‬\n‫حتــت اســم ‪ ،..............‬ويف جلســة أخــرى قــال املدعــي‪ :‬إن التقريــر املشــار‬\n‫إليــه لــم يحــدد العيــب وقــد ذكــر احتمــاالت أمــا التقريــر الــذي قدمتــه‬\n‫فهــو محــدد اخللــل كمــا أنــه  ســبق لنــا االجتمــاع يف ‪1997/10/19‬م‬\n‫ومــن ضمــن النقــاط التــي حصــل االتفــاق عليهــا (خامســا) يتــم إصــاح‬\n‫البركــة بــدون التعــذر بأخطــاء الغيــر وكذلــك املكيفــات ولــم يتــم‬\n‫إصــاح البركــة وقمــت بإصالحهــا؛ ألنــه مت تشــغيل املشــروع قريبــا‬\n‫ورغبــة يف كســب الــزوار وتلبيــة رغباتهــم وعلــى أمــل أن تســد لــي قيمــة‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫اإلصــاح‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبســؤال املدعــى عليــه‬\n      ‫عــن محضــر االجتمــاع املوقــع يف يــوم األحــد املوافــق ‪1997/10/19‬م مــن‬\n      ‫األستاذ ‪ ............‬و‪ ...................‬و‪ ..............‬و‪ ....................‬و‪......................‬‬\n      ‫ومــا جــاء يف الفقــرة (خامســا) يتــم إصــاح البركــة بــدون التعــذر‬\n      ‫بأخطــاء الغيــر وكذلــك املكيفــات أجــاب قائــا‪ :‬أن ‪ ...............‬مســافر‬\n      ‫خــارج اململكــة وهــو ســوف يصــل اليــوم أو غــدا‪ ،‬كمــا جــرى ســؤال‬\n      ‫املدعــي عــن دعــواه بأنــه يطالــب بإيجــار الشــاليه رقــم ‪ 6‬بأجــرة وقدرهــا‬\n      ‫أربعــة وأربعــون ألــف وخمســمائة ريــال وأن املقدم له من إدارة الشــاليهات‬\n      ‫عــن تأجيــر الشــاليه رقــم ‪ 6‬تســع وثالثــون ألــف وخمســمائة ريــال وأجــاب‬\n      ‫قائــا‪ :‬أن الشــاليه مؤجــر مببلــغ وقــدره أربعــة وأربعــون ألــف وخمســمائة‬\n      ‫ريــال حســب عقــد اإليجــار املــؤرخ يف ‪1418/2/21‬ه ـ املوافــق‬\n      ‫‪1997/6/26‬م وأبــرز العقــد املــؤرخ بالتاريــخ أعــاه واملوضــح فيــه املؤجر‬\n      ‫شــاليهات الترفيــه املمثــل لهــا ‪ ....................‬الطــرف الثانــي ‪.................‬‬\n      ‫مــدة اإليجــار ســنة هجريــة اعتبــارا مــن بدايــة اإلشــعار والتشــغيل و‬\n      ‫اجلاهزيــة بأجــرة إجماليــة قدرهــا أربعــة وأربعــون ألــف وخمســمائة ريــال‬\n      ‫أ‪.‬هــ  وأضــاف املدعــي‪ :‬إن بدايــة التشــغيل مــن ‪1997/10/1‬م‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬بأنــي ال أعلــم عــن مطالبــة املدعي؛‬\n      ‫ألنــه ليــس لــي علــم عــن عقــد اإليجــار وأطلــب  إمهالــي للرجــوع إلــى‬\n      ‫موكلــي‪ ،‬ويف جلســة أخــرى جــرى ســؤال املدعــى عليــه عمــا طلــب‬\n      ‫اإلمهــال لــه أن الشــاليه املؤجــر علــى ‪ ...‬اخللــف أجرتــه بالســنة أربعــة‬\n      ‫وأربعــون ألــف وخمســمائة ريــال ولــم يســلم ل‪ ..............‬مــن بدايــة العقــد‬\n      ‫وقــد حســبت لــه املــدة التــي يســتحقها مــن اإليجــار تســعة وثالثــن ألــف‬\n      ‫وخمســمائة ريــال‪ ،‬وطلــب مــن املدعــى عليــه حتديــد تاريــخ اســتالم‬\n\n\n‫‪137‬‬\n\f‫الشــاليه فاســتعد بذلــك‪ ،‬ويف جلســة أخــرى حضــر املدعــي  وحضــر‬\n‫حلضــوره ‪ ..............‬احلامــل للبطاقــة رقــم ‪ ...........‬رقــم احلفيظــة ‪ ............‬يف‬\n‫‪1406/9/6‬ه ـ الصــادرة مــن الريــاض بالوكالــة عــن ‪....................‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل ‪ ......‬برقــم ‪ ......‬يف ‪......‬‬\n‫اجللد ‪ .....‬حال كونه وكيال عن و‪ .................‬و‪ ...............‬و‪.....................‬‬\n‫و‪ .............‬واملذكورون هم أعضاء إدارة مجلس الشركة ‪.....................‬‬\n‫احملــدودة واملخولــة لــه مطالبــة ومداعــاة ‪ ..................‬وجــرى ســؤال‬\n‫املدعــى عليــه عمــا طلــب اإلمهــال لــه فأجــاب قائال أنه مت تســليم الشــاليه‬\n‫ل‪ ................‬يف ‪1997/11/1‬م وهــو بدايــة اإليجــار علــى ‪ ..........‬وطلــب‬\n‫حتديــده بالتاريــخ الهجــري فاســتعد بذلــك ويف جلســة أخــرى قال املدعى‬\n‫عليه‪ :‬إنه مت تســليم الشــاليه ل‪ ................‬بتاريخ ‪1418/7/1‬هـ‪  ،‬وجرى‬\n‫ســؤال املدعــي عــن كيفيــة دفــع أجــرة الصيانــة فأجــاب قائــا‪ :‬أنــه يتــم‬\n‫دفعهــا شــهريا‪ ،‬وجــرى ســؤاله أيضــا عــن أربــاح التأمــن التــي يطالــب بهــا‬\n‫فأجــاب قائــا‪ :‬إن مشــروع الشــاليهات قــد مت تقديــره مــن قبــل شــركة‬\n‫الترفيــه بأحــد عشــر مليــون ودفعــت عليــه تأمني لدى الشــركة التعاونية‬\n‫للتأمــن مبلــغ وقــدره أحــد عشــر ألــف ريــال بنســبة واحــد باأللــف ويف‬\n‫حالــة عــدم حــدوث أي شــيء علــى املشــروع حتســب األربــاح حســب املبلــغ‬\n‫الــذي دفعــه واســتحق عــن ذلــك جــزء مــن عــام ‪1997‬م وعــام ‪1998‬م مبلــغ‬\n‫وقــدره ثمامنائــة وتســعة وثمانــون ريــال‪ ،‬وأضــاف املدعــي قائــا‪ :‬إن‬\n‫الهواتــف التــي مت تأمينهــا مــن قبلــي مــن نــوع (ســيناو الســلكي)‪ ،‬وحيث‬\n‫أن املدعــي ذكــر يف دعــواه أنــه يتــم تأمــن الهواتــف أيــا كان نوعهــا‬\n‫وذكــر املدعــى عليــه أنــه يتــم تأمــن هواتــف عــن طريــق شــركة ‪،.......‬‬\n‫لــذا فقــد رفعــت اجللســة وذلــك للكتابــة لهيئــة النظــر وذلــك لتحديــد نــوع‬\n\n\n                                                                                               ‫‪138‬‬\n\f        ‫الهواتــف التــي يتــم تركيبهــا حســب اتفــاق الطرفــن وســوف يرفــق لهــم‬\n        ‫صــورة مــن وثيقــة االتفــاق علــى الهواتــف‪ ،‬فــوردت اإلجابــة أن العطــل‬\n        ‫النــاجت يف املســبح ال ميكــن أن يتــم فيــه عطــل خــال أســبوع أو مــا يقــارب‬\n        ‫ذلــك ال بــد أن يكــون فيــه أخطــاء فنيــه ال ميكــن معرفتهــا إال بســؤال‬\n        ‫أهــل اخلبــرة لــذا نعتــذر عــن اإلجابــة عضــو هيئــة النظــر ‪................‬‬\n        ‫و‪ ،.....................‬وحيــث لــم توضــح هيئــة النظــر مــا طلــب منهــم عــن‬\n        ‫الهاتــف فقــد جــرى إعــادة األوراق لفضيلــة الرئيــس بطلــب إعادتهــا لهيئــة‬\n        ‫النظــر بتقريــر نــوع الهاتــف الــذي يجــب أن يتــم إيصالــه حســب االتفاقيــة‬\n        ‫املرفقــة مــع االســتعانة بأهــل اخلبــرة وذلــك بخطابنــا رقــم ‪ 4/807‬يف‬\n        ‫‪1425/4/11‬ه ـ وقــد أعيــدت لنــا األوراق مــن فضيلــة الرئيــس برقــم‬\n        ‫‪ 7925‬يف ‪1425/6/7‬ه ـ شــرحا علــى خطــاب هيئــة النظــر رقــم‬\n        ‫‪ 24/16505‬يف ‪1425/6/4‬ه ـ املتضمــن أنــه مضــى عليهــا مــدة ولــم‬\n        ‫يراجــع أحــد‪ ،‬وبتأمــل مــا مضــى حيــث أن املدعــي قــرر أنــه ال بينــة لــه‬\n        ‫علــى مــا يدعــي بــه نســبة الدعايــة واإلعــان‪ ،‬وجــرى إفهامــه أن لــه ميــن‬\n        ‫املديــر الســابق ‪ .............‬ورئيــس مجلــس اإلدارة الســابق ‪...............‬‬\n        ‫وأجــاب‪ :‬أنــه ال يرغــب بيمينهمــا واليمــن الواجبــة هــي علــى نفــي مــا‬\n        ‫يدعــي بــه ولعــدم االســتطاعة يف إحضارهــم وهــذا ســبب عــدم طلــب‬\n      ‫ميينهمــا‪ ،‬وحيــث أن املدعــى عليــه قــرر بأنــه لــم يتم اســتالم أربــاح التأمني ‬\n        ‫وذكــر املدعــي أنــه مت اســتالم األربــاح لعــام ‪1997‬م‪ ،‬وجــرى ســؤاله هــل‬\n      ‫لديــه بينــة علــى ذلــك‪ ،‬فأجــاب قائــا‪ :‬أطلــب إمهالــي للبحــث عــن البينة‪  ،‬‬\n        ‫ويف جلســة أخــرى قــال املدعــي عنــد ســؤاله عــن نــوع الزجــاج ومقاســه‪:‬‬\n        ‫إن مقاســه ‪ 80‬ســم يف متريــن ونوعــه زجــاج أخضــر ســادة‪ ،‬ويف جلســة‬\n        ‫أخــرى حضــر الطرفــان وبطلــب البينــة مــن املدعــي علــى صــرف أربــاح‬\n\n\n‫‪139‬‬\n\f‫التأمــن أجــاب قائــا‪  :‬إن املبلــغ قليــل ويحتــاج إلــى بحــث وقــد ذكــرت‬\n‫ذلــك يف دعــواي وذلــك ملجــرد توضيــح تعســف الشــركة واســتحواذها‬\n‫علــى حقــوق الغيــر مهمــا قلــت وأنــا متنــازل يف الدعــوى ضــد ذلــك‪،‬‬\n‫وأجــاب املدعــى عليــه عــن الزجــاج قائــا‪ :‬إن الســندين املقدمــة مــن‬\n‫املدعــي خاصــة مبجمــع ‪ .....‬الــذي يبيــع ويركــب الزجــاج ونحــن يف‬\n‫الشــركة لســنا مســئولني عــن ســندات محــل آخــر رمبــا مجمــع ‪ .....‬ال‬\n‫يســتخدم ســندات القبــض إال عنــد طلــب الزبــون  والفــرق بــن الســندين‬\n‫حوالــي ثالثــة شــهور مــن ‪1997/10/12‬م إلــى ‪1998/1/10‬م‪ ،‬فأمــا‬\n‫عــن نــوع الزجــاج فالســند األول رقــم ‪ 502‬بقيمــة خمســمائة ريــال فهــو‬\n‫عــن قيمــة لــوح زجــاج مــع التركيــب‪ ،‬والثانــي رقــم ‪ 503‬بقيمــة ألــف‬\n‫وثالثمائــة ريــال فهــو عــن قيمــة لوحــن زجــاج ولوحــن بالســتيك وأجــرة‬\n‫تركيــب‪ ،‬فالشــيء الطبيعــي أن يكــون فــرق بالقيمــة؛ ألن الســند األول‬\n‫خــاص بلــوح واحــد فقــط دون وجــود لــوح بالســتيك وســند الصــرف‪ ،‬فهو‬\n‫مــن مؤسســة ‪ ...............‬التــي تســببت يف كســر الزجــاج ودفعــت مبوجــب‬\n‫الســند لنــا تعويــض ألــف وثمامنائــة ريــال واملســتلم مديــر الشــاليهات وهــو‬\n‫مــن الشــركة ‪ ...............‬ونــرى أن املوضــوع ليــس لــه عالقــة بقضيــة‬\n‫‪.........‬؛ ألن مؤسســة ‪ .....‬كســرت الزجــاج ومجمــع ‪ ....‬ركــب الزجــاج‪،‬‬\n‫وســمع ذلــك املدعــي وقــال‪ :‬إن مؤسســة ‪ .....‬هــي مؤسســتي والســند‬\n‫الصــادر للشــاليهات بالصــرف صــادر مــن مؤسســتي ألن اســتعمال‬\n‫مطبوعاتها بدل من اســتخدام األوراق العادية وذلك لضبط حســاباتي‪،‬‬\n‫وأضــاف قائــا‪ :‬إن مجمــع التقــوى أصبــح اســمه مجمــع ‪ ،........‬وســوف‬\n‫تتــم الكتابــة ملجمــع ‪ ....‬لطلــب اإلفــادة عــن الســندين املشــار إليــه آنفــا‪،‬‬\n‫ويف جلســة أخــرى أضــاف املدعــي قائــا‪ :‬بأننــي متنــازل عــن املطالبــة‬\n\n\n                                                                                       ‫‪140‬‬\n\f      ‫بقيمــة الزجــاج‪ ،‬ويف جلســة أخــرى قــال املدعــي عنــد ســؤاله عــن‬\n      ‫التجهيــزات اإلضافيــة وهــي كالتالــي‪ :‬أوال‪/‬ســلطانية صغيــرة عــدد ‪21‬‬\n      ‫ســعر الواحــدة خمســة عشــر ريــال املجمــوع ثالثمائــة وخمســة عشــر‬\n      ‫ريــال‪ .‬ثانيا‪/‬أربعــة أباريــق شــاي كبيــر ســعر اإلبريــق أربعــون ريــال‬\n      ‫املجمــوع مائــة وســتون ريــال‪ .‬ثالثا‪/‬عــدد اثنــن درام زبالــة للمطبــخ مببلــغ‬\n      ‫اثنــان وثالثــون ريــال‪ .‬رابعا‪/‬ثالثــة عشــر فرشــات تنظيــف حمــام ســعر‬\n      ‫الواحــدة عشــرة ريــاالت مببلــغ مائــة وثالثــون ريــال‪ .‬خامســا‪/‬عدد اثنــن‬\n      ‫ســرير معدنــي مــع فرشــة ســعر الواحــدة مائــة وســبعون ريــال املجمــوع‬\n      ‫ثالثمائــة وأربعــون ريــال‪ .‬سادســا‪/‬عدد ‪ 52‬شرشــف فيتــو ســعر الواحــد‬\n      ‫ســتة وســتون ريــال واملجمــوع ثالثــة آالف وأربــع مائــة واثنــان وثالثــون‬\n      ‫ريــال‪ ،‬ومجمــوع قيمــة هــذه الزيــادات أربعــة آالف وأربعمائــة وتســعة‬\n      ‫ريــاالت وهــذه الزيــادات موضحــة يف بيــان التســليم باإلضافــة إلــى‬\n      ‫الزيــادات املوضحــة يف هــذا البيــان‪ ،‬وقــدم بيــان موضــح يف تســعة عشــر‬\n      ‫صنفــا ومجمــوع قيمتهــا مــع مــا ســبق أعــاه ســتة عشــر ألــف وثالثمائــة‬\n      ‫وتســعة وتســعون ريــال‪ ،‬وجــرى عــرض مــا ذكــره املدعــي والبيــان املشــار‬\n      ‫إليــه أعــاه علــى املدعــى عليــه فأجــاب قائــا‪ :‬أطلــب تســليمي صــورة‬\n      ‫منهــا وإمهالــي لإلجابــة علــى ذلــك‪ ،‬ويف جلســة أخــرى حضــر املدعــي‬\n      ‫ولــم يحضــر املدعــى عليــه‪ ،‬وطلــب مــن املدعــي البينــة علــى التجهيــزات‬\n      ‫اإلضافيــة أبــرز الوثيقــة املعنونــة الشــركة ‪ .......................‬املؤرخــة يف‬\n      ‫‪1419/6/27‬ه املوافــق ‪1998/10/17‬م وهــذا نصهــا‪( :‬محضــر اســتالم‬\n      ‫شــاليهات الترفيــه أنــه يف يــوم الســبت واألحــد املوافقــن ‪ 4/3‬أكتوبــر‬\n      ‫‪1998‬م ثــم جــرد شــاليهات الترفيــه بكامــل مرفقاتهــا وملحقاتهــا‬\n      ‫وبجميــع جتهيزاتهــا ومحتوياتهــا متهيــدا لعمليــة التســليم واالســتالم فيمــا‬\n\n\n‫‪141‬‬\n\f‫بــن الشــركة املالكــة للشــاليهات ومســتثمرها ‪ .........................‬وقــد‬\n‫تكونــت جلنــة اجلــرد لهــذا الغــرض مــن الطرفــن علــى النحــو التالــي‪/1 :‬‬\n‫الشــركة املالكــة (الشــركة ‪ )................‬الســيد‪ ............./‬والــس‬\n‫يــد‪ ............................/‬والســيد‪ ......................./‬والســيد‪....................../‬‬\n‫‪/2‬املســتثمر ‪/‬الســيد ‪ .......................‬والســيد ‪ .................‬والســيد‬\n‫‪.................‬هــذا وقــد مت اجلــرد بالفعــل خــال اليومــن املشــار إليهــا‬\n‫أعــاه‪ ،‬وتبــن بعــض النواقــص واملفقــودات مــن جتهيــزات الشــاليهات‪،‬‬\n‫وقــد مت إدراجهــا بالبيانــات املرفقــة‪ ،‬وعليــه فقــد اســتلمت الشــركة‬\n‫‪ ..............‬الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا‬\n‫باإلضافــة لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر‬\n‫وتعتبــر مــن التاريــخ املذكــور أعــاه بحوزتهــم وحتــت مســئوليتهم‬\n‫وتصرفهــم ولــم يعــد للمســتثمر أي عالقــة بالشــاليهات مــا عــدا النواقــص‬\n‫واملفقــودات مــن التجهيــزات واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات‬\n‫اجلــرد املرفقــة واملوقعــة مــن قبــل الطرفــن وعلــى أن يكــون اســتكمال‬\n‫النواقــص واملفقــودات إمــا باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة‬\n‫ال تقــل عنهــا جــودة وإن تعــذر ذلــك فيتــم تقييــم أســعار كل منهــا حســب‬\n‫مــا جــاء يف بيانــات اســتالمها يف العــام املاضــي مــع مراعــاة العمــر‬\n‫االفتراضــي حســبما ورد بالعقــد‪ ،‬أمــا مــن حيــث النواحــي املالية فســوف‬\n‫تتــم التســويات واملطالبــات املاليــة بــن الطرفــن كل فيمــا يخصــه بعــد‬\n‫التوقيــع علــى هــذا احملضــر مباشــرة واهلل املوفــق‪ ،‬املســتثمر توقيعــه‬\n‫‪ ................‬عــن الشــركة ‪ .................‬توقيــع ‪ .................‬نائــب املديــر‬\n‫العــام) أ‪.‬هــ‪ ،‬ويف جلســة أخــرى قــال املدعــى عليــه إجابــة عــن فواتيــر‬\n‫التجهيــزات التــي أبرزهــا املدعــي‪ :‬إن املدعــي اســتأجر الشــاليهات وهــي‬\n\n\n                                                                                                     ‫‪142‬‬\n\f      ‫مؤثثــة ومجهــزة بالكامــل وقــد عايــن الشــاليهات فوجدهــا صاحلــة‬\n      ‫لالســتخدام واســتلمها علــى تلــك احلــال‪ ،‬ثانيا‪/‬التــزم باحملافظــة علــى‬\n      ‫الشــاليهات ومــا يتبعهــا مــن منقــوالت ومعــدات وأجهــزة وأن يســلمها‬\n      ‫باحلــال التــي تســلمها بهــا‪ .‬ثالثا‪/‬تتحمــل املســؤولية الكاملــة عنــد وجــود‬\n      ‫أي ضــرر ال قــدر اهلل‪ .‬رابعا‪/‬يتحمــل جميــع أعمــال الصيانــة بالكامــل‬\n      ‫وال يوجــد يف تلــك الفواتيــر مــا يفيــد أنــه مت شــراؤها بنــاء علــى طلبهــا‪،‬‬\n      ‫أو أننــا تســلمنا محتويــات تلــك الفواتيــر بالتالــي ال نقــر بهــا‪ ،‬أمــا بالنســبة‬\n      ‫للهواتــف فــإن العقــد مــع املدعــي نــص علــى أن أي إضافــة إلــى املشــروع‬\n      ‫مــن املدعــي يجــب أن يأخــذ موافقــة موكلتــي عليهــا خطيــا وحيــث أن‬\n      ‫األصــل أخــذ العقــد علــى ظاهــره مــا لــم يثبــت املدعــي ذلــك‪ ،‬فــإذا كان‬\n      ‫لــدى املدعــي البينــة علــى أنــه اتفــق مــع موكلتــي علــى إدخــال الهاتــف‬\n      ‫بــأي طريقــة فليقدمهــا‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬إن‬\n      ‫التجهيــزات اإلضافيــة اعترفــوا بهــا وســلمت لهــم مبوجــب محضــر‬\n      ‫التســليم املــؤرخ يف ‪1419/6/27‬ه ـ وســبق تقــدمي صــورة يف احملضــر ومــا‬\n      ‫ذكــره املدعــى عليــه مــن أن أعمــال الصيانــة علـ ّـي‪ ،‬فــإن أعمــال الصيانة‬\n      ‫قــد حتولــت علــى الشــركة مبوجــب عقــد وهــي املســؤولة عــن الصيانــة‪،‬‬\n      ‫وأمــا بالنســبة للهاتــف فإنــه مت تأمينــه وذلــك حســب محضــر االجتمــاع‬\n      ‫يف يــوم األربعــاء املوافــق ‪1997/9/3‬م وهــي موافقــة خطيــة من الشــركة‬\n      ‫حســب مــا جــاء يف العقــد‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه مــع تســليمه‬\n      ‫صــورة مــن محضــر االجتمــاع ومحضــر اســتالم شــاليهات الترفيــه أجــاب‬\n      ‫قائــا‪ :‬بالنســبة حملضــر إيصــال الهاتــف فإننــي أطلــب إمهالــي ملراجعــة‬\n      ‫موكلتــي‪ ،‬وأمــا بالنســبة حملضــر االســتالم فإنــه ذكــر فيــه أنــه يوجــد‬\n      ‫نواقــص ومفقــودات مــن التجهيــزات واملــواد اخلاصــة بالصيانــة‪ ،‬وال أعلــم‬\n\n\n‫‪143‬‬\n\f‫هــل مت تأمــن هــذه النواقــص واملفقــودات كمــا أشــار باحملضــر أنــه مت‬\n‫اســتالم أغــراض وجتهيــزات مســتكملة مــن قبــل املســتثمر‪ ،‬وال أعلــم‬\n‫هــل هــذه التجهيــزات هــي نفــس التجهيــزات التــي قــدم فواتيرهــا‬\n‫املدعــي‪ ،‬وأحتــاج إلــى الرجــوع إلــى البيــان املشــار إليــه‪ ،‬وقــد أضــاف‬\n‫املدعــي‪ :‬إن جميــع النواقــص واملفقــودات مت تأمينهــا ومعاجلتهــا مــع‬\n‫الشــركة يف وقتهــا واملدعــى عليــه ليــس لــه دخــل يف النواقــص؛ ألننــي‬\n‫أنــا املدعــي‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبطلبنــا اجلــواب مــن‬\n‫املدعــى عليــه عــن اخلطــاب املــؤرخ يف ‪2007/9/25‬م وقــد جــاء فيــه بعــد‬\n‫املقدمــة‪ :‬أوال‪/‬بخصــوص النواقــص واملفقــودات حســب احملضــر املوقــع‬\n‫مــن املدعــي ‪ ........................‬بتاريــخ ‪1419/9/27‬هــ‪ ،‬عليــه يجــب علــى‬\n‫املدعــي إثبــات أن األغــراض والتجهيــزات املســتكملة مــن قبلــه هــي‬\n‫نفــس النواقــص واملفقــودات مــن التجهيــزات وفقــا لبيانــات اجلــرد املرفقة‬\n‫واملوقعــة بــن الطرفــن‪ .‬ثانيا‪/‬بخصــوص تكلفة تأســيس هاتف مشــروع‬\n‫شــاليهات الترفيــه حســب احملضــر املوقــع مــن املدعــي ‪........................‬‬\n‫بتاريــخ ‪1997/9/3‬م عليــه فــإن الشــركة تلتــزم بتحمــل نســبة ‪% 75‬مــن‬\n‫تكلفــة تأســيس هاتــف مشــروع شــاليهات الترفيــه هــذا يف حالــة إذا‬\n‫كان لــدى املدعــي مــا يفيــد فعــا بأنــه قــام بتأســيس هاتــف املشــروع‬\n‫واعتمــاد التكلفــة مــن قبــل إدارة الشــركة‪ ،‬وبعــرض ذلــك علــى املدعي‬\n‫أجــاب قائــا‪ :‬بأننــي ســبق وأن أجبــت أن جميــع النواقــص واملفقــودات مت‬\n‫تأمينهــا ومعاجلتهــا مــع الشــركة يف وقتهــا واملدعــى عليهــم ليــس لهــم‬\n‫دخــل يف النواقــص؛ ألننــي أنــا املدعــي وأطالــب بقيمــة التجهيــزات‬\n‫اإلضافيــة التــي قمــت بتكميلهــا‪ ،‬وأمــا بالنســبة للهاتــف قــد مت تأمينــه‬\n‫مــن قبلــي وبعــد خروجــي مــن املشــروع مت تســليم املشــروع لهــم والهاتــف‬\n\n\n                                                                                     ‫‪144‬‬\n\f      ‫ضمــن املشــروع‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬إن مــا‬\n      ‫ذكــره املدعــي يف أن النواقــص واملفقــودات مــن التجهيــزات مت تأمينهــا‬\n      ‫ومعاجلتهــا مــع الشــركة فهــذا الــكالم يحتــاج إلــى تثبــت‪ ،‬فنطلــب فيــه‬\n      ‫إثباتــه‪ ،‬وكذلــك الهاتــف نطلــب منه ما يفيد تأمينه وتســليمه للشــركة‬\n      ‫بعــد خروجــه‪ ،‬وأمــا بالنســبة للتجهيــزات أطلــب إمهالــي ملراجعــة‬\n      ‫الشــركة‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬أن النواقــص‬\n      ‫واملفقــودات مت معاجلتهــا مبوجــب إثباتــات ومحاضــر مســجله بدفاتــري‬\n      ‫ودفاتر الشــركة والهاتف مت تركه يف إدارة الشــاليهات ومت اســتعماله‬\n      ‫مــن قبــل الشــركة واملســتثمر الــذي اســتأجر بعــدي‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر الطرفــان وبطلــب اجلــواب مــن املدعــى عليــه أجــاب قائــا‪ :‬بأننــي‬\n      ‫راجعــت الشــركة وأفــادت بأنــه ال يوجــد لديهــا أي معلومــات خاصــة‬\n      ‫بالتجهيــزات اإلضافيــة‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬بــأن‬\n      ‫الشــركة قــد أقــرت باســتالم األغــراض والتجهيــزات املســتكملة مــن‬\n      ‫قبلنــا بصفــة عامــة وذلــك حســب محضــر االســتالم املــؤرخ يف‬\n      ‫‪1419/6/27‬ه ـ املوافــق ‪1998/10/17‬م‪ ،‬وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه أجــاب قائــا‪ :‬إن هــذا احملضــر مرفــق بــه بيانــات والبيانــات ال‬\n      ‫توجــد لــدى موكلتــي صــورة منهــا حيــث أنــه مضــى عليــه أكثــر مــن‬\n      ‫عشــر ســنوات والبحــث يصعــب يف ذلــك‪ ،‬وطلــب مــن املدعــي رقــم‬\n      ‫الهاتــف الــذي مت تأمينــه فأجــاب قائــا‪ :‬بأنــه مت تأمــن هاتفــن ومت‬\n      ‫اســتئجار ســطح مبنــى يف الظهــران لتثبيــت اجلهــاز مبنطقــة الظهــران؛‬\n      ‫ألنــه أقــرب نقطــة إلــى موقــع الشــاليهات‪ ،‬ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان وأجــاب املدعــي قائــا‪ :‬أنــه مت تأســيس خطــن هاتــف ثابــت‬\n      ‫رقــم ‪ 8611567‬ورقــم ‪ 8611491‬قيمــة اجلهازيــن ســتة عشــر ألــف ريــال‬\n\n\n‫‪145‬‬\n\f ‫حيــث مت دفــع الثمــن مبوجــب الشــيك رقــم ‪ 237‬يف ‪1997/10/20‬م علــى‬\n ‫البنك ‪ .....‬لشــركة ‪ .........‬وشــريكه مببلغ عشــرة آالف ريال‪ ،‬والشــيك‬\n ‫الثانــي علــى شــركة ‪ ......‬برقــم ‪ 188‬وتاريــخ ‪1418/9/22‬ه ـ واملوافــق‬\n ‫‪1998/1/20‬م مببلــغ وقــدره ســتة آالف ريــال لشــركة ‪.............‬‬\n ‫وشــريكه‪ ،‬وقــد دون علــى الشــيك األول عبــارة نصهــا‪( :‬دفعــه مقــدم‬\n ‫مــن قيمــة جهــاز هوائــي ألكــون عــدد اثنــن خــط مــع التركيــب‬\n ‫والتشــغيل والضمــان والصيانــة ســنة) ودون علــى الشــيك الثانــي‪( :‬باقــي‬\n ‫قيمــة عــدد اثنــان جهــاز هاتــف هوائــي ماركــة ألكــون مــع التركيــب‬\n ‫والتشــغيل والضمــان)‪ .‬ثانيــا‪  :‬قيمــة االشــتراكات الشــهرية الرســوم‬\n ‫الثابتــة لــكال اخلطــن ولكامــل املــدة مــن بدايــة اســتخدامهما يف‬\n‫‪1418/10/10‬ه ـ وحتــى ألغاهمــا  يف ‪1424/2/10‬ه ـ أربعــة وســتني ‬\n ‫شــهرا عــدد اثنــن هاتــف ضــرب أربعــة وســتني ضــرب خمســة وأربعــن‬\n ‫ريــال شــهريا النــاجت خمســة آالف وســبعمائة وســتون ريــال إجمالــي‬\n ‫التكاليــف واحــد وعشــرون ألــف وســبعمائة وســتون ريــال تتحمــل‬\n ‫الشــركة مبوجــب االتفــاق ‪ % 75‬املطلــوب ســتة عشــر ألــف وثالثمائــة‬\n ‫وعشــرون ريــال‪ ،‬وأرفــق أصــل فواتيــر الهاتــف مــن البدايــة حتــى النهايــة‬\n ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬أطلــب تســليمي صــورة‬\n ‫منهــا وإمهالــي لإلجابــة عليهــا‪ ،‬ويف جلســة أخــرى حضــر الطرفــان‬\n ‫وبطلــب اجلــواب مــن املدعــى عليــه قــدم مذكــرة جــاء فيهــا مــا نصــه‪:‬‬\n ‫(أوال‪/‬ذكــر املدعــي يف خطابــه املــؤرخ يف ‪1429/11/20‬ه ـ الــذي قدمه‬\n ‫يف اجللســة املشــار إليهــا أعــاه أنــه قــام بتركيــب هاتــف هوائــي وذكــر‬\n ‫تكاليــف ذلــك (حســب رأيــه) وبالرجــوع إلــى محضــر االجتمــاع املــؤرخ‬\n ‫يف ‪1997/9/3‬م املوقــع مــن املدعــي أصالــة ورئيــس مجلــس إدارة‬\n\n\n                                                                                   ‫‪146‬‬\n\f      ‫الشــركة ‪ ........‬جنــده نــص يف الفقــرة (‪ )2‬منــه علــى أن تتكفــل‬\n      ‫الشــركة مبــا قيمتــه ‪ % 75‬مــن تكلفــة تأســيس هاتــف مشــروع‬\n      ‫الشــاليهات و‪ % 25‬يتحملهــا املســتثمر ‪ ........................./‬املدعــي علــى أن‬\n      ‫يــؤول جميــع ذلــك فيمــا بعــد إلــى الشــركة ‪ ،................‬ومــن هــذا النــص‬\n      ‫يتضــح لفضيلتكــم أن املقصــود تأســيس هاتــف يف املشــروع وليــس مــا‬\n      ‫ذكــره املدعــي والفــرق بينهمــا كبيــر وظاهــره فالتأســيس شــيء‬\n      ‫واالســتفادة مــن خدمــة قائمــة شــيء آخــر مختلــف متامــا ال ســيما وأنــه مت‬\n      ‫النــص علــى انتقــال جميــع ذلــك إلــى املدعــى عليــه‪ .‬ثانيا‪/‬مــع مــا ذكرنــاه‬\n      ‫أعــاه فــإن مــا قدمــه املدعــي مــن صــور فواتيــر ال يفيــد بــأن الهواتــف مت‬\n      ‫اســتخدامها للشــاليهات ال ســيما وأنها باســمه الشــخصي والذي يؤكد‬\n      ‫ذلــك أنــه اســتمر يف اســتخدامها إلــى تاريــخ ‪1424/2/10‬ه ـ مــع أنه ســلم‬\n      ‫املوقــع بتاريــخ ‪1419/6/27‬ه ـ مبــا يدحــض  قولــه بــأن هــذه الهواتــف هي‬\n      ‫للشــاليهات‪ .‬ثالثا‪/‬يطلــب املدعــي قيمــة األجهــزة مــع حتفظنــا علــى هــذه‬\n      ‫املطالبــة ويف الوقــت نفســه لــم يلتــزم مبــا نصــت عليــه الفقــرة (‪ )2‬مــن‬\n      ‫احملضــر املشــار إليــه أعــاه والتــي نصــت علــى ( أن يــؤول جميــع ذلــك إلى‬\n      ‫املدعــى عليهــا ) علــى فرضيــة أن قــول املدعــي باالســتفادة مــن هواتــف‬\n      ‫خاصــة بــه هــو املتفــق عليــه مــع املدعــى عليهــا وهــو غيــر صحيــح‪ .‬رابعــا‪/‬‬\n      ‫يطالــب املدعــي يف خطابــه املذكــور أعــاه بإلــزام املدعــى عليهــا بدفــع‬\n      ‫قيمــة اشــتراكات اخلطــن للهاتفــن مــن تاريــخ ‪1418/10/10‬هــ  وحتــى‬\n      ‫تاريــخ ‪1424/2/10‬ه ـ وهــذا جتــاوز للحــق الظاهــر حيــث أن املدعــي‬\n      ‫ســلم املوقــع بتاريــخ ‪1419/6/27‬ه وبالتالــي فليــس لــه احلــق يف املطالبــة‬\n      ‫بقيمــة اشــتراكات ‪ 45‬شــهرا بينمــا املــدة احلقيقيــة ال تتجــاوز ثمانيــة‬\n      ‫أشــهر‪ .‬خامســا‪/‬كيف يصــح للمدعــي املطالبــة بقيمــة اشــتراكات‬\n\n\n‫‪147‬‬\n\f‫شــهرية للهواتــف يف الوقــت الــذي هــو املســتفيد منهــا ســواء علــى فتــرة‬\n‫الثمانيــة أشــهر التــي متثــل املــدة احلقيقيــة التــي بــدأت مــن إدخــال الهواتــف‬\n‫حســب قولــه وانتهــت بتســليمه املوقــع‪ ،‬أو اخلمســة وأربعــن شــهرا التــي‬\n‫ذكرهــا‪ ،‬ممــا تقــدم يتضــح لكــم أن مطالبــة املدعــي غيــر صحيحــة‬\n‫وتســتند إلــى فهــم املدعــي الــذي يخالــف املســتندات والواقــع‪ ،‬لــذا فــإن‬\n‫موكلتــي تطلــب مــن فضيلتكــم رد مطالبــة املدعــي) أ‪.‬هــ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعــي أجــاب قائــا‪ :‬إن الهــدف هــو إيصــال اخلدمــة الســريعة‬\n‫للمشــروع وقــد مت حتقــق ذلــك وكان وقــت التنفيــذ هــي اخلدمــة املتاحــة‬\n‫ويعتبــر ذلــك مبثابــة التأســيس ولــو لــم يوجــد ذلــك التخــذ طريــق آخــر‪،‬‬\n‫ومحضــر التأســيس لــم يفــرق بــن ثابــت أو هوائــي وأن الهاتفــن منــذ‬\n‫تأسيســهما اســتخدمتها للمشــروع ولــم يتــم اســتخدامهما بصفــة‬\n‫شــخصية ومت االحتفــاظ بالهواتــف ورأينــا إبقائهــا حيــث أن القضيــة‬\n‫منظــورة باحملكمــة وملــا طالــت مت إلغاءهمــا والهاتفــن الوســيلة الوحيدة‬\n‫املســتخدمة يف املشــروع‪ ،‬وســمع ذلــك املدعــى عليــه وقــال مــا ذكــره‬\n‫املدعــي مــن أن اخلدمــة الوحيــدة هــي الهاتــف الهوائــي‪ :‬هــذا غيــر صحيــح‬\n‫حيــث يوجــد خدمــة التأســيس ولــو رأت موكلتــي اســتبدال خدمــة‬\n‫التأســيس بخدمــة أخــرى لنــص عليهــا ومــا ذكــره مــن أنــه اســتخدم‬\n‫الهواتــف حتــى مت إلغائهــا يف عــام ‪1424‬ه ـ هــذا يتناقــض مــع الواقــع ومــع‬\n‫محضــر تســليم املشــروع حيــث ســلم املشــروع يف ‪1419/6/27‬هــ‪،‬‬\n‫وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬إننــي لــم أذكــر أنهــا الوســيلة‬\n‫الوحيــدة وإمنــا هــي الوســيلة املتاحــة الســريعة لالســتفادة مــن املشــروع‬\n‫بصفــة عاجلــة وإن ذلــك يعتبــر مبثابــة التأســيس والهاتفــن لــم يتــم‬\n‫اســتخدامهما بعــد تســليم املشــروع ومت دفــع رســوم االشــتراك فقــط‪،‬‬\n\n\n                                                                                          ‫‪148‬‬\n\f      ‫وأضــاف املدعــى عليــه قائــا‪ :‬أن املدعــي أقــر بــأن هــذه اخلدمــة ليســت‬\n      ‫تأســيس وإمنــا هــي خدمــة بديلــة وهــذا خــاف االتفــاق مــع موكلتــي‪،‬‬\n      ‫ويف جلســة أخــرى لــدي أنــا ‪ .......................‬القاضــي اخللــف باملكتــب‬\n      ‫القضائــي ‪ .....‬وقــد جــرى مناقشــة املدعــي حــول بعــض اإلشــكاالت يف‬\n      ‫القضيــة فأبــدى اســتعداده لإلجابــة عنهــا محــررة ‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر املدعــي ‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــة‬\n      ‫‪ ................‬وقــدم املدعــي أصالــة مذكــرة مكونــة مــن ســبع صفحــات‬\n      ‫مــع عــدد مــن املرفقــات وفيهــا إجابــة عــن بعــض اإلشــكاالت التــي‬\n      ‫طــرأت‪ ،‬وهــذا نصهــا‪( :‬جتــدون أدنــاه أجوبــه لالستفســارات املطروحــة‬\n      ‫علــي مــن قبــل فضيلتكــم باجللســة املنعقــدة يف يــوم ‪1431/12/28‬ه ـ‬\n      ‫لنظــر القضيــة التــي رفعتهــا ضــد الشــركة ‪ ...................‬فقــد ســألني‬\n      ‫فضيلتكــم عــن ســبب طلبــي إيجــار الســنة األولــى وأجــرة الصيانــة‬\n      ‫فأقــول‪ :‬إنــه ال يخفــى علــى فضيلتكــم بــأن عقــدي مــع الشــركة عقــد‬\n      ‫اســتثماري وليــس عقــد ســكني والفــرق بينهمــا ظاهــر فعقــد االســتثمار‬\n      ‫تخويــل بالبحــث عــن مســتأجرين آخريــن (طــرف ثالــث) لالنتفــاع‬\n      ‫باملأجــور وذلــك عــن طريــق الدعايــة والترغيــب والعــرض والتســويق مــع‬\n      ‫توفيــر الصيانــة والتشــغيل وأي إعاقــة تعتــرض خطــة اســتثماره تؤثــر‬\n      ‫ســلبا يف تشــغيله وتكــون ســببا مباشــر يف خســارته‪ ،‬وعليــه فبعدمــا‬\n      ‫وقعــت مــع الشــركة عقــد إيجــار الشــاليهات وقعــت عقــد صيانتهــا‪،‬‬\n      ‫فصــارت بذلــك هــي املســؤولة الوحيــدة عــن أي تقصيــر يحــول دون منفعة‬\n      ‫اســتثمار الشــاليهات وقــد جعــل يف مــدة هذيــن العقديــن مــا يلــي‪/1 :‬‬\n      ‫هبــوط يف أرضيــات وممــرات الشــاليهات وتشــققات يف اجلــدران وحرصا‬\n      ‫منــي علــى ســامة مبنــى املشــروع وســامة مرتاديــه والعاملــن فيــه‬\n\n\n‫‪149‬‬\n\f‫استشــرت يف حالتــه االنشــائية جهــة هندســية متخصصــة وبعــد معاينــة‬\n‫املهندســن للموقــع أثبتــوا حالتــه املعيبــة بتقريرهــم املرفــق لفضيلتكــم‬\n‫صــورة منــه وعلــى ضــوء ذلــك أشــعرت الشــركة بخطــورة ذلــك يف وقــت‬\n‫مبكــر مرفقــا لهــم صــورة مــن التقريــر الهندســي‪ ،‬وبنــاء عليــه كتبــت‬\n‫الشــركة للمقــاول املنفــذ للمشــروع تعتــرف فيــه بخطــورة وضــع‬\n‫الشــاليهات وحتملــه كافــة املســؤولية ولعــل العيــوب اإلنشــائية التــي‬\n‫أثبتتهــا اجلهــة االســتثمارية احملايــدة واخلطــورة التــي اعترفــت بهــا‬\n‫الشــركة للمقــاول املنفــذ همــا الســبب الــذي جعــل الشــركة تفســخ‬\n‫العقــد برغبتهــا لعلمهــم أن العقــد الزم مــا لــم يطــرأ عليــه عــذر مينــع مــن‬\n‫االنتفــاع باملأجــور‪/2 .‬حصــل إهمــال مــن متعهــد الصيانــة (الشــركة‬\n‫‪ )..............‬خلزانــات امليــاه ومضخاتهــا التــي كانــت تفيــض بامليــاه احملالة‬\n‫ليــا وتصــب هــدرا مــارة بطــرق ومشــايات الشــاليهات أهملناهــا بذريعــة‬\n‫أنهــا لــم تكلــف الطاقــم الفنــي بالصيانــة بالعمــل يعــد الــدوام الرســمي‬\n‫ملدينتهــم لأللعــاب‪/3 .‬أهملــت الشــركة صيانــة الزراعــة ورعايــة‬\n‫املســطحات اخلضــراء ونبتــت حــول البحيــرة جــراء اإلهمــال أحــواش‬\n‫موحشــة تخيــف نــزالء الشــاليهات كمــا أهملــت رش املبيــدات احلشــرية‬\n‫حتى صارت الشــاليهات وحدائقها مرتفعا خصبا للقوارض واحلشــرات‪.‬‬\n‫‪/4‬امتنعــت الشــركة عــن صيانــة  وإصــاح أعطــال أجهــزة  االتصــال‬\n‫الهاتفيــة وأجهــزت اســتقبال القنــوات الفضائيــة متذرعــة بأنهــا ال متتلــك‬\n‫األرقــام الســرية لألجهــزة والتــي بدونها يتعذر عمــل أي صيانة‪ ،‬فاملقاول‬\n‫الــذي قامــوا بتعميــده لتنفيــذ أعمــال االتصــاالت هــو وحده الــذي يحتفظ‬\n‫باألرقــام ويرفــض قطعــا اطالعنــا عليهــا وهــذا الرفــض والتعنــت مــن‬\n‫قبــل الشــركة ومــن املقــاول املنفــذ يفــرغ القاعــدة الفقهية مــن مضمونها‬\n\n\n                                                                                       ‫‪150‬‬\n\f       ‫وهــي‪ :‬إلــزام املؤجــر بتمكــن املســتأجر مــن االنتفــاع بالعــن املعقــود‬\n       ‫عليهــا وذلــك بتســليمه العــن ومســتلزماتها حســب العــرف كاملفاتيــح‬\n       ‫واألرقــام ونحوهــا والتــي ال ميكــن حتقيــق االنتفــاع املطلــوب إال بهــا‪،‬‬\n      ‫كمــا ال يخفــى علــى فضيلتكــم أنــه إذا انصرمــت مــدة مــن غيــر متكني ‬\n       ‫املســتأجر مــن االنتفــاع باملعقــود عليــه ال يســتحق املؤجــر شــيئا مــن‬\n       ‫األجــرة ولــو مضــى مــن العقــد مــدة قبــل التمكني وهذا احلكم ينســحب‬\n       ‫علــى مبلغــي إيجــار الشــاليهات وصيانتهــا لعــدم انفــكاك أحدهمــا علــى‬\n       ‫اآلخر‪ ،‬وجاء يف عقد الشــاليهات بند (‪ )18‬يســمح  لشــاغلي الشــاليهات‬\n       ‫بالدخــول ملدينــة األميــر محمــد بــن فهــد ويتــم ربطهــا مــع برامــج تســويقية‬\n       ‫مشــتركة وعمــل حوافــز للســكان يتــم االتفــاق عليهــا مــع مراعــاة‬\n       ‫إمكانية ذكر الشــاليهات يف إعالنات الشــركة الشــيخ‪................... /‬‬\n       ‫وبحضــور مديــر عــام الشــركة الســيد ‪ ..................‬التــزم لــي شــفاهه‬\n       ‫رئيــس مجلــس اإلدارة بتحميــل الشــركة مــا نســبته ‪ % 25‬مــن مصاريــف‬\n       ‫الدعايــة التــي ســوف أصرفهــا علــى الشــاليهات‪ ،‬فــكل هــذا اإلهمــال‬\n       ‫والتقصيــر مــن قبــل الشــركة إخــال بعقــدي التأجيــر والصيانــة‬\n       ‫باإلضافــة للنكــوص عمــا يتــم االلتــزام بــه أثنــاء اجتماعــي بهــم ويف ثنايــا‬\n       ‫مكاتبتــي لهــم فصــارت الشــركة ســببا مباشــرا يف فشــل اســتثماري‬\n       ‫ملشــروع الشــاليهات بــل هــو الســبب املتعمــد والوحيــد ونتيجــة لذلــك تعذر‬\n       ‫احلصــول علــى منفعــة االســتثمار التــي مت التعاقــد‪ ،‬وعليــه تكــون‬\n       ‫الشــركة هــي املتســبب يف خســارتي وهــي الغــارم الوحيــد املبلــغ إليجــار‬\n       ‫والصيانــة‪ ،‬وعــن ســؤال فضيلتكــم عــن صحــة اســتالم الشــركة‬\n       ‫لألجهــزة اإلضافيــة وهــل  وقعــت الشــركة علــى االســتالم‪ ،‬فأقــول‪ :‬نعــم‬\n       ‫لقد اســتلمت الشــركة ‪ ..............‬األجهزة اإلضافية التي قمت بتأمينها‬\n\n\n‫‪151‬‬\n\f‫مــن حســابي اخلــاص ووقــع علــى االســتالم نائــب مديــر عــام الشــركة‬\n‫أ‪ ......../‬وذلــك ضمــن محضــر اســتالم الشــاليهات والــذي جــاء فيــه مــا‬\n‫نصــه‪( :‬وعليــه فقــد اســتلمت الشــركة ‪ ............‬ملراكــز الترفيــه‬\n‫الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة‬\n‫لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر وتعتبــر مــن‬\n‫تاريــخ ‪1419/6/27‬ه ـ املوافــق ‪1998/10/17‬م بحوزتهــم وحتــت‬\n‫ـدي مــا ُيثبــت أن الهواتــف‬ ‫مســئوليتهم)‪ ،‬وعــن ســؤال فضيلتكــم هــل لـ ّ‬\n‫اســتخدمت يف الشــاليهات فأقــول‪ :‬إنــه ال يخفــى علــى فضيلتكــم بــأن‬\n‫شــركة ‪ .....‬هــي القــادرة علــى اإلجابــة علــى هــذا الســؤال إمــا مــن خــال‬\n‫تركيــب اخلدمــة الهاتفيــة باملوقــع أو مــن خــال الفواتيــر ومبــا أنــه لــم‬\n‫تتوفــر آنــذاك فقــد وفــرت خدمــة هاتفيــة هوائيــة كالتــي تســتخدم يف‬\n‫املــزارع واملناطــق البعيــدة عــن املدينــة وبعــد إنهــاء التعاقــد تركــت‬\n‫أجهــزت االتصــال الهوائيــة يف الشــاليهات‪ ،‬أمــا رقمــي الهاتــف التــي‬\n‫باســمي فقــد أبقيتهــا ســارية املفعــول أدفــع لهــا رســوم اشــتراك شــبكة‬\n‫فقــط وكنــت منتظــرا إمــا أن تقــوم الشــركة ‪ ..............‬بنقــل األرقــام‬\n‫باســمها وإمــا أمــر القاضــي بقطــع االشــتراك وقــد مت إيقــاف االشــتراك‬\n‫بتاريــخ ‪1424/3/26‬هــ‪ ،‬وعــن ســؤال فضيلتكــم عــن املخالصــة التــي‬\n‫متــت بــن الطرفــن هــل فيهــا قيــود أم مخالصــة مطلقــة فأقــول إننــي ال‬\n‫أعلــم الفــرق بــن املخالصــة املقيــدة مــن املخالصــة املطلقــة لكنــي ســوف‬\n‫أصــف لفضيلتكــم أدنــاه مراحــل وآليــات املخالصــة التــي متــت بيننــا‬\n‫فيمــا يلــي‪/1 :‬جــاء يف التمهيــد لعقــد اإليجــار مــا نصــه‪( :‬إن الطــرف‬\n‫الثانــي (املســتثمر) لديــه الرغبــة األكيــده يف اســتثمار هــذا املشــروع)‪،‬‬\n‫وجــاء يف البنــد رقــم (‪  )10‬أن أعمــال الصيانــة تقــع علــى عاتــق املســتثمر‬\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫مــع االلتــزام يجــدول صيانــة وقائــي وكفائــه عاليــه مــع التفتيــش‬\n      ‫والتوجيهــات مــن فعــل الطــرف األول‪ ،‬ومثلــه البنــد (‪ )11‬امللــزم بصيانــة‬\n      ‫املســطحات اخلضــراء واحملافظــة علــى نظــام الــري وبركــة الســباحة‬\n      ‫وبعــد عقــد الصيانــة الالحــق لعقــد تأجيــر الشــاليهات انقلبــت شــروط‬\n      ‫الصيانــة علــى الطــرف األول (الشــركة ) فمــا كان يف العقــد  واجبــا‬\n      ‫للطــرف الثانــي صــار حقــا لــه ومــا كان حــق للطــرف األول صــار واجبــا‬\n      ‫عليــه وجــاء يف البنــد (‪( )12‬ويف حالــة وجــود أي عيــوب يف املشــروع‬\n      ‫يتحمــل الطــرف األول إصالحهــا) وبعــد إشــعاري للشــركة خطيــا‬\n      ‫بالعيــوب اإلنشــائية يف املشــروع والتــي أثبتتهــا اجلهــة املختصــة مبوجــب‬\n      ‫التقريــر الهندســي الــذي أرفقتــه لهــم انتهــت حالــة التعاقــد مــع الشــركة‬\n      ‫وهــم يكاتبــون املقــاول املنفــذ للمشــروع حيــث رآه املســؤولون يف‬\n      ‫الشــركة أن عقــد الصيانــة وإثبــات العيــوب اإلنشــائية حمــل ثقيل عليهم‬\n      ‫ال أحتملــه‪ ،‬فتلمســوا املخــارج واحليــل إلنهــاء التعاقــد وصياغــة‬\n      ‫املخالصــات‪/2 .‬كتبــت لــي الشــركة متهيــدا إلنهــاء التعاقــد خطابــا‬\n      ‫يطلبــون فيــه االجتمــاع بــي ليبلغونــي برغبتهــم يف إنهــاء التعاقــد ويف يــوم‬\n      ‫االجتمــاع مت إنهــاء عقــد اإليجــار بنــاء علــى رغبــة الشــركة وكان‬\n      ‫توقيعــي علــى املخالصــة مــن أجــل إيقــاف الضــرر املتمثــل بســريان مفعــول‬\n      ‫العقــد مــع حجــب املنفعــة مــن املأجــور وقعــت بتحفــظ شــديد علــى حفــظ‬\n      ‫حقوقــي فلــو لــم أوقــع لطالبونــي فــورا بقيمــة إيجــار الســنة اجلديــدة‬\n      ‫فأكــون قــد أخليــت بالبنــد (‪ )23‬فقــرة (ب) والتــي تنــص علــى أنــه إذا‬\n      ‫تأخــر الطــرف الثانــي (املســتثمر) عــن ســداد أي دفعــة مســتحقة يكــون‬\n      ‫للطــرف األول (الشــركة) احلــق يف مصــادرة الضمــان‪ ،‬ثــم تــا  هــذا‬\n      ‫االجتمــاع محضــر جــرد موجــودات ومفقــودات وتســليم املوقــع ومــا زالــت‬\n\n\n‫‪153‬‬\n\f  ‫حقوقــي املاليــة والتعويضيــة معلقــة يف ذمــة الشــركة حتــى تاريخــه ومــا‬\n  ‫زالــت الشــركة متاطــل يف تنفيــذ وتفعيــل الشــرط الــذي ينــص علــى‬\n  ‫التــزام الطرفــن‪( :‬بإمتــام التســويات واملطالبــات املاليــة كل فيمــا يخصه‬\n  ‫بعــد التوقيــع مباشــرة علــى محضــر اســتالم الشــاليهات) ممــا ســبق مــن‬\n  ‫وصــف مراحــل املخالصــة يســتطيع فضيلتكــم باالســتنتاج احلكــم علــى‬\n  ‫املخالصــة بأنهــا مطلقــة أم مقيــدة‪ ،‬وبطلــب فضيلتكــم البينــة علــى أن‬\n  ‫الرصيــف البــري داخــل ضمــن العقــد رغــم أن العقــد منحصــر يف ‪60‬‬\n  ‫شــاليه فأقــول أن العقــد منحصــر يف ‪ 60‬دون ذكــر األلعــاب ودون ذكــر‬\n  ‫ملواقــف الســيارات ودون ذكــر للمســجد ونحــو ذلــك لكنهــا كلهــا‬\n  ‫داخلــة ضمنــا يف العقــد مبــا فيهــا الرصيــف البحــري بــل أن البينــة ظاهــرة‬\n  ‫يف تواتر القرائن املشــاهدة واملكتوبة والتي تثبت اســتحقاق االســتفادة‬\n  ‫مــن الرصيــف البحــري فقــد التــزم لــي رئيــس مجلــس إدارة الشــركة‬\n  ‫بوقــت مبكــر والتــزم معــه نائــب املديــر العــام بســرعة تنفيــذ الرصيــف‬\n  ‫البحــري مبوجــب توقيعهــا علــى محضــر اجتمــاع يــوم األحــد املوافــق‬\n  ‫‪1997/10/19‬م الــذي أوصــى املوقعــون عليــه‪( :‬بإعــادة صبيــة املزلقــان‬\n  ‫لوضعهــا الصحيــح برفعهــا وتســوية قاعدتهــا وترتيبهــا) ممــا تعهــد أيضــا‬\n  ‫مديــر عــام الشــركة شــرحا بخــط يــده علــى خطابــي‪( :‬وأقــول خطابــي‬\n  ‫أنــا) قائــا  لقــد مت توجيــه التعليمــات إلــى الســيد‪/‬مدير املشــاريع‬\n  ‫لالتصــال بالشــركات املختصــة بذلــك إلنهــاء اإلجــراءات ملــا يخــص‬\n‫املوضــوع أعــاه ( إجنــاز الرصيــف البحــري ) وســيتم التنفيذ بعد االتفاق  ‬\n  ‫مــع أحدهــم‪ ،‬وهــل كل ذلــك عبــث ومراوغــة أم التــزام وتعهــد مكتــوب‬\n  ‫وموقــع عليــه وبينــة داحضــة‪ ،‬هــذا باإلضافــة إلــى أن الشــركة خصصت‬\n  ‫بابــا واســعا ركبــت منــه حاجــزا حديــدا علقــت عليــه لوحــة كتبــت فيهــا‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫(مزلــق القــوارب املائيــة ) وحبــث حولــه قطعتــن كبيرتــن مــن اخلرســانة‬\n      ‫املســلحة كل هــذه القرائــن والبينــات كانــت أثنــاء معاينــة املشــروع‬\n      ‫وقبــل التوقيــع علــى عقــد االســتثمار‪ ،‬وعليــه فيكــون عــدم تنفيــذ‬\n      ‫الرصيــف إمــا ســلب حلقوقــي أو مــن بــاب تزيــن الســلعة مبــا ليــس فيهــا‬\n      ‫وهــذا غــش متعمــد وال أظنــه يخفــى علــى فضيلتكــم أن الغــش يدخــل‬\n      ‫املكتســبات‪ ،‬أمــا بخصــوص الســؤال عــن مســوغ طلــب التعويــض عــن‬\n      ‫األربــاح املتوقعــة عــن (‪ )9‬ســنوات فــإن املــادة (‪ )23‬فقــرة ه ـ تقــول‪( :‬إن‬\n      ‫الطــرف األول الشــركة احلــق يف فســخ العقــد يف حالــة عــدم قيــام‬\n      ‫الطــرف الثانــي املســتثمر بأعمــال الصيانــة علــى الوجــه املطلــوب‬\n      ‫ومصــادرة الضمانــات بعــد خصــم التلفيــات والضمانــات ومصاريــف‬\n      ‫أخــرى) وبعــد مــا صــارت الشــركة هــي املطالبــة بالصيانــة مبوجــب عقد‬\n      ‫إيجابــي وشــيكات مدفوعــة ولــم تقــم بأعمــال الصيانــة علــى الوجــه‬\n      ‫املطلــوب انقلــب الســحر علــى الســاحر‪ ،‬فصــارت الشــركة هــي الغارمــة‬\n      ‫عــن كل خســارة كانــت هــي املتســبب فيهــا‪ ،‬وعليــه فيلزمهــا دفــع قيمــة‬\n      ‫التلفيــات ومصاريــف أخــرى كمــا جــاء يف العقــد فمــن املصاريــف‬\n      ‫تكلفــة اســتقدامي لطاقــم إداري وفنــي متخصــص مــن اجــل إدارة‬\n      ‫املشــروع تســعة ســنوات متبقيــة يف العقــد‪ ،‬إضافــة إلــى أن مؤسســة‬\n      ‫‪ ....................‬للمفروشــات عرضــت علـ ّـي مليــون ريــال كخلــو وقــد‬\n      ‫رفضــت هــذا املبلــغ يف حينــه لعــدم كفايتــه‪ ،‬فهــذا مســوغ كاف لطلــب‬\n      ‫التعويــض كمــا وقــع علـ ّـي مــن خســائر وفاتنــي مــن أربــاح‪ ،‬ويف اخلتــام‬\n      ‫آمــل أن يســمح لــي فضيلــة الشــيخ أن أحيلــه للمذكــرة املقيــدة بــوارد‬\n      ‫الشــيخ‪ .................../‬رقم ‪ 7024‬وتاريخ ‪1424/4/29‬هـ لعلكم جتدون‬\n      ‫فيهــا إيضــاح للمجمــل أعــاه‪ ،‬هــذا وجتــدون برفقــه صــورة معــه عقــد‬\n\n\n‫‪155‬‬\n\f‫الشــاليه رقــم (‪ )6‬حســب طلبكــم مرفقــا بــه كشــف حســاب مــن‬\n‫الشــركة يثبــت حتصيلكــم حلســابنا مــن املســتأجر قمــة إيجــار الشــاليه‬\n‫ووثائــق تثبــت صحــة إجابتــي علــى استفســارات فضيلتكــم وأحيــط‬\n‫فضيلتكــم كذلــك بــأن خروجنــا مــن الشــاليهات كان بتاريــخ‬\n‫‪1419/6/10‬ه ـ املوافــق ‪1998/10/1‬م‪ ،‬ويف جلســة أخــرى حضــر‬\n‫املدعــي ‪ ............‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .......‬وقــدم‬\n‫مذكــرة مكونــة مــن أربــع صفحــات ســيجري رصدهــا الحقــا ونــص‬\n‫املقصــود منهــا‪( :‬وجوابــا علــى املذكــرة املســلمة لــي بجلســة األحــد‬\n‫‪1432/11/18‬ه ـ ومــا تضمنــه مــن إجابــات املدعــي أورد لفضيلتكــم‬\n‫جــواب موكلتــي علــى النحــو التالــي‪ :‬أوال‪/‬مــا ذكــره املدعي من أســباب‬\n‫تبــرر طلبــه إيجــار الســنة األولــى وأجــرة الصيانــة فهــي غيــر صحيحــة‬\n‫جملــة وتفصيــا ودليــل ذلــك أن املدعــي وافــق علــى إنهــاء العقــد واإلقالــة‬\n‫منــه مبوجــب محضــر تســليم الشــاليهات املــؤرخ يف ‪1998/10/17‬م دون‬\n‫أي حتفــظ أو اســتثناء بــل إن املدعــي أقــر هــذا احملضــر بأنــه ملتــزم‬\n‫بالنواقــص واملفقــودات حيــث ورد يف احملضــر‪ :‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‬\n‫واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات اجلــرد املرفقــة واملوقعــة مــن‬\n‫ممثلــي الطرفــن‪ ،‬وعليــه يكــون اســتكمال النواقــص واملفقــودات إمــا‬\n‫باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة ال تقــل عنهــا جــودة وإن‬\n‫تعــذر ذلــك فيتــم تقييــم  أســعار كل منهمــا حســب مــا جــاء يف بيانــات‬\n‫اســتالمها العــام املاضــي مــع مراعــاة العمــر االفتراضــي حســبما ورد يف‬\n‫العقــد‪ ،‬وبالتالــي فــإن موكلتــي هــي التــي لهــا حقــوق لــدى املدعــي‬\n‫وليــس بالعكــس ويؤكــد ذلــك اخلطابــان الصــادران مــن املدعــي‬\n\n\n                                                                                       ‫‪156‬‬\n\f      ‫املرفقــان رقــم (‪1‬ـ‪ )2‬اخلطــاب األول‪ :‬بتاريــخ ‪1998/12/1‬م أي بعــد إنهــاء‬\n      ‫العقــد وتســليم الشــاليهات بشــهرين والــذي ينــص فيــه علــى مــا يلــي‪:‬‬\n      ‫(يســرنا إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه وفــق خطاباتكــم‬\n      ‫املشــار إليهــا) واخلطــاب الثانــي‪ :‬بتاريــخ ‪1998/12/30‬م والــذي نــص‬\n      ‫فيــه علــى مــا يلــي‪( :‬يبــدو ذلــك بغيــة الوصــول إلــى حلــول مرضيــة مثلهــا‬\n      ‫مثــل املواضيــع األخــرى التــي مت حلهــا كل واحــدة علــى حــدة لــذا‬\n      ‫نفيدكــم مبوافقتنــا علــى مطالبتكــم هــذه حســب خطابيكــم املشــار‬\n      ‫إليهــا واخلاصــة باســتهالك الكهربــاء‪ ،‬وعليــه نأمــل منكــم قيــد املبلــغ‬\n      ‫املوضحــة بعاليــه برفقنــا لصاحلكــم وقــدره ‪225135‬ريــاال باإلضافــة‬\n      ‫إلــى املبالــغ املســتحقة علينــا والتــي ســبق أن وافقنــا عليهــا كتابيــا) ومــن‬\n      ‫هــذا اخلطــاب يتضــح لفضيلتكــم مــا يلــي‪/1 :‬إقــرار املدعــي صراحــة‬\n      ‫بأنــه مت حــل املواضيــع بــن الطرفــن بحلــول مرضيــة ولــم يتبــق شــيء لــم‬\n      ‫يحــل ولــو تبقــى شــيء لــم يحلــه الطرفــان ألســتثناه املدعــي‪/2 .‬أن هــذان‬\n      ‫اخلطابــان تاريخهــا الحــق لتاريــخ إنهــاء العقــد وتســليم الشــاليهات‬\n      ‫وبالتالــي فــا توجــد أي تخوفــات أو ضغــوط علــى املدعــي كمــا يدعــي‬\n      ‫تدفعــه للتعجــل وكتابــة مثــل هــذا اإلقــرار‪/3 .‬أن موكلتــي هــي صاحبــة‬\n      ‫احلــق جتــاه املدعــي وليــس العكــس فهــو يقــول‪( :‬باإلضافــة إلــى املبالــغ‬\n      ‫املســتحقة علينــا والتــي ســبق أن وافقنــا عليهــا )‪/4 .‬مــا تضمنــه هــذان‬\n      ‫اخلطابــان مــن إقــرارات املدعــي ومــا تضمنــه محضــر اســتالم الشــاليهات‬\n      ‫يؤكــد أن املدعــي غيــر محــق يف دعــواه وأن احلــق ملوكلتــي‪ ،‬إضافــة ملــا‬\n      ‫ســبق إيــراده فــإن املدعــي تســلم الشــاليهات كاملــة بــكل جتهيزاتهــا‬\n      ‫وفــق إقــراره املرفقــة صورتــه (رقــم ‪ )3‬ومــن ضمنهــا جهــاز مركــزي‬\n      ‫للهاتــف مــع أربــع خطــوط جــوال ماركــة أي تــي تــي  مــع التوصيــات‬\n\n\n‫‪157‬‬\n\f‫والتجهيــزات وأجهــزة التحكــم مــع عــدد ‪ 92‬جهــاز هاتــف ماركــة أي‬\n‫تــي تــي مــع شــريحة هاتــف نقــال رقــم ‪( ...............‬ص ‪ 2‬فقــرة ‪ 5‬مــن‬\n‫املرفــق ) ومــع مــا تقــدم ال يــزال املدعــي يصــر علــى أن موكلتــي أخلــت‬\n‫بالتزاماتهــا يف العقــد الــذي وافــق علــى إنهائــه بــإرادة حــرة‪ ،‬ثانيــا‪:‬‬\n‫بخصــوص اســتالم موكلتــي لألجهــزة اإلضافيــة مــن عدمــه لــم يتضــح‬\n‫مــا املقصــود باألجهــزة اإلضافيــة فــإذا كان املقصــود النواقــص‬\n‫واملفقــودات فــإن موكلتــي لــم تســتلمها إطالقــا ودليــل ذلــك هــو مســتند‬\n‫املدعــي الــذي أورده ولــم يكملــه‪ ،‬ألنــه يدينــه حيــث جــاء يف محضــر‬\n‫اســتالم الشــاليهات الــذي اســتند إليــه املدعــي‪( :‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‬\n‫واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات اجلــرد املرفقــة واملوقعــة مــن‬\n‫ممثلــي الطرفــن وعليــه يكــون اســتكمال النواقــص واملفقــودات إمــا‬\n‫باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة ال تقــل عنهــا جــودة وإن‬\n‫تعــذر ذلــك فيتــم تقييــم أســعار كل منهــا حســب مــا جــاء يف بيانــات‬\n‫اســتالمها العــام املاضــي مــع مراعــاة العمــر االفتراضــي حســب مــا جــاء‬\n‫يف العقــد)‪ ،‬واملقصــود ببيــان اســتالمها العــام املاضــي هــو املرفــق رقــم‬\n‫(‪ )3‬بهــذه املذكــرة أمــا إن كان املقصــود باألجهــزة اإلضافيــة أشــياء‬\n‫أخــرى فــإن موكلتــي تطلــب بينــة املدعــي علــى تســليمها لهــا‪ .‬ثالثــا‪/‬‬\n‫بخصــوص الهواتــف وهــل اســتخدمت يف الشــاليهات‪ ،‬أقــر املدعــي بأنــه‬\n‫وفــر خدمــة هاتفيــة هوائيــة ومعلــوم أن الهاتــف الهوائــي هــو اســتفادة مــن‬\n‫خدمــة قائمــة وليســت تأســيس كمــا ال يخفــى علــى نظــر فضيلتكــم أن‬\n‫اخلدمــة الهوائيــة التــي ذكرهــا املدعــي (يف ضبــط إحــدى اجللســات‬\n‫الســابقة أقــر بأنــه اســتخدم جهــاز ســيناو) غيــر نظاميــة و ال يوجــد لــدى‬\n\n\n                                                                                       ‫‪158‬‬\n\f        ‫املدعــي مــا يفيــد مبوافقــة موكلتــي علــى هــذه اخلدمــة‪ ،‬كمــا أقــر‬\n        ‫املدعــي بــأن الهاتــف باســمه ولــم يقــدم مــا يثبــت أنــه مت تركيبــه يف‬\n        ‫الشــاليهات ومنعــا لإلطالــة يف هــذه النقطــة أحيــل نظــر فضيلتكــم إلــى‬\n      ‫مذكرتــي املقدمــة بجلســة ‪1429/5/30‬ه ـ مرفــق صورتهــا رقــم ‪  4‬‬\n        ‫وألفــت نظــر فضيلتكــم إلــى أن املدعــي أقــر بأنــه اســتلم أجهــزة هاتــف‬\n        ‫وشــريحة جــوال الســتخدامها يف الشــاليهات مرفــق رقــم ‪ .3‬رابعــا‪/‬‬\n        ‫بخصــوص املخالصــة بــن الطرفــن وهــل هــي مطلقــة أم مقيــدة‪ ،‬فإننــي‬\n        ‫أكتفــي مبــا أوردتــه يف الفقــرة أوال مــن هــذه املذكــرة والتــي تبــن أن‬\n        ‫العالقــة التعاقديــة مــع املدعــي انتهــت مبوجــب تلــك املخالصــة و تبقــى يف‬\n        ‫ذمتــه مــا نصــت عليــه‪ ،‬وأمــا قولــه بأنــه وقّ ــع املخالصــة إليقــاف الضــرر‬\n        ‫الــذي يدعيــه وأنــه وقــع بتحفــظ شــديد علــى حفــظ حقوقــه‪ ،‬فغيــر‬\n        ‫صحيــح وتناقضــه يف إقراراتــه يف خطابيــه الذيــن أشــرت إليهــا يف الفقرة‬\n        ‫أوال مــن هــذه املذكــرة‪ .‬خامســا‪/‬بخصوص طلــب فضيلتكــم البينــة‬\n        ‫مــن املدعــي علــى أن الرصيــف البحــري داخــل ضمــن العقــد رغــم أنــه‬\n        ‫منحصــر يف الســتني شــاليه‪ ،‬مــع األخــذ مبــا ذكرتــه يف أوال مــن هــذه‬\n        ‫املذكــرة‪ ،‬فــإن املدعــي يدعــي أن الرصيــف البحــري داخــل ضمــن‬\n        ‫العقــد‪ ،‬وقــد طلبتــم فضيلتكــم منــه البينــة علــى ذلــك ولــم يقدمهــا؛ ألنــه‬\n        ‫ال توجــد لديــه بينــة‪ ،‬وهــذا هــو الصحيــح فالرصيــف البحــري ليــس‬\n        ‫ضمــن العقــد وقــد أقــر املدعــي بذلــك يف خطابــه الــذي اســتند إليــه‬\n        ‫املرفــق رقــم (‪ )5‬حيــث قــال‪ ...( :‬وعدمتونــا باســتكمال املنزلــق البحــري‬\n        ‫‪...‬الــخ) فــا يخــرج األمــر عــن وعــد والوعــد كمــا هــو معلــوم غيــر ملــزم‬\n        ‫كمــا أن الوعــد بالتنفيــذ معلــق باالتفــاق مــع أحدهــم وليــس ناجــزا‪.‬‬\n        ‫سادســا‪/‬بخصوص مســوغ طلــب املدعــي التعويــض عــن األربــاح املتوقعــة‬\n\n\n‫‪159‬‬\n\f‫عــن تســع ســنوات‪ ،‬كمــا أنــه توقــع أن تكــون هنــاك أربــاح فإنــه توقــع‬\n‫أن تكــون هنــاك خســائر نتيجــة لعــدم قدرتــه علــى إدارة املشــروع‬\n‫بطريقــة اســتثمارية ناجحــة وهــذا التوقــع هــو الــذي دفعــه إلنهــاء العقــد‬\n‫وتســليم الشــاليهات‪ ،‬وكمــا أوردت يف أوال مــن هــذه املذكــرة فــإن‬\n‫إنهــاءه للعقــد ال يجعــل لــه احلــق يف املطالبــة بشــيء الســيما مــع إقراراتــه‬\n‫أن بذمتــه حقــوق ملوكلتــي كمــا ســبق إيضاحــه‪ .‬ســابعا‪/‬ملوكلتي يف‬\n‫ذمــة املدعــي مبالــغ إجماليهــا ‪( 1360802,62‬مائــة وســتة وثالثــون ألفــا‬\n‫وثمامنائــة وريــاالن واثنــان وســتون هللــه) مفصلــة علــى النحــو التالــي‪/1 :‬‬\n‫فواتيــر هاتــف جــوال الشــاليهات املســتحق ‪ 2505,82‬ريــال حســب العقد‪.‬‬\n‫‪/2‬املنصــرف مــن املخــزون لصيانــة الشــاليهات املســتحق ‪ 4939,34‬ريــال‬\n‫حســب العقــد‪/3 .‬قيمــة املســتهلك مــن الكهربــاء املســتحق ‪78899,33‬‬\n‫حســب العقــد ‪/4‬قيمــة املســتهلك مــن امليــاه املســتحق ‪ 73688,63‬ريــال‬\n‫حســب العقــد اإلجمالــي ‪ 160033,12‬ريــال يطــرح منــه املســدد مــن‬\n‫فواتيــر الهاتــف ‪ 1683‬ريــال وقيمــة إيجــار ســنوي مــن قبــل الشــركة‬\n‫الســعودية ‪ 39500‬ريــال صــايف املســتحق ‪ 11885012‬ريــال تضــاف‬\n‫املصاريــف التاليــة عنــد االســتالم نواقــص وتالــف عنــد اســتالم‬\n‫الشــاليهات ‪ 15900‬ريــال وقيمــة مــواد صيانــة الزمــة إلصــاح بعــض‬\n‫التلــف ‪ 1240‬ريــال وقيمــة إصــاح أســرة ‪ 81250‬ريــال إجمالــي املســتحق‬\n‫‪ 3680262‬ريــال وحيــث أن املدعــي يقــر بــأن يف ذمتــه حقــوق ماليــة‬\n‫ملوكلتــي‪ ،‬فــإن موكلتــي تطلــب مــن فضيلتكــم مــا يلــي‪/1 :‬احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي‪/2 .‬احلكــم بإلــزام املدعــي دفــع مــا‬\n‫بذمتــه ملوكلتــي مــن مســتحقات ماليــة إجماليهــا ‪ 120000‬مائــة‬\n‫وعشــرون ألــف ريــال‪/3 .‬احلكــم بإلــزام املدعــي دفــع أجــرة احملامــاة‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫وقدرهــا مائــة وعشــرون ألــف ريــال الشــركة ‪ ..............‬أ‪.‬ه ـ عنــد هــذا‬\n      ‫املوضــع رفعــت اجللســة مــع إفهــام املدعــي بإحضــار جوابــه على مــا ذكره‬\n      ‫املدعــى عليــه وكالــة بخصــوص اخلطــاب الصــادر مــن املدعــي املــؤرخ يف‬\n      ‫‪1998/12/30‬م‪ ،‬ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى‬\n      ‫عليــه وقــدم املدعــي مذكــرة نصهــا كالتالــي‪ :‬أوال‪/‬حــن لــم يســتطع‬\n      ‫محامــي الشــركة أن يفنــد مــا جــاء مبذكراتــي حــاول جاهــدا بــأن‬\n      ‫يشــطب الدعــوى مــن أساســها وذلــك بتجاهــل القــرار األخيــر الصــادر‬\n      ‫مــن مجلــس القضــاء األعلــى بهيئتــه الدائمــة رقــم ‪/2/97‬س يف‬\n      ‫‪1430/2/13‬ه ـ األمــر الــذي بســببه قــد يتأخــر البــت يف هــذه القضيــة‪.‬‬\n      ‫ثانيــا‪ /‬أن مبــررات طلــب قيمــة إيجــار الســنة األولــى وقيمة أجــرة الصيانة‬\n      ‫ليســت متوقفــة علــى إنهــاء العقــد وال علــى اإلقالــة منــه وال علــى محضــر‬\n      ‫التســليم الشــاليهات بــل حــق ثبــت بتعــذر حصــول منفعــة االســتثمار‬\n      ‫املنفعــة التــي مــن اجلهــا مت التعاقــد وتعــذر حصولهــا بســبب العيــوب‬\n      ‫اإلنشــائية واملعماريــة التــي ظهــرت يف املشــروع يف بدايــة التشــغيل والتــي‬\n      ‫شــهدت بهــا جهــة هندســية محايــدة واعتــرف بخطورتهــا نائــب مديــر‬\n      ‫عــام الشــركة بخطابــه املــؤرخ يف ‪1998/2/25‬م املوجــه للمقــاول منفــذ‬\n      ‫املشــروع أضــف علــى ذلــك رفــض الشــركة إلعمــال الصيانــة امللتزمــة‬\n      ‫بهــا مبوجــب عقــد موقــع مــن رئيــس مجلــس إدارة الشــركة ودعــم‬\n      ‫اســتالمهم ألجــرة الصيانــة مبوجــب شــيكات موثقــة باإلضافــة إلــى‬\n      ‫رفــض اجنــاز الرصيــف البحــري وغيــر ذلــك مــن عوائــق اســتثمار‬\n      ‫الشــاليهات‪/3 .‬أن العبــارة التــي وردت بخطابــي املوجهــة للشــركة‬\n      ‫بتاريــخ ‪1998/12/1‬م ونصهــا‪( :‬لــذا يســرنا   إفادتكــم مبوافقتنــا‬\n      ‫مطالباتكــم هــذه ‪ )..‬إمنــا هــي تفعيــل وتطبيــق ملــا ورد يف محضــر تســليم‬\n\n\n‫‪161‬‬\n\f‫الشــاليهات والــذي نصــه‪( :‬أمــا مــن حيــث النواحــي املاليــة فســوف تتــم‬\n‫التســويات املطالبــات املاليــة مــن الطرفــن كل فيمــا يخــص) فقــد وفيت‬\n‫وأبــرأت ذمتــي ممــا يخصهــم أمــا مــا يخصنــي وهــي حقوقي التــي بذمتهم‬\n‫فبعــد إنكارهــم لبعضهــا واملماطلــة يف دفــع بعضهــا اآلخــر أقمــت عليهــم‬\n‫هــذه الدعــوى‪ ،‬وأمــا خطابــي املوحــد للشــركة بتاريــخ ‪1998/12/30‬م‬\n‫فهــو خــاص مبوضــوع اســتهالك الكهربــاء فقــط واملقصــود بعبــارة‪:‬‬\n‫(املواضيــع األخــرى التــي مت حلهــا كل علــى حــدة) إشــارة إلــى االتفاقــات‬\n‫معهــم والتوصــل لتحديــد قيمــة املفقــودات والتالــف مــن التجهيــزات‬\n‫واألســرة ومــواد الصيانــة املفصلــة بخطابــي املــؤرخ يف ‪1998/12/1‬م‬\n‫وبنــاء عليــه يتضــح لفضيلتكــم بــأن محضــر تســليم الشــاليهات مــا هــو‬\n‫إال تســليم للموقــع بجميــع محتوياتــه‪ :‬أوال‪/‬علــى أن تتــم التســويات املاليــة‬\n‫الحقــا ولــم يســتحق إال مــا يخصنــي مــن حقــوق وتعويضــات مــا زالــت‬\n‫حتــت نظــر فضيلتكــم رابعــا‪/‬إن التجهيــزات اإلضافيــة التــي أمنتهــا‬\n‫للشــاليهات مــن حســابي اخلــاص ســبق وأن أدرجتهــا ببيــان مفصــل مرفــق‬\n‫بصــور مــن فواتيــر الشــراء رفعتهــا بخطــاب وجهتــه لفضيلــة عضــو العامة‬\n‫بالدمام‪/‬الشــيخ ‪ ..................‬وهــو مســجل بــوارد احملكمــة رقــم‬\n‫‪ 27/25284‬يف ‪1427/12/4‬ه ـ وأمــا البينــة علــى اســتالم الشــركة‬\n‫لهــذه األجهــزة فهــي مــا جــاء مبحضــر اســتالم الشــاليهات املــؤرخ يف‬\n‫‪1419/6/27‬ه ـ واملوقــع منــي ومــن نائــب مديــر عــام الشــركة ونصــه‪:‬‬\n‫(وعليــه فقــد اســتلمت الشــركة ‪ ..................‬الشــاليهات بكامــل‬\n‫مرفقاتهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة لألغــراض والتجهيــزات‬\n‫املســتلمة مــن قبــل املســتثمر)‪ .‬خامســا‪/‬وأما بخصــوص الهاتــف فلــو‬\n‫كانــت اخلدمــة الهاتفيــة متوفــرة مبوقــع الشــاليهات وقــت التعاقــد لــزال‬\n\n\n                                                                                    ‫‪162‬‬\n\f      ‫اإلشــكال وملــا كلفتنــي الشــركة بالبحــث عــن حلــول مناســبة وملــا‬\n      ‫التزمــت لــي الشــركة بتحمــل مــا نســبته ‪% 75‬مــن تأســيس هاتــف هوائي‬\n      ‫(ســيناو) حيــث كان حينئــذ هــو احلــل األمثــل واملســتخدم للتواصــل مــع‬\n      ‫القــرى واملــزارع واملناطــق النائيــة وقــد ركــب الفنيــون طرفيــة أجهــزة‬\n      ‫الهواتــف يف مكتــب االســتقبال وركبــوا لواقطهــا (االناتــل) فوق ســطح‬\n      ‫املكتــب ثــم ســلمتها للشــركة مــن ضمــن االجهــزة اإلضافيــة‪ ،‬كمــا‬\n      ‫نــص علــى ذلــك محضــر تســليم الشــاليهات واســتالم الشــركة لهــا دليــل‬\n      ‫وبينــة علــى موافقتهــا باســتخدام الهاتــف الهوائــي واالســتفادة مــن هــذه‬\n      ‫اخلدمــة املؤمنــة ولــم أقــم بفصــل احلــرارة عــن الهواتــف إال بعــد فتــرة مــن‬\n      ‫إنهــاء التعاقــد علــى أمــل أن تنقلهــا الشــركة باســمها وتدفــع لــي نســبة‬\n      ‫التأســيس التــي التزمــت بهــا‪ .‬سادســا‪/‬أن الوعــد بإجنــاز الرصيــف‬\n      ‫البحــري ملــزم وناجــز؛ ألنــه وعــد موثــق ومكتــوب صــدرت بــه تعليمــات‬\n      ‫إداريــة مــن نائــب مديــر عــام الشــركة ملديــر املشــاريع بإنهــاء إجــراءات‬\n      ‫إجنــاز الرصيــف البحــري لكــن هــذه التعليمــات لــم تنفــذ إال يــوم ســلمت‬\n      ‫الشــاليهات للشــركة  فبــد التســليم صــار الوعــد اخللــف بقــدرة قــادر‬\n      ‫ملزمــا وناجــزا) أ‪.‬ه ـ وحضــر يف هــذه األثنــاء املدعــى عليــه ‪ ...‬وجــرى‬\n      ‫تســليمه صــورة مــن املذكــرة وطلــب اإلمهــال للــرد‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر الطرفــان ثــم قــدم املدعــى عليــه ‪ .....................‬مذكــرة جوابيــة‬\n      ‫علــى مذكــرة املدعــي املقدمــة يف جلســة ‪1432/12/3‬ه ـ ونصهــا‬\n      ‫كالتالــي‪/1 :‬أقــر املدعــي يف الفقــرة (‪ )2‬مــن مذكرتــه بإنهــاء العقــد‬\n      ‫واإلقالــة منــه وأن ذلــك لــم يكــن معلقــا بشــرط أو قيــد‪/2 .‬لــم يقــدم‬\n      ‫املدعــي جوابــا مالقيــا ومقابــا  ملــا أقــر بــه يف خطابــه املــؤرخ يف‬\n      ‫‪1998/12/30‬م مــن أن جميــع املواضيــع األخــرى مت حلهــا كل علــى‬\n\n\n‫‪163‬‬\n\f‫حــدة ولــم يتبــق ســوى موضــوع فواتيــر الكهربــاء الــذي وافــق يف اخلطــاب‬\n‫نفســه علــى حتمــل قيمــة تلــك الفواتيــر وتقييــد قيمتهــا علــى حســابه لــدى‬\n‫موكلتــي‪ /3 .‬ال عــذر ملــن أقــر واإلقــرار ملــزم لصاحبــه وخطــاب املدعــي‬\n‫يف ‪1998/12/30‬م والــذي جــاء بعــد إنهــاء العقــد وتســليم املوقــع‬\n‫ملوكلتــي وأن جميــع املواضيــع األخــرى مت حلهــا كل علــى حــده‪/4 .‬‬\n‫املدعــي أصالــة األخ ‪.................‬هــو الــذي كتــب اخلطــاب أعــاه وهــو‬\n‫الــذي يكتــب معظــم مذكراتــه املقدمــة لفضيلتكــم وهــو معلــم لغــة‬\n‫عربيــة ملــدة تزيــد عــن الثالثــن عامــا ويعــي ويــدرك معانــي الكلمــات‬\n‫ومقاصدهــا وليــس رجــا عاميــا‪ ،‬وبالتالــي فــإن محاولتــه تبريــر إقــراره‬\n‫تبريــرا ال يحتملــه النــص يف غيــر محلــه ملــا تقــدم وحيــث أن املدعــي أنهــى‬\n‫العقــد وقبــل اإلقالــة منــه دون شــرط أو قيــد وفــق مــا أوضحتــه ومــا‬\n‫قدمتــه مــن خطابــات صــادرة منــه حيــث أن املدعــي يقــر بــأن يف ذمتــه‬\n‫حقــوق ماليــة ملوكلتــي فــإن موكلتــي تطلــب مــن فضيلتكــم مــا يلــي‪:‬‬\n‫‪/1‬احلكــم بصــرف النظــر عــن دعــوى املدعــي‪ /2 .‬احلكــم بإلــزام‬\n‫املدعــي دفــع مــا بذمتــه ملوكلتــي مــن مســتحقات ماليــة إجماليهــا‬\n‫(‪)1360802062‬ريــال‪/3 .‬احلكــم بإلــزام املدعــي دفــع أجــرة احملامــاة‬\n‫وقدرهــا (‪ )120000‬مائــة وعشــرون ألــف ريــال) أ‪.‬هــ  ويف جلســة أخــرى‬\n‫افتتحــت اجللســة الســاعة التاســعة والنصــف وفيهــا حضــر املدعــي‬\n‫‪ .............‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .......................‬وقــد‬\n‫قــدم املدعــي مذكــرة رد علــى مــا جــاء يف مذكــرة املدعــى عليــه وكالة‬\n‫ونصهــا كالتالــي (( إشــارة إلــى جلســة يــوم ‪1432/11/23‬ه ـ والــذي‬\n‫طلبتــم فيهــا فضيلتكــم منــي إيضاح ـ ًا مكتوب ـ ًا ملــا ورد باخلطابــن‬\n‫املوجهــن للشــركة ‪ ................‬واملــؤرخ أحدهمــا يف ‪1419/08/12‬ه ـ‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫واآلخــر يف ‪1419/9/12‬ه عليــه فإنــي أقــدم لفضيلتكــم اإليضــاح‬\n      ‫التالــي ‪ -1 :‬أن التســويات املاليــة املتبادلــة بينــي وبــن الشــركة واملشــار‬\n      ‫إليهــا بخطابــي املــؤرخ يف ‪1419/08/12‬ه ـ وهــي قيمــة مــا اتفقنــا عليــه‬\n      ‫مــن تعويــض للتالــف و املفقــود مــن جتهيــزات الشــاليهات وهــي متثــل قيمــة‬\n      ‫أشــياء محــددة ومنصــوص عليهــا صراحــة ومقيــدة بقولــي ( لــذا يســرنا‬\n      ‫إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه ) أقــول ( هــذه ) أي أنهــا‬\n      ‫قيمــة لألشــياء احملــددة واملنصــوص عليهــا يف اخلطــاب املشــار إليــه‬\n      ‫وليســت اتفاق ـ ًا علــى كل شــي معلــق ‪ - 2‬كمــا أن التســويات املاليــة‬\n      ‫املشــار إليهــا بخطابــي املــؤرخ ‪1419/09/12‬هـ وهي متثل قيمة اســتهالك‬\n      ‫كهربــاء فهــذه القيمــة محــددة عليهــا صراحــة ومقيــدة بقولــي ( لــذا‬\n      ‫يســرنا إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه ( أقول هذه ) حســب‬\n      ‫خطابكــم املشــار إليهمــا واخلاصــة باســتهالك الكهربــاء ) نعــم إنهــا‬\n      ‫قيمــة خاصــة باســتهالك الكهربــاء وليســت تنــاز ًال عــن حقوقــي الثابتــة‬\n      ‫يف ذمــة الشــركة ويف دفاترهــا أمــا عبــارة ( وذلــك بغيــة الوصــول إلــى‬\n      ‫حلــول مرضيــة مثلهــا مثــل املواضيــع األخــرى التــي مت حلهــا كل علــى‬\n      ‫حــده ) فمعناهــا أن قبــول االتفــاق علــى قيمــة اســتهالك الكهربــاء مثلــه‬\n      ‫مثــل قبــول االتفــاق الســابق لــه وهــو تقديــر قيمــة التالــف واملفقــود‬\n      ‫والنواقــص مــن التجهيــزات فــكل حــل مــن هــذه احللــول مت علــى حــده أن‬\n      ‫مقصــود بعبــارة ( التــي مت حلهــا كل علــى حــده ) وتفســيرها يطلــب منــي‬\n      ‫أنــا وليــس مــن غيــري فأنــا الــذي كتبتهــا وأعــي مــا أقــول متامـ ًا واألمــور‬\n      ‫مبقاصدهــا وبســياقها محــل االتفــاق وأنــا الــذي مــا زلــت اعتــرف بأنــي‬\n      ‫قــد توصلــت مــع الشــركة علــى حــل بعــض اجلزئيــات وهــي مبثابــة آليــة‬\n      ‫لتنفيــذ مــا اتفقــت عليــه مــع الشــركة مبحضــر تســليم الشــاليهات ونصه‬\n\n\n‫‪165‬‬\n\f‫( أمــا مــن حيــث النواحــي املاليــة فســوف تتــم التســويات واملطالبــات بــن‬\n‫الطرفــن كل فيمــا يخصــه ) فاحللــول التــي وردت باخلطابــن أمنــا هــي‬\n‫تســويات ماليــة تخــص الشــركة امــا مــا يخصنــي مــن حقــوق بذمــة‬\n‫الشــركة فهــو مــا أنكــرت الشــركة بعضــه ومــا طلبــت بالبعــض اآلخــر‬\n‫األمــر الــذي دفعنــي للتقــدمي للمحكمــة مطالب ـ ًا بحقوقــي وهــي مثبتــة‬\n‫بدفاتــر الضبــط لــدى فضيلتكــم منــذ اثنــا عشــر عامـ ًا فاحلــق ال يســقط‬\n‫بالتقــادم كمــا ال يخفــى عليكــم فالعبــارات املتبادلــة بينــي وبــن‬\n‫ا قــد قبلــت‬   ‫الشــركة ال تــدل ال مــن قريــب وال مــن بعيــد علــى أنــي مث ـ ً‬\n‫بخطــورة الوضــع اإلنشــائي للشــاليهات وال علــى أنــي تنازلــت عــن حقــي‬\n‫الثابــت برصيــف بحــري دامــت مماطلــة الشــركة يف إجنــازه حتــى نهايــة‬\n‫الســنة األولــى مــن العقــد وال علــى أنــي مذعــن للشــركة التــي وقعــت‬\n‫معــي عقــد الصيانــة واســتلمت أجرتهــا مبوجــب شــيكات موثقــة ثــم‬\n‫رفضــت تنفيذهــا بــل حتــى تاريــخ اليــوم وهــي مــا زالــت تعتبرنــي  ظامل ـ ًا‬\n‫وجــور ًا أنــا املســئول عــن تنفيــذ الصيانــة وغيــر ذلــك أن خطــورة الوضــع‬\n‫اإلنشــائي للشــاليهات واملماطلــة يف إجنــاز الرصيــف البحــري ورفــض‬\n‫الصيانــة كل واحــد منهــا كفيــل يعتــذر حصــول منفعــة االســتثمار التــي‬\n‫مــن أجلهــا مت التعاقــد فتعــذر منفعــة االســتثمار ال يلغــي معــه كمــا أفهــم‬\n‫مصــروف الكهربــاء حيــث أنــه خــاص بطــرف ثالــث ( ‪ ) ....‬ال يعتــرف‬\n‫باخلــاف القائــم بــن املالــك واملســتأجر فــإن رأي فضيلتكــم أن‬\n‫الشــركة الســعودية ملراكــز الترفيــه ال يســتحق شــرع ًا قيمــة اســتهالك‬\n‫تبعــا لتعــذر املنفعــة فأمتنــى ذلــك واملوضــوع بــن أيدكــم ‪ - 3‬وأخيــر ًا أن‬\n‫محامــي الشــركة قــد كــذب علــي يف مذكرتــه املؤرخــة يف‬\n‫‪1432/11/27‬ه ـ وقولنــي مــا لــم اقلــه وذلــك حينمــا أدعــى مــا نصــه (‬\n\n\n                                                                                      ‫‪166‬‬\n\f       ‫يتضــح لفضيلتكــم مــا يلــي ‪ - 1 :‬إقــرار املدعــي صراحــة بأنــه مت حلــه‬\n       ‫املواضيــع بــن الطرفــن بحلــول مرضيــة ولــم يبــق شــيء لــم يحلــه ) فأنــا‬\n      ‫لــم اقــل عبــارة ( ولــم يبــق شــيء لــم يحــل ) واحللــول التــي متــت بــن الطرفني ‬\n       ‫بحلــول مرضيــة إمنــا هــي املشــار إليهــا أعــاه كمــا وأنــه يف املذكــرة‬\n       ‫نفســها ســبق أن حــاول شــطب القضيــة مــن أساســها وذلــك بتجاهــل‬\n       ‫القــرار األخيــر القاضــي باســتئنافها ثــم أدعــى كذب ـ ًا يف مذكرتــه‬\n       ‫املؤرخــة يف ‪1432/12/23‬ه ـ ( أننــي معلــم لغــة عربيــة ملــدة تزيــد عــن‬\n       ‫الثالثــن عامـ ًا ) وهــذه مــن تلقــاء نفســه بــل ومحــض افتــراء )) أ‪.‬ه ـ وبــرد‬\n       ‫ذلــك علــى املدعــى عليــه وكالــة قــال أو ًال ‪ -‬مــا ورد يف الفقرتــن األولــى‬\n       ‫والثانيــة مــن مذكــرة املدعــي ليــس فيــه جديــد بنقــض مــا ســبق أن أقــر‬\n       ‫بــه املدعــي بانتهــاء جميــع املواضيــع وحلهــا واألصــل أنــه ال عــذر لــم أقــر‬\n       ‫كمــا أن الســكوت عــن البيــان يف معــرض احلاجــة لبيــان بيانــه وقــول‬\n       ‫املدعــي أن خطابيــه يتعلقــان بالكهربــاء غيــر صحيــح فــكل منهمــا‬\n       ‫مذيــل بعبــارة حســابي لديكــم أو مطالباتكــم لــدي اجتاهــي ومــا أورده‬\n       ‫املدعــي يف هاتــن الفقرتــن كالم مرســل ال يخــرج عمــا ســبق أن ذكره‬\n       ‫يف اجللســتني املاضيتــن أمــا مــا ورد يف الفقــرة الثالثــة فجوابـ ًا علــى أنــي‬\n       ‫كذبــت علــى املدعــي يف مســألة إقــراره فإنــي أنــزه مجلــس القضــاء مــن‬\n       ‫الــرد عــن هــذه اإلســاءة ولعــل فهــم املدعــي قصــر بــه عــن إدراك معنــى‬\n       ‫عبارتــي أمــا كونــه معلــم لغــة عربيــة فســبق أن أقــر بهــا يف مجلــس‬\n       ‫القضــاء هــذا مــا لــدي ثــم جــرى ســؤال الطرفــن هــل لديهمــا زيــادة علــى‬\n       ‫مــا ذكــراه فقــاال ليــس لدينــا ســوى مــا ذكرنــاه يف هــذه اجللســة‬\n       ‫واجللســات الســابقة ورفعــت اجللســة لتأمــل جميــع مــا ســبق ضبطــه ويف‬\n       ‫جلســة أخــرى افتتحــت اجللســة الســاعة ‪  10 : 31‬وفيهــا حضــر املدعــي‬\n\n\n‫‪167‬‬\n\f‫‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .........‬وجــرى ســؤال‬\n‫املدعــي ‪ .............‬عمــا ذكــره املدعــى عليــه وكالــة يف أحــد اجللســات‬\n‫بخصــوص الشــاليه رقــم ‪  6‬وأن الشــاليه لــم يســلم للمســتأجر مــن بدايــة‬\n‫العقــد لذلــك فقــد جــرى حســاب األجــرة لتكــون تســعة وثالثــون الــف‬\n‫وخمســمائة ريــال فقــال املدعــي هــذا الــكالم غيــر صحيــح فالعقــد‬\n‫يثبــت أن اســتالم املســتأجر للشــاليه كان يف نفــس تاريــخ العقــد (‬\n‫اعتبــار ًا مــن جاهزيتــه لالســتخدام ) وســوف أحضــر مــا يثبــت ذلــك ثــم‬\n‫جــرى ســؤال املدعــي عمــا جــاء يف مذكــرة املدعــى عليه وكالــة املؤرخة‬\n‫يف ‪143/11/27‬هـ يف الفقرة السابعة واملتضمنة أن الشركة ‪...............‬‬\n‫تطالبــه مببلــغ مائــة وســتة وثالثــون ألــف وثمامنائــة وريــاالن واثنــان وســتون‬\n‫هللــه فقــال أقــر بــأن يف ذمتــي للشــركة املدعــى عليهــا مبلــغ خمســون‬\n‫ألــف ريــال وهــذا املبلــغ يشــمل جميــع تكاليــف الكهربــاء واملــاء و‬\n‫املفقــودات والنواقــص وبينتــي علــى ذلــك املخالصــة املوقعــة مــن رئيــس‬\n‫مجلــس اإلدارة والعضــو املنتــدب والتــي تثبــت أن يف ذمتــي مبلــغ خمســون‬\n‫ألــف ريــال فقــط وهنــاك مخالصــة أخــرى موقعــة مــن رئيــس مجلــس‬\n‫اإلدارة تتضمــن تفصيــل املبلــغ املذكــور يف املخالصــة األولــى أقدمهــا‬\n‫لفضيلتكــم وقــد جــرى اإلطــاع منــا علــى املخالصتــن فوجــدت األولــى‬\n‫محررة على مطبوعات الشركة ‪......‬برقم ‪ 99/99‬يف ‪1419/11/01‬هـ‬\n‫املوافــق ‪1999/02/17‬م وعنوانهــا مخالصــة نهائيــة ونصهــا كالتالــي‬\n‫((إشــارة إلــى العقــد بــن الطرفــن ‪ - 1‬الشــركة ‪ ( ..............‬طــرف أول)‬\n‫‪ - 2‬واألســتاذ ‪ ( ................. /‬طــرف ثانــي ) الســتثمار شــاليهات ‪...‬‬\n‫وحيــث انتهــى العقــد بتاريــخ ‪ /1‬أكتوبــر ‪1998 /‬م وحيــث هنــاك مبالــغ‬\n‫مطلوبــة للشــركة لــم يتــم تســديدها مــن قبــل األســتاذ ‪ ..............‬فقــد مت‬\n\n\n                                                                                        ‫‪168‬‬\n\f       ‫االتفــاق بتاريخــه علــى عمــل هــذه املخالصــة النهائيــة والتــي يقــوم‬\n       ‫مبوجبهــا األســتاذ ‪ ............‬بدفــع مبلــغ ( ‪ 50.000‬ريــال ) خمســون الــف‬\n       ‫ا قــام املذكــور بتســديد هــذا املبلــغ مبوجــب الشــيك رقــم‬            ‫ريــال وفع ـ ً‬\n       ‫(بــدون ) وتاريــخ ( بــدون ) مســحوب علــى البنــك ( بــدون ) وبذلــك لــم يعــد‬\n       ‫ال‬\n        ‫ألي مــن الطرفــن احلــق يف مطالبــة الطــرف اآلخــر حاضــر ًا أو مســتقب ً‬\n       ‫بــأي مبالــغ أخــرى ويعتبــر هــذا املبلــغ مبثابــة مخالصــة نهائيــة بــن‬\n       ‫الطرفــن املذكوريــن فيمــا يخــص العقــد املذكــور أعــاه )) أ‪.‬ه ـ‬\n       ‫‪ ...............‬رئيــس مجلــس اإلدارة والعضــو املنتــدب توقيعــه وختــم‬\n       ‫الشــركة ‪ ....................‬و‪ ....................‬مســتثمر الشــاليهات بــدون توقيــع‬\n       ‫كمــا  جــرى اإلطــاع منــا علــى املخالصــة الثانيــة فوجدتهــا  محــررة‬\n       ‫علــى مطبوعــات الشــركة ‪ ...........‬برقــم ‪ 99/99‬يف ‪1419/11/01‬ه ـ‬\n       ‫املوافــق ‪1999/02/17‬م وعنوانهــا مخالصــة نهائيــة ونصهــا كالتالــي‬\n       ‫((إشــارة إلــى العقــد بــن الطرفــن ‪ - 1‬الشــركة ‪( ..................‬طــرف‬\n       ‫أول) ‪ - 2‬واألستاذ ‪ ( .......... /‬طرف ثاني ) الستثمار شاليهات ‪..............‬‬\n       ‫وحيــث انتهــى العقــد بتاريــخ ‪ /1‬أكتوبــر ‪1998 /‬م وحيــث هنــاك مبالــغ‬\n       ‫مطلوبــة للشــركة لــم يتــم تســديدها مــن قبــل األســتاذ ‪ ...................‬فقــد‬\n       ‫مت االتفــاق بتاريخــه علــى عمــل هــذه املخالصــة النهائيــة والتــي يقــوم‬\n       ‫مبوجبهــا األســتاذ ‪ ..................‬بدفــع مبلــغ ( ‪ 50.000‬ريــال ) خمســون‬\n       ‫ألــف ريــال ‪ 15.900 ( - 1 :‬ريــال ) قيمــة املفقــودات ‪ 1420 ( - 2‬ريــال )‬\n       ‫الصيانــة  ‪ 812 ( - 3‬ريــال ) إصــاح األســرة ‪ 22.513 ( - 4‬ريــال )‬\n       ‫ا قــام‬ ‫اســتهالك الكهربــاء ‪ 9355 ( - 5‬ريــال ) اســتهالك املــاء  وفع ـ ً‬\n       ‫املذكــور بتســديد هــذا املبلــغ مبوجــب الشــيك رقــم ( بــدون ) وتاريــخ‬\n      ‫(بــدون ) مســحوب علــى البنــك ( بــدون ) وبذلــك لــم يعد ألي من الطرفني ‬\n\n\n‫‪169‬‬\n\f‫ال بــأي مبالــغ أخــرى‬ ‫احلــق يف مطالبــة الطــرف اآلخــر حاضــر ًا أو مســتقب ً‬\n‫ويعتبــر هــذا املبلــغ مبثابــة مخالصــة نهائيــة بــن الطرفــن املذكوريــن‬\n‫فيمــا يخــص العقــد املذكــور أعــاه )) أ‪.‬ه ـ ‪ ...................‬رئيــس مجلــس‬\n‫اإلدارة والعضــو املنتــدب توقيعــه  و ‪ ...................‬مســتثمر الشــاليهات‬\n‫بــدون توقيــع ثــم جــرى ســؤال املدعــى عليــه وكالــة عــن البيــان املقــدم من‬\n‫قبــل املدعــي بخصــوص التجهيــزات اإلضافيــة والتــي يطالــب بهــا‬\n‫الشــركة املدعــى عليهــا مببلــغ ســتة عشــر الــف وثالثمائــة وتســعة‬\n‫وتســعون ريــال كمــا جــرى ســؤاله عــن املبلــغ الــذي أقــر بــه املدعــي‬\n‫وقــدره خمســون ألــف ريــال لصالــح الشــركة املدعــى عليهــا فقــال اطلــب‬\n‫إمهالــي لإلعــداد اجلــواب وقــد جــرى تســليمه صــور مــن البيــان املتضمــن‬\n‫التجهيــزات اإلضافيــة واملخالصتــان املقدمتــان مــن املدعــي ثــم قــال‬\n‫املدعــى عليــه وكالــة اطلــب قبــل رفــع اجللســة توجيــه ســؤال للمدعــي هــل‬\n‫املخالصــة التــي قدمهــا يف هــذه اجللســة ال يقــر فيهــا إال بلــزوم ذمتــه مبلــغ‬\n‫اخلمســون الــف ريــال مــع أن الصيــاغ يثبــت مــن أولــه إلــى آخــره أنــه ليــس‬\n‫ال بــن الطرفــن فجرى‬      ‫لــه حــق وتعتبــر منهيــة للمطالبــة حاضــر ًا ومســتقب ً‬\n‫توجيــه ذلــك للمدعــي فقــال  أن الشــركة ‪ ..............‬هــي مــن أعــدت‬\n‫املخالصــة وعلــى مطبوعاتهــم وكان صياغتهــا لصاحلهــم ومت توقيعهــم‬\n‫ا أقــر باخلمســن الــف ريــال وهــي يف ذمتــي وأنــا لــم أوقــع‬  ‫عليهــا وأنــا فعـ ً‬\n‫هــذه املخالصــة والســبب إنكارهــم وبخســهم حلقوقــي وقــد أعــدو‬\n‫املخالصــة وأنــا معهــم يف الشــركة ‪ .................‬فقالــو لــي وقــع ولكنــي‬\n‫رفضــت ألنهــم أنكــروا حقوقــي وأخــذت صــورة مــن املخالصــة األولــى‬\n‫والثانيــة وغــادرت الشــركة علمـ ًا بــأن التفصيــل املذكــور يف املخالصــة‬\n‫الثانيــة أنــا مــن طلبــت إضافتــه يف املخالصــة حتــى نعــرف تفصيــل جميــع‬\n\n\n                                                                                          ‫‪170‬‬\n\f      ‫املطلــوب منــي وعنــد هــذا املوضــع رفعــت اجللســة مــع إفهــام املدعــى عليــه‬\n      ‫وكالــة بإحضــار املطلــوب منــه ويف يــوم جلســة أخــرى وفيهــا حضــر‬\n      ‫املدعــي ‪................‬وحضــر حلضــوره ‪ ...............‬الوكيــل الشــرعي عــن‬\n      ‫الشــركة ‪ ..............‬للترفيــه وبســؤال املدعــى عليــه وكالــة عــن جوابــه‬\n      ‫علــى مــا ورد يف اجللســة الســابقة فقــدم مذكــرة مــن ثــاث صفحــات‬\n      ‫محــرره علــى مطبوعــات شــركة ‪ ..............‬و‪ .............‬محامــون‬\n      ‫ومستشــارون مؤرخــه يف ‪1433/6/3‬ه ونصهــا كالتالــي ( جواب ـ ًا علــى‬\n      ‫مــا دار يف جلســة الثالثــاء ‪1433/4/27‬ه ـ ومــا مت ضبطــه أود أن أبــن‬\n      ‫لفضيلتكــم مــا يلــي‪ :‬أوالً‪ :‬بيــان التجهيــزات اإلضافيــة املقــدم مــن‬\n      ‫املدعــي‪-1.‬ورد يف مقدمــة البيــان (إشــارة إلــى العقــد ‪.......‬وقــد أقــر‬\n      ‫الســيد ‪ .........‬بتحمــل كافــة النواقــص وبيانها)‪،‬وبالتالــي فــإن هــذا‬\n      ‫البيــان يتحــدث عــن نواقــص التــزم املدعــي باســتكمالها‪-2.‬الصفحة‬\n      ‫الثانيــة مــن البيــان مت إدراجهــا ضمــن البيــان وليســت مــن ضمنــه يف‬\n      ‫األصــل وهــذا واضــح مــن اختــاف اخلــط وطريقــة احلقول‪-3.‬الصفحــة‬\n      ‫الثالثــة مــن البيــان تضمنــت مالحظــات إضافيــة بنواقــص يجــب‬\n      ‫اســتكمالها مــن املدعــي وهــذا منصــوص عليــه‪ ،‬وبالتالــي فــإن هــذا‬\n      ‫البيــان يتحــدث عــن نواقــص علــى املدعــي فقط‪-4.‬الفواتيــر التــي أرفقهــا‬\n      ‫املدعــي تضمنــت مشــتريات ال عالقــة لهــا بالشــاليهات كاألدوات‬\n      ‫واألجهــزة األساســية مطلق ـاً( ســياكل‪ ،‬أحذيــة تزحلــق‪ ،‬آلــة حاســبة‪،‬‬\n      ‫طاولــة تنــس ومســتلزماتها‪ ،‬حامــل ملفــات‪ ،‬ملفــات عالقــي‪ ،‬موقــد‬\n      ‫طبــخ أمريكــي لــزوم موظفــي املدعي‪...‬الخ)‪-5.‬التجهيــزات التــي يطالب‬\n      ‫بهــا املدعــي مكتوبــة يف البيــان بخــط اليــد‪ ،‬كمــا أن أقيامهمــا مبالــغ‬\n      ‫فيها(ســلطانية صغيــرة بخمســة عشــر ريال)‪-6.‬هــذا البيــان املقــدم مــن‬\n\n\n‫‪171‬‬\n\f‫املدعــي ال يظهــر فيــه توقيــع أي مــن الطرفــن كمــا أنــه صــورة وليــس‬\n‫أصــل وال يوجــد مــا يفيــد باســتالم موكلتــي ملــا يدعــي بــه املدعــي‪-7.‬‬\n‫املدعــي كمــا هــو معــروف يعمــل يف نشــاط الشــقق املفروشــة وقــد‬\n‫تكــون هــذه املشــتريات تخــص تلــك األنشــطة‪-8.‬األصل أن املدعــي‬\n‫ملتــزم باســتكمال نواقــص مبوجــب محضــر اســتالم الشــاليهات املــؤرخ‬\n‫يف ‪1998/10/17‬م‪،‬حيــث ورد فيه(هــذا وقــد مت اجلــرد بالفعــل خــال‬\n‫اليومــن املشــار إليهمــا أعــاه وتبينــت بعــض النواقــص واملفقــودات مــن‬\n‫جتهيــزات الشــاليهات وقــد مت إدراجهــا بالبيانــات املرفقة(لــم أرفــق‬\n‫صــورة احملضــر منع ـ ًا لتكــرار املرفقات)‪-9.‬محضــر االجتمــاع املوقــع‬\n‫بتاريــخ ‪1998/8/26‬م (املرفــق رقم‪)1‬املوقــع مــن املدعــي نــص صراحــة‬\n‫على موافقة املدعي تســليم الشــاليهات ولم يذكر أن له أي مســتحقات‬\n‫أو خالفــه‪ .‬ثانيـاً‪ :‬املخالصتــان النهائيتــان املقدمــة مــن املدعــي يف اجللســة‬\n‫الســابقة‪-1.‬أقر املدعــي بأنــه مديــن ملوكلتــي مببلــغ خمســن ألــف ريــال‬\n‫مبوجــب هاتــن املخالصتني‪-2.‬ذكــر املدعــي أنــه كان موجــود ًا عنــد‬\n‫إعــداد املخالصــة األولــى يف مقــر موكلتــي وأنــه لــم يوقــع عليهــا كونهــا‬\n‫لــم تتضمــن حقوقــه‪ ،‬ثــم أقــر بأنــه تســلمها وغــادر الشــركة ثــم عــاد‬\n‫وطلــب مــن موكلتــي إضافــة التفصيــل الــوارد يف املخالصــة الثانية‪،‬ومــع‬\n‫ذلــك لــم يطلــب إدراج حقوقــه التــي يزعم‪،‬والقاعــدة الفقهيــة تقــول(أن‬\n‫الســكوت عــن البيــان يف معــرض احلاجــة لبيــان بيــان) فكونــه تســلم‬\n‫املخالصــة األولــى وطلــب صياغــة أخــرى بالتفصيــل الــذي نــص عليــه دون‬\n‫أن يذكــر حقوقــه التــي يزعــم فهــذا يــدل علــى عــدم صحــة قولــه وأن‬\n‫احلقيقــة أن ال حقــوق له‪-3.‬يؤكــد ذلــك مــا أقــر بــه املدعــي يف خطابيــه‬\n‫املؤرخني يف ‪ 1998/12/1‬والثاني يف ‪ 1998/12/30‬حيث أن التفصيل‬\n\n\n                                                                                     ‫‪172‬‬\n\f      ‫يف املخالصــة الثانيــة يطابــق مــا أقــر بــه يف خطابــه املــؤرخ يف‬\n      ‫‪1998/12/30‬م مــن أنــه ليــس لــه حقــوق كمــا يزعم‪-4.‬زعــم املدعــي‬\n      ‫بــأن اخلطابــان أعــاه كان يقصــد منهمــا إنهــاء موضــوع الكهربــاء‬\n      ‫فقط‪،‬وجــاءت املخالصتــان بعــد شــهرين ونصــف مــن اخلطابــن ومــع ذلك‬\n      ‫لــم يطلــب مــن موكلتــي ذكــر حقوقــه املزعومــة يف الوقــت الــذي أصــر‬\n      ‫علــى ذكــر تفصيــل مســتحقات موكلتــي بذمتــه يف املخالصــة الثانيــة‬\n      ‫حســب إقراره‪-5.‬العالقــة بــن موكلتــي واملدعــي محصــورة فقــط يف‬\n      ‫موضــوع الشــاليهات وال توجــد أي أعمــال بينهما‪،‬وحينمــا يقــول بأنــه مت‬\n      ‫حــل املواضيــع األخــرى كل علــى حــده فإنــه يقصــد الناشــئة عــن عالقتــه‬\n      ‫مــع موكلتــي‪ ،‬وهــذا اإلقــرار منــه ليــس عامـ ًا بــل هــو مخصــص يف كل‬\n      ‫موضــوع مــع موكلتــي ‪-6.‬قــول املدعــي(كل علــى حــده )هــو تفصيــل‬\n      ‫وحتديــد وليــس فيــه عمــوم مطلقاً‪.‬فهــو يصــرح بــأن جميــع املواضيــع‬\n      ‫األخــرى مــا عــدا موضــوع خطابيه(الكهربــاء) مت حلهــا كل علــى حــده‪.‬‬\n      ‫‪-7‬إذا كان املدعــي يدعــي بــأن هنــاك أعمــا ًال ومواضيــع أخــرى مــع‬\n      ‫موكلتــي خــاف موضــوع الشــاليهات فعليــه إقامــة دعــوى مســتقلة‬\n      ‫به‪،‬أمــا املواضيــع املتعلقــة بالشــاليهات فقــد مت حــل كل موضــوع منهــا‬\n      ‫علــى حــده كمــا هــو إقراره‪-8.‬جميــع اخلطابــات املوجهــة مــن املدعــي‬\n      ‫إلــى موكلتــي قبــل وبعــد محضــر اســتالم الشــاليهات ال يوجــد فيهــا أي‬\n      ‫ذكــر ملــا يزعمــه مــن حقوق‪،‬أمــا العبــارة التــي يتمســك بهــا املدعــي‬\n      ‫الــواردة يف محضــر اســتالم الشــاليهات ونصها(وعليــه فقــد اســتلمت‬\n      ‫الشــركة ‪.....‬املســتكملة مــن املســتثمر‪)....‬فإنها ضــده وليســت‬\n      ‫له‪،‬فكلمــة مســتكملة تعنــي أن هنــاك نقــص مت اســتكمال بعضــه‬\n      ‫والبعــض اآلخــر لــم يســتكمل‪،‬ويؤكد هــذا مــا ورد قبــل ذلك(‪...‬وتبينت‬\n\n\n‫‪173‬‬\n\f‫بعــض النواقــص واملفقودات‪...‬الــخ)‪ ،‬وبعــده (‪...‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‪...‬‬\n‫الخ)‪-9.‬جميــع مــا ذكرتــه يف هــذه املذكــرة ومــا ســبق ذكرتــه مــن أدلة‬\n‫وقرائــن يؤكــد أن املدعــي ســلم الشــاليهات وليــس لــه أي مطالبــات‬\n‫ســواء يف محضــر تســليم الشــاليهات أو احملضــر املرفــق رقم(‪)1‬ومــا‬\n‫أورده مــن دفــع هــو غيــر صحيح‪.‬ملــا تقــدم ومــا ســبق إيــراده يف مذكراتــي‬\n‫الســابقة فــإن موكلتــي تطلــب مــن فضيلتكم‪-1:‬احلكــم بــرد دعــوى‬\n‫املدعــي لعــدم صحتها‪-2.‬احلكــم بإلزامــه بدفــع مــا بذمتــه ملوكلتــي‬\n‫وهــي  مبلــغ ‪(136.802.62‬مائــة وســتة وثالثــون ألف ـ ًا وثمامنائــة وريــاالن‪.‬‬\n‫‪-3‬احلكــم بإلزامــه بدفــع أجــرة احملامــاة وقدرهــا ‪(120.000‬مائــة‬\n‫وعشــرون ألــف ريــال)‪ .‬وفــق اهلل اجلميــع للحــق والعمــل بــه هــذا مــا لــدي‬\n‫ورفعــت اجللســة للــرد علــى املذكــرة ويف جلســة أخــرى وفيهــا حضــر‬\n‫‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــه ‪ ...............‬وقــد قــدم‬\n‫املدعــي مذكرتــه والتــي تعــذر كتابتهــا يف اجللســة الســابقة ونصهــا‬\n‫كالتالــي (اشــارة الــى مذكــرة وكيــل الشــركة ‪ ................‬املقدمــه‬\n            ‫لفضيلتكم يف جلسه يوم ‪ 1433/6/3‬هـ أود ايضاح مايلي‪-:‬‬\n‫أوالً‪ :‬جــاء يف املذكــرة كالم حــول جتهيــزات الشــاليهات ‪ ،‬وفيــه خلــط‬\n‫وتداخــل بــن مــا للشــركة ومــا عليهــا‪ .‬ولعــل معــد املذكــرة لــم يســتوعب‬\n‫تفاصيــل القضيــة التــي يدافــع عنهــا وكيــل الشــركة ‪ ،‬فلإليضــاح‬\n    ‫وتبســيط هــذه اجلزئيــة اقــول ‪ :‬ان جتهيــزات الشــاليهات هــي نوعــان‪:‬‬\n‫النــوع االول‪ :‬أدوات واغــراض اشــترتها الشــركة وأمنتهــا مــن حســابها‬\n‫لتجهيــز الشــاليهات وقمــت انــا بإســتالمها يف بدايــة التعاقــد وبعــد‬\n‫فســخ العقــد مــن قبــل الشــركة وتســليمها يف نهايــة التعاقــد مت جــرد‬\n\n\n                                                                                       ‫‪174‬‬\n\f      ‫تلــك التجهيــزات فوجــد يف بعضهــا نقــص ويف البعــض األخــر تلــف فتــم‬\n      ‫تقديــر قيمــة الناقــص والتألــف منهــا مببلــغ خمســة عشــر ألفـ ًا وتســعمائة‬\n                                ‫‪ 15900‬ريــال ســجلته يف ذمتــي حلســاب الشــركة‬\n      ‫النــوع الثانــي ‪ :‬أدوات ناقصــة كانــت حتتــاج إليهــا الشــاليهات وهــي‬\n      ‫مبثابــة اســتكمال جتهيــزات ضروريــه لــم تقــم الشــركة أصــا ‬\n      ‫بتأمينهــا فقمــت بتأمينهــا مــن حســابي اخلــاص مببلــغ إجمالــي قــدرة ســتة‬\n      ‫عشــر الف ـ ًا وثالثمائــة وتســعه وتســعون ‪ 16399‬ريــال وذلــك يف الشــهور‬\n      ‫األولــى مــن العقــد وعنــد تســليم الشــاليهات بعــد فســخ العقــد اســتلمتها‬\n      ‫الشــركة منــي ضمــن كامــل التجهيــزات املنصــوص عليهــا مبحضــر‬\n      ‫تســليم الشــاليهات ونصــه ( وعليــه فقــد اســتلمت الشــركة ‪.................‬‬\n      ‫الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة‬\n      ‫لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر ) وهــي مازالــت‬\n      ‫مــن ضمــن حقوقــي التــي بذمــة الشــركة وممــا يجــب إيضاخــه أيضــا‬\n      ‫ان مســئولي الشــركة هــم الذيــن اعــدوا بيانــات التجهيــزات الناقصــة‬\n      ‫والتجهيــزات الزائــدة اثنــاء اجلــرد فمــا كان فيهــا زائــدا عمــا اســتلمته‬\n      ‫ا خاصـ ًا بــه ثــم طلبــوا بعــد ذلــك‬\n                                            ‫مــن الشــركة افــردوا لــه يف البيــان حقـ ً‬\n      ‫منــي اســعارها مبوجــب الفواتيــر التــي تتوفــر لــدي ومــا ليســت فاتورتــه‬\n      ‫عنــدي رجعــوا اليهــا مبلــف الشــاليهات الــذي بحوزتهــم واي صنــف لــم‬\n      ‫يعثــروا لــه علــى فاتــورة ( كالســلطانيه مثــا ) حــددوا قيمتهــا بنفــس‬\n      ‫الســعر الــذي هــم أمنوهــا بــه يف بدايــة التجهيــز حســب مــاورد بخانتــه‬\n      ‫وســجلوه‪ .‬فــإن كان وكيــل الشــركة يــرى ان ســعر الســلطانيه مبالــغ‬\n      ‫فيــه فليرجــع لبيــان موكلتــه ‪ ،‬أمــا التشــكيك يف مصداقيــة البيانــات‬\n      ‫واختــاف اخلــط كمــا يزعــم فإنــي ال أظنــه يجهــل الفــرق بــن صيغــة (‬\n\n\n‫‪175‬‬\n\f‫وقــد اقــر الســيد ‪ )........ /‬وصيغــة (أقــر انــا ‪ )..........‬حيــث االولــى وهــي‬\n‫الصيغــة املكتوبــه تؤكــد للمطلــع علــى البيانــات ان مســئولي الشــركه‬\n‫هــم مــن قامــوا بإعــداد البيانــات ‪ ،‬وليــس انــا‪ .‬وهــم مــن جتاهــل التوقيــع‬\n‫عليهــا اوالً‪ .‬فــإن كان وكيــل الشــركة اليعتــرف ببيانــات التجهيــزات‬\n‫الزائــدة اص ـاً‪ .‬فعليــة تبع ـ ًا لذلــك ان ال يطالــب بقيمــة التجهيــزات‬\n‫الناقصــة وذلــك لعــدم التوقيــع‪ .‬ثاني ـ ًا ‪ :‬ان محضــر االجتمــاع بتاريــخ‬\n‫‪1998/8/26‬م املوقــع مــن الطرفــن نــص صراحــة علــى أن فســخ العقــد‬\n‫مت (بنــاء علــى رغبــة الشــركة) املشــروطة (مبــا تضمنتــه املراســات)‬\n‫الس ــابقة لتوقيــع احملض ــر [ مرفــق رقــم ‪ ]1‬ومــن ضمــن املراســات ايضـ ًا‬\n‫‪ .1‬خطــاب عــدم االنتفــاع باملأجــور نتيجــة لوجــود عيــوب إنشــائية‬\n‫ومعماريــة يف املشــروع واملثبتــة بتقريــر هندســي اعترفــت بهــا الشــركة‬\n‫وأكــدت خطورتهــا بخطابهــا املوجــة للمقــاول املنفــذ للمشــروع [ مرفــق‬\n                                                                           ‫رقــم ‪.]2‬‬\n‫‪.2‬خطاباتــي املتعــدده للشــركة بتحميلهــم املســئولية كاملــة نتيجــة‬\n‫إلهمــال أعمــال الصيانــه ‪ ،‬وجتاهــل العنايــة بالزراعــة [ مرفــق رقــم ‪]3‬‬\n‫رغــم انهــم قبضــوا اجرتهــا بشــيكات مدفوعــه مقدمـ ًا عنــد بدايــة كل‬\n‫شــهر فأنــا ال اطالــب الشــركة باجــرة الصيانــه لذاتهــا فقــط بــل اطالبهم‬\n              ‫ايض ـ ًا بأثــر االهمــال والتجاهــل اللذيــن تســببا يف خســارتي‪.‬‬\n‫‪.3‬خطاباتــي للشــركة املطالبــة بإجنــاز الرصيــف البحــري [ مرفــق رقــم‬\n                                                                       ‫‪ 4‬ورقــم ‪.]5‬‬\n‫‪.4‬خطابــي للشــركه بطلــب االرقــام الســريه ألجهــزة االتصــاالت‬\n‫الهاتفيــه وأجهــزة اســتقبال القنــوات الفضائيــة التــي تكثــر اعطالهــا‬\n‫والتــي الميكــن اصالحهــا إال مبعرفــة االرقــام الســرية لهــا والتــي هــي‬\n\n\n                                                                                        ‫‪176‬‬\n\f      ‫بحوزتهــم وعنــد وجــود أي عطــل يحتــاج االمــر الــى وقــت ليــس بالقصيــر‬\n                                                    ‫لالتصــال باملتعهــد ثــم االصــاح‪.‬‬\n      ‫فضيلــة القاضــي‪ :‬إن الشــركة ‪ ..............‬أجرتنــي مرفق ـ ًا ســياحي ًا ‪،‬‬\n      ‫وبعدمــا قبضــت وضمنــت كامــل اجرتــه ‪ ،‬عطلــت صيانتــه‪ ،‬وأهملــت‬\n      ‫زراعتــه ‪ ،‬ومنعــت عنــي ارقــام تشــغيل واصــاح اجهزتــه لفتــرات متقطعــة‬\n                                                                        ‫[مرفــق رقــم ‪.]6‬‬\n      ‫ثالث ـاً‪ :‬أمــا إشــارة وكيــل الشــركة الــى مــا جــاء بخطابــي املوجــه‬\n      ‫للشــركة بتاريــخ ‪1998/12/1‬م وخطابــي املــؤرخ يف ‪1998/12/30‬م‬\n      ‫‪ ،‬فــإن ســياقهما يؤكــد لفضيلتكــم أنهمــا خاصــان مبعاجلــة موضــوع‬\n      ‫التجهيــزات الناقصــة ‪ ،‬واســتهالك الكهربــاء ‪ ،‬ومنع ـ ًا لإلطالــة‬\n      ‫والتكــرار فإنــي احيــل فضيلتكــم مشــكور ًا الــى مذكرتــي الســابقة‬\n                                                           ‫املؤرخــة يف ‪1433/1/2‬هــ‪.‬‬\n      ‫رابعـ ًا ‪ :‬مــا يدعيــه وكيــل الشــركة بــأن (الســكوت عــن البيــان ‪ -‬بعــد‬\n      ‫اطالعــي علــى صياغتهــم للمخالصــة ؟ بيــان ) فأقــول أن احلــال وقتهــا لــم‬\n      ‫يكــن ســكوت ًا بــل كان رد ًا منــي للصياغــة التــي هــي لصالــح طــرف‬\n      ‫واحــد دون اعتبــار للطــرف االخــر ‪ ،‬وحيــث ان االمــر بهــذا الشــكل‬\n      ‫ال يحتمــل‪ .‬نتيجــة جحودهــم ونكرانهــم لكامــل حقوقــي حتــى مــا هــو‬\n      ‫منهــا ثابــت لديهــم وقتهــا فضلــت االنســحاب واخلــروج من الشــركة ألنهم‬\n      ‫وبهــذه الصفــة التعســفية املماثلــة ملــا ســبق ال جــدوى مــن التفاهــم معهــم او‬\n      ‫االذعــان ملطالبهــم‪ ،‬والتوســل لهــم وعندهــا فضلــت اللجــوء للقضــاء ولــم‬\n      ‫يكــن آنــذاك وكيــل الشــركة حينهــا حاضــر ًا حتــى يصــف املوقــف‬\n      ‫بالســكوت او االذعــان وهــو يعلــم بــأن عــدم توقيعــي علــى مــا يســميه‬\n      ‫مخالصــة إمنــا هــو اعتــراض علــى جتاهلهــم حقوقــي وامنــا توقيعهــم عليهــا‬\n\n\n‫‪177‬‬\n\f‫هــو حتديــد وتثبيــت حلقوقهــم قبلــي بخمســن الــف ‪ 50000‬ريــال وهــذا‬\n‫املبلــغ هــو مجمــوع مــا مت التفاهــم حولــه ودراســته كل علــى حــده ومت‬\n‫تثبيتــه ســابق ًا بنــد ًا بنــداً‪ ،‬وبعــد ذلــك االنــكار حلقوقــي الثابتــة يف ذمــة‬\n‫الشــركة جلــأت الــى القضــاء طالب ـ ًا انتــزاع حقوقــي مــن الشــركة‬\n                                     ‫‪ .......................‬وهــي محــددة كمــا يلــي‪:‬‬\n‫‪ .1‬مبلــغ مليــون ‪ 1.000.000‬ريــال مدفــوع مقدم ـ ًا اســتلمته الشــركة‬\n                      ‫منــي كإيجــار لســنه واحــده وحجبــت عنــي املنفعــة‪.‬‬\n‫‪ .2‬مبلــغ إثنــان وعشــرون الــف وســبعمائة واربعــه وســبعون ‪ 22774‬ريــال‬\n‫مدفــوع مقدم ـ ًا ايض ـ ًا لــكل شــهر اســتلمتها الشــركة منــي كأجــرة‬\n‫صيانــه لــم تقــم بهــا ‪ ،‬ومازالــت تنكــر املســئولية بتحمل اعمــال الصيانة‪.‬‬\n‫‪ .3‬مبلــغ تســعه وتســعون الــف وثمامنائــه وخمســه عشــر ‪99815‬ريــال‬\n‫قيمــة مشــتريات وإصالحــات ‪ ،‬وحســابات مقيــده يف دفاتــر الشــركة‬\n                                                                            ‫لصاحلنــا‪.‬‬\n‫‪ .4‬مبلــغ مليــون وثالثمائــة وخمســون الــف ‪ 1350000‬ريــال تعويــض جــراء‬\n‫فســخ عقــد الشــاليهات ‪ ،‬وحجــب املنفعــة املتوخــاة مــن اســتثمار املشــروع‬\n‫للتســع ســنوات املتبقيــة يف العقــد مبعــدل ربــح ‪ %15‬مــن قيمــة االيجــار‪. .‬‬\n‫مبلــغ مائتــان واربعــون الــف ‪ 240000‬ريــال أجــرة وأتعــاب وكيــل شــرعي‬\n‫قــام مبتابعــة وحضــور جلســات هــذه القضيــة ملــدة تزيــد عــن ثالثــة عشــر‬\n                                                                                  ‫عاماً‪.‬‬\n‫وفقكــم اهلل ‪ ،‬وفهمكــم حلكمــه ‪ ،‬والســام عليكــم ورحمــه اهلل‬\n                                                                   ‫وبركاتــه‪ .‬أ‪.‬ه ـ‬\n‫وبســؤال املدعــى عليــه وكالــه عــن جوابــه علــى املذكــرة فقــال أكتفــي‬\n‫مبــا قدمتــه ســابقا بنــاء عليــه فقــد رفعــت اجللســة لتأمــل جميــع مــا ســبق‬\n\n\n                                                                                           ‫‪178‬‬\n\f      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي ‪ ...............‬وحضــر حلضــوره‬\n      ‫املدعــى عليــه وكالــه ‪ ..............‬وبعــد ســماع الدعــوى واإلجابــة وجميــع‬\n      ‫مــا ســبق فقــد تقــدم املدعــي ‪ ......................‬بدعــوى للمطالبــة بإعــادة‬\n      ‫إيجــار الســنة األولــى مبلــغ ‪ 1000000‬ريــال‪ ،‬وقيمــة الصيانــة مبلــغ‬\n      ‫‪ 22774‬ريــال‪ ،‬ومطالبــات متفرقــة متعلقــة بالعقــد بقيمــة ‪ 99815‬ريــال‪،‬‬\n      ‫واملطالبــة بالتعويــض عــن األربــاح املتوقعــة عــن تســع ســنوات‪ ،‬وبعــد‬\n      ‫مــداوالت متعــددة ويف اجللســة املؤرخــة يف ‪ 1433/04/27‬اســتند املدعــي‬\n      ‫يف إثبــات مــا يف ذمتــه للشــركة املدعــى عليهــا مــن مبالــغ ماليــة علــى‬\n      ‫الوثيقــة احملــررة بتاريــخ ‪1419/11/01‬ه ـ وعنوانهــا (مخالصــة نهائيــة)‪،‬‬\n      ‫حيــث ورد يف املخالصــة مــا نصــه‪( :‬فقــد مت االتفــاق بتاريخــه علــى عمــل‬\n      ‫هــذه املخالصــة النهائيــة والتــي يقــوم مبوجبهــا أ‪ ....................../‬بدفــع‬\n      ‫(ويعتبــر هــذا‬\n                   ‫مبلــغ ‪ 50000‬ريــال(‪ ،‬كمــا تضمنــت الوثيقــة مــا نصــه‪ُ :‬‬\n      ‫املبلــغ مبثابــة مخالصــة بــن الطرفــن)‪ ،‬ثــم يف نفــس اجللســة ذكــر‬\n      ‫املدعــي أنــه طلــب تعديــل ورقــة املخالصــة لتفصيــل مــا عليــه مــن أمــوال‪،‬‬\n      ‫وقــد جــرى حتريرهــا بتاريــخ ‪1419/11/01‬هــ‪ ،‬وبتأمــل ذلــك  وجــدت‬\n      ‫ـزء وتــرك جــزء‪ ،‬مــع أن مبلــغ‬     ‫أن املدعــي أخــذ مــن هاتــن املخالصتــن جـ ً‬\n      ‫اخلمســن ألــف ريــال خــرج يف املخالصتــن مخــرج االتفــاق ولــم يكــن‬\n      ‫إقــرار ًا مجــرد ًا مــن املدعــي أو إقــرارا مــن الشــركة املدعــى عليهــا‬\n       ‫قبــل إبــرام املخالصــة ‪ ،‬ومعلــوم أن االتفــاق كلٌ ال يتجــزأ‪ ،‬إذ كيـ َ‬\n      ‫ـف‬\n      ‫ُي َوافـ ُـق أحــد طــريف النــزاع علــى أخــذ مــا يريــد مــن املخالصــة وتــرك مــا ال‬\n      ‫خصمــه وال يلتــزم‬\n                     ‫َ‬                   ‫يريــد‪ ،‬وكيــف يســتند أحدهمــا علــى شــي ٍء ُ‬\n                               ‫ويلــزم بــه‬\n      ‫هــو مبــا فيــه إلــزام لــه‪ ،‬ويعضــد هــذا االســتنتاج انضمــام قرينــة أخــرى‬\n      ‫وهــي خطــاب حــرره املدعــي بتاريــخ ‪1419/09/12‬ه ـ املتضمــن معاجلــة‬\n\n\n‫‪179‬‬\n\f‫موضــوع اســتهالك الكهربــاء حيــث تضمــن يف آخــره مــا نصــه‪( :‬رغبــة‬\n‫منــا يف إنهــاء موضــوع الكهربــاء بغــض النظــر عــن هــذه األخطــاء وذلــك‬\n‫بغيــة الوصــول إلــى حلــول مرضيــة مثلهــا مثــل املواضيــع األخــرى التــي مت‬\n‫حلهــا كل علــى حــده)‪ ،‬وقــد ورد يف املــادة ‪ 155‬مــن نظــام املرافعــات‬\n‫الشــرعية‪( :‬يجــوز للقاضــي أن يســتنتج قرينــة‪ ،‬أو أكثــر مــن وقائــع‬\n‫الدعــوى‪ ،‬أو ُمناقشــة اخلصــوم أو الشــهود؛ لتكــون ُمســتند ًا حلُكمِ ــه‬\n‫ا ناقص ـ ًا ثبــت لديــه ليكـ ِّـون بهمــا مع ـ ًا اقتناعــه‬‫أو ُليكمِ ــل ِبهــا دلي ـ ً‬\n‫بثبــوت احلــق إلصــدار ا ُحلكــم)‪ ،‬وهــو مــا قــرره أهــل العلــم رحمهــم اهلل‬\n‫حيــث يقــول ابــن رجــب احلنبلــي رحمــه اهلل يف جامــع العلــوم واحلكــم‬\n‫ص ‪( :316‬وقــد كان شــريح وإيــاس بــن معاويــة يحكمــان يف األمــوال‬\n‫املتنــازع فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعيــن ‪..‬‬\n‫وكان يقضــي بنحــو ذلــك أبــو بكــر الشــامي مــن الشــافعية ورجــح قولــه‬\n‫ـدي أن يف‬  ‫ابــن عقيــل مــن أصحابنــا)‪ ،‬بنــاء علــى مــا ســبق فلــم يثبــت لـ ّ‬\n‫ذمــة الشــركة املدعــى عليهــا حــق مالــي للمدعــي وصرفــت النظــر عــن‬\n‫ـدي أن يف ذمــة املدعــي ‪....................‬‬\n                                           ‫مطالبتــه لعــدم اســتحقاقه‪ ،‬وثبــت لـ ّ‬\n‫مبلــغ ‪ 50000‬ريــال وألزمتــه بدفعهــا حــا ًال للشــركة ‪ ،...................‬وبــه‬\n‫حكمــت‪ ،‬وبعــرض ذلــك علــى الطرفــن قــرر املدعــي عليــه وكالــة‬\n‫قناعتــه أمــا املدعــي فقــرر عــدم القناعــة وجــرى إفهامــه أن عليــه مراجعــة‬\n‫احملكمــة خــال عشــرة أيــام الســتالم نســخة مــن احلكــم ثــم تبــدأ املــدة‬\n‫االعتراضيــة وأن عليــه تقــدمي الئحتــه خــال ثالثــن يومــا فــإذا لــم يقــدم‬\n‫اعتراضــه خــال هــذه املــدة ســقط حقــه يف طلــب االســتئناف واكتســب‬\n‫احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/21‬هــ‪.‬‬\n\n\n                                                                                           ‫‪180‬‬\n\f        ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n        ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n        ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n        ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪341437809‬‬\n      ‫وتاريــخ ‪1434/7/12‬ه واملقيــدة لــدى احملكمــة برقــم ‪  341724906‬‬\n        ‫وتاريــخ ‪1434/7/17‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n        ‫باحملكمــة الشــيخ د‪ ........................‬املسـ ّـجل برقــم ‪ 3416698‬وتاريــخ‬\n        ‫‪1434/1/19‬ه ـ اخلــاص بدعــوى‪ ..................../‬ضد‪/‬الشــركة‬\n        ‫‪ ....................‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه‬\n        ‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحة‬\n        ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                                  ‫حــرر يف ‪1434/9/22‬هــ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":125,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"98894f9b092143dfc7828fa6f593f2bd0da199a2ef4cbf20de54865c5bd8b4de","normalized_text_hash":"95a597e754195a414213ed6d4ab369de421926b339d5507e57210e38ebf09ea3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p125-3416698"},{"id":"8a7488c8-82b6-5c9b-a968-b9d9bfac2f2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بقيمة األجرة احلال منها واملتأخر -إقرار املدعى عليه بعدم السداد -تعديل الطلبات بإضافة فسخ العقد -سجن املدعى عليه يف قضايا حقوقيه وعجزه عن السداد -احلكم بسداد قيمة األجرة وتسليم العن محل اإلجارة .","document_number":"34224021","case_number":"34224021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"إجارة -مطالبة بقيمة األجرة احلال منها واملتأخر -إقرار املدعى عليه بعدم السداد -تعديل الطلبات بإضافة فسخ العقد -سجن املدعى عليه يف قضايا حقوقيه وعجزه عن السداد -احلكم بسداد قيمة األجرة وتسليم العن محل اإلجارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/27 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34224021 :‬‬\n                   ‫َر ْق ُم الدعوى‪34224021 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34274920‬تاريخه‪1434/7/22 :‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة بقيمــة األجــرة احلــال منهــا واملتأخــر ‪ -‬إقــرار املدعــى‬\n‫عليــه بعــدم الســداد ‪ -‬تعديــل الطلبــات بإضافــة فســخ العقــد ‪ -‬ســجن‬\n‫املدعــى عليــه يف قضايــا حقوقيــه وعجــزه عــن الســداد ‪ -‬احلكــم بســداد‬\n                              ‫قيمــة األجــرة وتســليم العــن محــل اإلجــارة ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                             ‫تســبيب احلكــم‬\n\n\n\n\n‫ادعــى املدعــى ضــد املدعــى عليــه انــه اســتأجر منــه عقــار ًا مــدة خمــس‬\n‫ســنوات باجــره ســنويه معلومــه املقــدار علــى ان تدفــع على ثــاث دفعات‪-‬‬\n‫مت ســداد قيمــة الدفعــه االولــى ‪ -‬والثانيــه منقوصــه عشــرة االف ‪ -‬ولــم‬\n‫يســلم الدفعــة الثالثــه علم ـ ًا بانهــا حالــة عليــه ‪ -‬طلــب املدعــي احلكــم‬\n                                                    ‫بدفــع املتبقــي مــن األجــرة‪.‬‬\n‫يف جلســه اخــرى حضــر الطرفــان واقــر املدعــى عليــه مبــا ذكــره املدعى‬\n‫جملــة وتفصيــا واكــد انــه يف ذمتــه مبلــغ ‪ 37000‬ريــال وال مانــع لديــه‬\n‫مــن ســدادها‪ -‬عــدل املدعــى عــن طلباتــه باالضافــه لســداد احلــال مــن‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫القيمــة االيجاريــه بطلــب االخــاء الفــوري ملماطلتــه وملخالفتــه مقتضــى‬\n      ‫عقــد االيجــار  ثــم عــرض االخــاء علــى املدعــى عليــه ولــم يقــره وبالتالــي‬\n      ‫والقــرار املدعــى عليــه مبــا يف ذمتــه مــن القيمــة االيجاريــه احلالــه وعــدم‬\n      ‫ســداده اياهــا طيلــة الفتــرة املاضيــه وملقتضــى العقــد الــذي يوجــب‬\n      ‫فســخه دفع ـ ًا للضــرر الواقــع علــى املالــك ‪ -‬ولكــون املدعــى عليــه لــم‬\n      ‫يحضــر ملجلــس احلكــم إال بعــد ان مت ســجنه يف عــدة قضايــا حقوقيــه‬\n      ‫اخــرى ممــا يــدل علــى عجــزه بالوفــاء بالعقــد حكــم عليــه بــان يســلم‬\n      ‫للمدعــى مبلــغ ‪ 37000‬ريــال وان يســلم العمــارة محــل الدعــوى فــور ًا دون‬\n      ‫تأخيــر‪ -‬قنــع املدعــى باحلكــم ولــم يقنــع املدعــى عليــه ‪ -‬صــدق احلكــم‬\n                                                         ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 3362412‬وتاريــخ‬\n      ‫‪1433/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33161638‬وتاريــخ‬\n      ‫‪1433/1/24‬ه ـ واملتعلقــة بدعــوى ‪ ......................‬ضــد ‪...........................‬‬\n      ‫يف أجــرة عقــار  حضــر ‪ .....................‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .................‬الوكيــل عــن ‪ ...................‬بالوكالــة رقــم‬\n      ‫‪ 51370‬يف ‪1431/8/20‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة والتــي‬\n        ‫تخــول لــه ( املداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا وإقامــة‬\n        ‫البينــة والدفــع وقبــول احلكــم واإلعتــراض عليــه ‪ ) ..‬ولــم يحضــر املدعــى‬\n      ‫عليــه وقــررت ســماع الدعــوى غيابيـ ًا ‪ .‬وبســؤال وكيــل املدعي عن دعواه  ‬\n‫‪209‬‬\n\f‫ا ‪:‬أدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم  ‬              ‫أدعــى قائ ـ ً‬\n  ‫‪ ..............................‬بأنــه اســتأجر مــن موكلــي عقــاره الكائــن يف ‪...‬‬\n‫مــدة خمــس ســنوات تبــدأ يف ‪1432/1/1‬ه ـ وتنتهــي يف ‪1436/12/30‬هـ  ‬\n  ‫وهــو عبــارة عــن عمــارة ســكينة مملوكــة لــه مبوجــب الصــك رقــم ‪...‬‬\n  ‫يف ‪1431/9/18‬ه ـ بأجــرة ســنوي ًة قدرهــا مئتــان وعشــرون ألــف ريــال‬\n  ‫علــى دفعــات ثــاث الدفعــة األولــى ثمانــن الــف ريــال ســلمها ملوكلــي‪،‬‬\n  ‫والدفعــة الثانيــة ســبعني الــف ريــال ســلم منهــا ملوكلــي ســتني ألــف ريــال‬\n  ‫وبقــي منهــا عشــرة آالف ريــال‪ ،‬لــم تســلم حتــى اآلن‪ ،‬والدفعــة الثالثــة‬\n  ‫ســبعني ألــف ريــال لــم يســلمها ملوكلــي حتــى االن‪ ،‬علمـ ًا أنهــا حالــة مــن‬\n  ‫تاريــخ ‪1432/09/20‬ه ـ أطلــب احلكــم علــى املدعــى عليــه بدفــع املتبقــي‬\n  ‫مــن اإليجــار وقــدره ثمانــن ألــف ريــال ‪ .‬هــذه دعواي ‪ .‬وقررت رفع اجللســة‬\n  ‫لتبليــغ املدعــى عليــة أصالــة مبوعدها‪ ،‬وأفهمــت وكيل املدعي بإحضار‬\n  ‫مســتنداته (صــك العقــار‪ ،‬وعقــد اإليجــار) ويف جلســة  أخــرى أحضــر‬\n‫املدعــي وكالــة ‪ ....................‬بالســجل املدنــي رقــم ………………  ‬\n  ‫بوكالتــه عــن ‪ ..............‬وجــرى الالطــاع علــى أصــل صــك العقــار‬\n  ‫رقــم … يف ‪1431/9/18‬ه ـ ومت اإلطــاع عليــه فوجــد يتضمــن متلــك‬\n  ‫املدعــي للعقــار املذكــور‪ ،‬كمــا مت اإلطــاع علــى أصــل عقــد اإليجــار‬\n  ‫ووجــد يتضمــن ‪ ( :‬أنــه مت يف يــوم الســبت ‪1431/12/28‬ه ـ التعاقــد‬\n  ‫بــن الطــرف األول ‪( ...............‬املؤجــر)‪ ،‬والطــرف الثانــي ‪.....................‬‬\n  ‫(املســتأجر) علــى تأجيــر الطــرف األول للطــرف الثانــي العقــار املدعــى‬\n  ‫بــه للطــرف الثانــي‪ ،‬بايجــار ســنوي وقــدره مائتــان وعشــرون ألــف ريــال‪،‬‬\n  ‫تدفــع علــى النحــو التالــي ‪ :‬أو ًال ‪ :‬ثمانــن ألــف ريــال عنــد توقيــع العقــد‪،‬‬\n  ‫وتدفــع يف الســنوات الالحقــة للســنة األولــى يف األول مــن شــهر محــرم‬\n\n\n                                                                                             ‫‪210‬‬\n\f        ‫مــن كل عــام ‪ .‬ثاني ـ ًا ‪ :‬ســبعون ألــف ريــال يف األول مــن شــهر جمــادى‬\n        ‫األول مــن كل عــام ‪ .‬ثالث ـ ًا ‪ :‬ســبعون ألــف ريــال يف يــوم عشــرين مــن‬\n        ‫شــهر رمضــان مــن كل عــام ) أ‪.‬هــ  طلبــت مــن املدعــي وكالــة إحضــار‬\n        ‫األصيــل للجلســة القادمــة ألداء اليمــن ‪.‬ويف جلســة أخــرى حضــر املدعــي‬\n        ‫وكالــة ‪ ......................‬ولــم يحضــر املدعــى عليــه ويف  جلســة أخــرى‬\n        ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــي أصالــة ألداء اليمــن كمــا‬\n        ‫لــم يحضــر املدعــى عليــه ولــم جنــد يف املعاملــة مايفيــد تبلغــه ورفعــت‬\n        ‫اجللســة ويف جلســة اخــرى حضــر وكيــل املدعــي ولــم يحضــر املدعــى‬\n        ‫عليــه كمــا لــم يحضــر املدعــي اصالــة ورفعــت اجللســة ويف جلســة أخــرى‬\n        ‫حضــر املدعــى وكالــة ولــم يحضــر املدعــى عليــه ورفعــت اجللســة  ويف‬\n        ‫جلســة أخــرى لــم يحضــر الطرفــان وشــطبت الدعــوى ويف جلســة أخــرى‬\n        ‫حضــر الطرفــان وبعــرض الدعــوى علــى املدعــى عليــه قــال أريــد مهلــة‬\n        ‫للــرد علــى هــذه الدعــوى يف اجللســة القادمــة ورفعــت اجللســة  حضــر‬\n        ‫املدعــي أصالــة ولــم يحضــر املدعــى عليــه ويف جلســة أخــرى   حضــر‬\n        ‫أصالــة ‪ ....................‬ســعودي بالســجل املدنــي رقــم ‪.........................‬‬\n        ‫كمــا حضــر حلضــوره املدعــى عليــه ‪ ...................‬ســعودي بالســجل‬\n        ‫املدنــي رقــم ‪ ...........................‬وبعــرض الدعــوى علــى املدعــى عليــه‬\n        ‫ا ‪ :‬مــا ذكــره املدعــي كلــه صحيــح جملــة وتفصيــا ‪،‬‬               ‫أجــاب قائ ـ ً‬\n        ‫فقــد اســتأجرت منــه العمــارة الواقعــة يف حــي ‪ ...‬يف املدينــة املنــورة جــوار‬\n        ‫مســجد ‪ ، ...‬واملكونــة مــن أربعــة طوابــق واململوكــه للمدعــي بالصــك‬\n        ‫الصــادر مــن كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪ ..............‬يف‬\n      ‫‪1431/09/18‬ه ـ ‪ ،‬منــذ ‪1432/01/01‬ه ـ ولــم أســدده ســوى دفعتــن  ‬\n        ‫فقــط ‪ ،‬وبقــي لــه يف ذمتــي الدفعــة األخيــرة مــن عــام ‪1432‬ه ـ وقدرهــا‬\n\n\n‫‪211‬‬\n\f  ‫ســبعون ألف ريال ‪ ،‬وكذلك لم أســدده من إيجار عامي ‪1433‬و ‪1434‬‬\n  ‫ه ـ وال ريــا ًال واحــد ًا ‪ ،‬علمـ ًا أنــه قــد حلــت علــي دفعتــان مــن عــام ‪1434‬ه ـ‬\n  ‫فقــط  ‪ ،‬ومجمــوع مــا تبقــى لــه يف ذمتــي ثالثمائــة وســبعون ألــف ريــال‬\n  ‫‪ ،‬وال مانــع لــدي مــن تســديده هــذا املبلــغ إذا تيســرت أمــوري ‪ ،‬وأطلــب‬\n  ‫منــه إمهالــي حتــى تتيســر أمــوري ‪ .‬هكــذا أجــاب‪ .‬وبعــرض جوابــه علــى‬\n  ‫ا ‪ :‬ماذكــره املدعــى عليــه يف جوابــه فهــو‬         ‫املدعــي أصالــة أجــاب قائ ـ ً‬\n  ‫صحيــح ‪ ،‬وهــو املبلــغ الــذي أدعــى بــه فقــط ‪ ،‬وغيــر موافــق علــى إمهالــه‬\n  ‫وأطلــب احلكــم عليــه بهــذا املبلــغ ‪ ،‬كمــا أطلــب احلكــم عليــه باإلخــاء‬\n  ‫الفــوري ملاطلتــه ومخالفتــه مقتضــى العقــد بعــدم تســليمي اإليجــارات‬\n  ‫‪ ،‬والتــي أقــر بهــا لديكــم يف هــذه اجللســة ‪ .‬هكــذا أجــاب ‪ .‬وبعــرض‬\n  ‫ا ‪ :‬أنــا غيــر مســتعد باإلخــاء‬     ‫اإلخــاء علــى املدعــى عليــه أجــاب قائ ـ ً‬\n  ‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة ‪ ،‬وإلقــرار‬       ‫‪ .‬هكــذا أجــاب ‪ .‬بنـ ً‬\n  ‫املدعــى عليــه بــأن يف ذمتــه للمدعــي مبلــغ قــدره ثالثمائــة وســبعون ألــف‬\n  ‫ريــال لــم يســددها مــن اإليجــارات ‪ ،‬وإلقــرار املدعــى عليــه بعــدم الســداد‬\n  ‫طيلــة الفتــرة املاضيــة حتــى وصلــت املديونيــة إلــى املبلــغ الــذي أقربــه يف‬\n  ‫هــذه اجللســة ‪ ،‬وكل هــذا يعــد مخالفــة صريحــة ملقتضــى العقــد ويوجــب‬\n  ‫الفســخ دفعــا للضــرر الواقــع علــى املالــك ‪ ،‬وألن املدعــى عليــه لــم يحضــر‬\n  ‫ملجلــس احلكــم إال بعــد أن ســجن يف قضايــا حقوقيــة أخــرى ‪ ،‬ممــا‬\n  ‫يــدل علــى عجــزه عــن الوفــاء بالعقــد ؛ فقــد حكمــت علــى املدعــى عليــه‬\n‫‪ .....................‬بــأن يســلم للمدعــي ‪ ..................‬مبلــغ ثالثمائــة وســبعني ‬\n  ‫ألــف ريــال ‪ ،‬كمــا حكمــت عليــه بــأن يســلم العمــارة  محــل الدعــوى‬\n‫ذات الصــك الصــادر كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪  ........‬‬\n  ‫يف ‪1431/09/18‬هــ   فــور ًا مــن غيــر تأخيــر ‪ .‬وبعــرض احلكــم علــى‬\n\n\n                                                                                             ‫‪212‬‬\n\f      ‫املدعــى عليــه قــرر عــدم القناعــة باحلكــم ؛ فأفهــم بــان لــه مهلــة ثالثــن‬\n      ‫يومــا مــن اســتالمه احلكــم ليقــدم الئحتــه االعتراضيــة ‪ ،‬وأنــه إن لــم‬\n      ‫يعتــرض خاللهــا فسيســقط حقــه يف االعتــراض ‪ ،‬كمــا أفهــم باحلضــور‬\n      ‫احلضــور يــوم االثنــن ‪1434/5/27‬ه ـ الســاعة العاشــر الســتالم نســخة‬\n      ‫احلكــم ‪ ،‬وأنــه إن لــم يحضــر الســتالم الصــك فــإن املــدة ستحتســب‬\n      ‫عليــه مــن هــذا التاريــخ ففهــم ذلــك ‪ ،‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/05/25‬هــ‪..‬‬\n      ‫احلمــد هلل وحــده‪ :‬وبعــد رفــع كامــل أوراق املعاملــة إلــى محكمــة‬\n      ‫اإلســتئناف عــادت وقــد مت تصديــق احلكــم مبوجــب قــرار الدائــرة‬\n      ‫احلقوقيــة األولــى رقــم ‪ 34274920‬يف ‪1434/7/22‬ه ـ املظهــر علــى صك‬\n      ‫احلكــم رقــم ‪ 34224021‬يف ‪1434/5/27‬ه ـ ‪ .‬وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/3‬ه‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم‬\n      ‫‪ 33/161638‬وتاريــخ ‪1434/7/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ..........................‬القاضــي باحملكمــة العامــة باملدينــة‬\n      ‫املنــورة واملســجل بعــدد ‪ 34224021‬وتاريــخ ‪1434/5/27‬هـ ـ واملتضمــن‬\n      ‫دعــوى‪ .......................... /‬ضــد‪ ........................... /‬واحملكــوم فيــه مبــا‬\n      ‫دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينا محمد‬\n                                                         ‫وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b4e1a41bfbe32c85789f3653519b4942a9630f1e315ac44f53423599c3ecf58","normalized_text_hash":"06a23ef68d769beef60a58c19aebafd9d8214155df597d833079a82fb8e7014f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p208-34224021"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7e58acbe-c20a-520a-bb35-1227947166e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -عقد -إجارة من الباطن -استراد ثمن اجرة لعدم حتقق شرط يف العقد -دفع املدعى عليه باالنتفاع مدة من العقد -تقدير اجرة املثل من قسم اخلبراء -ثبوت بطان العقد لعدم موافقة املؤجر األصلي -إلزام املدعى عليه بإعادة الثمن املسلم وإفهامه بأن له املطالبة بأجرة املثل خال فترة انتفاعه بدعوى مستقلة.","document_number":"33415126","case_number":"3441","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/18","year":"1434","subject":"إجارة -عقد -إجارة من الباطن -استراد ثمن اجرة لعدم حتقق شرط يف العقد -دفع املدعى عليه باالنتفاع مدة من العقد -تقدير اجرة املثل من قسم اخلبراء -ثبوت بطان العقد لعدم موافقة املؤجر األصلي -إلزام املدعى عليه بإعادة الثمن املسلم وإفهامه بأن له املطالبة بأجرة املثل خال فترة انتفاعه بدعوى مستقلة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/18:‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪33415126 :‬‬\n                       ‫َر ْق ُم الدعوى‪3441:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‬\n         ‫‪ 34191043:‬تاريخه‪1434/4/17 :‬هـ‬\n\n\n‫إجــارة ‪ -‬عقــد ‪ -‬إجــارة مــن الباطــن ‪ -‬اســتراد ثمــن اجــرة لعــدم حتقــق‬\n‫شــرط يف العقــد ‪ -‬دفــع املدعــى عليــه باالنتفــاع مــدة مــن العقد ‪ -‬تقدير‬\n‫اجــرة املثــل مــن قســم اخلبــراء ‪ -‬ثبــوت بطــان العقــد لعــدم موافقــة‬\n‫املؤجــر األصلــي ‪ -‬إلــزام املدعــى عليــه بإعــادة الثمــن املســلم وإفهامــه‬\n‫بــأن لــه املطالبــة بأجــرة املثــل خــال فتــرة انتفاعــه بدعــوى مســتقلة‪.‬‬\n\n\n\n\n‫‪ -1‬قــول شــيخ اإلســام ابــن تيميــة أن األصــل يف العقــود والشــروط‬\n‫اجلــواز والصحــة وال يحــرم منهــا ويبطــل إال مــا دل الشــرع علــى‬\n‫حترميــه وإبطالــه نص ـ ًا أو قياســا عنــد مــن يقــول بــه وقــال مانصــه‬\n‫«وأصــول أحمــد املنصوصــة عنــه أكثرهــا يجــري علــى هــذا القــول ‪،‬‬\n‫ومالــك قريــب منــه‪ ،‬لكــن أحمــد أكثــر تصحيح ـ ًا للشــروط ‪ ،‬فليــس‬\n‫يف الفقهــاء األربعــة أكثــر تصحيحـ ًا للشــروط منــه ‪.»...‬ا‪.‬ه ـ مجمــوع‬\n                                                ‫الفتــاوى(‪)132-126/29‬‬\n‫‪ -2‬قــول ابــن قدامــة يف الشــرح‪(:‬فإذا عــاد أحدهمــا فبــذل اليمــن ‪ ،‬لــم‬\n‫يســمعها يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا يف‬\n‫مجلــس آخــر فــإذا اســتأنف الدعــوى أعيــد احلكــم بينهمــا كاألول)‬\n                          ‫الشــرح الكبيــر مــع اإلنصــاف (‪ 436/28‬و ‪.)437‬‬\n\n\n\n                                                                                  ‫‪54‬‬\n\f     ‫ادعــت املدعيــة «الشــركة» ضــد املدعــى عليها»شــركة أخــرى» بدعــوى‬\n     ‫بأنهــا اســتأجرت منهــا مجموعــة مســتودعات بثمــن محــدد واشــترطت‬\n     ‫بــأن تســتخرج لهــا تراخيــص وســلمت الدفعــة األولــى وبقيــت فيــه فتــرة ‪-‬‬\n     ‫عليــه ولعــدم قيامهــا باســتخراج التراخيــص الالزمــة وملــا جــاء يف منطــوق‬\n     ‫وثيقــة العقــد مــن اعتبــار العقــد الغيــا وإلتــزام املدعــى عليهــا بإعــادة مــا‬\n     ‫ســلم مــن ثمــن لــذا فقــد طلبــت إلــزام املدعــى عليهــا بإعــادة الثمــن املســلم‬\n     ‫‪ -‬أقــر وكيــل املدعــى عليهــا بالدعــوى جملــة وتفصيــا لــذا فــإن العقــد‬\n     ‫يعتبــر الغيــا ودفــع بــأن املدعيــة اســتفادت مــن العقــار قرابــة الســنة لــذا‬\n     ‫فهــي غيــر مســتعدة بإعــادة مــا تطالــب بــه ‪ -‬متســك وكيــل املدعــن مبــا‬\n     ‫ورد يف منطــوق اخلطــاب املوجــه مــن املدعــى عليهــا للمدعيــة بإلتزامهــا‬\n     ‫باســتخراج الترخيــص وإال فيعــد العقــد الغيــا وتلتــزم بإعــادة املبلــغ لهــا‬\n     ‫‪ -‬طلبــت احملكمــة مــن املدعــى عليهــا مســتند متلكهــا فأبــرزت وثيقــة‬\n     ‫العقــد املبرمــة بينهــا وبــن املؤجــر وقــد تضمــن يف أحــد بنــوده إلتزامهــا‬\n     ‫بتوثيــق أي عقــد أجــرة تبرمــه يف الباطــن لديه وقرر وكيل املدعى عليها‬\n     ‫بــأن موكلتــه لــم تقــم بهــذا اإلجــراء ‪ -‬عليــه وألن املدعــى عليهــا صادقــت‬\n     ‫علــى دعــوى املدعيــة وأقــرت بعــدم اســتخراج رخصــة مــن البلديــة اخلاصــة‬\n     ‫باملســتودعات محــل الدعــوى يف املوعــد الــذي تشــارطا عليــه كمــا‬\n     ‫أقــرت أنــه يف حــال عــدم القــدرة علــى اســتخراجه يف التاريــخ املنــوه عنــه‬\n     ‫فــإن العقــد يعتبــر الغي ـ ًا وملــا جــاء يف إجابــة املدعــى عليــه مــن أن أصــل‬\n     ‫العقــار مســتأجر مــن املؤسســة ‪ ...‬عليــه وألن مذهــب جمهــور العلمــاء‬\n     ‫مــن املالكيــة والشــافعية واملذهــب عنــد احلنابلــة واحلنفيــة علــى تفصيــل‬\n\n‫‪55‬‬\n\f‫عندهــم وقــول ابــن حــزم واختيــار شــيخ اإلســام ابــن تيميــة علــى جــواز‬\n‫إجــارة العــن املســتأجرة بعــد قبضهــا وال يشــترط إذن املؤجــر ومــا ذكــر‬\n‫يف العقــد بــن املؤجــر األول واملؤجــر الثانــي مــن اشــتراط عــدم جــواز‬\n‫التأجيــر مــن الباطــن إال بعــد توثيــق اإلجــراء لــدى املؤجــر األول علــى‬\n‫التفصيــل املذكــور فــإن الصحيــح مــن مذاهــب العلمــاء جــواز مثــل هــذه‬\n‫الشــروط التــي تعــود علــى املؤجــر األول بنفــع مقصــود ولــه فيهــا مصلحــة‬\n‫و أن األصــل يف العقــود والشــروط اجلــواز والصحــة وال يحــرم منها ويبطل‬\n‫إال مــا دل الشــرع علــى ت ـ ــحرميه وإبطالــه ‪ ،‬نص ـ ًا ‪ ،‬أو قياس ـ ًا عنــد مــن‬\n‫يقــول بــه وملصادقــة الطرفــن علــى عــدم توثيــق العقــد لــدى املؤجــر األول‬\n‫فعلــى هــذا فــإن العقــد الثانــي لــم يــن علــى عقــد إيجــار صحيــح ومبــا أن‬\n‫املدعــي وكالــة يطالــب بإعــادة األجــرة املدفوعــة للســنة األولــى وقدرهــا‬\n‫خمســمائة وســبعة وســتون ألــف ريــال ولعــدم طلــب أحــد منهمــا تقديــر‬\n‫أجــرة املثــل وألن األصــل يف مثــل هــذا أن يطالــب بتقديــر أجــرة املثــل‬\n‫يف دعــوى مســتقلة‪ ،‬لــذا فقــد ثبــت لــدى احملكمــة أن بذمــة الشــركة‬\n‫املدعــى عليهــا خمســمائة وســبعة وســتني ألــف ريــال تدفعهــا للمدعيــة‬\n‫لعــدم صحــة العقــد الثانــي مــن الباطــن بــن املؤجــر الثانــي واملســتأجر‬\n‫الثالــث وافهــم وكيــل املدعــى عليهــا بــأن لــه مطالبــة الشــركة املدعيــة‬\n‫بأجــرة املثــل ‪ -‬وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة القناعــة‬\n‫وقــرر املدعــى عليــه وكالــة عــدم القناعــة فأفهــم بالتعليمــات ‪ -‬عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبلحوظــة بــأن وكيــل املدعــى عليهــا‬\n‫طالــب بأجــرة املثــل فأجابــت احملكمــة بــأن وكيــل املدعــى عليهــا ذكر‬\n‫يف الئحتــه باعتراضــه علــى بطــان العقــد ثــم طالــب بأجــرة املثــل وال‬\n‫ميكــن النظــر يف طلبــه واحلــال هــذه إال بعــد اكتســاب احلكــم بثبــوت‬\n\n\n                                                                                      ‫‪56‬‬\n\f     ‫بطــان العقــد لكونــه فــرع عنهــا كمــا أن مطالبتــه بأجــرة املثــل لــم‬\n     ‫تــرد إال بعــد النطــق باحلكــم وال تقبــل الطلبــات بعــد قفــل بــاب املرافعــة‬\n     ‫وأكــدت علــى مــا قررتــه ســابقا بــأن لهــا إقامــة دعــوى مســتقلة بذلــك‬\n     ‫ونظيــر هــذا مــا جــاء يف الشــرح الكبيــر إذا نــكل مــن توجهــت اليمــن‬\n     ‫يف حقــه قــال ‪ -‬رحمــه اهلل ‪ -‬مــا نصه‪(:‬فــإذا عــاد أحدهمــا فبــذل اليمــن‬\n     ‫‪ -‬لــم يســمعها يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا‬\n     ‫يف مجلــس آخــر فــإذا اســتأنف الدعــوى أعيــد احلكــم بينهمــا كاألول)‬\n     ‫الشــرح الكبيــر مــع اإلنصــاف (‪ - )437.436/28‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد  لــدي أنــا ‪ .................‬القاضــي باحملكمــة العامــة‬\n     ‫ـاء علــى األوراق الــواردة لنــا مــن فضيلــة رئيــس محاكــم‬          ‫بالدمــام بنـ ً‬\n     ‫املنطقــة الشــرقية علــى خطــاب مديــر شــرطة الدمــام رقــم‬\n     ‫‪2/30625‬يف‪1430/8/27‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n     ‫‪2912973‬يف ‪1429/5/19‬ه ـ حضــر‪ .............. /‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬بالوكالــة عــن ‪ .................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــده‬\n     ‫برقــم ‪31290‬يف ‪1429/3/22‬ه ـ جلــد ‪ 7048‬بصفتــه وكيــا  عــن‬\n     ‫‪ ...................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫شــمال محافظــة جــدة برقــم ‪ 96970‬يف ‪1428/11/24‬ه ـ جلــد ‪6646‬‬\n     ‫بصفتــه شــريك ومديــر شــركة ‪ ......................‬مبوجــب عقــد التأســيس‬\n     ‫الصــادر مــن كاتــب عــدل الغرفــة التجاريــة بجــدة برقــم ‪19‬يف‬\n‫‪57‬‬\n\f‫‪1423/11/2‬ه ـ ومبوجــب الســجل التجــاري رقــم ‪ 4030141450‬يف‬\n‫‪1423/11/17‬ه ـ الصــادر مــن جــدة وحضــر حلضــوره ‪...................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم …………‪ ..‬بالوكالــة‬\n‫عــن م‪ .....................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمام‬\n‫الثانيــة برقــم ‪ 48966‬يف ‪1430/10/7‬ه ـ جلــد ‪ 8343‬وبالوكالــة عــن‬\n‫‪ ...................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n‫الثانيــة برقــم ‪56849‬يف ‪1430/11/15‬ه ـ جلــد ‪ 8422‬وهمــا أصحــاب‬\n‫شــركة ‪.......................‬مبوجــب عقــد التأســيس املثبــت لــدى كاتــب‬\n‫العــدل املكلــف بالعمــل بالغرفــة التجاريــة الصناعيــة باملنطقــة الشــرقية‬\n‫برقــم ‪132‬جلــد ‪ 60‬لعــام ‪1426‬ه ـ ومبوجــب الســجل التجــاري  الصــادر‬\n‫مــن الدمــام برقــم …………‪..‬يف ‪1422‬هــ  وادعــى األول بقولــه‪ :‬لقــد‬\n‫اســتأجرت شــركة ‪ ...........................‬مــن شــركة ‪ ...............‬تســعة‬\n‫مســتودعات مبنطقــة ‪ ................‬وذلــك بتاريــخ ‪2006/7/5‬م ملــدة خمــس‬\n‫ســنوات اعتبــار ًا مــن ‪2006/12/5‬م حتــى ‪2011/12/4‬م بأجــرة ســنوية‬\n‫قدرهــا خمســمائة وســبعة وســتون ألــف ريــال لكامــل املســتودعات‬\n‫وتســدد أجــرة كل ســنة دفعــة واحــدة يف بدايــة كل ســنة مبوجــب العقــد‬\n‫احملــرر بينهمــا واملشــتمل علــى عشــرة مــواد وقــد قامــت الشــركة‬\n‫موكلتــي بتســليم أجــرة الســنه االولــى وقدرهــا خمســمائة وســبعة‬\n‫وســتون ألــف  ريــال للشــركة املدعــي عليهــا مبوجــب شــيك مســحوب‬\n‫علــى البنــك ‪ .....‬برقــم ‪ 4171‬يف‪2006/7/5‬م وبتاريــخ ‪2006/7/11‬م‬\n‫تعهــدت الشــركة املؤجــرة بتجهيــز رخــص البلديــة اخلاصة باملســتودعات‬\n‫التســعة وتســليمها للشــركة موكلتــي وإذا لــم تقــم بتجهيــز الرخــص‬\n‫املذكــورة يف موعــد أقصــاه نهايــة شــهر ‪2006/9‬م فإنهــا ملتزمــة بإعــادة‬\n\n\n                                                                                    ‫‪58‬‬\n\f       ‫كامــل أجــرة الســنة األولــى ويعتبــر العقــد الغي ـ ًا إال أنهــا لــم تــف مبــا‬\n       ‫تعهــدت بــه ثــم قامــت بتســليم املســتودعات التســعه للشــركة موكلتــي‬\n       ‫بتاريــخ ‪2006/10/12‬م وقــد اســتمرت الشــركه موكلتــي يف‬\n       ‫املســتودعات حتــى ‪2007/9/26‬م وكانــت خاللهــا تطالــب بالرخــص‬\n       ‫دون جــدوى ثــم قامــت بإعــادة املســتودعات للشــركة املؤجــرة لــذا أطلــب‬\n       ‫إلــزام شــركة ‪ ...................‬بإعــادة أجــرة الســنة األولــى وقدرهــا‬\n       ‫خمســمائة وســبعة وســتون ألــف ريــال للشــركة موكلتــي هــذه دعــواي‬\n       ‫وبســؤال املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬ماذكــره املدعــي وكالــة‬\n       ‫ا والشــركة موكلتــي لــم‬               ‫يف دعــواه كلــه صحيــح جملــة وتفصي ـ ً‬\n     ‫تســتطع جتهيــز رخــص البلديــه  اخلاصــة باملســتودعات التســعه املؤجــرة  ‬\n       ‫علــى الشــركة موكلــة املدعــى يف املوعــد الــذي التزمــت فيــه وهــو نهايــة‬\n       ‫ـاء علــى هــذا فــإن العقــد الــذي بينهمــا يعتبــر الغي ـ ًا‬   ‫شــهر ‪2006/9‬م وبنـ ً‬\n       ‫إال أن الشــركة املدعيــة اســتلمت املســتودعات التســعة بتاريــخ‬\n       ‫‪2006/10/12‬م واســتمرت بهــا وانتفعــت منهــا  حتــى إرجاعها للشــركة‬\n       ‫موكلتــي بتاريــخ ‪2007/9/26‬م أي مايقــارب ســنة الشــركة موكلتــي‬\n       ‫ليســت مســتعدة مبــا طلبــه املدعــي وكالــة ألن مــا دفعتــه الشــركة‬\n       ‫املدعيــة هــو مقابــل انتفاعهــا ملــدة بقائهــا يف املســتودعات هكــذا أجــاب‬\n       ‫ثــم يف جلســة أخــرى  حضــر ‪ ...................‬ســعودي اجلنســيه مبوجــب‬\n       ‫الســجل املدنــي رقــم ‪ ....................‬بالوكالــة عــن ‪ ......................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة  ‬\n       ‫برقــم ‪ 29746‬يف ‪1431/29‬ه ـ جلــد ‪ 9444‬باألصالــة عــن نفســه وبصفتــه‬\n       ‫ا عــن كل مــن ‪ .................... .................‬و‪....................‬‬        ‫وكي ـ ً‬\n       ‫و‪ .....................‬و‪ ...................‬بصفتهــم الشــركاء يف شــركة‬\n\n\n‫‪59‬‬\n\f‫‪ ...................‬مبوجــب عقــد التأســيس املوثــق   لــدى كاتــب العــدل‬\n‫بالغرفــة التجاريــة الصناعيــة بجــدة رقــم ‪19‬صحيفــة ‪/42/23/22‬جلــد‬\n‫‪/9‬ش‪4/‬يف ‪1423/11/2‬ه ـ والســجل التجــاري رقــم ‪/4030/4/450‬يف‬\n‫‪1423/11/17‬ه ـ الصــادر مــن جــدة مبوجــب الوكالــة الصــادرة  مــن‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 27578‬يف‬\n‫‪1431/3/22‬ه ـ جلــد ‪ 9412‬املخــول للوكيــل فيهــا حــق املطالبــة بحقــوق‬\n‫الشــركة وإقامــة وســماع الدعــاوي والــرد عليهــا واملرافعــة والصلــح‬\n‫والتنــازل واإلقــرار واإلنــكار واإلجابــة ويف يــوم الســبت املوافــق‬\n‫‪1431/3/20‬ه ـ الســاعة العاشــرة صباحـ ًا فتحــت اجللســة وفيهــا حضــر‬\n‫املدعي وكاله ‪ ...‬وحضر حلضوره ‪ .................‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ‪ ..................‬بالوكالــة عــن ‪ ......................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابة عدل الدمام الثانية برقم ‪1429/6/21‬هـ‬\n‫ا عــن ‪........................‬‬\n                              ‫ا عــن نفســه ووكي ـ ً‬    ‫جلــد ‪ 7523‬بصفتــه أص ـ ً‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم‬\n‫‪ 29973‬يف ‪1426/7/8‬هـ جلد ‪ 4699‬بصفتها أصحاب ……………‪..‬‬\n‫مبوجــب عقــد التأســيس املوثــق مــن كاتــب عــدل الدمــام برقــم ‪ 45‬عــدد‬\n‫‪ 48‬مــن جلــد ‪3‬العــام ‪1422‬ه ـ وملحــق التعديــل املوثــق مــن كاتــب العــدل‬\n‫املكلــف بالعمــل بالغرفــة التجاريــة الصناعيــة باملنطقــة الشــرقية‬\n‫بالصحيفــة ‪144‬عــدد‪ 132‬جلــد ‪6‬يف ‪1426/3/15‬ه ـ وألن وكالــة‬\n‫املدعــي املشــار إليهــا آنف ـ ًا قــد  نصــت علــى أن للوكيــل مراجعــة جميــع‬\n‫اجلهــات والدوائــر احلكوميــة واخلاصــة والهيئــات واحملاكــم ومطالبــه‬\n‫كل مــن شــركة ‪ ..................‬و‪ .....................‬بقيمــة اإليجــار املدفــوع‬\n‫لهــم مقابــل املســتودعات  مبدينــة ‪ ................‬وتقــدمي الدعــاوي واالنهاءات‬\n\n\n                                                                                           ‫‪60‬‬\n\f     ‫واســتالم م كافــة احلقــوق باســم الشــركة مبوجــب شــيكات واملرافعــه‬\n     ‫عــن الشــركة لــدى جميــع مواصلــة الســير يف الدعــوى الفتقارهــا إلــى‬\n     ‫حــق االقرارواحضــار لســياق وطلــب اليمــن والقناعــه باحلكــم‬\n     ‫واالعتــراض عليــه ونحــو ذلــك لــذا فقــد أفهمــت املدعــي وكالــة بذلــك‬\n     ‫فقــال أطلــب إمهالــي إلحضــار وكالــة حتولنــي جميــع ماتقتضيــه‬\n     ‫الدعــوى هكــذا قــرر فأجــاب لطلبــه ورفعــت اجللســه لذلــك بعــد‬\n     ‫إعالمهمــا باحلضــور يــوم الســبت املوافق‪1431/5/17‬هـ واجلرح والتعديل‬\n     ‫واملنــع مــن الســفر وتوريــد الشــهود والبينــات واالعتــراض وتن ـ ــفيذ‬\n     ‫األحــكام واالســتئناف واإلجابــة وطلــب اليمــن وســماع وطلــب احلكــم‬\n     ‫وقبولــه ونفيــه واالعتــراض عليــه وطلــب متييــزه والفســخ واإلبــراء‬\n     ‫واملخالصــه واســتالم الصكــوك واالعتــراض عليهــا إلى أخــر ماوردفيها‬\n     ‫وحضــر حلضــوره املدعــى عليــه وكالــه …………………‪ .‬وبعــرض‬\n     ‫إجابــة املدعــى عليــه وكالــة ‪ ...............‬علــى املدعــي وكالــة قــال‬\n     ‫ماذكــره املدعــى عليــه وكالــة مــن أن الشــركة موكلتــه لــم تســتطع‬\n     ‫جتهيــز رخــص البلديــة للمســتودعات التســعة يف املدة احملــددة وأن العقد‬\n     ‫ـاء علــى هــذا يعتبــر ال غياًفهــو صحيــح حيــث ســبق أن بعثــت شــركة‬        ‫بنـ ً‬\n     ‫‪ ...............‬لشــركة ‪ ...........‬خطاب ـ ًا بتاريــخ ‪2006/7/11‬م تتعهــد فيــه‬\n     ‫بتجهيــز الرخــص  يف مــدة أقصاهــا نهايــة  الشــهر التاســع عــام ‪2006‬م‬\n     ‫وإذا لــم يتــم جتهيــز الرخــص فــإن شــركة  ‪ ........‬ملتزمــه بــإ عــادة املبلــغ‬\n     ‫ا ويعتبــر العقــد الغي ـ ًا‬ ‫الــذي اســتلمته مــن الشــركة موكلتــي كام ـ ً‬\n     ‫وقــد وافقــت الشــركة موكلتــي علــى مــاورد يف خطــاب الشــركة‬\n     ‫موكلــة املدعــى عليــه وأصبــح إتفاق ـ َا بينهمــا هكــذا قــرر ثــم أبــرز‬\n     ‫املدعــي وكالــة عقــد االتفــاق الصــادر مــن شــركة ‪ ...........‬بتاريــخ‬\n\n\n‫‪61‬‬\n\f‫‪2006/7/5‬م وباالطــاع عليــه وجــد أنــه يتضمن قيام شــركة ‪...............‬‬\n‫بتأجيــر تســعة مســتودعات مبنطقــة اخلالديــة علــى شــركة ‪.................‬‬\n‫ملــدة خمــس ســنوات تبــدأ مــن ‪2006/12/5‬م وتنتهــي يف ‪2011/12/4‬م‬\n‫بأجــرة ســنوية قدرهــا خمســمائة وســبعة وســتون ألــف ريــال تدفــع دفعــة‬\n‫واحــدة وهــذا العقــد وفــق خمســة عشــر بنــد ومذيــل بتوقيــع كل مــن‬\n‫شــركة ‪ .............‬وشــركة ‪ ...................‬كمــا أبــرز املدعــي وكالــة‬\n‫خطاب ـ ًا صــادر ًا مــن شــركة ‪ ...‬وموجه ـ ًا لشــركة ‪ ..................‬بتاريــخ‬\n‫‪2006/7/11‬م يتضمــن مانصــه ‪ :‬املوضــوع ‪ :‬تعهــد والتــزام بتجهيــز‬\n‫رخصــة بلديــة بخطابنــا هــذا نتعهــد لكــم نحــن شــركة ‪...............‬‬\n‫بتجهيــز رخصــة بلديــة لعــدد واحــد مســتودع تخزيــن املــواد الغذائيــة‬\n‫وجتهيــز أيض ـ ًا رخصــة بلديــة أخــرى لعــدد ثمانيــة مســتودعات تخزيــن‬\n‫أدوات كهربائيــة متنوعــه وذلــك يف منطقــة ‪ ...‬بالدمــام وإذا لــم يتــم‬\n‫جتهيــز رخــص البلديــة املطلوبــة وذلــك حتــى نهايــة شــهر ســبتمبر ‪2006‬م‬\n‫ا ويعتبــر العقــد ال غيـ ًا ‪ .‬أه ـ ‪ .‬ومذيــل‬\n                                            ‫نتعهــد ونلتــزم  بإعــادة املبلــغ كامـ ً‬\n‫هــذا اخلطــاب بتوقيــع املديــر العــام ومختــوم بختــم شــركة ‪ ...‬وبعــرض‬\n‫العقــد واخلطــاب املشــار إليهمــا بعاليــه علــى املدعــى عليــه وكالــة صــادق‬\n‫عليهمــا ثــم ســألت الطرفــن هــل حصــل اتفــاق جديــد بــن شــركة‬\n‫‪ .............‬وشــركة ‪ ......................‬بعــد إلغــاء العقــد املبــرم بينهمــا وقبــل‬\n‫اســتالم شــركة ‪ ..................‬للمســتودعات بتاريــخ ‪2006/10/12‬م‬\n‫فقــاال لــم يحصــل أي إتفــاق جديــد علــى التأجيــر مكتوبـ َا وال مشــافهة‬\n‫هكــذا قــرر ثــم ســألت املدعــى عليــه وكالــة عــن مســتند ملكيــة‬\n‫شــركة ‪ ..............‬للمســتودعات فقــال إن موقــع املســتودعات مؤجــر‬\n‫علــى الشــركة موكلتــي مــن قبــل ‪ ...‬هكــذا قــرر فســألته عــن عقــد‬\n\n\n                                                                                              ‫‪62‬‬\n\f       ‫اإليجــار فقــال أطلــب إمهالــي إلحضــاره لكــم هكــذا قــرر فأجيــب‬\n       ‫لطلبــه ثــم يف جلســة أخــرى  حضــر الطرفــان كل مــن املدعــي  وكالــة‬\n       ‫‪ ...‬واملدعــى عليــه وكالــة ‪ ...‬وأبــرز املدعــي وكالــة ‪ ...‬صــك الوكالــة‬\n       ‫الصــادر مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 9827‬يف‬\n       ‫ا عــن‬    ‫‪1431/2/2‬ه ـ تتضمــن أن ‪ .....................‬بصفتــه وكي ـ ً‬\n       ‫‪ ........................‬بصفتــه شــريك ومديــر شــركة ‪ .......................‬مبوجــب‬\n       ‫عقــد التأســيس رقــم ‪ 19‬يف ‪1432/11/2‬ه ـ صحيفــة رقــم ‪24/23/22‬‬\n     ‫مجلــد ‪/9‬ش‪/‬ع الصــادر مــن كتــاب عــدل الغــرف التجاريــة بجــده  ‬\n       ‫مبوجب السجل التجاري رقم ‪ 4030141450‬يف تاريخ ‪1423/11/17‬هـ‬\n       ‫ســجل جــدة بالوكالــة الصــادرة مــن كتابــة عــدل جــدة الثانيــة شــمال‬\n       ‫محافظــة جــدة برقــم ‪ 96970‬يف ‪1428/11/24‬ه ـ جلــد ‪ 6646‬قــد أقامــا‬\n       ‫‪ ...................‬وكيــا  ينــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وإقامــة‬\n       ‫الدعــوى ضــد شــركة ‪ .............‬أو ‪ .................‬وابنــه ‪.....................‬‬\n       ‫للمطالبــة بإعــادة قيمــة املبالــغ املدفوعــة لهــم مقابــل عقــد اســتئجار‬\n       ‫مســتودعات يف ‪ ...‬ولــه حــق اإلقــرار عــن الشــركة واســتالم الصكــوك‬\n       ‫واالعتــراض عليهــا وإنهــاء مايلــزم حضــوره إلــى اخــر مــاورد فيهــا ثــم أبــرز‬\n       ‫املدعــى عليــه وكالــة ‪ ....‬أصــل العقــد الصــادر مــن املؤسســة … برقــم‬\n       ‫‪ 2631‬يف ‪1426/11/19‬ه ـ وباالطــاع عليــه وجدتــه يتضمــن تأجيــر‬\n       ‫املؤسســة … لقطعــة األرض  رقــم ‪ 3/46‬يف ‪ ...‬علــى شــركة ‪..................‬‬\n       ‫ملــدة تســع ســنوات تنتهــي يف ‪1435/12/29‬ه ـ بأجــرة ســنوية قدرهــا‬\n       ‫مائــة وســتة وثالثــون ألف ـ ًا وأربعمائــة وثــا ثــون ريــا ًأل وهــذا العقــد وفــق‬\n       ‫ثالثــة وعشــرين مــادة ومذيــل بتوقيــع كل مــن الطــرف األول املؤسســة ‪...‬‬\n       ‫والطــرف الثانــي شــركة ‪ ......................‬وقــد تضمنــت املــادة احلاديــة‬\n\n\n‫‪63‬‬\n\f ‫عشــر علــى أنــه ال يجــوز للطــرف الثانــي تأجيــر األرض موضــوع العقــد‬\n ‫املنشــآت املقامــة عليهــا كليـ ًا أو جزئيــا للغيــر إال بشــرط أن يوثــق هــذا‬\n ‫اإلجــراء لــدى الطــرف األول وعلــى النمــوذج املخصــص لهــذا الغــرض‬\n ‫خــال شــهر مــن تاريــخ  التأجيــر مــن الباطــن علــى أن ال تتجــاوز مــدة‬\n‫التاجيــر مــن الباطــن مــدة هــذا العقــد هكذا تضمنت وبســؤال الطرفني ‬\n ‫هــل قامــا بتوثيــق عقــد اإليجــار الــذي بينهمــا علــى الصفــة الــواردة يف‬\n ‫املــادة احلاديــة عشــر املشــار إليهــا بعاليــه فقــاال‪ :‬لــم يتــم توثيقــه علــى‬\n ‫الصفــة املذكــورة هكــذا قــررا وحيــث األمــر ماذكــر وألن عقــد‬\n ‫اإليجــار املبــرم بــن الشــركتني  قــد مت إلغــاؤه بإقــرار الطرفــن وألن‬\n ‫اســتالم الشــركة املدعيــة للمســتودعات التســعة وإنتفاعهــا بهــا للفتــرة‬\n ‫مــن ‪2006/10/12‬م حتــى ‪2007/9/26‬م لــم يبنــى علــى عقــد إيجــار‬\n ‫صحيــح لــذا فقــد رأيــت الكتابــة لهيئــة النظــر لتقديــر أجــرة املثــل‬\n ‫للمستودعات التسعة املذكورة يف الدعوى اعتبار ًأ من ‪2006/10/12‬م‬\n ‫حتــى ‪2007/9/26‬م واإلفــادة ثــم يف جلســة أخــرى فلــدي أنــا ‪ ...‬القاضــي‬\n ‫باحملكمــة العامــة بالدمــام حضــر الطرفــان كل مــن املدعــي وكالــة‬\n ‫‪ .......................‬واملدعــى عليــه ‪ .......................‬ســعودي اجلنســية مبوجــب‬\n ‫الســجل املدنــي رقــم ‪    .......................‬الوكيــل عــن ‪.......................‬‬\n ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالدمــام برقــم‬\n ‫‪ 3384196‬وتاريــخ ‪1433/5/23‬ه ـ بصفتــه الوكيــل عــن‬\n ‫‪ ............................‬واملخــول لــه فيهــا املطالبــة وإقامــة الدعــاوي واملرافعــة‬\n ‫واملدافعــة وســماع الدعــاوي والــرد عليهــا وطلــب اليمــن ورده واالمتنــاع‬\n ‫عنــه وطلــب تطبيــق املــادة ‪ 230‬مــن نظــام املرافعــات الشــرعية واملطالبــة‬\n ‫بتنفيــذ االحــكام وقبــول االحــكام ونفيهــا واالعتــراض علــى االحكام‬\n\n\n                                                                                                ‫‪64‬‬\n\f     ‫وطلــب االســتئناف واســتالم املبالــغ بشــيك لــدى احملاكــم الشــرعية ويف‬\n     ‫هــذه اجللســة جــرى تــاوة مــا ســبق ضبطــه مــن الدعــوى واإلجابــة ومــا مت‬\n     ‫بعــد ذلــك فســألت املتداعيــن عــن ذلــك فصادقــا عليــه وطلبا  االســتمرار‬\n     ‫يف الدعــوى والنظــر علــى ضــوء مــا ســبق ضبطــه وطلبــا الفصــل يف‬\n     ‫القضيــة  ثــم يف جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره‬\n     ‫املدعــى عليــه أصالــة   ‪ ...........................‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪  ....................‬وبالرجــوع إلــى أوراق املعاملــة وجــد‬\n     ‫قــرار هيئــة اخلبــراء برقــم ‪ 163‬وتاريــخ ‪1432/4/28‬ه ـ واملتضمــن مــا‬\n     ‫نصــه ‪ ( :‬بنــاء علــى آمــر صاحــب الفضيلــة الشــيخ ‪ ..................... /‬رقــم‬\n     ‫‪ 31/19687‬يف ‪1431/12/2‬هـ املتعلقة بدعوى ‪ .....................‬بالوكالة‬\n     ‫عــن شــركة ‪ ...................‬ضــد ‪ .................‬أجــرة املســتودعات املنــوه‬\n     ‫عنهــا بحضــور أطــراف القضيــة ومــن ثــم تقديــر أجــرة املثــل لهــذه‬\n     ‫املســتودعات اعتبــار ًا مــن ‪2006/10/12‬م حتــى ‪2007/9/26‬م مــع‬\n     ‫االســتعانة بأهــل اخلبــرة يف ذلــك عليــه جــرى املكاتبــة ملكتــب كل مــن‬\n     ‫شــركة ‪ .....................‬وشــركاه ‪ ...‬ومكتــب شــركة ‪ .............‬املرفقــة‬\n     ‫باملعاملــة مكتــب ‪ ..........‬يذكــر ان األجــرة يف تلــك الفتــرة مــا بــن ‪90‬‬\n     ‫إلــى ‪ 120‬للمتــر املربــع ومكتــب ‪ ...‬يذكــر أن األجــرة يف تلــك الفتــرة مــا‬\n     ‫بــن ‪ 100‬إلــى ‪ 110‬ريــال للمتــر املربــع يف حــال املبنــى جديــد غير مرخص‬\n     ‫مــن اجلهــات الرســمية لــذا تــرى هيئــة النظــر أن االجــرة املتوســطة بــن‬\n     ‫التقديريــن أجــرة وقدرهــا ‪ 95‬ريــال للمتــر املربــع وهــذه أجــرة معتدلــة مــن‬\n     ‫تاريــخ ‪2006/10/12‬م إلــى ‪2007/9/26‬م هــذا مــا جــرى وباهلل التوفيق‬\n     ‫عضــو هيئــة النظــر ‪ .................‬وعضــو هيئــة النظــر ‪ ............‬وعضــو هيئــة‬\n     ‫النظــر ‪ )......................‬وبعرضــه علــى املتداعيــن طلبــا إمهالهمــا للجواب‬\n\n\n‫‪65‬‬\n\f‫علــى قــرار هيئــة النظــر ثــم يف جلســة أخــرى  حضــر الطرفــان وقــد مت‬\n‫تأمــل مــا ســبق ضبطــه فبــدا لــي عــدم وجاهــة إجــراء فضيلــة القاضــي‬\n‫الســلف مــن جهــة إحالــة تقديــر أجــرة املثــل لهيئــة النظــر  ويف هــذه اجللســة‬\n‫ـاء علــى مــا تقــدم‬\n                  ‫جــرى عــرض الصلــح علــى الطرفــن فلــم يوفقــا إليــه فبنـ ً‬\n‫مــن الدعــوى واإلجابــة وإقرارهمــا علــى مــا مت ضبطــه ومبــا أن املدعــى‬\n‫عليــه صــادق علــى دعــوى املدعــي وأقــر بعــدم اســتخراج رخصــة مــن‬\n‫البلديــة اخلاصــة باملســتودعات محــل الدعــوى  يف املوعــد الــذي تشــارطا‬\n‫عليــه كمــا أقــر أنــه يف حــال عــدم القــدرة علــى اســتخراجه يف التاريــخ‬\n‫املنــوه عنــه فــإن العقــد يعتبــر الغيـ ًا ومــا جــاء يف تضاعيــف إجابــة املدعــى‬\n‫عليــه مــن أن أصــل العقــار مســتأجر مــن ‪ ...‬فــإن مذهــب جمهــور العلمــاء‬\n‫مــن املالكيــة والشــافعية واملذهــب عنــد حلنابلــة واحلنفيــة علــى تفصيــل‬\n‫عندهــم وقــول ابــن حــزم واختيــار شــيخ االســام ابــن تيميــة علــى جــواز‬\n‫إجــارة العــن املســتأجرة بعــد قبضهــا وال يشــترط إذن املؤجــر ومــا ذكــر‬\n‫يف العقــد بــن املؤجــر  األول واملؤجــر الثانــي مــن اشــتراط عــدم جــواز‬\n‫التأجيــر مــن الباطــن إال بعــد توثيــق اإلجــراء لــدى املؤجــر األول علــى‬\n‫التفصيــل املذكــور فــإن الصحيــح مــن مذاهــب العلمــاء جــواز مثــل هــذه‬\n‫الشــروط التــي تعــود علــى املؤجــر األول بنفــع  مقصــود ولــه فيهــا مصلحــة‬\n‫وهــذا هــو مذهــب احلنابلــة والظاهــر مــن مذهــب املالكيــة  وذكــر شــيخ‬\n‫اإلســام ابــن تيميــة أن األصــل يف العقــود والشــروط اجلــواز والصحــة وال‬\n‫يحــرم منهــا ويبطــل إال مــا دل الشــرع علــى ت ـ ــحرميه وإبطالــه ‪ ،‬نصـ ًا ‪ ،‬أو‬\n‫قياسـ ًا عنــد مــن يقــول بــه وقــال مــا نصــه  ‪ ( :‬وأصــول أحمــد املنصوصــة‬\n‫عنــه أكثرهــا يجــري علــى هــذا القــول ‪ ،‬ومالــك قريــب منــه ‪ ،‬لكــن‬\n‫أحمــد أكثــر تصحيح ـ ًا للشــروط ‪ ،‬فليــس يف الفقهــاء األربعــة أكثــر‬\n\n\n                                                                                         ‫‪66‬‬\n\f     ‫تصحيح ـ ًا للشــروط منــه ‪ ) ...‬اه ـ مجمــوع الفتــاوى ‪. )132-126/29( :‬‬\n     ‫وحيــث صــادق الطرفــان علــى عــدم توثيــق العقــد لــدى املؤجــر األول‬\n     ‫فعلــى هــذا  فــإن العقــد الثانــي لــم يبنــى علــى عقــد إيجــار صحيــح  ومبــا‬\n     ‫أن املدعــي وكالــة يطالــب بإعــادة األجــرة املدفوعــة للســنة األولــى والتــي‬\n     ‫قدرهــا خمســمائة وســبعة وســتون ألــف ريــال ومبــا أن املتداعيــن لــم‬\n     ‫يطلــب أحــد منهمــا تقديــر أجــرة املثــل واألصــل يف مثــل هــذا أن يطالــب‬\n     ‫بتقديــر أجــرة املثــل يف دعــوى مســتقلة لــذا فقــد ثبــت لــدي أن بذمــة‬\n     ‫شــركة ‪ ................‬مبلغ ـ ًا قــدره خمســمائة وســبعة وســتون ألــف ريــال‬\n     ‫تدفعهــا لشــركة ‪ ...............................‬وذلــك لعــدم صحــة العقــد الثانــي‬\n     ‫مــن الباطــن بــن املؤجــر الثانــي واملســتأجر الثالــث وبــه حكمــت‬\n     ‫وأفهمــت وكيــل شــركة ‪ ...............‬بــأن للشــركة مطالبــة الشــركة‬\n     ‫املدعيــة بأجــرة املثــل وبذلــك حكمــت وبعرضــه علــى الطرفــن قــرر‬\n     ‫املدعــي وكالــة القناعــة وقــرر املدعــى عليــه وكالــة عــدم القناعــة‬\n     ‫وطلــب االســتئناف فأفهــم أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ بعــد‬\n     ‫مهلــة تنظيــم الصــك خمســة أيــام إذا مضــت املــدة ولــم يقــدم الئحــة‬\n     ‫اعتراضيــة ســقط حقــه يف طلــب االســتئناف ولــه املراجعــة خــال املهلــة‬\n     ‫واملــدة النظاميــة الســتالم نســخة احلكــم لالعتــراض عليــه وبــاهلل‬\n     ‫التوفيــق وختمــت اجللســة يف متــام الســاعة الثانيــة عشــر  ‪ ،‬وصلــى اهلل‬\n        ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف  ‪1433/08/18‬هـ‬\n     ‫احلمــد هلل وحــده   ففــي يــوم  األحــد املوافــق‪ 1434/06/11‬ه ـ الســاعة‬\n     ‫الثامنــة انعقــدت اجللســة بعــد انتهــاء انتدابنــا مــن املجلــس األعلــى للقضاء‬\n     ‫وقــد وردنــا كتــاب فضيلــة رئيــس االســتئناف باملنطقــة الشــرقية رقــم‬\n     ‫‪ 34620259‬وتاريــخ ‪1434/4/22‬ه ـ واملرفــق بها قرار املالحظة الصادر‬\n\n\n‫‪67‬‬\n\f‫مــن الدائــرة األولــى‪ -‬ق‪ 1/‬رقــم ‪ 34191042‬وتاريــخ ‪1434/4/17‬ه ـ‬\n‫ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لوحــظ أن املدعــى عليــه وكالــة طالــب يف‬\n‫الئحتــه االعتراضيــة بأجــرة املثــل وهــذا مــن حقــه يف هــذه الدعــوى ‪،‬‬\n‫فعلــى فضيلتــه مالحظــة ذلــك وإكمــال الــازم حســب الوجــة الشــرعي‬\n‫والتعليمــات) ‪ .‬اه ـ ‪ .‬وأجيــب أصحــاب الفضيلــة الكــرام أن الالئحــة‬\n‫االعتراضيــة تضمنــت االعتــراض علــى احلكــم ببطــان العقــد صراحــة‬\n‫يف مواضــع غيــر مــا دون يف الضبــط ‪ ،‬ثــم يف آخــر الالئحــة أشــار إلــى‬\n‫أجــرة املثــل ومبــا أن مطالبتــه هــذه تتضمــن املوافقة علــى احلكم ببطالن‬\n‫العقــد ‪ ،‬ويظهــر بهــذا عــدم حتريرهــا ‪ ،‬واألصــل أن املطالبــة بأجــرة املثل‬\n‫فــرع عــن بطــان العقــد أو انفســاخه ‪ ،‬ومبــا أنــه غيــر مقتنــع باحلكــم‬\n‫فــا ميكــن النظــر يف مطالبتــه أجــرة املثــل حتــى يكتســب احلكــم‬\n‫القطعيــة علــى مــا جــاء يف النظــام ‪ ،‬ثــم إن مطالبتــه أجــرة املثــل جــاءت‬\n‫بعــد احلكــم ‪ ،‬وتعديــل الدعــوى بعــد صــدور احلكــم الــذي جــاء مبني ـ ًا‬\n‫علــى مطالبتــه الســابقة يف دعــواه غيــر مقبــول ؛ ألن صــدور احلكــم مــن‬\n‫القاضــي يف القضيــة بعــد انتهــاء املرافعــة قفــل لبابهــا‪ ،‬ولــه رفــع دعــوى‬\n‫مســتقلة كمــا ُأ ْوضــح ذلــك يف تســبيب احلكــم‪ ،‬ونظيــر هــذا مــا جــاء يف‬\n‫الشــرح الكبيــر إذا نــكل مــن توجهــت اليمــن يف حقــه قــال ابــن قدامــه‬\n‫رحمــه اهلل ‪ -‬مــا نصــه ‪ ( :‬فــإذا عــاد أحدهمــا فبــذل اليمــن ‪ ،‬لــم يســمعها‬\n‫يف ذلــك املجلــس ألنــه أســقط حقــه منهــا حتــى يحتكمــا يف مجلــس‬\n‫آخــر فــإذا اســتأنف الدعــوى ؛ أعيــد احلكــم بينهمــا كاألول ) الشــرح‬\n‫الكبيــر مــع اإلنصــاف ‪ ، )437.436/28( :‬وســيجري رفــع املعاملــة‬\n‫حملكمــة االســتئناف للتدقيــق وبــاهلل التوفيــق وختمــت اجللســة يف متــام‬\n\n\n                                                                                    ‫‪68‬‬\n\f     ‫الســاعة الثامنــة وعشــر دقائــق وصلــى اهلل وســلم علــى نبينــا محمد وعلى‬\n     ‫آلــه وصحبــه حــرر يف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/11‬ه ـ احلمــد هلل وحــده‬\n     ‫والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه أمــا بعــد ‪ ...‬فقــد‬\n     ‫اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبدينــة الدمــام برقــم ‪ 34/1017287‬وتاريــخ ‪1434/6/18‬ه ـ‬\n     ‫واملقيــدة لــدى احملكمــة برقــم ‪ 34/1531166‬وتاريــخ ‪1434/6/25‬ه ـ‬\n     ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪ ....................... /‬املســجل‬\n     ‫برقــم ‪ 33415126‬وتاريــخ ‪1433/9/18‬ه ـ اخلــاص بدعــوى‪ /‬شــركة‬\n     ‫‪ ................‬ضــد‪ /‬شــركة ‪ ................‬يف قضيــة حقوقيــة وقــد تضمــن‬\n     ‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n     ‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه وأوراق‬\n     ‫ـاء علــى قرارنــا رقــم ‪ 34191042‬وتاريــخ ‪1434/4/17‬ه ـ فقــد‬         ‫املعاملــة بنـ ً‬\n     ‫قررنــا املصادقــة علــى احلكــم‪ ،‬ولبيانــه حــرر يف ‪1434/7/30‬ه ـ ‪ ،‬واهلل‬          ‫ّ‬\n                                                                        ‫ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":54,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8553645c5b52d2fb2a5a8d8072605d0a93c7540a85feb41ebeb16bf145765971","normalized_text_hash":"bd60c0e4323239da05a317fe6a3cf703f2db2272e29a980cfeadb6caff06a525","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p54-33415126"},{"id":"be45e6da-3601-5059-a89c-022656079ff8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بإخاء العقار أو مضاعفة األجرة ملخالفة بنود العقد -ثبوت سريان مدة العقد وعدم تغيير النشاط املتفق عليه- مصادقة الطرفن على مدة العقد والنشاط -صرف النظر عن","document_number":"33469025","case_number":"4958","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/29","year":"1434","subject":"إجارة -مطالبة بإخاء العقار أو مضاعفة األجرة ملخالفة بنود العقد -ثبوت سريان مدة العقد وعدم تغيير النشاط املتفق عليه- مصادقة الطرفن على مدة العقد والنشاط -صرف النظر عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/29 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33469025 :‬‬\n                        ‫َر ْق ُم الدعوى‪4958 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3437543‬تاريخه ‪1434/2/16‬هـ‬\n\n\n ‫إجــارة‪ -‬مطالبــة بإخــاء العقــار أو مضاعفــة األجــرة ملخالفــة بنــود‬\n ‫العقــد‪ -‬ثبــوت ســريان مــدة العقــد وعــدم تغييــر النشــاط املتفــق عليــه‪-‬‬\n ‫مصادقــة الطرفــن علــى مــدة العقــد والنشــاط‪ -‬صــرف النظــر عــن‬\n                                                                    ‫الدعــوى ‪.‬‬\n\n\n\n\n                   ‫ما أشار له القاضي من مبادئ وقواعد يف تسبيب حكمه‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي بقولــه أنــه أبــرم عقــد إيجــار عقــار ‪ ..‬ميلكــه للشــركة‬\n ‫املدعــى عليهــا ملــدة وأجــرة محددتــن ‪ ،‬قامــت الشــركة املدعــى عليهــا‬\n ‫مبخالفــة بنــود العقــد وذلــك بقيامهــا بتغييــر النشــاط املتفــق عليــه يف‬\n ‫العقــد‪ ،‬طالــب املدعــي بإخــاء املبنــى ومضاعفــة األجــرة‪ ،‬أنكــرت‬\n ‫املدعــى عليهــا دعــوى املدعــي ورفضــت اإلخــاء ومتســكت مبــدة العقد‪،‬‬\n ‫صــادق الطرفــان علــى ســريان مفعــول مــدة العقــد وعــدم تغييــر النشــاط‬\n ‫املتفــق عليــه ولــم يثبــت لــدى القاضــي خــاف ذلــك‪ ،‬وملــا كان فســخ‬\n ‫العقــد ال يكــون إال بإنتهــاء املــدة وتراضــي الطرفــن لــذا حكمــت‬\n ‫احملكمــة بصــرف النظــر عــن الدعــوى ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                          ‫اإلســتئناف ‪.‬‬\n\n                                                                                  ‫‪70‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n     ‫العامــة بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة بالدمــام برقــم ‪ 4958‬وتاريــخ ‪1431/07/03‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3119812‬وتاريــخ  ‪1431/7/3‬ه ففــي يــوم‬\n     ‫الســبت املوافق‪1432/06/18‬ه ـ حضــر ‪..................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .........................‬الوكيــل الشــرعي عــن‬\n     ‫‪ .....................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n     ‫برقــم ‪ 39925‬وتاريــخ ‪1432/10/12‬ه ـ جلــد ‪ 1885‬وحضــر حلضــوره‬\n     ‫‪ .......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..............‬‬\n     ‫الوكيــل الشــرعي عــن ‪ ...................‬بصفتــه رئيــس ‪ .................‬مبوجــب‬\n     ‫الوكالــة الصــادة مــن كاتــب العــدل املكلــف بوزارة التجــارة والصناعة‬\n     ‫ا يف دعــواه‪ :‬لقــد أجــر موكلــي علــى الشــركة ‪ ..................‬كامــل‬     ‫قائـ ً‬\n     ‫املبنــى املكــون مــن دوريــن وملحــق ومواقــف املقــام علــى القطعتــن‬\n     ‫رقــم ‪ 5‬و ‪ 6‬مــن مخطــط رقــم ‪ 1/791‬بحــي املنــار مبدينــة الدمــام ملــدة‬\n     ‫عشــر ســنوات إعتبــار ًا مــن تاريــخ تســليمه حســب العقــد املبــرم يف‬\n     ‫‪1432/11/5‬ه ـ بأجــرة قدرهــا ثالثمائــة وخمســن ألــف ريــال للســنة ويف‬\n     ‫عــام ‪1430‬ه ـ أخــل املدعــى عليــه بالعقــد حيــث كان العقــد علــى معهــد‬\n     ‫لتدريــب البنــن فقســم املدعــى عليــه املبنــى الــى قســمني وقــام بتشــغيل‬\n     ‫معهــد لتدريــب البنــات مــن غيــر رجــوع الــى موكلــي ويف هــذا مخالفــة‬\n     ‫للبنــد الســادس مــن العقــد لــذا أنذرتهــم لقــاء إخاللهــم بالعقــد وطلبــت‬\n     ‫منهــم إخــاء املبنــى أو مضاعفــة األجــرة لتصبــح ســبعمائة ألــف لــذا‬\n\n‫‪71‬‬\n\f‫أطلــب إلزامهــم بإخــاء العــن املؤجــرة ودفــع مبلــغ ســبعمائة ألــف عــن‬\n‫الســنتني األخيرتــن وبعــرض الدعــوى علــى املدعــى عليــه قــال أطلــب‬\n‫مهلــة للرجــوع إلــى موكلــي وإعــداد جــواب فطلبــت مــن املدعــي أصــل‬\n‫صــك امللكيــة وحتديــد بدايــة املــدة املطالــب فيهــا مبضاعفــة األجــرة‬\n                                      ‫وبيــان مجمــوع الواصــل فأســتعد بذلــك‬\n‫ويف جلســة ‪1432/09/10‬ه ـ حضــر الطرفــان وســألت املدعــي عــن صك‬\n‫امللكيــة فأبــرز الصــك الصــادر مــن كتابــة العــدل بالدمــام األولــى برقــم‬\n‫‪ 2/64/6000‬يف ‪1432/10/13‬ه ـ ويتضمــن ملكيــة مــوكل املدعــي‬\n‫لقطعتــي األرض ‪ 5‬و ‪ 6‬مــن مخطــط رقــم ‪ 791/1‬يف حــي املنــار بالدمــام‬\n‫وأمــرت بإيــداع صــورة مصدقــة منــا باملعاملــة كمــا ســألته عــن بدايــة‬\n‫املــدة املطالــب فيهــا مبضاعفــة االجــرة ومقــدار الواصــل فقــال لســت‬\n                            ‫متأكــد ًا وأطلــب مهلــة للرجــوع إلــى احلســابات‬\n‫ويف جلســة ‪1433/02/24‬هـ حضر الطرفان وســألت املدعي عن مقدار‬\n‫الواصــل فقــال مبلــغ مليونــن وثمامنائــة ريــال وســألته عــن بدايــة املــدة‬\n‫املطالــب فيهــا مبضاعفــة األجــرة فقــال تاريــخ ‪1431/04/04‬ه ـ فســألته‬\n‫عــن املبلــغ الــذي يطالــب بــه عــن الســنتني االخيرتــن مــا صفتــه فقــال‬\n‫صفتــه مبلــغ مضاعــف علــى االجــرة املنصــوص عليهــا يف العقــد وامــا‬\n‫حســب العقــد فــا يوجــد مبلــغ متخلــف وبعــرض الدعــوى ومــا أضيــف‬\n‫إليهــا علــى املدعــى عليــه قــال صحيــح اســتأجرت الشــركة موكلتــي‬\n‫املبنــى املذكــور مــن مــوكل املدعــي باألجــرة الســنوية املذكــورة واملــدة‬\n‫املذكــورة ولكــن لــم نخــل بالعقــد وال نقــر مبضاعفــة األجــرة وال يوجــد‬\n‫مبلــغ متخلــف مــن األجــرة وغيــر مســتعدين بإخــاء العــن املؤجــرة ألن‬\n‫العقــد ســاري املفعــول فطلبــت مــن املدعــي أصــل العقــد فأبــرزه ووقــع‬\n\n\n                                                                                   ‫‪72‬‬\n\f                             ‫الطرفــان علــى صــورة منــه وأمــرت بإرفاقــه باملعاملــة ‪.‬‬\n       ‫ويف جلســة ‪1433/10/28‬ه ـ حضــر الطرفــان وخلــص املدعــى عليــه‬\n       ‫مذكرتــه اجلوابيــة بقولــه تضمــن عقــد اإليجــار بعــض الشــروط‬\n       ‫اجلوهريــة  منهــا أن للمســتأجر حــق االنتفــاع منــه واالســتفادة بــكل‬\n       ‫الطــرق املشــروعة ومنهــا أن مــدة اإليجــار عشــر ســنوات حســب البنــد‬\n       ‫ثالثــة مــن الفقــرة ثانيـاً  ومنهــا أنــه ال يحــق ألحــد الطرفــن فســخ العقــد‬\n       ‫أال بانتهــاء املــدة أو تراضــي الطرفــن حســب البنــد الســابع ومنهــا أن‬\n     ‫علــى املســتأجر تســليم املبنــى املؤجــر للطــرف األول عنــد االســتغناء عنــه  ‬\n       ‫كمــا اســتلمه عنــد بدايــة العقــد وعليــه إصــاح مــا اتلــف أو دفــع كامــل‬\n       ‫التكاليــف كمــا يف البنــد الثامــن وأحلــق علــى العقــد يف ‪1424/9/6‬ه‬\n       ‫بزيــادة اإليجــار خمســن ألــف ريــال علــى نفــس مــدة العقــد وأؤكــد علــى‬\n       ‫أن عقــد اإليجــار خــا مــن أي عبــارة أو إشــارة بــأن املعهــد يخــص الرجــال‬\n       ‫أو النســاء أو كالهمــا ونســتند علــى البنــد األول مــن أو ًال وفيــه أن يقــوم‬\n       ‫الطــرف األول بتجهيــز مقــر العامليــة يف الدمــام ويف البنــد األول مــن ثانيـ ًا‬\n       ‫وللمســتأجر حــق االنتفــاع منــه واالســتفادة بــكل الطــرق املشــروعة‬\n       ‫وهــذا نــص يف العقــد وال اجتهــاد مــع النــص وموكلتــي مرخــص لهــا‬\n       ‫ممارســة نشــاط التدريــب ســواء للنســاء او الرجــال وممارســة هــذا‬\n       ‫النشــاط اســتفادة مشــروعة ال تتعــارض مــع النظــام او مــع عقــد اإليجــار‬\n       ‫ولــم تخالــف موكلتــي البنــد الســادس مــن عقــد اإليجــار ومــا قامــت‬\n       ‫بــه هــو فصــل قســم النســاء عــن قســم الرجــال مــن خــال عمــل فواصــل‬\n       ‫ميكــن إزالتهــا يف أي وقــت دون املســاس باملبنــى وال تعتبــر تعديــات‬\n       ‫مــن شــأنها اإلضــرار باملبنــى وال تنــدرج حتــت نــص املــادة السادســة ولــو‬\n       ‫اندرجــت فــإن ذات املــادة لــم تعــط احلــق للمؤجــر يف فســخ العقــد علــى‬\n\n\n‫‪73‬‬\n\f‫افتــراض وجــود املخالفــة مــع أنهــا لــم توجــد والفصــل بــن معهــد الرجــال‬\n‫والنســاء مطلــب شــرعي ونظامــي واملــادة الثامنــة مــن العقــد ألزمــت‬\n‫موكلتــي بتســليم املبنــى إلــى الطــرف األول كمــا اســتلمته وعليهــا‬\n‫إصــاح مــا تلــف أو التعويــض عنــه وهــذا اكبــر ضمــان للمدعــي ضــد‬\n‫أي تغييــر أو تعديــل أمــا مطالبــة املدعــي بإخــاء املبنــى فــور ًا فــان فيــه‬\n‫مخالفــة صريحــة لبنــود العقــد فــا يحــق ألحــد الطرفــن فســخ العقــد إال‬\n‫بانتهــاء املــدة والتراضــي ومطالبتــه مبضاعفــة قيمــة اإليجــار يكشــف‬\n‫هدفــه فهــذا الطلــب ينــايف جميــع مــا أورده يف دعــواه ويتعــارض مــع باقــي‬\n‫الطلبــات فكيــف يطالــب باإلخــاء للمخالفــة ثــم يخيرهــا أو يســاومها‬\n‫بــن ذلــك وبــن مضاعفــة اإليجــار فهــل يســتقيم أن يطالــب بفســخ العقــد‬\n‫لوجــود مخالفــات ثــم يف الوقــت نفســه يطالــب مبضاعفــة اإليجــار علمـ ًا‬\n‫بــأن اإليجــار مغالــى فيــه نســبه للمــكان والزمــان الــذي جــرى فيــه‬\n‫االتفــاق وقبلــت موكلتــي بذلــك تطبيقــا لسياســة طويلــة األجــل إلثبــات‬\n‫مصداقيتهــا عنــد عمالئهــا وباالطــاع علــى العقــد وجــد انــه مــؤرخ يف‬\n‫‪1423/11/05‬ه ـ ويف الفصــل أو ًال البنــد األول يقــوم الطــرف األول‬\n                                                   ‫بتجهيــز مقــر ‪ .......‬يف الدمــام‬\n‫ويف الفصــل الثانــي يف البنــد األول منــه ما نصه وللمســتأجر حق االنتفاع‬\n‫منــه واالســتفادة بــكل الطــرق املشــروعة ويف البنــد الثالــث مــا نصــه إن‬\n‫هــذا اإليجــار معقــود ملــدة عشــر ســنوات ميالديــة ويف البنــد الســادس ال‬\n‫يحــق للطــرف الثانــي أي تغييــر يف املوقــع املؤجــر لــه إال بعــد أخــذ املوافقة‬\n‫اخلطيــة مــن الطــرف األول املالــك ويتــم التنفيــذ حســب شــروط الطــرف‬\n‫األول ويف البنــد الســابع ال يحــق ألحــد الطرفــن فســخ العقــد إال بانتهــاء‬\n‫املــدة أو تراضــي الطرفــن ويف البنــد الثامــن علــى الطــرف الثانــي تســليم‬\n\n\n                                                                                        ‫‪74‬‬\n\f     ‫املبنــى املؤجــر ‪ ......‬كمــا اســتلمه وقــد أحلــق عليــه يف ‪1424/09/06‬‬\n     ‫إضافــات وتعديــات مــن ضمنهــا إضافــة وحدتــن ســكنيتني يف مقدمــة‬\n                          ‫البنــاء يف الــدور الثالــث لتكــون مكاتــب إلدارة املعهــد‬\n     ‫وتعديــل مبلــغ اإليجــار بزيــادة خمســن ألــف ريــال ســنوي ًا طــوال فتــرة‬\n     ‫العقــد بعــرض العقــد علــى الطرفــن صادقــا علــى مــا فيــه وانــه مــؤرخ يف‬\n     ‫‪1423/11/05‬ه ـ املوافــق ‪2003/01/08‬م ويف جلســة ‪1433/11/27‬ه ـ‬\n     ‫حضــر الطرفــان وســألت املدعــي هــل العقــد ال يــزال ســاري املفعــول‬\n     ‫فقــال نعــم ولــن ينتهــي إال يف ‪2014/03/01‬م أي بعــد ســتة أشــهر تقريبـ ًا‬\n     ‫وســألته مــا هــو وجــه انتفــاع املدعــى عليــه مــن العــن املؤجــرة فقــال‬\n     ‫التدريــب علــى احلاســب اآللــي ولــم يغيــر نشــاطه وبعرضــه علــى املدعــى‬\n     ‫عليــه صــادق علــى ذلــك إال أنــه ذكــر أن انتهــاء العقــد يف ‪2014/7/1‬م‬\n     ‫فســألته لــدى موكلتــه ترخيــص لتدريــب النســاء فقــال نعــم وأبــرز‬\n     ‫رخصــة تدريــب نســاء باســم ‪ .....................‬النســائي للتدريــب برقــم‬\n     ‫‪135927/1/8‬وتاريــخ ‪1433/06/30‬ه ـ وهــو صــادر مــن اإلدارة العامــة‬\n     ‫للتدريــب ‪ ...‬يف املؤسســة العامــة للتدريــب التقنــي واملهنــي وأمــرت بإيــداع‬\n     ‫صــورة مصدقــة منهــا باملعاملــة وبعرضهــا علــى املدعــي صــادق عليهــا‬\n     ‫فســألت الطرفــن ألديهمــا زيــادة يريــدان إضافتهــا فقــاال ال زيــادة لدينــا‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيث تصــادق الطرفان على‬       ‫فبنـ ً‬\n     ‫أن العقــد ال يــزال ســاري املفعــول وان املدعــى عليــه انتفــع بالعــن املؤجــرة‬\n     ‫يف التدريــب علــى احلاســب اآللــي ولــم يغيــر نشــاطه ومبــا أن النشــاط‬\n     ‫الــذي متارســه املدعــى عليهــا مرخــص بــه مــن اجلهــة املختصــة وألن مســتند‬\n     ‫املدعــي يف طلبــه مــن املدعــى عليــه اإلخــاء أو مضاعفــة األجــرة هــو‬\n     ‫البنــد الســادس وألن البنــد الســادس ال يجيــز فســخ العقــد وال مضاعفــة‬\n\n\n‫‪75‬‬\n\f‫األجــرة وألن البنــد األول مــن العقــد يجيــز للمدعــى عليــه االنتفــاع بالعــن‬\n‫املؤجــرة واالســتفادة بــكل الطــرق املشــروعة وألن البنــد الســابع مينــع‬\n‫فســخ العقــد إال بعــد انتهــاء املــدة أو تراضــي الطرفــن وحيــث لــم أجــد‬\n‫يف العقــد مــا يبــرر للمدعــي طلبــه لــذا كلــه صرفــت النظــر عــن دعــوى‬\n‫املدعــي ولــم يثبــت لــدي اســتحقاقه ملــا يدعيــه وبذلــك حكمــت وبعــرض‬\n‫احلكــم علــى الطرفــن قنــع بــه املدعــى عليــه ولــم يقنــع بــه املدعــي وطلــب‬\n‫متييــزه فأجبتــه لطلبــه‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/27‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد بشــأن دعوى ……………‪  /..‬ضد ‪  /‬الشــركة‬\n‫‪ .................‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية وبرفقهــا قرارهــا رقــم ‪ 3437543‬وتاريــخ ‪1434/02/16‬ه ـ‬\n‫املتضمــن مــا نصــه ( بدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ) رئيــس‬\n‫الدائــرة الشــيخ ‪ .................‬توقيعــه بقلمــه وختمــه ‪ ،‬وقاضــي اســتئناف‬\n‫الشــيخ ‪ .................‬توقيعــه بقلمــه وختمــه ‪ ،‬وقاضــي اســتئناف الشــيخ‬\n‫‪ ........................‬توقيعــه بقلمــه وختمــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1434/3/22‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام املســاعد برقــم‬\n‫‪ 3119812‬وتاريــخ ‪ 1434/1/14‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34193124‬وتاريــخ ‪1434/1/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ........................./‬املســجل برقــم‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫‪ 33469025‬وتاريــخ ‪1433/11/29‬ه ـ اخلــاص بدعــوى‪................../‬‬\n     ‫ضد‪/‬الشــركة ‪ ......................‬يف قضيــة حقوقيــة وقــد تضمــن الصــك‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n     ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                      ‫حــرر يف ‪1434/2/16‬ه ـ ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":70,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"705d1697f2a7933f2d25f7adf8308b140ebf988d197ec38ce5901450902e5de3","normalized_text_hash":"6616d9f43ed4f7db3bb4e6ac8e769eb4c8d71b37adae3dc3117268be04570fd7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p70-33469025"},{"id":"75941498-0fb4-5449-8bbd-570c0e463844","document_type":"judgment","category":"judicial","subcategory":"general","title":"اجارة -عقد -اجاره سيارة -مطالبة باجرة سيارة -تخلف املدعى عليه عن احلضور رغم تبلغه -االستعانه باهل اخلبره يف مضاهاة اخلط -إحضار البينة بأن السيارة كانت بحوزة املدعى عليه وقت القبض ،حتليف اليمن -إلزام املدعى عليه بدفع باقي األجرة - الغائب على حجته متى حضر.","document_number":"34254640","case_number":"15788","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة واحملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/28","year":"1434","subject":"اجارة -عقد -اجاره سيارة -مطالبة باجرة سيارة -تخلف املدعى عليه عن احلضور رغم تبلغه -االستعانه باهل اخلبره يف مضاهاة اخلط -إحضار البينة بأن السيارة كانت بحوزة املدعى عليه وقت القبض ،حتليف اليمن -إلزام املدعى عليه بدفع باقي األجرة - الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/28:‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪34254640 :‬‬\n                     ‫َر ْق ُم الدعوى‪15788:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‬\n         ‫‪  34346223:‬تاريخه‪1434/11/2:‬هـ‬\n\n\n‫اجــارة ‪ -‬عقــد ‪ -‬اجــاره ســيارة ‪ -‬مطالبــة باجــرة ســيارة ‪-‬تخلــف املدعــى‬\n‫عليــه عــن احلضــور رغــم تبلغــه ‪ -‬االســتعانه باهــل اخلبــره يف مضاهــاة‬\n‫اخلــط ‪ -‬إحضــار البينــة بــأن الســيارة كانــت بحــوزة املدعــى عليــه وقــت‬\n‫القبــض ‪ ،‬حتليــف اليمــن ‪ -‬إلــزام املدعــى عليــه بدفــع باقــي األجــرة ‪-‬‬\n                                          ‫الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه غيابيــا بأنــه اســتأجر منــه‬\n‫ســيارة ملــدة ســبعة وعشــرين يومــا مبائــة وعشــرة ريــاالت يوميــا ثــم‬\n‫اســتبدلها بســيارة أخــرى وبنفــس األجــرة إال أنــه لــم يســلم الســيارة‬\n‫إال بعــد املــدة وابــاغ اجلهــات الرســمية والتعميــم عنــه والقبــض عليــه‪،‬‬\n‫عليــه وألن الســيارة بقيــت عنــده أربعمائــة وأحــد عشــر يومــا فقــد طلــب‬\n‫إلزامــه بدفــع أربعــة وثالثــن ألفــا وأربعمائــة ريــال بعــد حســم مــا ســلمه‪،‬‬\n‫جــرى تبليــغ ابنــه بجلســتني إال أنــه لــم يحضــر كمــا وردت إفــادة بأنــه‬\n‫جــرى تبليغــه هاتفيــا فاعتــذر عــن عــدم احلضــور ‪ ،‬طلــب مــن املدعــي‬\n                                                                                      ‫‪92‬‬\n\f     ‫البينــة فأحضــر رجلــي  األمــن اللذيــن قبضــا علــى املدعــى عليــه وشــهدا‬\n     ‫بالقبــض عليــه وضبــط الســيارة معــه وال يذكــران أكثــر مــن ذلــك ‪-‬‬\n     ‫وردت إفــادة الشــرطة بأنــه جــرى التعميــم عليــه وإدراجــه ضمــن قائمــة‬\n     ‫إيقــاف اخلدمــات ‪ -‬جــرى االطــاع علــى إقــرار خطــي منســوب للمدعــى‬\n     ‫عليــه يقــر فيــه باملبلــغ املدعــى بــه وموجبــه فطلــب مــن املدعــي احضــاره‬\n     ‫وإحضــار أصــل وثيقــة عقــد األجــرة إلجــراء املضاهــاة لــدى األدلــة‬\n     ‫اجلنائيــة ‪ -‬طلبــت األدلــة اجلنائيــة أوراقــا محــررة يف أحــوال عاديــة مــن‬\n     ‫املدعــى عليــه فــردت اإلفــادة بتعــذر ذلــك لعــدم حضــور املدعــى عليــه‬\n     ‫وطلــب اإلفــادة هــل التوقيــع علــى وثيقــة العقــد متفقــة مــع اإلقــرار باحملرر‬\n     ‫فعــادت اإلفــادة بأنهمــا متفقــان ‪ -‬طلــب مــن املدعــي اليمــن علــى صحــة‬\n     ‫دعــواه تقويــة جلانبــه فحلــف اليمــن املطلوبــة ‪ -‬بنــاء علــي مــا تقــدم مــن‬\n     ‫الدعــوي واالجابــة وبنــاء علــي مــا جــاء بعقــد االيجــار ومــا جــاء باالقــرار‬\n     ‫املذكــور وبنــاء علــي ماجــاء بتقريــر األدلــة اجلنائيــة وحيــث أدى املدعــي‬\n     ‫اليمــن الشــرعية تقويــة جلانبــه وعلــى عــدم اســتالمه املبلــغ املذكــور‬\n     ‫فقــد صــدر احلكــم علــي املدعــي عليــه الغائــب  بدفــع أربعــة وثالثــن‬\n     ‫الف ـ ًا وأربعمئــة ريــال للمدعــي وتقــرر بعــث صــورة مــن صــك احلكــم‬\n     ‫للمدعــى عليــه ‪ -‬تعــذر ابالغــه فرفعــت لالســتئناف ‪ -‬صــدق احلكــم مــن‬\n     ‫محكمــة االســتئناف وأضافــت بــأن الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــي مــن النبــي بعــده وبعــد لــدي‬\n     ‫أنــا د‪ .................. /‬القاضــي باحملكمــة العامــة باملدينــة املنــورة واحملالــة‬\n     ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــه برقــم ‪30/60155‬يف‬\n‫‪93‬‬\n\f‫‪1430/11/14‬ه ـ واملقيــدة بأســاس احملكمــة برقــم ‪ 15788‬يف‬\n‫‪1430/11/14‬ه ـ ففــي يــوم الســبت املوافــق ‪1431/10/23‬ه ـ حضــر‪/‬‬\n‫‪....................‬بالســجل املدنــي رقــم ‪ .................‬املدينــة وادعــي علــي‬\n‫الغائــب عــن مجلــس احلكــم ‪ ........... /‬ســعودي اجلنســية   بالســجل‬\n‫املدنــي رقــم ‪ .............‬بقولــه أننــي أجــرت املدعــي عليــه ســيارة ‪ ...‬رقــم‬\n‫اللوحــة (‪ ).............‬لــون ‪ ...‬مــدة ســبعة وعشــرين يومــا بأجــرة يوميــة‬\n‫قدرهــا مائــة وعشــرة ريــاالت اعتبارمــن ‪1429/9/9‬ه ـ ثــم يف يــوم األثــن‬\n‫‪1429/9/22‬ه ـ حضــر واســتبدل الســيارة بســيارة أخــرى مــن نــوع ‪...‬‬\n‫وبنفــس االجــرة وبنفــس املــدة ولكنــه لــم يســلم الســيارة بعــد نهايــة املــدة‬\n‫املذكــورة فأبلغــت اجلهــات الرســمية عنــه ومت التعميــم عنــه ومت القبــض‬\n‫علــى الســيارة يف ‪1430/11/6‬ه ـ وبذلــك فقــد بقيــت الســيارة لديــه‬\n‫أربعمائــة واحــد عشــر يومــا بلغــت أجرتهــا واحــد وأربعون ألفــا ومائة ريال‬\n‫وقــد ســلمني خمســة آالف ومائتــي ريــال وبقــي عليــه خمســة وثالثــون الفا‬\n‫وتســعمائة ريــال وقــد كتــب لــي إقــرار ًا بذلــك بتاريــخ ‪1430/11/6‬ه ـ‬\n‫وهــذا مانصــه أقــر أنــا ‪ ...................‬بأننــي اســتأجرت ســيارة ‪ ...‬رقــم(‬\n‫‪)...........‬مبوجــب العقــد رقــم ‪ 407‬يف ‪1429/9/9‬ه ـ ملــدة ‪ 27‬يومــا ثــم‬\n‫تغيــب حتــي عمــم عــن الســيارة وقبضــت مــن قبــل البحــث اجلنائــي يف يــوم‬\n‫االحــد ‪1430/11/6‬ه ـ وحســبت املــدة التــي بقيــت وهــي أربعمائــة وأحــد‬\n‫عشــر يومـاً  بأجــرة يوميــة قدرهــا مائــة ريــال بعــد اخلصــم ليصبــح املبلــغ‬\n‫قــدره واحــد واربعــون الفـ ًا ومائــة ريــال دفعــت منهــا خمســة آالف ومئتــي‬\n‫ريــال ومبوجــب العقــد علــى دفعــات وتبقــى لــدى مبلــغ قــدره خمســة‬\n‫وثالثــون الف ـ ًا وتســعمائة ريــال وهــو يف ذمتــي وســوف اســدده يف مــدة‬\n‫عشــرة أيــام بــدون تأخيــر وعلــي ذلــك قــررت بذلــك وأشــهد علــي نفســي‬\n\n\n                                                                                        ‫‪94‬‬\n\f     ‫واهلل خيــر الشــاهدين املقرمبــا فيــه ‪ ..............‬توقيعــه يف ‪1430/11/6‬ه ـ‬\n     ‫أ‪ .‬هــ  وبعــد ذلــك ســلمنى الــف وخمســمائة ريــال فقــط وبقــي عليــه أربعــه‬\n     ‫وثالثــون الفــا وأربعمائــة ريــال  أه ـ ‪ .‬وملــا أنتهــت املهلــة بحثــت عنــه فلــم‬\n     ‫أجــده وتقدمــت ضــده بهــذه الدعــوي ولــذا فأطلــب احلكــم عليــه بدفــع‬\n     ‫املبلــغ املذكــور وقــدره أربعــة وثالثــون الف ـ ًا وأربعمائــة ريــال هكــذا‬\n     ‫قــرر دعــواه هــذا وقــد جــري االطــاع علــى عقــد التأجيــر الصــادر مــن‬\n     ‫مؤسســة ‪ ...............‬لتأجيــر الســيارات برقــم ‪ ...‬املتضمــن اســتئجار‬\n     ‫املدعــو‪ ......................... /‬للســيارة املذكــورة باألجــرة املذكــورة املــدة‬\n     ‫املذكــورة واملشــروح عليــه بــأن املذكــور اســتبدل الســيارة ‪ ...‬بســيارة ‪...‬‬\n     ‫برقــم ‪ ...............‬هــذا وقــد جــري طلــب املذكوربحضــور جلســة الثالثــاء‬\n     ‫‪1430/11/29‬هـ حيث تبلغ ابنه ‪ ...‬من قبل محضر اخلصوم ‪  ...‬ولكنه‬\n     ‫لــم يحضــر كمــا جــرى طلبــه حلضــور جلســة الســبت ‪1431/1/23‬ه ـ‬\n     ‫فوردنــا خطــاب قســم احملضريــن املتضمــن انــه مت الذهــاب الــي املنــزل‬\n     ‫عــدة مــرات وبعــد االتصــال باملدعــى عليــه أفــاد بأنــه يف املستشــفي يف‬\n     ‫الريــاض مــن قبــل احلــج إلجــراء عمليــه جراحيــة يف قلبــه وال يعلــم متــى‬\n     ‫يخــرج علم ـ ًا بأنــه تبلــغ مبوعــد اجللســة هاتفي ـ ًا كمــا مت حتديــد جلســة‬\n     ‫الســبت ‪1431/3/13‬ه ـ فأفــاد احملضــر أنــه مت الذهــاب للمنــزل عــدة‬\n     ‫مــرات ولــم جنــده وافــاد احلــارس بأنــه يف الريــاض إلجــراء عمليــه ثــم مت‬\n     ‫حتديــد جلســة يف يــوم الســبت ‪1431/4/25‬ه ـ فعــاد اخلطــاب بواســطة‬\n     ‫محضــر اخلصــوم ‪ ...‬أنــه مت الذهــاب ملنــزل املذكــور عــدة مــرات واليوجد‬\n     ‫مــن يتــم تبليغــه وقــد ســلمت صــورة اخلطــاب الــي عمــدة احلــي كمــا جــرى‬\n     ‫ارســال خطــاب مســجل برقــم ‪ 495‬يف ‪1431/3/20‬ه ـ كمــا مت حتديــد‬\n     ‫جلســة يف يــوم الثالثــاء ‪1431/8/15‬ه ـ ومت ابــاغ ابنــه املدعــو‪......... /‬‬\n\n\n‫‪95‬‬\n\f‫الــذي أفــاد أن أبــاه مــا يــزال يف املستشــفي حســب كالمــه مــن قبــل‬\n‫احملضــر ‪ .............‬وحيــث احلــال مــا ذكــر فقــد قــررت النظــر يف القضيــة‬\n‫غيابي ـ ًا وطلبــت مــن املدعــي البينــة فقــال لــدي شــاهدان مــن البحــث‬\n‫اجلنائــي شــهدا علــى اإلقــرار املذكــور ومســتعد بإحضارهمــا ثــم رفعــت‬\n‫اجللســة لذلــك وعليــه حصــل التوقيــع ‪ .‬ويف يــوم األحــد ‪1431/12/1‬ه ـ‬\n‫حضــر املدعــي كمــا حضــر معــه كل مــن ‪ .................‬بالســجل املدنــي‬\n‫رقــم ‪ ...............‬املدينــة و‪ ........................‬بالســجل املدنــي رقــم ‪..............‬‬\n‫املدينــة وبســؤالهما عمــا لديهمــا مــن شــهادة قــاال أننــا أســتلمنا املدعــو‪/‬‬\n‫‪ ....................‬مــن الدوريــات األمنيــة وقــد حضــر عندنــا وكان قــد‬\n‫ســبق التعميــم عنــه كمــا اســتلمنا منــه الســيارة العائــدة للمدعــي هــذا‬\n‫احلاضــر حيــث إنهــا كانــت ســيارة تأجيــر وســلمناها لهــذا احلاضــر‬\n‫‪ ...................‬ووقــع بإســتالمها وبعــد ذلــك أوقفنــا البحــث عــن املذكــور‬\n‫وانتهــى دورنــا بذلــك وال نذكــر اكثــر مــن ذلــك هكــذا شــهدا هــذا‬\n‫وقــد ســبق أن وردنــا خطــاب مديــر شــرطة املدينــة برقــم ‪ 5/5/2/22‬يف‬\n‫‪1432/1/1‬ه ـ املتضمــن إدراج اســم ‪ ................‬علــى قائمــة املطلوبــن‬\n‫إجــراء (إيقــاف خدمــات) وحيــث أنــه لــم يراجعنــا املدعــي عليــه طيلــة‬\n‫تلــك املــدة فقــد جــرى ســؤال املدعــي عــن اإلقــرار األساســي املنســوب‬\n‫للمدعــى عليــه فقــال إنــه موجــود لــدي فطلبــت منــه إحضــار العقــد‬\n‫لتأجيــر الســيارة وإحضــار اإلقــرار األســاس للمدعــى عليــه ملضاهــات‬\n‫التوقيعــن العائديــن للمدعــى عليــه مــع بعضهمــا مــن قبــل األدلــة اجلنائيــة‬\n‫فإســتعد بذلــك ورفعــت اجللســة ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/3/4‬ه ـ‬\n‫وفيهــا حضــر املدعــي وقــد عــادت املعاملــة مــن األدلــة اجلنائيــة برقــم‬\n‫‪ 117/5320‬يف ‪1433/5/22‬ه ـ والــذي جــاء فيــه بشــأن مضاهــاة توقيــع‬\n\n\n                                                                                                   ‫‪96‬‬\n\f     ‫‪ ...................‬علــي أقــرار وعقــد تأجيــر ســيارة منســوبة إليــه (موضوعــي‬\n     ‫الفحــص) وباطــاع املختصــن لدينــا تبــن أنــه يلــزم إلكمــال الفحــص‬\n     ‫حتقيــق األتــي ‪1 -:‬ـ  تزويدنــا بــأوراق محــرره بظــروف طبيعيــة وفيــرة‬\n     ‫العــدد حتتــوي علــي توقيــع املدعــو‪................ /‬علــى أن تكــون أساس ـ ًا‬\n     ‫ولديــه صــور ًا ومــن واقــع تعامالتــه الرســمية ‪ -2 ،‬تكليــف ‪..............‬‬\n     ‫باحلضــور لشــعبة التزويــف والتزويــر طرفنــا ليتــم اســتكتابة مــن قبــل‬\n     ‫املختصــن لدينــا ‪ .‬لــذا نعيــد لكــم أوراق القضيــة ويف حالــة اســتكمال‬\n     ‫املطلــوب إعادتهــا لنــا ‪ .‬وحيــث إن املدعــى عليــه متهــرب عــن القضيــة‬\n     ‫منــذ مــا يزيــد عــن حوالــي ثــاث ســنوات وحيــث مت إيقــاف خدماتــه منــذ‬\n     ‫مــا يزيــد عــن ســنتني ولــم يتــم حضــوره إلــى تاريخــه وحيــث أن ورقــة‬\n     ‫عقــد اإليجــار ورقــة أســاس واقــراره باملبلــغ علــي ورقــة أســاس وكال‬\n     ‫التوقيعــن توقعــن اساســيني فقــد قــررت اعــادة املعاملــة لإلدلــة اجلنائيــة‬\n     ‫ملضاهــات التوقيعــن املذكوريــن علــي حالهــا حيــث أن املذكــور‬\n     ‫متهــرب ولــم نتمكــن مــن احضــاره ولــو حضــر لدينــا ملــا احتجنــا الــي‬\n     ‫مخاطبتهــم ورفعــت اجللســة‪ .‬ثــم جــرت اعــادة املعاملــة مــرة آخــرى لالدلــة‬\n     ‫اجلنائيــة ملضاهــات التوقيــع املوجــود علــى االقــرار مــع التوقيــع علــي عقــد‬\n     ‫االيجــار فقــط ثــم عــادت مــن األدلــة اجلنائيــة برقــم ‪ 1/7/3386/22‬يف‬\n     ‫‪1434/4/3‬ه ـ والــذي جــاء فيــه تقريــر فنــى رقــم ‪ 50‬مــادة الفحــص (‪)1‬‬\n     ‫عقد ســيارة (‪ )2‬اقرارواملطلوب املضاهات بني توقيع ‪ .........‬املنســوب له‬\n     ‫علــى االقــرار والتوقيــع املثبــت علــي عقــد إيجــار ســيارة مــن فــرع مؤسســة‬\n     ‫‪ ...‬الفحــص والنتيجــة باملضاهــات بعــد النتيجــة‪ -:‬باملضاهــات بــن‬\n     ‫التوقيعــن موضــوع الفحــص (‪ )1‬و(‪)2‬ومقارنتهمــا وجــد أنهما يتفقان أي‬\n     ‫محــرره شــخص واحــد‪ .‬انتهــى الفاحصــون رقيــب ‪  ..................../‬رئيــس‬\n\n\n‫‪97‬‬\n\f  ‫شــعبة الفحــوص الفنيــة ‪ ..............‬أه ـ وحيــث احلــال ماذكــر فقــد أفهمت‬\n  ‫املدعــي بــأن عليــه اليمــن تقويــة جلانبــه واليمــن علــى أنــه لــم يســتلم املبلــغ‬\n  ‫ا واهلل العظيــم الــذي ال‬      ‫املذكــور فاســتعد بــأداء اليمــن ثــم حلــف قائ ـ ً‬\n  ‫الــه إال هــو عالــم الغيــب والشــهادة أنــه بقــي لــي بذمــة املدعــي عليــه مــن‬\n  ‫الســند الــذي حــرره لــي أربعــة وثالثــون ألف ـ ًا وأربعمائــة ريــال وأربعمائــة‬\n  ‫ريــال وواهلل العظيــم أننــي لــم أســتلم منــه شــيئا إلــى تاريخــه هكــذا‬\n  ‫حلــف فبنــاء علــي مــا تقــدم مــن الدعــوي واإلجابــة وبنــاء علــي مــا جــاء‬\n  ‫بعقــد اإليجــار وماجــاء باإلقــرار املذكــور وبنــاء علــي ماجــاء بتقريــر‬\n  ‫األدلــة اجلنائيــة وحيــث أدى املدعــي اليمــن الشــرعية تقويــة جلانبــه وعلــى‬\n  ‫عــدم اســتالمه املبلــغ املذكــور فقــد حكمــت علــي املدعــي عليــه الغائب‬\n  ‫‪  .............‬بدفــع املبلــغ املدعــي بــه وقــدره أربعــة وثالثــون ألف ـ ًا وأربعمائــة‬\n  ‫ريــال للمدعــي هــذا مــا حكمــت بــه فليعلــم وقــررت بعــث صــورة مــن‬\n  ‫احلكــم للمدعــي عليــه إلبــداء قناعتــه باحلكــم مــن عدمهــا حســب‬\n  ‫املتبــع  وضبــط يف الضبــط املفتــوح جلــد ‪ 10/52‬لعــام ‪1431‬ه ـ صفحــة‬\n              ‫‪121‬وصلــي اهلل علــي نبينــا محمــد وعلــي آلــه وصحبــه وسـ ـ ـ ــلم‬\n  ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد  املوافــق ‪ 1434/11/23‬ه ـ فقــد‬\n  ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة باخلطــاب‬\n  ‫رقــم‪ 34872890‬يف‪ 1434/11/06‬ه ـ وبرفقهــا الصــك الصــادر منــا‬\n  ‫برقــم ‪ 34293027‬يف ‪ 1434/08/09‬ه ـ ومظهــر عليــه بالقــرار رقــم‬\n  ‫‪ 34346223‬يف ‪ 1434/11/02‬ه ـ الصــادر مــن الدائــرة احلقوقيــة‬\n  ‫اخلامســة  املتضمــن املوافقــة علــى احلكــم واهلل املوفــق‪ .‬قاضــي اســتئناف‬\n‫‪ .....................‬ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ‪  ...........................‬‬\n  ‫ختمــه وتوقيعــه  ‪ ،‬رئيــس الدائــرة ‪  .....................‬ختمــه وتوقيعــه ‪ .‬وصلــى‬\n\n\n                                                                                                ‫‪98‬‬\n\f                         ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ‬\n     ‫فقــد جــرى م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة‬\n     ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى‬\n     ‫هــذا احلكــم الصــادر مــن فضيلــة الشــيخ ‪   ................... /‬القاضــي‬\n     ‫يف احملكمــة العامــة باملدينــة املنــورة   املســجل بعــدد ‪34254640‬‬\n     ‫وتاريخ‪1434/6/28‬ه ـ املتضمــن دعــوى ‪ ................... /‬ضــد ‪..................‬‬\n     ‫الغائــب عــن مجلــس احلكــم ‪ ،‬احملكــوم في ــه مبــا دون باطــن الصــك ‪،‬‬\n     ‫وبدراســة احلكــم وص ــورة ضبط ــه تقــرر املوافقــة علــى احلكــم والغائــب‬\n     ‫علــى حجتــه إذا حضــر ‪ .‬وبــاهلل التوفيــق‪  ،‬وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                              ‫وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":92,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2967fd2523fefdf7fb6df0bfd582b73a3a49d78067ac627fc699d3081a3ea8f4","normalized_text_hash":"9a6dd15b652fcafbe24159c80827495b05b01b2ba39674bfef19c3e50820b73f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p92-34254640"},{"id":"3aee44c8-8073-54f2-90b9-ad4a35cbff62","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -عقد -مطالبة بفسخ العقد وإخاء العقار لعدم إلتزام املستأجر بشروط العقد -إقرار املدعى عليه بعدم دفع األجرة املستحقة يف موعدها -والدفع بالقيام بإصالحات بإذن املؤجر واملطالبة بحسمها من األجرة املستحقة -إلزام املدعى عليه باإلخاء وصرف النظر عن طلبه احلسم لعدم ثبوت إذن املؤجر","document_number":"33286548","case_number":"17043","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/8","year":"1434","subject":"إجارة -عقد -مطالبة بفسخ العقد وإخاء العقار لعدم إلتزام املستأجر بشروط العقد -إقرار املدعى عليه بعدم دفع األجرة املستحقة يف موعدها -والدفع بالقيام بإصالحات بإذن املؤجر واملطالبة بحسمها من األجرة املستحقة -إلزام املدعى عليه باإلخاء وصرف النظر عن طلبه احلسم لعدم ثبوت إذن املؤجر","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/8:‬هـ   ‬\n                   ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33286548 :‬‬\n                        ‫َر ْق ُم الدعوى‪17043 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 3430181‬تاريخه‪1434/2/5:‬هـ‬\n\n\n‫إجــارة ‪ -‬عقــد‪ -‬مطالبــة بفســخ العقــد وإخــاء العقــار لعــدم إلتــزام‬\n‫املســتأجر بشــروط العقــد ‪ -‬إقــرار املدعــى عليــه بعــدم دفــع األجــرة‬\n‫املســتحقة يف موعدهــا ‪ -‬والدفــع بالقيــام بإصالحــات بــإذن املؤجــر‬\n‫واملطالبــة بحســمها مــن األجــرة املســتحقة ‪ -‬إلــزام املدعــى عليــه‬\n‫باإلخــاء وصــرف النظــر عــن طلبــه احلســم لعــدم ثبــوت إذن املؤجــر‬\n                                                           ‫علــى احلســم‪.‬‬\n\n\n\n\n‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه اســتأجر منهــا دورا ملــدة ثــاث‬\n‫ســنوات بأجــرة معلومــة وقــد ســدد املبلــغ احلــال إال أنهــا تطالبــه بإخــاء‬\n‫الــدور لعــدم قيامــه بســحب البيــارة وعــدم قيامــه بعمــل الســراميك وعــدم‬\n‫انتظامــه بدفــع األجــرة يف وقتهــا احملــدد واقتنائــه احلمــام والدجــاج يف‬\n‫ســطح الــدور وقــد تــأذت منــه وإلزالتــه احلاجــز املوضــوع علــى النافــذة‬\n‫املطلــة علــى فنــاء موكلتــه ‪ -‬أقــر املدعــى عليــه بالعقــد وأنكــر كل‬\n\n                                                                                    ‫‪100‬‬\n\f      ‫موجبــات اإلخــاء وأن الطيــور يف ســطحه ال أذى لهــا عليهــا وأنــه لــم‬\n      ‫يتفــق معهــا علــى وضــع الســراميك لكامــل الــدور ‪ -‬قــرر وكيــل املدعية‬\n      ‫بأنــه لــم يعــد احلاجــز كمــا كان وأن الســراميك كان لكامــل الــدور‬\n      ‫وهــو لــم يقــم إال ببعضــه ‪ -‬قــرر وكيــل املدعــى عليــه بــأن خســر مــا‬\n      ‫يقــارب الثالثــن ألــف ريــال مقابــل اصالحــات ويطالــب بحســمها مــن‬\n      ‫األجــرة ‪ -‬قــرر وكيــل املدعيــة بــأن هــذه االصالحــات لــم تكــن بــإذن‬\n      ‫موكلتــه عــدا الســراميك فقــد حســم لــه مــن األجــرة ألجلهــا ‪ -‬أحضــر‬\n      ‫املدعــي وكالــة شــاهدا شــهد بأنــه الــدور اســتؤجر عــن طريقــه وقــد‬\n      ‫جــرى تخفيــض األجــرة مقابــل قيــام املدعــى عليــه بعمــل الســراميك‬\n      ‫والتعتيــق ويكــون للمؤجــر حــق الفســخ إذا تأخــر عــن دفــع األجــرة ‪ -‬لــم‬\n      ‫يطعــن املدعــى عليــه بشــهادة الشــاهد بشــيء ‪ -‬أحضــر املدعــي وكالــة‬\n      ‫البينــة علــى عدالــة شــاهده ‪ -‬جــرى ســؤال وكيــل املدعــى عليــه البينــة‬\n      ‫علــى دفعــه بــأن االصالحــات كانــت بــإذن املدعيــة فقــرر بــأال بينــة لديــه‬\n      ‫فأفهمــه بــأن ملوكلــه طلــب ميــن املدعيــة إال أن وكالتــه ال تخولــه تقريــر‬\n      ‫طلبهــا مــن عدمــه وأن علــى موكلــه احلضــور أو احضــار وكالــة تخولــه‬\n      ‫طلبهــا ‪ -‬جــرى االطــاع علــى وثيقــة العقــد وقــد ظهــر فيهــا أن للمدعيــة‬\n      ‫خيــار الفســخ إذا تأخــر املســتأجر عــن الســداد أو ازعــاج اجليــران ويف‬\n      ‫اجلانــب األميــن مــن العقــد دون بأنــه جــرى تخفيــض األجــرة مقابــل‬\n      ‫تركيــب الســراميك ‪ -‬أقــر وكيــل املدعــى عليــه بــأن موكلــه تأخــر‬\n      ‫يف ســداد األجــرة ‪ -‬فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ومبــا أن‬\n      ‫عقــد اإليجــار نــص علــى فســخ العقــد يف حالــة التأخــر يف تســديد األجــرة‬\n      ‫وأذى اجليــران ومبــا أن املدعــى عليــه وكالــة أقــر بتوقفــه عــن دفع األجرة‬\n      ‫وهــو مخــول باإلقــرار يف الوكالــة وألن املدعــى عليــه وكالــة يشــغل‬\n\n\n‫‪101‬‬\n\f‫العقــار حتــى اآلن وذكــر املدعــى عليــه أن عقــد اإليجــار ســا ٍر ومبــا أن‬\n‫املدعــى عليــه طالــب بخصــم اإلصالحــات مــن ثمــن األجــرة وألنــه ذكــر‬\n‫يف العقــد أنــه جــرى تخفيــض األجــرة مقابــل تركيــب الســيراميك وألن‬\n‫املدعــي وكالــة أنكــر موافقــة موكلتــه علــى قيــام املدعــى عليــه أصالــة‬\n‫باإلصالحــات وألن املدعــى عليــه لــم يحضــر بينــة ولــم يخــول وكيلــه‬\n‫طلــب اليمــن ولــم يحضــر ليقــرر هــل يطلــب اليمــن أم ال وملصادقــة‬\n‫املدعــى عليــه علــى عقــد اإليجــار لــذا فقــد صــدر احلكــم بإلــزام املدعــى‬\n‫عليــه أصالــة بإخــاء العقــار املســتأجر وتســليمه للمدعيــة أصالــة عــن‬\n‫طريــق احلقــوق املدنيــة وصــرف النظــر عــن طلبــه خصــم اإلصالحــات‬\n‫التــي ذكرهــا مــن قيمــة اإليجــار ‪ -‬بعــرض احلكــم علــى املدعــى عليــه‬\n‫وكالــة قــرر عــدم القناعــة فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 17043‬وتاريــخ ‪1431/04/05‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3156358‬وتاريــخ ‪1431/04/01‬ه ـ ففــي يــوم الثالثاء‬\n‫املوافق‪1431/08/29‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 57‬وفيهــا حضــر‬\n‫‪ ...............‬ســجل رقــم ‪ ....................‬بالوكالــة عــن  ‪ .................‬مبوجــب‬\n‫الوكالــة رقــم ‪ 9861‬يف ‪ 1428/02/15‬ه ـ الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بجنــوب الريــاض وحضــر حلضــوره ‪ ................‬ســجل رقــم‬\n‫‪ .......................‬وادعــى األول بقولــه لقــد اســتأجر املدعــى عليــه مــن‬\n                                                                                              ‫‪102‬‬\n\f      ‫موكلتــي دورا علويــا يف الفلــة الواقعــة بحــي ‪ ...............‬بالقــرب مــن‬\n      ‫شــارع ‪ ........‬بتاريــخ ‪ 1430/06/01‬ه ـ ملــدة ثــاث ســنوات بأجــرة ســنوية‬\n      ‫قدرهــا واحــد وعشــرون ألــف ريــال وقــد ســدد املبلــغ احلــال وموكلتــي‬\n      ‫تطلــب إلزامــه بفســخ العقــد وإخــاء العقــار وذلــك إلخاللــه بشــروط‬\n      ‫العقــد التاليــة ‪ -1 :‬عــدم ســحب البيــارة ‪ -2‬عــدم قيامــه بعمــل ســيراميك‬\n      ‫لكامــل الــدور كمــا هــو متفــق عليــه  ‪ -3‬عــدم ســداده االيجــار يف وقتــه‬\n      ‫‪ -4‬وجــود حمــام ودجــاج يف ســطح الفلــة وقــد تــأذت منــه موكلتــي ‪-5‬‬\n      ‫كمــا أنــه قــام بإزالــة احلاجــز املوضــوع علــى النافــذة التــي تطــل علــى فنــاء‬\n      ‫تابــع ملوكلتــي هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه كلــه غيــر صحيــح‬\n      ‫مــا عــدا وجــود احلمــام والدجــاج ولكــن ليــس فيــه أذى علــى موكلتــه‬\n      ‫أمــا ســحب البيــارة فقــد قمــت بذلــك مرتــن أو ثــاث وأمــا الســيراميك‬\n      ‫فاملتفــق عليــه كان علــى الصالــة وقــد عملــت وأمــا احلاجــز فقــد كســر‬\n      ‫بســبب لعــب األوالد وقــد أعدتــه كمــا كان وأنــا غيــر مســتعد بإخــاء‬\n      ‫العقــار وبعــرض ذلــك علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه‬\n      ‫مــن أنــه أعــاد احلاجــز فصحيــح ولكنــه لــم يعــده كمــا كان ومــا ذكــره‬\n      ‫مــن أن االتفــاق علــى الســيراميك علــى الصالــة فقــط فغيــر صحيــح‬\n      ‫والصحيــح أن املتفــق عليــه للــدور كامــا وهــو منصــوص عليــه يف العقــد‬\n      ‫فجــرى ســؤال املدعــى عليــه هــل لديــه بينــة علــى أن املتفــق عليــه هــو‬\n      ‫عمــل الســيراميك للصالــة فقــط فقــال نعــم وســوف أحضرهــا يف اجللســة‬\n      ‫القادمــة وعليــه رفعــت اجللســة وحــدد لهــا موعــد يــوم الثالثــاء املوافــق‬\n      ‫‪ 1431/11/04‬ه ـ الســاعة ‪ 09,30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1431/08/29‬ه ـ احلمــد هلل‬\n\n\n‫‪103‬‬\n\f  ‫وحــده وبعــد ففــي يــوم الثالثــاء  املوافــق ‪1431/11/4‬ه ـ أفتتحــت اجللســة‬\n  ‫الســاعة ‪  09 : 52‬وفيهــا حضــر املتداعيــان ويف هــذه اجللســة قــال املدعــى‬\n  ‫عليــه بــأن الــدور مت عمــل ســراميك لــه وأطلــب خــروج جلنــه عليــه وعليــه‬\n  ‫فقــد رفعــت اجللســة للكتابــة لهيئــة النظــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1431/11/4‬ه ـ‬\n  ‫احلمد هلل وحده وبعد ففي يوم االربعاء املوافق ‪1432/9/10‬هـ أفتتحت‬\n  ‫اجللســة الســاعة ‪  01 : 15‬وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره‬\n  ‫ا عــن ‪..........................‬‬\n                                  ‫‪ ...................‬ســجل رقــم ‪ ....................‬وكي ـ ً‬\n  ‫مبوجــب الوكالــة رقــم ‪ 76581‬يف ‪1432/9/8‬ه ـ الصــادرة مــن كتابــة‬\n  ‫العــدل الثانيــة بجنــوب الريــاض وفيهــا وردنــا قــرار هيئــة اخلبــراء رقــم‬\n  ‫‪ 1/633‬وتاريــخ ‪1432/5/2‬ه ـ واملتضمــن فقــد مت الوقــوف علــى محــل‬\n  ‫النــزاع بحضــور الطرفــن وهــو عبــارة عــن دور ثانــي يف فلــة املدعيــة‬\n  ‫وقــد قــام املدعــى عليــه بوضــع بــاط ســيراميك لكامــل الــدور ماعــدا‬\n  ‫غرفتــن وممــر بينهمــا حيــث أن بهــا فرشــة أرضيــة ونقــدر أن الــذي وضــع‬\n‫الســيراميك فيــه يعــادل ثالثــة أربــاع مســاحة الــدور هــذا مالدينــا أ ‪ .‬هــ  ‬\n  ‫ويف هــذه اجللســة قــال املدعــى عليــه وكالــة إن التهميــش املوضــوع علــى‬\n  ‫عقــد اإليجــار واخلــاص بالســيراميك لــم يكــن مبوافقــة موكلــي كمــا‬\n  ‫أن موكلــي قــد عمــل إصالحــات يف الــدور كلفــت ثالثــن ألــف يطلــب‬\n  ‫خصمهــا مــن اإليجــار فجــرى ســؤاله عــن نــوع اإلصالحــات وهــل كانــت‬\n  ‫بإتفــاق مــع املدعــي فقــال ســوف أســأل موكلــي ورفعــت اجللســة وحــدد‬\n  ‫لهــا موعــد يــوم االثنــن املوافــق ‪1432/11/19‬ه ـ الســاعة ‪ 9.30‬وبــاهلل‬\n  ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                               ‫حــرر يف ‪1432/9/10‬ه ـ‬\n\n\n                                                                                                 ‫‪104‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1432/11/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 35‬وفيهــا حضــر املتداعيــان ويف هــذه‬\n      ‫اجللســة جــرى ســؤال املدعــى عليــه وكالــة عمــا طلــب فيــه اإلمهــال‬\n      ‫فقــدم مذكــرة هــذا نصهــا إشــارة إلــي طلــب فضيلتكــم باجللســة‬\n      ‫الســابقة حتديــد أعمــال اإلصالحــات التــي قــام بهــا موكلنــا املدعــى‬\n      ‫عليــه ‪ ................. /‬بعقــار املدعيــة ‪ .................. /‬ويطلــب إلــزام املدعيــة‬\n      ‫بتكاليــف تلــك األعمــال فقــد أفادنــي موكلــي أن تلــك األعمــال هــي‬\n      ‫كاآلتــي ‪ :‬إصالحــات احلمــام اخلــاص بالقســم الصغيــر بتكلفــة ‪350‬‬\n      ‫ريــال وفتــح بــاب خارجــي مــع شــراء البــاب وتركيبــه بتكلفــة ‪500‬‬\n      ‫ريــال وبــاب قاطــع للقســم اخلــاص بالنســاء ‪ 220‬ريــال وبــاب عــازل‬\n      ‫لغــرف النــوم ‪ 220‬ريــال وأجــرة تركيــب األبــواب املشــار إليهــا وإصــاح‬\n      ‫تلفيــات األبــواب القدميــة بتكلفــة ‪ 400‬ريــال وتركيــب مجلــى إيطالــي‬\n      ‫‪ 370‬ريــال وتعتيــق الســيب املوصــل بــن قســم الرجــال والنســاء ســعر‬\n      ‫املتــر ‪ 10‬ريــال الكميــة وتعتيــق مقلــط الرجــال مــع بويــة الســقف ســعر‬\n      ‫املتــر ‪ 10‬ريــال بتكلفــة إجماليــة وشــراء ســيراميك ســعر املتــر ‪ 14‬ريــال‬\n      ‫إجمالــي وتركيــب الســيراميك ســعر تركيــب املتــر ‪ 10‬ريــال إجمالــي‬\n      ‫وعــدد متــر نعلــه ســعر املتــر ‪ 5‬ريــال ‪ +‬تركيــب ‪ 2‬ريــال للمتــر ليكــون‬\n      ‫إجمالــي مــا تكلفــه موكلــي ويطلــب إلــزام املدعيــة بــه مــا تقــرره اللجنــة‬\n      ‫املختصــة إضافــة إلــى ذلــك تقديــر أجــرة الســيارة تقديــر أجــرة ملوكلــي‬\n      ‫عــن قيامــه بتلــك األعمــال و وقوفــه مــع العمــال وإحضــار األغــراض علمـ ًا‬\n      ‫أن جميــع تلــك اإلصالحــات متــت مبعرفــة املدعيــة يثبــت ذلــك العقــد‬\n      ‫املوقــع مــن الطرفــن نطلــب مــن فضيلتكــم إحالتهــا إلــي هيئــة اخلبــراء‬\n      ‫لتقديــر اإلصالحــات ا‪.‬ه ـ وبعرضهــا علــى املدعــي وكالــة قــال مــا‬\n\n\n‫‪105‬‬\n\f‫ذكــره املدعــى عليــه مــن إصــاح احلمــام وتلفيــات األبــواب القدميــة فأنــا‬\n‫مــن قــام بذلــك وأمــا بخصــوص فتــح البــاب اخلارجــي وبــاب قاطــع لقســم‬\n‫النســاء وبــاب عــازل لغــرف النــوم وأجــرة تركيبهــا واملجلــى فجميعهــا‬\n‫لــم نــأذن لــه فيهــا وأمــا بخصــوص التعتيــق والســيراميك فقــد اســتعد‬\n‫هــو بذلــك عنــد اســتئجاره للــدور وقــد أنقــص يف أجــرة الــدور مقابــل‬\n‫ذلــك هكــذا ذكــر وبعرضــه علــى املدعــى عليــه وكالــة قــال الصحيــح‬\n‫مــا ذكرتــه ولــدي البينــة عليــه وســوف أحضرهــا يف اجللســة القادمــة‬\n‫وبســؤال املدعــي هــل لديــه بينــة علــى دفعــه قــال نعــم وســوف أحضرهــا‬\n‫يف اجللســة القادمــة وعليــه رفعــت اجللســة وحــدد لهــا موعــد يــوم االربعــاء‬\n‫‪1432/1/19‬ه ـ وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/11/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء  املوافــق ‪ 1433/01/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪  08 : 40‬وفيهــا حضــر املتداعيــان وفيهــا‬\n‫أحضــر املدعــي وكالــة شــاهدا هــو ‪ .................‬ســجل رقــم ‪..................‬‬\n‫واملولــود يف ‪1383‬ه ـ ويســكن الريــاض وال يوجــد صلــة قرابــة والــذي‬\n‫شــهد بقولــه إننــي صاحــب املكتــب العقــاري الــذي مت اســتئجار الــدور‬\n‫عــن طريقــه وقــد حصــل االتفــاق بينهــم عنــد االســتئجار بأن يتــم تخفيض‬\n‫مقــدار األجــرة إلــى واحــد وعشــرين ألــف ريــال ســنويا ملــدة ثــاث ســنوات‬\n‫مقابــل قيــام املســتأجر بأعمــال الســيراميك والتعتيــق ويكــون للمؤجــر‬\n‫حــق فســخ العقــد عنــد تأخــر املســتأجر يف دفــع األجــرة هكــذا شــهد‬\n‫وبســؤال املدعــي هــل لديــه زيــادة بينــة قــال ال يوجــد لــدي بينــة هكــذا‬\n‫ذكــر فجــرى عــرض الشــاهد علــى املدعــى عليــه وكالــة فقــال ال أقــول‬\n‫فيــه شــيئا فطلبــت مــن املدعــي تزكيــة شــاهدة فاســتعد بذلــك ورفعــت‬\n\n\n                                                                                        ‫‪106‬‬\n\f      ‫اجللســة وحــدد لهــا موعــد يف يــوم األربعــاء ‪1433/3/9‬ه ـ الســاعة ‪09.15‬‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف  ‪ 1433/01/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪ 1433/03/09‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪  09 : 50‬وفيهــا حضــر املتداعيــان وأحضــر‬\n      ‫املدعــي وكالــة تزكيــة لشــاهده وهمــا ‪ ...................‬مصــري اجلنســية‬\n      ‫يحمــل إقامــة رقــم …………… و ‪ ...............‬مصــري اجلنســية يحمــل‬\n      ‫إقامــة رقــم ‪ .................‬وقــد شــهدا بعدالــة الشــاهد وبســؤال املتداعيــن‬\n      ‫هــل لديهمــا مــا يرغبــان يف إضافتــه قــال املدعــى عليــه وكالــة ال وقــال‬\n      ‫املدعــي وكالــة نعــم أرغــب إفهــام املدعــى عليــه وكالــة بــأن موكلتــي ال‬\n      ‫ترغــب يف جتديــد العقــد الــذي ينتهــي يف ‪ 1433/05/30‬ه ـ مــع مطالبتنا‬\n      ‫باإلخــاء قبــل هــذه املــدة فجــرى إفهــام املدعــى عليــه وكالــة بذلــك‬\n      ‫إلبــاغ موكلــه بــه عنــد ذلــك جــرى إفهــام املتداعيــن بأنــه قــد مت إقفــال‬\n      ‫بــاب املرافعــة ورفعــت اجللســة لذلــك وحــدد لهــا موعــد يــوم األربعــاء‬\n      ‫املوافــق ‪1433/3/30‬ه ـ الســاعة ‪ 09.15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/03/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم  األربعــاء املوافــق ‪ 1433/03/30‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪  09 : 17‬وفيهــا حضــر املتداعيــان وكالــة‬\n      ‫ويف هــذه اجللســة جــرى ســؤال املدعــى عليــه وكالــة هــل لــدى موكلــه‬\n      ‫بينــة علــى أن اإلصالحــات كانــت بــإذن مــن املدعيــة فقــال ال يوجــد‬\n      ‫بينــة ســوى التذييــل الــذي علــى عقــد اإليجــار والــذي ســبق أن ذكــره‬\n      ‫املدعــي وكالــة عنــد ذلــك أفهمتــه أن ملوكلــه ميــن املدعيــة وباالطــاع‬\n      ‫علــى وكالتــه وجدتهــا ال تخولــه اجلــواب عــن ذلــك فأفهمتــه بأنــه البــد‬\n\n\n‫‪107‬‬\n\f‫مــن إضافــة طلــب اليمــن و ردهــا يف الوكالــة أو حضــور موكلــه وعليــه‬\n‫رفعــت اجللســة وحــدد لهــا موعــد يــوم األربعــاء املوافــق ‪ 1433/06/04‬ه ـ‬\n‫الســاعة ‪ 09.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1433/03/30‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ...................‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض خلــف الشــيخ ‪ ..................‬وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪17043‬‬\n‫وتاريــخ ‪ 1431/04/05‬هــ  املقيــدة باحملكمــة برقــم ‪ 3156358‬وتاريــخ‬\n‫‪ 1431/04/01‬هــ  ففــي يــوم  األربعــاء املوافق‪ 1433/06/04‬هـ افتتحت‬\n‫اجللســة الســاعة ‪  09 : 44‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وكالــة ‪ ....................‬املذكوريــن أعــاه وبســؤال املدعــى عليــه وكالــة‬\n‫عمــا طلــب منــه يف اجللســة املاضيــة قــال إن موكلــي غيــر موجــود يف‬\n‫الريــاض وهــو مجــاز مــن عملــه وقــد أخبرنــي بأنــه يطلــب منكــم احلكــم‬\n‫يف القضيــة أو حتديــد جلســة أخــرى ليحضــر فيهــا ويقــرر مــا لديــه وقــد‬\n‫أبــرز املدعــي وكالــة نســخة كربونيــة لعقــد إيجــار صــادر مــن مكتــب‬\n‫‪ ...‬للعقــارات برقــم ‪ 144‬يف ‪1430/6/1‬ه ـ اســتئجار املدعــى عليــه أصالــة‬\n‫دور علوي عوائل يقع يف حي ‪ ............‬الغربي بأجرة سنوية قدرها واحد‬\n‫وعشــرون ألــف ريــال ملــدة ثــاث ســنوات طريقــة الدفــع دفعــة كل ســتة‬\n‫أشــهر وقدرهــا عشــرة آالف وخمســمائة ريــال ثــم ذكــرت شــروط العقــد‬\n‫و جــاء يف فقــرة املالحظــة مــا نصــه يحــق للمالــك فســخ العقــد وخــروج‬\n‫املســتأجر يف حالــة التأخيــر عــن تســديد اإليجــار أو إزعــاج اجليــران ويف‬\n‫اجلانــب األميــن مــن العقــد كتــب مــا نصــه مت تنزيــل اإليجــار مببلــغ قــدره‬\n‫واحــد وعشــرون ألــف ريــال ســنوي مقابــل تركيــب الســيراميك للــدور‬\n\n\n                                                                                         ‫‪108‬‬\n\f        ‫العلــوي ويف اجلانــب األيســر منــه عبــارة نصها ســباكة احلمامات واملطبخ‬\n        ‫والكهربــاء علــى املالــك كذلــك جــاء يف الفقــرة العاشــرة مــن الشــروط‬\n        ‫يف حالــة تأخــر املســتأجر عــن دفــع الدفعــة املســتحقة يحــق للمالــك فســخ‬\n        ‫العقــد وخروجــه عــن طريــق اجلهــات املختصــة ثــم يف أســفل العقــد توقيــع‬\n        ‫منســوب للطــرف األول ‪ ..............‬والطــرف الثانــي ‪ ................‬عنــه ابنــه‬\n        ‫‪ ..............‬وختــم املكتــب‪ .‬وبعــرض هــذا العقــد علــى املدعى عليه وكالة‬\n        ‫قــال هــذا هــو العقــد بــن موكلــي واملدعــي أصالــة وقــال املدعــي وكالــة‬\n        ‫إن املدعــى عليــه أصالــة لــم يســدد اإليجــار مــن ‪1431/12/1‬ه ـ حتــى‬\n        ‫اآلن وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال نعــم إن موكلــي لــم‬\n      ‫يدفــع األجــرة مــن ‪1431/12/1‬ه ـ علمــا أن موكلــي الزال يشــغل العقــار  ‬\n        ‫وعقــد اإليجــار كان ســاريا فبنــاءا علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n        ‫ومبــا أن عقــد اإليجــار املشــار إليــه أعــاه نــص علــى فســخ العقــد يف حالــة‬\n        ‫التأخــر يف تســديد األجــرة و أذى اجليــران ومبــا أن املدعــى عليــه وكالــة‬\n        ‫أقــر بعــدم دفــع موكلــه األجــرة مــن تاريــخ ‪1431/12/1‬ه ـ وهــو مخــول‬\n        ‫باإلقــرار يف الوكالــة ومبــا أن املدعــى عليــه وكالــة يشــغل العقــار‬\n        ‫حتــى اآلن وذكــر املدعــى عليــه أن عقــد اإليجــار ســا ٍر ومبــا أن املدعــى‬\n        ‫عليــه طالــب بخصــم اإلصالحــات مــن قيمــة األجــرة ومبــا أنــه ذكــر يف‬\n        ‫العقــد أنــه جــرى تخفيــض األجــرة مقابــل تركيــب الســيراميك ومبــا أن‬\n        ‫املدعــي وكالــة أنكــر موافقــة موكلتــه علــى قيــام املدعــى عليــه أصالــة‬\n        ‫باإلصالحــات ومبــا أن املدعــى عليــه لــم يحضــر بينــة ولــم يخــول وكيلــه‬\n        ‫طلــب اليمــن ولــم يحضــر ليقرر هل يطلب اليمني أم ال وملصادقة املدعى‬\n        ‫عليــه علــى عقــد اإليجــار لــذا فقــد ألزمــت املدعــى عليــه أصالــة بإخــاء‬\n        ‫العقــار املســتأجر وتســليمه للمدعيــة أصالــة عــن طريــق احلقــوق املدنيــة‬\n\n\n‫‪109‬‬\n\f‫وصرفــت النظــر عــن طلبــه خصــم اإلصالحــات التــي ذكرهــا مــن قيمــة‬\n‫اإليجــار وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب‬\n‫االســتئناف بالئحــة اعتراضيــة فجــرى إفهامــه مبراجعــة احملكمــة يــوم‬\n‫األحــد ‪1433/6/8‬ه ـ الســتالم نســخة مــن احلكــم وتقــدمي اعتراضــه‬\n‫عليــه خــال ثالثــن يومــا مــن تاريــخ اســتالمها وأنــه إذا انتهــت املــدة ولــم‬\n‫يقــدم اعتراضــه خاللهــا  ســقط حقــه يف االســتئناف واكتســب احلكــم‬\n‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1433/06/04‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/3/25‬ه ـ‬\n‫فتحــت اجللســة وفيهــا حضــر املدعــي وكالــة وقــد وردت املعاملــة‬\n‫مــن محكمــة االســتئناف مرفقــا بهــا القــرار رقــم ‪ 3430181‬يف‬\n‫‪1434/2/5‬ه ـ املــدون علــى ظهــر الصــك املتضمــن أنــه لــم يظهــر مــا‬\n‫يوجــب االعتــراض علــى احلكــم مــع تنبيــه فضيلتــه بإفهــام املدعــي بــأن‬\n‫لــه حــق املطالبــة فيمــا ورد يف الئحتــه االعتراضيــة زائــدا علــى اإلخــاء‬\n‫واهلل املوفــق وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/03/25‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n‫‪ 3156358‬وتاريــخ ‪1433/12/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــه القاضــي باحملكمــة الشــيخ‪ ...................../‬املســجل برقــم‬\n‫‪ 33286548‬وتاريــخ ‪1433/6/8‬ه ـ اخلــاص بدعــوى‪.................../‬‬\n‫وكالــة ضــد‪ ............../‬بشــأن خــاف يف عقــار علــى الصفــة املوضحــة‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫بالصــك واملتضمــن حكــم فضيلتــه كمــا هــو موضــح يف الصــك‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫لــم يظهــر مايوجــب االعتــراض علــى احلكــم مــع تنبيــه فضيلتــه بــا فهــام‬\n      ‫املدعــي بــأن لــه حــق املطالبــة فيمــا ورد يف الئحتــه االعتراضيــة زائــدا‬\n      ‫علــى اإلخــاء‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                              ‫وســلم‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":100,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d1e473a5d29df886f526a9e657266945139ea38d5cd4023dab89dc00427aae20","normalized_text_hash":"6a689ece6153479841b1e61168027cec89a79cfb14c8d14bbfa1996a69d01422","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p100-33286548"},{"id":"609cf8b1-4a23-5881-8e50-9d8bfb4099b4","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -صيانة -استئجار املدعي عدة شاليهات من الشركة املدعى عليها ملدة معينة -االتفاق على قيام الشركة بأعمال الصيانة للشاليهات ودفع املدعي مقابل الصيانة -مطالبة الشركة بفسخ العقد قبل نهاية املدة -موافقة املدعي على الفسخ واإلخاء مقابل رد املبالغ التي أنفقها والتعويض عن األرباح املتوقعة باقي مدة العقد -دفع املدعي بوجود مخالصة ببراءة ذمته جتاه الشركة املدعى عليها -قيام القرينة على إقرار املدعي باملخالصة -صرف","document_number":"3416698","case_number":"3311858","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/19","year":"1434","subject":"إجارة -صيانة -استئجار املدعي عدة شاليهات من الشركة املدعى عليها ملدة معينة -االتفاق على قيام الشركة بأعمال الصيانة للشاليهات ودفع املدعي مقابل الصيانة -مطالبة الشركة بفسخ العقد قبل نهاية املدة -موافقة املدعي على الفسخ واإلخاء مقابل رد املبالغ التي أنفقها والتعويض عن األرباح املتوقعة باقي مدة العقد -دفع املدعي بوجود مخالصة ببراءة ذمته جتاه الشركة املدعى عليها -قيام القرينة على إقرار املدعي باملخالصة -صرف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/19 :‬هـ   ‬\n                         ‫ُ‬               ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3416698:‬‬\n                           ‫َر ْق ُم الدعوى‪3311858 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‬\n                 ‫‪  34324644:‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬صيانــة‪ -‬اســتئجار املدعــي عــدة شــاليهات مــن الشــركة املدعــى‬\n      ‫عليهــا ملــدة معينــة‪ -‬االتفــاق علــى قيــام الشــركة بأعمــال الصيانــة‬\n      ‫للشــاليهات ودفــع املدعــي مقابــل الصيانــة‪ -‬مطالبــة الشــركة بفســخ‬\n      ‫العقــد قبــل نهايــة املــدة‪ -‬موافقــة املدعــي علــى الفســخ واإلخــاء مقابــل‬\n      ‫رد املبالــغ التــي أنفقهــا والتعويــض عــن األربــاح املتوقعــة باقــي مــدة‬\n      ‫العقــد‪ -‬دفــع املدعــي بوجــود مخالصــة ببــراءة ذمتــه جتــاه الشــركة‬\n      ‫املدعــى عليهــا‪ -‬قيــام القرينــة علــى إقــرار املدعــي باملخالصــة‪ -‬صــرف‬\n                                                     ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول ابــن رجــب احلنبلــي رحمــه اهلل يف جامــع العلــوم واحلكــم ص‬\n      ‫‪»:316‬وقــد كان شــريح وإيــاس بــن معاويــة يحكمــان يف األمــوال املتنــازع‬\n      ‫فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعيــن ‪ ..‬وكان‬\n      ‫يقضــي بنحــو ذلــك أبوبكــر الشــامي مــن الشــافعية ورجــح قولــه ابــن‬\n                                                                   ‫عقيــل مــن أصحابنــا»‪.‬‬\n      ‫‪ -2‬املــادة (‪ )155‬مــن نظــام املرافعــات الشــرعية ونصها‪»:‬يجــوز للقاضــي‬\n      ‫أن يســتنتج قرينــة‪ ،‬أوأكثــر مــن وقائــع الدعــوى‪ ،‬أو ُمناقشــة اخلصــوم‬\n      ‫ا ناقص ـ ًا ثبــت‬‫ليكمِ ــل ِبهــا دلي ـ ً‬\n                                             ‫حلكمِ ــه أو ُ‬\n                                                         ‫أو الشــهود؛ لتكــون ُمســتند ًا ُ‬\n              ‫احلكــم»‪.‬‬\n                     ‫لديــه ليك ـ ِّون بهمــا مع ـ ًا اقتناعــه بثبــوت احلــق إلصــدار ُ‬\n\n‫‪125‬‬\n\f‫أقــام املدعــي دعــواه ضــد الشــركة املدعــى عليهــا بأنــه اســتأجر منهــا‬\n‫عــدة شــاليهات ملــدة عشــر ســنوات علــى مبلــغ معلــوم لديهمــا‪ ،‬كمــا‬\n‫اتفقــا علــى قيــام الشــركة بعمــل صيانــة لهــذه الشــاليهات مقابــل دفــع‬\n‫املدعــي مبلــغ معــن إال أن الشــركة لــم تقــم بالعمــل املطلــوب كمــا‬\n‫أنهــا وقبــل نهايــة الســنة األولــى مبــا لهــا مــن حــق خيــار الفســخ املثبــت‬\n‫بأحــد بنــود العقــد طلبــت فســخ العقــد‪ ،‬وافــق املدعــي علــى الفســخ‬\n‫وإخــاء الشــاليهات شــريطة إعــادة املبالــغ التــي أنفقهــا (أجــرة وصيانــة‬\n‫وجتهيــزات إضافيــة) والتعويــض عــن األربــاح املتوقعــة باقــي مــدة العقــد‪،‬‬\n‫اتفــق الطرفــان ودي ـ ًا علــى فســخ العقــد واإلخــاء‪ ،‬قامــت الشــركة‬\n‫مبطالبــة املدعــي بســداد مبلــغ ‪ .....‬قيمــة تكاليــف الكهربــاء واملــاء‬\n‫واملفقــودات‪ ،‬أنكــر املدعــي مديونيتــه للشــركة بهــذه املبالــغ عــدا مبلــغ‬\n‫خمســن ألــف ريــال فقــط وقــدم لذلــك «مخالصــة نهائيــة» مطبوعــة علــى‬\n                                ‫ورق الشــركة املدعــى عليهــا تؤكــد قولــه ‪.‬‬\n‫ـاء علــى مــا تقــدم وملــا كان االتفــاق كل ال يتجــزأ‪ ،‬ويف حالــة‬         ‫وبنـ ً‬\n‫عــدم اهتــداء القاضــي للدليــل اليقينــي للحكــم يف الدعــوى يجــوز لــه‬\n‫اســتنتاج قرينــة أو أكثــر مــن وقائــع الدعــوى أو مناقشــة اخلصــوم أو‬\n‫الشــهود لتكــون مســتند ًا حلكمــه أو تكملــة لدليــل ناقــص ثبــت لديــه‬\n‫ليكــون بهمــا معـ ًا اقتناعــه بثبــوت احلــق‪ ،‬كمــا أنــه يحكــم يف األمــوال‬\n‫املتنــازع فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعــن‪،‬‬\n‫وبإعمــال ذلــك علــى الدعــوى املاثلــة ومبــا أنــه لــم يثبــت لــدى احملكمــة‬\n‫أن يف ذمــة الشــركة املدعــى عليهــا حــق مالــي لــذا صرفــت النظــر عــن‬\n\n                                                                                       ‫‪126‬‬\n\f      ‫مطالبــة املدعــي لعــدم اســتحقاقه‪ ،‬وإلــزام املدعــي بســداد مبلــغ خمســن‬\n      ‫ألــف ريــال للشــركة لثبوتهــا لديــه ‪ -‬قــرر املدعــي عــدم القناعــة فأفهــم‬\n                     ‫بالتعليمــات‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ......................‬القاضــي باحملكمــة‬\n      ‫العامــة بالدمــام بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس‬\n      ‫برقــم ‪ 9514‬يف ‪1420/10/22‬ه ـ حضــر ‪ .................‬احلامــل للبطاقــة‬\n      ‫رقــم ‪ ................‬رقــم احلفيظــة ‪ ........‬يف ‪ ......‬الصــادرة مــن ‪ .....‬وحضــر‬\n      ‫حلضــوره ‪ .......................‬احلامــل للبطاقــة رقــم ‪ .................‬رقــم احلفيظــة‬\n      ‫‪ ........‬يف   ‪1403/4/1‬ه ـ الصــادرة مــن الريــاض بالوكالــة عــن‬\n      ‫‪ ........................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‪ .......‬برقــم‬\n      ‫‪ .....‬يف ‪ ......‬اجللد ‪ ......‬وبالوكالة عن ‪ ...............‬و‪ .......................‬مبوجب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل ‪  ......‬برقــم ‪ .....‬يف ‪ .....‬اجللــد ‪.....‬‬\n      ‫وبالوكالــة عــن ‪......................‬و‪ ..................‬و ‪ ....................‬بالوكالــة‬\n      ‫عــن ‪.......................‬و‪ .....................‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل ‪ .....‬برقــم ‪ .....‬يف ‪ .......‬اجللــد ‪ ...‬املخولــة لــه يف املرافعــة‬\n      ‫واملدافعــة واالعتــراض كمــا حضــر ‪ ....................‬احلامــل للبطاقــة رقــم‬\n      ‫……………‪ ..‬رقــم احلفيظــة ‪ 120040‬الصــادرة مــن الريــاض يف‬\n      ‫‪1395/6/19‬ه ـ ومــوكل املدعــى عليــه واحلاضــر ‪......................‬‬\n      ‫واملذكــورون هــم أعضــاء إدارة مجلــس ‪ .............................‬مبوجــب‬\n      ‫محضــر جمعيــة الشــركاء الســابعة عشــر وقــد جــاء يف املــادة ‪ 1/14‬ميثــل‬\n      ‫مجلــس إدارة الشــركة يف عالقاتهــا لــدى الدوائــر احلكوميــة‬\n‫‪127‬‬\n\f‫والشــركات واألفــراد يف املرافعــة واملدافعــة واملخاصمــة واملراجعــة‬\n‫واالعتــراض ‪ ...‬الــخ‪ ،‬وادعــى األول قائــا‪ :‬بأننــي اســتأجرت مــن‬\n‫الشــركة املذكــورة ‪ 60‬وحــدة شــاليه املســماة بشــاليهات ‪.................‬‬\n‫ملــدة عشــر ســنوات بأجــرة ســنوية قدرهــا مليــون ريــال اعتبــارا مــن‬\n‫‪1418/5/30‬ه ـ املوافــق ‪1997/10/1‬م وبعــد اســتئجاري بــدأت‬\n‫الشــركة مبضايقتــي واختــاق األعــذار والزعــم أني مقصــر يف الصيانة‬\n‫وقــد اتفقــت معهــم علــى أن يقومــوا بالصيانــة مقابــل مبلــغ ألفــن ريــال يف‬\n‫الشــهر إال أنهــم لــم يقومــوا بالصيانــة وقصــروا معــي وقبــل نهايــة الســنة‬\n‫األولــى طلبــوا منــي اإلخــاء حيــث طلبــوا منــي ذلــك بشــهرين وبنــاء علــى‬\n‫ذلــك قــد أخليــت الشــاليهات وســلمتها لهــم‪ ،‬وبنــاء علــى ذلــك فإننــي‬\n‫أطالبهــم بإعــادة اإليجــار للســنة األولــى وقــدره مليــون ريــال‪ ،‬وإعــادة‬\n‫قيمــة الصيانــة وقدرهــا اثنــان وعشــرون ألــف وســبعمائة وأربعــة وســبعون‬\n‫ريــال‪ ،‬ثالثــا مطالبتهــم مببلــغ وقــدره تســعة وتســعون ألــف وثمامنائــة‬\n‫وخمســة عشــر ريــال وتفصيلهــا كمــا يلــي‪ :‬ســتة عشــر ألــف وثالثمائــة‬\n‫وتســعة وتســعون ريــال قيمــة جتهيــزات إضافيــة‪ ،‬وثالثــة عشــر ألــف‬\n‫وســبعة وعشــرون ريــال قيمــة دعايــة وإعــان‪ ،‬واثنــا عشــر ألــف نســبة‬\n‫تكلفــة الهواتــف‪ ،‬وأربعــة وأربعــون ألــف وخمســمائة ريــال إيجــار‬\n‫الشــاليه رقــم ‪ ،6‬وثمامنائــة وتســعة وثمانــون ريــال أربــاح التأمــن التعاونــي‬\n‫لعــام ‪97‬و ‪ ،98‬وألــف وســبعمائة ريــال إصــاح الزجــاج‪ ،‬وإحــدى عشــر‬\n‫ألــف وثالثمائــة ريــال إصــاح معــدات البركــة‪ ،‬وكذلــك تعويضــي عــن‬\n‫األربــاح املتوقعــة عــن تســع ســنوات الباقيــة مــن العقــد هــذه دعــواي‪،‬‬\n‫أطلــب احلكــم عليهــم بذلــك‪ ،‬وباســتجواب املدعــى عليــه أجــاب قائــا‪:‬‬\n‫إن الشــركة قامــت بإنشــاء شــاليهات ذات مســتوى جيــد‪ ،‬ونظــرا لعــدم‬\n\n\n                                                                                      ‫‪128‬‬\n\f      ‫تخصص الشــركة يف اإليواء فقد رأت تأجير الشــاليهات على شــخص‬\n      ‫متخصــص‪ ،‬وقــد تقــدم املدعــي بطلــب االســتئجار ومت االتفــاق معــه علــى‬\n      ‫تأجيــره الشــاليهات عشــر ســنوات بأجــرة قدرهــا مليــون ريــال للســنة‬\n      ‫مبوجــب العقــد املــؤرخ يف ‪1418/3/28‬ه املوافــق ‪1997/8/1‬م ويشــتمل‬\n      ‫علــى ‪ 31‬بنــد‪ ،‬وقــد جــاء يف البنــد الثالــث أنــه يلتــزم الطــرف الثانــي‬\n      ‫باحملافظــة علــى الشــاليهات‪ ،‬واملــادة الثامنــة بســداد قيمــة فواتيــر‬\n      ‫الهاتــف والكهربــاء وامليــاه‪ ،‬واملــادة العاشــرة أن تكــون الصيانــة علــى‬\n      ‫عاتــق املســتثمر بنفــس مســتوى اإلنشــاءات مــع االلتــزام بجــدول الصيانــة‬\n      ‫الوقائيــة املرفــق بالعقــد‪ ،‬وجــاء يف املــادة الثالثــة والعشــرين أنــه يحــق‬\n      ‫للطــرف األول فســخ العقــد يف إحــدى احلــاالت ومنهــا عــدم القيــام‬\n      ‫بالصيانــة علــى الوجــه املطلــوب بعــد إشــعاره مرتــن متتاليتــن الــخ‪،‬‬\n      ‫ونظــرا لعــدم قيــام املدعــي بالصيانــة علــى الدرجــة املطلوبــة وكــون‬\n      ‫العمالــة التــي تديــر املشــروع ال يتجــاوز عددهــم أصابــع اليــد الواحــدة ومت‬\n      ‫االجتمــاع معــه عــدة مــرات ومت االتفــاق علــى إنهــاء العقــد وديــا ومت‬\n      ‫اإلخــاء مــن املدعــي‪ ،‬وأمــا الصيانــة التــي ذكــر فهــي صيانــة للحدائــق‬\n      ‫فقــط دون املبانــي ومــا يتبعهــا‪ ،‬ومــا ذكــره مــن مطالبتــه بقيمــة‬\n      ‫جتهيــزات‪ ،‬فــا أعلــم مــا هــي التجهيــزات‪ ،‬وأمــا بالنســبة للدعايــة‬\n      ‫واإلعــان فهــو مســئول عنهــا حســب العقــد‪ ،‬وأمــا بالنســبة للهواتــف فــإن‬\n      ‫العقــد قــد نــص علــى تأمــن ثــاث هواتــف جــوال اســتقبال فقــط ومت‬\n      ‫تأمينهــا‪ ،‬وأمــا بالنســبة إليجــار الشــاليه رقــم ‪ 6‬فهــو مؤجــر قبــل أن‬\n      ‫يســتأجر املدعــي ملــدة ســنة وقــد نصــت املــادة ‪ 14‬مــن العقــد بــأن علــى‬\n      ‫الطــرف الثانــي قبــول العقــود املوقعــة مــع املســتأجرين قبــل بدايــة هــذا‬\n      ‫العقــد‪ ،‬وأربــاح التأمــن لــم تســتلم منهــا شــيء‪ ،‬وأمــا إصــاح الزجــاج‬\n\n\n‫‪129‬‬\n\f‫وإصــاح معــدات البركــة فهــو املســئول عنهــا حســب بنــد الصيانــة‪،‬‬\n‫كمــا أضــاف املدعــى عليــه‪ :‬إذا كان املدعــي لديــه القــدرة علــى تشــغيل‬\n‫الشــاليهات فــا مانــع لدينــا مــن تســليمها لــه مبوجــب شــروط العقــد‬\n‫ونخفــض لــه مــن األجــرة مئــة ألــف ريــال‪ ،‬وبعــرض مــا ذكــره املدعــى‬\n‫عليــه علــى املدعــي مــن أنــه مت اإلخــاء مبوجــب اتفــاق أجــاب قائــا‪ :‬بأنــه‬\n‫قــد ورد لـ ّـي خطــاب مــن املدعــى عليــه بطلــب اإلخــاء حســب املــاده ‪23‬‬\n‫مــن بنــد العقــد وقــد قمــت باإلخالء بنــاء على طلبهم املشــروع‪ ،‬والهواتف‬\n‫مت التفاهــم مــع رئيــس مجلــس اإلدارة واملديــر الســابق ‪ ...‬علــى أنــه مت‬\n‫تامــن هواتــف ّأيــن كانــت وعليهــم حتمــل ‪% 75‬مــن التكلفــة‪ ،‬وأمــا‬\n‫الشــاليه رقــم ‪ 6‬فقــد مت تســليمي كشــف حســاب يفيــد بــأن لــي بذمتهــم‬\n‫مبلــغ أربعــه وأربعــون ألــف وخمســمائة ريــال قيمــه الشــالية‪ ،‬وأربــاح‬\n‫التأمــن اســتلموا مــا يخــص عــام ‪97‬م‪ ،‬وإصــاح الزجــاج والبركــة هــم‬\n‫املســؤولني عنهــا؛ ألنهــا مــن الصيانــة‪ ،‬وأمــا مــا ذكــر ه مــن العــرض علـ ّـي‬\n‫بالعــودة للمشــروع مببلــغ تســعمائة ألــف ريــال فــا أرغــب بذلــك بســبب‬\n‫معاملتهــم لــي ولتقــادم املــدة حيــث ذهــب وعمالــي‪ ،‬وطلبــت مــن الطرفــن‬\n‫البينــة منهمــا بــكل مــا يدعيــاه‪ ،‬فاســتعدا بذلــك‪ ،‬ويف جلســة أخــرى‬\n‫حضــر الطرفــان وبطلــب البينــة منهمــا أبــرز املدعــى عليــه عقــد صيانــة‬\n‫مشــروع شــاليهات الترفيــة واملــؤرخ يف ‪1418/6/19‬ه ـ املوافــق‬\n‫‪1997/10/20‬م املتضمــن إتفــاق الشــركة ‪ ................‬ثانيا‪/‬الســيد‬\n‫‪ ..................‬ويشــار إليــه الطــرف الثانــي قــد جــاء يف العقــد الفقــرة الثانية‬\n‫مــا نصــه‪( :‬يقــوم الطــرف األول بتقــدمي خدمــات الصيانــة بواســطة فريــق‬\n‫الصيانــة اخلــاص بــه حــن احلاجــة مقابــل مبلــغ شــهري قــدرة ألفــان ريــال‬\n‫بــدون قطــع الغيــار التــي يتحملهــا الطــرف الثانــي ويقــوم بتوريدهــا حــال‬\n\n\n                                                                                            ‫‪130‬‬\n\f      ‫طلبهــا مــن الطــرف األول لتــايف أي أضــرار تلحــق بالعمــل أو املشــروع أو‬\n      ‫يقــوم الطــرف األول بتوفيرهــا وتقــدمي الفواتيــر للطــرف الثانــي للدفــع)‬\n      ‫أ‪.‬هــ‪ ،‬وبعــرض العقــد علــى املدعــي أجــاب قائــا‪ :‬إن هــذا العقــد صحيــح‬\n      ‫وهــو عقــد صيانــة لكامــل املشــروع وليــس مخصــص للزراعــة‪ ،‬كمــا‬\n      ‫ذكــر املدعــى عليــه وســمع ذلــك املدعــى عليــه وقــال‪ :‬نعــم إن الصيانــة‬\n      ‫هــي ملشــروع شــاليهات الترفيــة كاملــة‪ ،‬وبطلــب البينــة مــن املدعــي علــى‬\n      ‫الهواتــف أبــرز وثيقــة معنونــة لشــركة ‪ .................‬وهــذا نصهــا‪( :‬محضر‬\n      ‫اجتمــاع يف يــوم األربعــاء ‪1997/9/3‬م ومبكاتــب الشــركة اجتمــع‬\n      ‫كل مــن رئيــس مجلــس إدارة الشــركة ‪ ..........‬وبحضــور مديــر عــام‬\n      ‫الشــركة واألســتاذ ‪ ...........‬مســتثمر شــاليهات الترفيــه وذلــك حــول‬\n      ‫اســتالم املســتثمر للشــاليهات وقــد مت االتفــاق علــى مــا يلــي‪ )1 :‬يبــدأ‬\n      ‫ســريان عقــد االســتثمار يــوم ‪1997/10/1‬م‪ )2 .‬تتكفــل الشــركة‬\n      ‫‪ ...................‬مبــا قيمتــه ‪ % 75‬مــن تكلفــة تأســيس هاتــف مشــروع‬\n      ‫شــاليهات الترفيــه ‪ % 25‬يتحملهــا املســتثمر ‪ .............‬علــى أن يــؤول جميع‬\n      ‫ذلــك فيمــا بعــد إلــى الشــركة ‪ )3 ..................‬متــت مناقشــة جميــع‬\n      ‫مالحظــات املســتثمر الــواردة يف خطابــه بتاريــخ ‪1997/8/31‬م ومت‬\n      ‫االتفــاق علــى املعاجلــة اخلاصــة بهــا‪ .‬الشــركة ‪ .................. ..........‬املديــر‬\n      ‫العــام التوقيــع املســتثمر ‪ ..................‬التوقيــع كذلــك ختــم الشــركة‬\n      ‫‪ ................‬حتــت توقيــع املديــر العــام لشــركة ‪ ).............‬وبعرضهــا علــى‬\n      ‫املدعــى عليــه أجــاب قائــا‪ :‬هــذا االتفــاق صحيــح ولكــن املقصــود فيــه‬\n      ‫هــو إيصــال الهاتــف عــن طريــق شــركة ‪ .....‬حتــى اآلن لــم يصــل املنطقة‪،‬‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وجــرى عــرض مــا أجــاب بــه املدعــى‬\n      ‫عليــه علــى املدعــي مــن أن املقصــود بالهاتــف هــو إيصــال الهاتــف عــن‬\n\n\n‫‪131‬‬\n\f‫طريــق شــركة ‪ .......‬فأجــاب املدعــي قائــا‪ :‬إن االتفــاق إيصــال الهاتــف‬\n‫أي كان نوعــه ولــم يحــدد‪ ،‬وجــرى ســؤاله ألديــه البينــة علــى مــا ذكــر‬\n‫فأجــاب قائــا‪ :‬بينتــي هــي محضــر االتفــاق املــدون آنفــا‪ ،‬كمــا أضــاف‬\n‫املدعــي قائــا أنــه بعــد اســتالمي للمشــروع بأســبوع تعطلــت معــدات‬\n‫بركــة الســباحة وقمــت بإصالحهــا مــع قطــع غيــار بإحــدى عشــر ألــف‬\n‫وثالثمائــة ريــال‪ ،‬كمــا أن الشــركة اســتلمت منــي ألــف وثمامنائــة ريــال‬\n‫قيمــة إصــاح الزجــاج وقيمــة الزجــاج فقــط مائــة ريــال والتركيــب علــى‬\n‫الشــركة؛ ألنــه مــن الصيانــة‪ ،‬كمــا أبــرز املدعــي كشــف حســاب رقــم‬\n‫‪ 4‬واملرســل بالفاكــس للعميــل الســيد ‪ ....................‬املــؤرخ يف‬\n‫‪1998/7/1‬م صــادر مــن الشــركة ‪...................‬وقــد جــاء فيــه املســتحق‬\n‫لكــم عــن قيمــة تأجيــر شــاليه رقــم( ‪ 39500  )6‬ريــال‪ ،‬وســمع ذلــك‬\n‫املدعــى عليــه وأجــاب قائــا‪ :‬إن الزجــاج مت تركيبــه مبوجــب فاتــورة‬\n‫وأطلــب إمهالــي إلحضارهــا‪ ،‬ومــا ذكــره املدعــي مــن أنــه مت إصــاح‬\n‫البركــة بعــد أســبوع فقــط أطلــب منــه إثبــات ذلــك‪ ،‬كمــا جــرى  ســؤال‬\n‫املدعــى عليــه عمــا ذكــره يف إجابتــه ســابقا أن الدعايــة واإلعــان علــى‬\n‫املدعــي فأجــاب قائــا‪ :‬بــأن العقــد قــد نــص باملــادة الثامنــة منــه بأنــه‬\n‫يلتــزم الطــرف الثانــي بســداد رســوم البلديــة اخلاصــة باللوحــات اإلعالنية‬\n‫اخلاصــة بشــاليهات الترفيــه وعددهــا أربعــة أوجــه إعالنيــة مبســاحة‬\n‫ســبعة وتســعني متــر‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬إن ذلــك خــاص بالالفتة‬\n‫التــي علــى الشــاليهات نفســها‪ ،‬أمــا مــا جــاء يف دعــواي فهــو املقصــود‬\n‫الدعايــة واإلعــان يف وســائل اإلعــام وقــد اتفقــت مــع املديــر الســابق‬\n‫‪ ..................‬ورئيــس مجلــس اإلدارة الســابق ‪ ..................‬حيــث اتفقــت‬\n‫معهمــا علــى أن يدفــع خمســة وعشــرين باملائــة مــن قيمــة  الدعايــة ال أننــي‬\n\n\n                                                                                      ‫‪132‬‬\n\f      ‫ســوف أضمــن الدعايــة‪ ،‬وإن الشــاليهات تقــع بجــوار مدينــة ‪......‬‬\n      ‫الترفيهيــة‪ ،‬وســمع ذلــك املدعــى عليــه وأجــاب قائــا‪ :‬إن مــا ذكــره‬\n      ‫املدعــي مــن أنــه اتفــق مــع املديــر الســابق ورئيــس مجلــس اإلدارة فــا ‬\n      ‫أعلــم عنــه‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬إنــه مت االتفــاق معهمــا مشــافهة‬\n      ‫وعندمــا طلبــت منهمــا كتابــة ذلــك وإضافتــه مبحضــر الهاتــف قــال لــي‬\n      ‫‪ ..............‬نحــن موجوديــن ونتعامــل بثقــة‪ ،‬ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان وبســؤال املدعــى عليــه عــن فاتــورة الزجــاج التــي وعــد‬\n      ‫بإحضارهــا أجــاب قائــا‪ :‬بأننــي لــم أمتكــن مــن إحضارهــا‪ ،‬وجــرى‬\n      ‫ســؤال املدعــي عــن إثبــات فواتيــر بركــة الســباحة‪ ،‬أبــرز وثيقــة هــذا‬\n      ‫نصهــا‪(  :‬بســم اهلل الرحمــن الرحيــم التاريــخ ‪1418/6/22‬ه ـ املكــرم‬\n      ‫مديــر شــاليهات ‪ ...........‬احملتــرم الســام عليكــم ورحمــة اهلل وبركاتــه‬\n      ‫وبعــد‪ :‬نحيطكــم علمــا بتقريــر مفصــل بعــد زيــارة بركــة الســباحة‬\n      ‫املتعطلــة الكائنــة بشــاليهات ‪ ......‬حيــث وجــد مــا يلــي‪/1 :‬هنــاك كســر‬\n      ‫وانفجــار بالفلتــر نتيجــة عيــب فنــي يف التوصيــات اخلاصــة بالفلتــر‬\n      ‫واملضخــة متمثــل يف وضــع قطــع توصيــات ال تتناســب مــع كميــة‬\n      ‫الضغــط الناشــئ مــن ســحب املضخــة كذلــك وضــع مواســير ‪ 40‬بــدال‬\n      ‫مــن ‪ 80‬الالزمــة لهــذه احلالــة‪/2 .‬عــدم وضــع املضخــات علــى قواعــد‬\n      ‫حلمايتهــا مــن امليــاه املتواجــدة بأرضيــة غرفــة املعــدات ممــا أدى إلــى تلــف‬\n      ‫إحــدى املضخــات والتــي يلــزم اســتبدالها إلــى جانــب الفلتــر املنفجــر‪/3 .‬‬\n      ‫عــدم وجــود غرفــة تفتيــش بداخــل غرفــة املعــدات الالزمــة لتجميــع امليــاه‬\n      ‫داخــل غرفــة املعــدات يف حالــة وجــود أي تســرب داخلهــا كذلــك يلــزم‬\n      ‫وجــود مضخــة داخــل غرفــة التفتيــش لدفــع امليــاه إلــى اخلــارج‪/4 .‬قلــة‬\n      ‫عــدد فتحــات الرجــوع حيــث املوجــودة ســتة فقــط بينمــا الالزمــة عشــرة‬\n\n\n‫‪133‬‬\n\f‫ممــا يــؤدي إلــى قلــة كميــة امليــاه املرجتعــة خــال اإلســلميرات اخلمســة‬\n‫بالبركــة ‪ ............‬مديــر املشــاريع توقيعــه) أ‪.‬هــ‪ .‬كمــا أبــرز أيضــا وثيقــة‬\n‫هــذا نصهــا‪( :‬بســم اهلل الرحمــن الرحيــم التاريــخ ‪1418/6/21‬ه ـ‬\n‫املكــرم مديــر شــاليهات ‪ ............‬احملتــرم الســام عليكــم ورحمــة اهلل‬\n‫وبركاتــه وبعــد‪ :‬بنــاء علــى تعميدكــم لنــا مبعاينــة معــدات بركــة‬\n‫الســباحة املتعطلــة واخلاصــة بشــاليهات الترفيــه وطلبكــم تقــدمي التقريــر‬\n‫الــازم والتســعيرة املتعلقــة بهــذا اإلصــاح عليــه نحيطكــم أن فريــق‬\n‫العمــل املكــون مــن املهنــدس والفنيــن قــد عاينــوا املعــدات فوجــدوا أن‬\n‫العطــل احلاصــل ســببه ضغــط زائــد علــى الفلتــر ممــا أدى إلــى انفجــار‬\n‫الفلتــر كذلــك تســرب امليــاه داخــل املضخــة ممــا أدى إلــى احتراقهــا‪،‬‬\n‫وعلــى هــذا فــا بــد مــن إعــادة تركيــب فلتــر ومضخــة جديــدان مــن‬\n‫نفــس النوعيــة وكذلــك إعــادة تركيــب توصيــات جديــدة بــدال مــن‬\n‫القائمــة حاليــا القيمــة اإلجماليــة لألعمــال أعــاه ‪11800‬ريــال ال غيــر‬\n‫املهنــدس ‪ ..............‬مديــر املشــاريع توقيعــه) أ‪.‬ه ـ ‪ .‬وأبــرز ســند قبــض‬\n‫معنــون مؤسســة ‪ ...............‬للتجــارة واملقــاوالت ســند قبــض رقــم ‪ 258‬يف‬\n‫‪1997/11/2‬م املوافــق ‪1418/7/2‬ه ـ اســتلمنا مــن األســتاذ املكــرم‬\n‫‪ ......................‬شــاليهات ‪ ........‬فقــط خمســة آالف وســبعمائة ريــال ال‬\n‫غيــر وذلــك عــن دفعــة أخيــرة مــن عمليــة تركيــب معــدات املســبح وذلــك‬\n‫بعــد خصــم مبلــغ خمســمائة ريــال ليصبــح إجمالــي مــا وصلنــا أحــد عشــر‬\n‫ألــف وثالثمائــة ريــال‪ ،‬وأبــرز ســند آخــر برقــم ‪ 256‬مببلــغ خمســة آالف‬\n‫وســتمائة ريــال وكتبــت البيانــات باللغــة اإلجنليزيــة‪ ،‬وبعــرض ذلــك على‬\n‫املدعــى عليــه أجــاب قائــا‪ :‬إن املدعــي ملــا عــرض علــى الشــركة عطــل‬\n‫املســبح مت عرضــه علــى الشــركة املنفــذة وأصــدرت تقريــر بأنــه مــن‬\n\n\n                                                                                        ‫‪134‬‬\n\f      ‫ســوء االســتخدام‪ ،‬وســمع ذلــك املدعــي وقــال‪ :‬ال يوجــد أي خطــاب‪،‬‬\n      ‫واســتعد املدعــى عليــه بإحضــاره وإحضــار فاتــورة الزجــاج‪ ،‬ويف جلســة‬\n      ‫أخــرى حضــر املدعــي وحضــر حلضــوره ‪ ........‬احلامــل للبطاقــة رقــم‬\n      ‫‪ ................‬رقــم احلفيظــة ‪ .........‬يف ‪ ........‬الصــادرة مــن ‪ .......‬بالوكالــة‬\n      ‫عــن ‪............‬حــال كونــه وكيــا  عــن ‪ ...............‬و‪........................‬‬\n      ‫و‪ ................‬و‪ ..............‬و‪ .................‬و‪ .......................‬و‪....................‬‬\n      ‫وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل ‪ .....‬برقــم ‪ ......‬يف‬\n      ‫‪ ......‬واملخولــة لــه ينــوب عــن موكله فيما يخصهم يف الشــركة واملرافعة‬\n      ‫واملدافعــة وبالوكالــة عــن ‪ .....................‬مبوجــب وكالتــه عــن‬\n      ‫‪ ...................‬واملخولــة لــه املرافعــة واملدافعــة واملطالبــة وذلــك فيما يخص‬\n      ‫موكليــه مــن الشــركة ‪ .................‬وبالوكالــة عــن ‪...................‬مبوجب‬\n      ‫الوكالــة الصــادرة مــن ‪ .....‬برقــم ‪ .....‬يف ‪ ......‬اجللــد ‪ ......‬واملخولــة لــه‬\n      ‫مبطالبــة ومداعــاة ‪ .....................‬وذلــك بخصــوص الشــاليهات املؤجــرة‬\n      ‫عليــه لــه حــق الدعــوى واإلجابــة والصلــح واالســتالم‪ ،‬وأضــاف املدعــى‬\n      ‫عليــه‪ :‬إن موكلينــي هــم أعضــاء مجلــس إدارة مراكــز ‪..............‬‬\n      ‫واملخــول لــه مــن مجلــس إدارة الشــركة حســب املــادة ‪ 1/14‬متثيــل‬\n      ‫الشــركة لــدى الغيــر باملرافعــة واملدافعــة واملخاصمــة ‪...‬الــخ وطلــب منــه‬\n      ‫مــا يثبــت أن موكليــه هــم أعضــاء مجلــس إدارة الشــركة واســتعد‬\n      ‫بذلــك‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبطلــب مــا طلــب إمهالــه مــن‬\n      ‫املدعــى عليــه أبــرز خطــاب مــن مؤسســة ‪ .........‬التجاريــة املــؤرخ يف‬\n      ‫‪1997/10/28‬م وهــذا نصــه‪( :‬بســم اهلل الرحمــن الرحيــم الســادة‬\n      ‫الشــركة ‪ ...............‬احملترمــن الســام عليكــم ورحمــة اهلل وبركاتــه‬\n      ‫إشــارة إلــى طلــب الســادة‪ /‬مؤسســة ‪ ..............‬للمقــاوالت ملعاينــة بركــة‬\n\n\n‫‪135‬‬\n\f‫الســباحة املنفــذة مــن قبلكــم يف موقــع شــاليهات ‪ .............‬وبنــاء علــى‬\n‫طلبكــم تقريــر حــول حادثــة الفلتــر بالبركــة املذكــورة‪ ،‬فقــد قمنــا‬\n‫يــوم ‪1997/10/27‬م  مبعاينــة املوقــع برفقــة مندوبكــم وقــد تبــن اآلتي‪:‬‬\n‫أوال‪/‬أن جميــع توصيــات املواســير والتجهيــزات يف غرفــة املعــدات‬\n‫صحيحــة وحســب املواصفــات املعمــول بهــا‪ .‬ثانيــا‪/‬أن عطــا كهــذا‬\n‫(وبعــد تشــغيل ألكثــر مــن شــهر مضــى) ال يحــدث إال نتيجــة خطــأ يف‬\n‫التشــغيل‪ ،‬أو تســكر أحــد احملابــس الراجعــة للبركــة وبالتالــي نحــن‬\n‫مطمئنــون إلــى أن تنفيــذ العمــل صحيــح وال تبعــة علــى املقــاول مــن أي نوع‬\n‫خاصــة وأن الفلتــر الثانــي يعمــل بشــكل صحيــح وســليم ولكــم حتياتنــا‬\n‫املشــرف الفنــي ‪ ..............‬توقيعــه) أ‪.‬هــ‪ ،‬كمــا أبــرز فاتــورة معنونــة مــن‬\n‫مجمــع ‪ ........ ........‬رقــم ‪ 2488‬يف ‪1998/8/30‬م واملكتــوب مــن الســيد‬\n‫الشــركة ‪ ......................‬ســتمائة وثالثــون ريــال خصــم ثالثــون ريــال‬\n‫املجمــوع ســتمائة زجــاج ســترميلي ســادة ســولورين ضــد الكســر‪،‬‬\n‫وبعرضهــا علــى املدعــي أصالــة أجــاب قائــا‪ :‬أن التقريــر يحتــاج إلــى‬\n‫الرجــوع إلــى التواريــخ حتــى أمتكــن مــن اإلجابــة‪ .‬ثانيا‪/‬التوقيــع علــى‬\n‫الفاتــورة ليــس توقيعــي وال أعلــم مــن هــو توقيعــه وهــو التوقيــع املــدون‬\n‫حتــت اســم ‪ ،..............‬ويف جلســة أخــرى قــال املدعــي‪ :‬إن التقريــر املشــار‬\n‫إليــه لــم يحــدد العيــب وقــد ذكــر احتمــاالت أمــا التقريــر الــذي قدمتــه‬\n‫فهــو محــدد اخللــل كمــا أنــه  ســبق لنــا االجتمــاع يف ‪1997/10/19‬م‬\n‫ومــن ضمــن النقــاط التــي حصــل االتفــاق عليهــا (خامســا) يتــم إصــاح‬\n‫البركــة بــدون التعــذر بأخطــاء الغيــر وكذلــك املكيفــات ولــم يتــم‬\n‫إصــاح البركــة وقمــت بإصالحهــا؛ ألنــه مت تشــغيل املشــروع قريبــا‬\n‫ورغبــة يف كســب الــزوار وتلبيــة رغباتهــم وعلــى أمــل أن تســد لــي قيمــة‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫اإلصــاح‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبســؤال املدعــى عليــه‬\n      ‫عــن محضــر االجتمــاع املوقــع يف يــوم األحــد املوافــق ‪1997/10/19‬م مــن‬\n      ‫األستاذ ‪ ............‬و‪ ...................‬و‪ ..............‬و‪ ....................‬و‪......................‬‬\n      ‫ومــا جــاء يف الفقــرة (خامســا) يتــم إصــاح البركــة بــدون التعــذر‬\n      ‫بأخطــاء الغيــر وكذلــك املكيفــات أجــاب قائــا‪ :‬أن ‪ ...............‬مســافر‬\n      ‫خــارج اململكــة وهــو ســوف يصــل اليــوم أو غــدا‪ ،‬كمــا جــرى ســؤال‬\n      ‫املدعــي عــن دعــواه بأنــه يطالــب بإيجــار الشــاليه رقــم ‪ 6‬بأجــرة وقدرهــا‬\n      ‫أربعــة وأربعــون ألــف وخمســمائة ريــال وأن املقدم له من إدارة الشــاليهات‬\n      ‫عــن تأجيــر الشــاليه رقــم ‪ 6‬تســع وثالثــون ألــف وخمســمائة ريــال وأجــاب‬\n      ‫قائــا‪ :‬أن الشــاليه مؤجــر مببلــغ وقــدره أربعــة وأربعــون ألــف وخمســمائة‬\n      ‫ريــال حســب عقــد اإليجــار املــؤرخ يف ‪1418/2/21‬ه ـ املوافــق‬\n      ‫‪1997/6/26‬م وأبــرز العقــد املــؤرخ بالتاريــخ أعــاه واملوضــح فيــه املؤجر‬\n      ‫شــاليهات الترفيــه املمثــل لهــا ‪ ....................‬الطــرف الثانــي ‪.................‬‬\n      ‫مــدة اإليجــار ســنة هجريــة اعتبــارا مــن بدايــة اإلشــعار والتشــغيل و‬\n      ‫اجلاهزيــة بأجــرة إجماليــة قدرهــا أربعــة وأربعــون ألــف وخمســمائة ريــال‬\n      ‫أ‪.‬هــ  وأضــاف املدعــي‪ :‬إن بدايــة التشــغيل مــن ‪1997/10/1‬م‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬بأنــي ال أعلــم عــن مطالبــة املدعي؛‬\n      ‫ألنــه ليــس لــي علــم عــن عقــد اإليجــار وأطلــب  إمهالــي للرجــوع إلــى‬\n      ‫موكلــي‪ ،‬ويف جلســة أخــرى جــرى ســؤال املدعــى عليــه عمــا طلــب‬\n      ‫اإلمهــال لــه أن الشــاليه املؤجــر علــى ‪ ...‬اخللــف أجرتــه بالســنة أربعــة‬\n      ‫وأربعــون ألــف وخمســمائة ريــال ولــم يســلم ل‪ ..............‬مــن بدايــة العقــد‬\n      ‫وقــد حســبت لــه املــدة التــي يســتحقها مــن اإليجــار تســعة وثالثــن ألــف‬\n      ‫وخمســمائة ريــال‪ ،‬وطلــب مــن املدعــى عليــه حتديــد تاريــخ اســتالم‬\n\n\n‫‪137‬‬\n\f‫الشــاليه فاســتعد بذلــك‪ ،‬ويف جلســة أخــرى حضــر املدعــي  وحضــر‬\n‫حلضــوره ‪ ..............‬احلامــل للبطاقــة رقــم ‪ ...........‬رقــم احلفيظــة ‪ ............‬يف‬\n‫‪1406/9/6‬ه ـ الصــادرة مــن الريــاض بالوكالــة عــن ‪....................‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل ‪ ......‬برقــم ‪ ......‬يف ‪......‬‬\n‫اجللد ‪ .....‬حال كونه وكيال عن و‪ .................‬و‪ ...............‬و‪.....................‬‬\n‫و‪ .............‬واملذكورون هم أعضاء إدارة مجلس الشركة ‪.....................‬‬\n‫احملــدودة واملخولــة لــه مطالبــة ومداعــاة ‪ ..................‬وجــرى ســؤال‬\n‫املدعــى عليــه عمــا طلــب اإلمهــال لــه فأجــاب قائال أنه مت تســليم الشــاليه‬\n‫ل‪ ................‬يف ‪1997/11/1‬م وهــو بدايــة اإليجــار علــى ‪ ..........‬وطلــب‬\n‫حتديــده بالتاريــخ الهجــري فاســتعد بذلــك ويف جلســة أخــرى قال املدعى‬\n‫عليه‪ :‬إنه مت تســليم الشــاليه ل‪ ................‬بتاريخ ‪1418/7/1‬هـ‪  ،‬وجرى‬\n‫ســؤال املدعــي عــن كيفيــة دفــع أجــرة الصيانــة فأجــاب قائــا‪ :‬أنــه يتــم‬\n‫دفعهــا شــهريا‪ ،‬وجــرى ســؤاله أيضــا عــن أربــاح التأمــن التــي يطالــب بهــا‬\n‫فأجــاب قائــا‪ :‬إن مشــروع الشــاليهات قــد مت تقديــره مــن قبــل شــركة‬\n‫الترفيــه بأحــد عشــر مليــون ودفعــت عليــه تأمني لدى الشــركة التعاونية‬\n‫للتأمــن مبلــغ وقــدره أحــد عشــر ألــف ريــال بنســبة واحــد باأللــف ويف‬\n‫حالــة عــدم حــدوث أي شــيء علــى املشــروع حتســب األربــاح حســب املبلــغ‬\n‫الــذي دفعــه واســتحق عــن ذلــك جــزء مــن عــام ‪1997‬م وعــام ‪1998‬م مبلــغ‬\n‫وقــدره ثمامنائــة وتســعة وثمانــون ريــال‪ ،‬وأضــاف املدعــي قائــا‪ :‬إن‬\n‫الهواتــف التــي مت تأمينهــا مــن قبلــي مــن نــوع (ســيناو الســلكي)‪ ،‬وحيث‬\n‫أن املدعــي ذكــر يف دعــواه أنــه يتــم تأمــن الهواتــف أيــا كان نوعهــا‬\n‫وذكــر املدعــى عليــه أنــه يتــم تأمــن هواتــف عــن طريــق شــركة ‪،.......‬‬\n‫لــذا فقــد رفعــت اجللســة وذلــك للكتابــة لهيئــة النظــر وذلــك لتحديــد نــوع‬\n\n\n                                                                                               ‫‪138‬‬\n\f        ‫الهواتــف التــي يتــم تركيبهــا حســب اتفــاق الطرفــن وســوف يرفــق لهــم‬\n        ‫صــورة مــن وثيقــة االتفــاق علــى الهواتــف‪ ،‬فــوردت اإلجابــة أن العطــل‬\n        ‫النــاجت يف املســبح ال ميكــن أن يتــم فيــه عطــل خــال أســبوع أو مــا يقــارب‬\n        ‫ذلــك ال بــد أن يكــون فيــه أخطــاء فنيــه ال ميكــن معرفتهــا إال بســؤال‬\n        ‫أهــل اخلبــرة لــذا نعتــذر عــن اإلجابــة عضــو هيئــة النظــر ‪................‬‬\n        ‫و‪ ،.....................‬وحيــث لــم توضــح هيئــة النظــر مــا طلــب منهــم عــن‬\n        ‫الهاتــف فقــد جــرى إعــادة األوراق لفضيلــة الرئيــس بطلــب إعادتهــا لهيئــة‬\n        ‫النظــر بتقريــر نــوع الهاتــف الــذي يجــب أن يتــم إيصالــه حســب االتفاقيــة‬\n        ‫املرفقــة مــع االســتعانة بأهــل اخلبــرة وذلــك بخطابنــا رقــم ‪ 4/807‬يف‬\n        ‫‪1425/4/11‬ه ـ وقــد أعيــدت لنــا األوراق مــن فضيلــة الرئيــس برقــم‬\n        ‫‪ 7925‬يف ‪1425/6/7‬ه ـ شــرحا علــى خطــاب هيئــة النظــر رقــم‬\n        ‫‪ 24/16505‬يف ‪1425/6/4‬ه ـ املتضمــن أنــه مضــى عليهــا مــدة ولــم‬\n        ‫يراجــع أحــد‪ ،‬وبتأمــل مــا مضــى حيــث أن املدعــي قــرر أنــه ال بينــة لــه‬\n        ‫علــى مــا يدعــي بــه نســبة الدعايــة واإلعــان‪ ،‬وجــرى إفهامــه أن لــه ميــن‬\n        ‫املديــر الســابق ‪ .............‬ورئيــس مجلــس اإلدارة الســابق ‪...............‬‬\n        ‫وأجــاب‪ :‬أنــه ال يرغــب بيمينهمــا واليمــن الواجبــة هــي علــى نفــي مــا‬\n        ‫يدعــي بــه ولعــدم االســتطاعة يف إحضارهــم وهــذا ســبب عــدم طلــب‬\n      ‫ميينهمــا‪ ،‬وحيــث أن املدعــى عليــه قــرر بأنــه لــم يتم اســتالم أربــاح التأمني ‬\n        ‫وذكــر املدعــي أنــه مت اســتالم األربــاح لعــام ‪1997‬م‪ ،‬وجــرى ســؤاله هــل‬\n      ‫لديــه بينــة علــى ذلــك‪ ،‬فأجــاب قائــا‪ :‬أطلــب إمهالــي للبحــث عــن البينة‪  ،‬‬\n        ‫ويف جلســة أخــرى قــال املدعــي عنــد ســؤاله عــن نــوع الزجــاج ومقاســه‪:‬‬\n        ‫إن مقاســه ‪ 80‬ســم يف متريــن ونوعــه زجــاج أخضــر ســادة‪ ،‬ويف جلســة‬\n        ‫أخــرى حضــر الطرفــان وبطلــب البينــة مــن املدعــي علــى صــرف أربــاح‬\n\n\n‫‪139‬‬\n\f‫التأمــن أجــاب قائــا‪  :‬إن املبلــغ قليــل ويحتــاج إلــى بحــث وقــد ذكــرت‬\n‫ذلــك يف دعــواي وذلــك ملجــرد توضيــح تعســف الشــركة واســتحواذها‬\n‫علــى حقــوق الغيــر مهمــا قلــت وأنــا متنــازل يف الدعــوى ضــد ذلــك‪،‬‬\n‫وأجــاب املدعــى عليــه عــن الزجــاج قائــا‪ :‬إن الســندين املقدمــة مــن‬\n‫املدعــي خاصــة مبجمــع ‪ .....‬الــذي يبيــع ويركــب الزجــاج ونحــن يف‬\n‫الشــركة لســنا مســئولني عــن ســندات محــل آخــر رمبــا مجمــع ‪ .....‬ال‬\n‫يســتخدم ســندات القبــض إال عنــد طلــب الزبــون  والفــرق بــن الســندين‬\n‫حوالــي ثالثــة شــهور مــن ‪1997/10/12‬م إلــى ‪1998/1/10‬م‪ ،‬فأمــا‬\n‫عــن نــوع الزجــاج فالســند األول رقــم ‪ 502‬بقيمــة خمســمائة ريــال فهــو‬\n‫عــن قيمــة لــوح زجــاج مــع التركيــب‪ ،‬والثانــي رقــم ‪ 503‬بقيمــة ألــف‬\n‫وثالثمائــة ريــال فهــو عــن قيمــة لوحــن زجــاج ولوحــن بالســتيك وأجــرة‬\n‫تركيــب‪ ،‬فالشــيء الطبيعــي أن يكــون فــرق بالقيمــة؛ ألن الســند األول‬\n‫خــاص بلــوح واحــد فقــط دون وجــود لــوح بالســتيك وســند الصــرف‪ ،‬فهو‬\n‫مــن مؤسســة ‪ ...............‬التــي تســببت يف كســر الزجــاج ودفعــت مبوجــب‬\n‫الســند لنــا تعويــض ألــف وثمامنائــة ريــال واملســتلم مديــر الشــاليهات وهــو‬\n‫مــن الشــركة ‪ ...............‬ونــرى أن املوضــوع ليــس لــه عالقــة بقضيــة‬\n‫‪.........‬؛ ألن مؤسســة ‪ .....‬كســرت الزجــاج ومجمــع ‪ ....‬ركــب الزجــاج‪،‬‬\n‫وســمع ذلــك املدعــي وقــال‪ :‬إن مؤسســة ‪ .....‬هــي مؤسســتي والســند‬\n‫الصــادر للشــاليهات بالصــرف صــادر مــن مؤسســتي ألن اســتعمال‬\n‫مطبوعاتها بدل من اســتخدام األوراق العادية وذلك لضبط حســاباتي‪،‬‬\n‫وأضــاف قائــا‪ :‬إن مجمــع التقــوى أصبــح اســمه مجمــع ‪ ،........‬وســوف‬\n‫تتــم الكتابــة ملجمــع ‪ ....‬لطلــب اإلفــادة عــن الســندين املشــار إليــه آنفــا‪،‬‬\n‫ويف جلســة أخــرى أضــاف املدعــي قائــا‪ :‬بأننــي متنــازل عــن املطالبــة‬\n\n\n                                                                                       ‫‪140‬‬\n\f      ‫بقيمــة الزجــاج‪ ،‬ويف جلســة أخــرى قــال املدعــي عنــد ســؤاله عــن‬\n      ‫التجهيــزات اإلضافيــة وهــي كالتالــي‪ :‬أوال‪/‬ســلطانية صغيــرة عــدد ‪21‬‬\n      ‫ســعر الواحــدة خمســة عشــر ريــال املجمــوع ثالثمائــة وخمســة عشــر‬\n      ‫ريــال‪ .‬ثانيا‪/‬أربعــة أباريــق شــاي كبيــر ســعر اإلبريــق أربعــون ريــال‬\n      ‫املجمــوع مائــة وســتون ريــال‪ .‬ثالثا‪/‬عــدد اثنــن درام زبالــة للمطبــخ مببلــغ‬\n      ‫اثنــان وثالثــون ريــال‪ .‬رابعا‪/‬ثالثــة عشــر فرشــات تنظيــف حمــام ســعر‬\n      ‫الواحــدة عشــرة ريــاالت مببلــغ مائــة وثالثــون ريــال‪ .‬خامســا‪/‬عدد اثنــن‬\n      ‫ســرير معدنــي مــع فرشــة ســعر الواحــدة مائــة وســبعون ريــال املجمــوع‬\n      ‫ثالثمائــة وأربعــون ريــال‪ .‬سادســا‪/‬عدد ‪ 52‬شرشــف فيتــو ســعر الواحــد‬\n      ‫ســتة وســتون ريــال واملجمــوع ثالثــة آالف وأربــع مائــة واثنــان وثالثــون‬\n      ‫ريــال‪ ،‬ومجمــوع قيمــة هــذه الزيــادات أربعــة آالف وأربعمائــة وتســعة‬\n      ‫ريــاالت وهــذه الزيــادات موضحــة يف بيــان التســليم باإلضافــة إلــى‬\n      ‫الزيــادات املوضحــة يف هــذا البيــان‪ ،‬وقــدم بيــان موضــح يف تســعة عشــر‬\n      ‫صنفــا ومجمــوع قيمتهــا مــع مــا ســبق أعــاه ســتة عشــر ألــف وثالثمائــة‬\n      ‫وتســعة وتســعون ريــال‪ ،‬وجــرى عــرض مــا ذكــره املدعــي والبيــان املشــار‬\n      ‫إليــه أعــاه علــى املدعــى عليــه فأجــاب قائــا‪ :‬أطلــب تســليمي صــورة‬\n      ‫منهــا وإمهالــي لإلجابــة علــى ذلــك‪ ،‬ويف جلســة أخــرى حضــر املدعــي‬\n      ‫ولــم يحضــر املدعــى عليــه‪ ،‬وطلــب مــن املدعــي البينــة علــى التجهيــزات‬\n      ‫اإلضافيــة أبــرز الوثيقــة املعنونــة الشــركة ‪ .......................‬املؤرخــة يف‬\n      ‫‪1419/6/27‬ه املوافــق ‪1998/10/17‬م وهــذا نصهــا‪( :‬محضــر اســتالم‬\n      ‫شــاليهات الترفيــه أنــه يف يــوم الســبت واألحــد املوافقــن ‪ 4/3‬أكتوبــر‬\n      ‫‪1998‬م ثــم جــرد شــاليهات الترفيــه بكامــل مرفقاتهــا وملحقاتهــا‬\n      ‫وبجميــع جتهيزاتهــا ومحتوياتهــا متهيــدا لعمليــة التســليم واالســتالم فيمــا‬\n\n\n‫‪141‬‬\n\f‫بــن الشــركة املالكــة للشــاليهات ومســتثمرها ‪ .........................‬وقــد‬\n‫تكونــت جلنــة اجلــرد لهــذا الغــرض مــن الطرفــن علــى النحــو التالــي‪/1 :‬‬\n‫الشــركة املالكــة (الشــركة ‪ )................‬الســيد‪ ............./‬والــس‬\n‫يــد‪ ............................/‬والســيد‪ ......................./‬والســيد‪....................../‬‬\n‫‪/2‬املســتثمر ‪/‬الســيد ‪ .......................‬والســيد ‪ .................‬والســيد‬\n‫‪.................‬هــذا وقــد مت اجلــرد بالفعــل خــال اليومــن املشــار إليهــا‬\n‫أعــاه‪ ،‬وتبــن بعــض النواقــص واملفقــودات مــن جتهيــزات الشــاليهات‪،‬‬\n‫وقــد مت إدراجهــا بالبيانــات املرفقــة‪ ،‬وعليــه فقــد اســتلمت الشــركة‬\n‫‪ ..............‬الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا‬\n‫باإلضافــة لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر‬\n‫وتعتبــر مــن التاريــخ املذكــور أعــاه بحوزتهــم وحتــت مســئوليتهم‬\n‫وتصرفهــم ولــم يعــد للمســتثمر أي عالقــة بالشــاليهات مــا عــدا النواقــص‬\n‫واملفقــودات مــن التجهيــزات واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات‬\n‫اجلــرد املرفقــة واملوقعــة مــن قبــل الطرفــن وعلــى أن يكــون اســتكمال‬\n‫النواقــص واملفقــودات إمــا باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة‬\n‫ال تقــل عنهــا جــودة وإن تعــذر ذلــك فيتــم تقييــم أســعار كل منهــا حســب‬\n‫مــا جــاء يف بيانــات اســتالمها يف العــام املاضــي مــع مراعــاة العمــر‬\n‫االفتراضــي حســبما ورد بالعقــد‪ ،‬أمــا مــن حيــث النواحــي املالية فســوف‬\n‫تتــم التســويات واملطالبــات املاليــة بــن الطرفــن كل فيمــا يخصــه بعــد‬\n‫التوقيــع علــى هــذا احملضــر مباشــرة واهلل املوفــق‪ ،‬املســتثمر توقيعــه‬\n‫‪ ................‬عــن الشــركة ‪ .................‬توقيــع ‪ .................‬نائــب املديــر‬\n‫العــام) أ‪.‬هــ‪ ،‬ويف جلســة أخــرى قــال املدعــى عليــه إجابــة عــن فواتيــر‬\n‫التجهيــزات التــي أبرزهــا املدعــي‪ :‬إن املدعــي اســتأجر الشــاليهات وهــي‬\n\n\n                                                                                                     ‫‪142‬‬\n\f      ‫مؤثثــة ومجهــزة بالكامــل وقــد عايــن الشــاليهات فوجدهــا صاحلــة‬\n      ‫لالســتخدام واســتلمها علــى تلــك احلــال‪ ،‬ثانيا‪/‬التــزم باحملافظــة علــى‬\n      ‫الشــاليهات ومــا يتبعهــا مــن منقــوالت ومعــدات وأجهــزة وأن يســلمها‬\n      ‫باحلــال التــي تســلمها بهــا‪ .‬ثالثا‪/‬تتحمــل املســؤولية الكاملــة عنــد وجــود‬\n      ‫أي ضــرر ال قــدر اهلل‪ .‬رابعا‪/‬يتحمــل جميــع أعمــال الصيانــة بالكامــل‬\n      ‫وال يوجــد يف تلــك الفواتيــر مــا يفيــد أنــه مت شــراؤها بنــاء علــى طلبهــا‪،‬‬\n      ‫أو أننــا تســلمنا محتويــات تلــك الفواتيــر بالتالــي ال نقــر بهــا‪ ،‬أمــا بالنســبة‬\n      ‫للهواتــف فــإن العقــد مــع املدعــي نــص علــى أن أي إضافــة إلــى املشــروع‬\n      ‫مــن املدعــي يجــب أن يأخــذ موافقــة موكلتــي عليهــا خطيــا وحيــث أن‬\n      ‫األصــل أخــذ العقــد علــى ظاهــره مــا لــم يثبــت املدعــي ذلــك‪ ،‬فــإذا كان‬\n      ‫لــدى املدعــي البينــة علــى أنــه اتفــق مــع موكلتــي علــى إدخــال الهاتــف‬\n      ‫بــأي طريقــة فليقدمهــا‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬إن‬\n      ‫التجهيــزات اإلضافيــة اعترفــوا بهــا وســلمت لهــم مبوجــب محضــر‬\n      ‫التســليم املــؤرخ يف ‪1419/6/27‬ه ـ وســبق تقــدمي صــورة يف احملضــر ومــا‬\n      ‫ذكــره املدعــى عليــه مــن أن أعمــال الصيانــة علـ ّـي‪ ،‬فــإن أعمــال الصيانة‬\n      ‫قــد حتولــت علــى الشــركة مبوجــب عقــد وهــي املســؤولة عــن الصيانــة‪،‬‬\n      ‫وأمــا بالنســبة للهاتــف فإنــه مت تأمينــه وذلــك حســب محضــر االجتمــاع‬\n      ‫يف يــوم األربعــاء املوافــق ‪1997/9/3‬م وهــي موافقــة خطيــة من الشــركة‬\n      ‫حســب مــا جــاء يف العقــد‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه مــع تســليمه‬\n      ‫صــورة مــن محضــر االجتمــاع ومحضــر اســتالم شــاليهات الترفيــه أجــاب‬\n      ‫قائــا‪ :‬بالنســبة حملضــر إيصــال الهاتــف فإننــي أطلــب إمهالــي ملراجعــة‬\n      ‫موكلتــي‪ ،‬وأمــا بالنســبة حملضــر االســتالم فإنــه ذكــر فيــه أنــه يوجــد‬\n      ‫نواقــص ومفقــودات مــن التجهيــزات واملــواد اخلاصــة بالصيانــة‪ ،‬وال أعلــم‬\n\n\n‫‪143‬‬\n\f‫هــل مت تأمــن هــذه النواقــص واملفقــودات كمــا أشــار باحملضــر أنــه مت‬\n‫اســتالم أغــراض وجتهيــزات مســتكملة مــن قبــل املســتثمر‪ ،‬وال أعلــم‬\n‫هــل هــذه التجهيــزات هــي نفــس التجهيــزات التــي قــدم فواتيرهــا‬\n‫املدعــي‪ ،‬وأحتــاج إلــى الرجــوع إلــى البيــان املشــار إليــه‪ ،‬وقــد أضــاف‬\n‫املدعــي‪ :‬إن جميــع النواقــص واملفقــودات مت تأمينهــا ومعاجلتهــا مــع‬\n‫الشــركة يف وقتهــا واملدعــى عليــه ليــس لــه دخــل يف النواقــص؛ ألننــي‬\n‫أنــا املدعــي‪ ،‬ويف جلســة أخــرى حضــر الطرفــان وبطلبنــا اجلــواب مــن‬\n‫املدعــى عليــه عــن اخلطــاب املــؤرخ يف ‪2007/9/25‬م وقــد جــاء فيــه بعــد‬\n‫املقدمــة‪ :‬أوال‪/‬بخصــوص النواقــص واملفقــودات حســب احملضــر املوقــع‬\n‫مــن املدعــي ‪ ........................‬بتاريــخ ‪1419/9/27‬هــ‪ ،‬عليــه يجــب علــى‬\n‫املدعــي إثبــات أن األغــراض والتجهيــزات املســتكملة مــن قبلــه هــي‬\n‫نفــس النواقــص واملفقــودات مــن التجهيــزات وفقــا لبيانــات اجلــرد املرفقة‬\n‫واملوقعــة بــن الطرفــن‪ .‬ثانيا‪/‬بخصــوص تكلفة تأســيس هاتف مشــروع‬\n‫شــاليهات الترفيــه حســب احملضــر املوقــع مــن املدعــي ‪........................‬‬\n‫بتاريــخ ‪1997/9/3‬م عليــه فــإن الشــركة تلتــزم بتحمــل نســبة ‪% 75‬مــن‬\n‫تكلفــة تأســيس هاتــف مشــروع شــاليهات الترفيــه هــذا يف حالــة إذا‬\n‫كان لــدى املدعــي مــا يفيــد فعــا بأنــه قــام بتأســيس هاتــف املشــروع‬\n‫واعتمــاد التكلفــة مــن قبــل إدارة الشــركة‪ ،‬وبعــرض ذلــك علــى املدعي‬\n‫أجــاب قائــا‪ :‬بأننــي ســبق وأن أجبــت أن جميــع النواقــص واملفقــودات مت‬\n‫تأمينهــا ومعاجلتهــا مــع الشــركة يف وقتهــا واملدعــى عليهــم ليــس لهــم‬\n‫دخــل يف النواقــص؛ ألننــي أنــا املدعــي وأطالــب بقيمــة التجهيــزات‬\n‫اإلضافيــة التــي قمــت بتكميلهــا‪ ،‬وأمــا بالنســبة للهاتــف قــد مت تأمينــه‬\n‫مــن قبلــي وبعــد خروجــي مــن املشــروع مت تســليم املشــروع لهــم والهاتــف‬\n\n\n                                                                                     ‫‪144‬‬\n\f      ‫ضمــن املشــروع‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬إن مــا‬\n      ‫ذكــره املدعــي يف أن النواقــص واملفقــودات مــن التجهيــزات مت تأمينهــا‬\n      ‫ومعاجلتهــا مــع الشــركة فهــذا الــكالم يحتــاج إلــى تثبــت‪ ،‬فنطلــب فيــه‬\n      ‫إثباتــه‪ ،‬وكذلــك الهاتــف نطلــب منه ما يفيد تأمينه وتســليمه للشــركة‬\n      ‫بعــد خروجــه‪ ،‬وأمــا بالنســبة للتجهيــزات أطلــب إمهالــي ملراجعــة‬\n      ‫الشــركة‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬أن النواقــص‬\n      ‫واملفقــودات مت معاجلتهــا مبوجــب إثباتــات ومحاضــر مســجله بدفاتــري‬\n      ‫ودفاتر الشــركة والهاتف مت تركه يف إدارة الشــاليهات ومت اســتعماله‬\n      ‫مــن قبــل الشــركة واملســتثمر الــذي اســتأجر بعــدي‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر الطرفــان وبطلــب اجلــواب مــن املدعــى عليــه أجــاب قائــا‪ :‬بأننــي‬\n      ‫راجعــت الشــركة وأفــادت بأنــه ال يوجــد لديهــا أي معلومــات خاصــة‬\n      ‫بالتجهيــزات اإلضافيــة‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬بــأن‬\n      ‫الشــركة قــد أقــرت باســتالم األغــراض والتجهيــزات املســتكملة مــن‬\n      ‫قبلنــا بصفــة عامــة وذلــك حســب محضــر االســتالم املــؤرخ يف‬\n      ‫‪1419/6/27‬ه ـ املوافــق ‪1998/10/17‬م‪ ،‬وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه أجــاب قائــا‪ :‬إن هــذا احملضــر مرفــق بــه بيانــات والبيانــات ال‬\n      ‫توجــد لــدى موكلتــي صــورة منهــا حيــث أنــه مضــى عليــه أكثــر مــن‬\n      ‫عشــر ســنوات والبحــث يصعــب يف ذلــك‪ ،‬وطلــب مــن املدعــي رقــم‬\n      ‫الهاتــف الــذي مت تأمينــه فأجــاب قائــا‪ :‬بأنــه مت تأمــن هاتفــن ومت‬\n      ‫اســتئجار ســطح مبنــى يف الظهــران لتثبيــت اجلهــاز مبنطقــة الظهــران؛‬\n      ‫ألنــه أقــرب نقطــة إلــى موقــع الشــاليهات‪ ،‬ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان وأجــاب املدعــي قائــا‪ :‬أنــه مت تأســيس خطــن هاتــف ثابــت‬\n      ‫رقــم ‪ 8611567‬ورقــم ‪ 8611491‬قيمــة اجلهازيــن ســتة عشــر ألــف ريــال‬\n\n\n‫‪145‬‬\n\f ‫حيــث مت دفــع الثمــن مبوجــب الشــيك رقــم ‪ 237‬يف ‪1997/10/20‬م علــى‬\n ‫البنك ‪ .....‬لشــركة ‪ .........‬وشــريكه مببلغ عشــرة آالف ريال‪ ،‬والشــيك‬\n ‫الثانــي علــى شــركة ‪ ......‬برقــم ‪ 188‬وتاريــخ ‪1418/9/22‬ه ـ واملوافــق‬\n ‫‪1998/1/20‬م مببلــغ وقــدره ســتة آالف ريــال لشــركة ‪.............‬‬\n ‫وشــريكه‪ ،‬وقــد دون علــى الشــيك األول عبــارة نصهــا‪( :‬دفعــه مقــدم‬\n ‫مــن قيمــة جهــاز هوائــي ألكــون عــدد اثنــن خــط مــع التركيــب‬\n ‫والتشــغيل والضمــان والصيانــة ســنة) ودون علــى الشــيك الثانــي‪( :‬باقــي‬\n ‫قيمــة عــدد اثنــان جهــاز هاتــف هوائــي ماركــة ألكــون مــع التركيــب‬\n ‫والتشــغيل والضمــان)‪ .‬ثانيــا‪  :‬قيمــة االشــتراكات الشــهرية الرســوم‬\n ‫الثابتــة لــكال اخلطــن ولكامــل املــدة مــن بدايــة اســتخدامهما يف‬\n‫‪1418/10/10‬ه ـ وحتــى ألغاهمــا  يف ‪1424/2/10‬ه ـ أربعــة وســتني ‬\n ‫شــهرا عــدد اثنــن هاتــف ضــرب أربعــة وســتني ضــرب خمســة وأربعــن‬\n ‫ريــال شــهريا النــاجت خمســة آالف وســبعمائة وســتون ريــال إجمالــي‬\n ‫التكاليــف واحــد وعشــرون ألــف وســبعمائة وســتون ريــال تتحمــل‬\n ‫الشــركة مبوجــب االتفــاق ‪ % 75‬املطلــوب ســتة عشــر ألــف وثالثمائــة‬\n ‫وعشــرون ريــال‪ ،‬وأرفــق أصــل فواتيــر الهاتــف مــن البدايــة حتــى النهايــة‬\n ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬أطلــب تســليمي صــورة‬\n ‫منهــا وإمهالــي لإلجابــة عليهــا‪ ،‬ويف جلســة أخــرى حضــر الطرفــان‬\n ‫وبطلــب اجلــواب مــن املدعــى عليــه قــدم مذكــرة جــاء فيهــا مــا نصــه‪:‬‬\n ‫(أوال‪/‬ذكــر املدعــي يف خطابــه املــؤرخ يف ‪1429/11/20‬ه ـ الــذي قدمه‬\n ‫يف اجللســة املشــار إليهــا أعــاه أنــه قــام بتركيــب هاتــف هوائــي وذكــر‬\n ‫تكاليــف ذلــك (حســب رأيــه) وبالرجــوع إلــى محضــر االجتمــاع املــؤرخ‬\n ‫يف ‪1997/9/3‬م املوقــع مــن املدعــي أصالــة ورئيــس مجلــس إدارة‬\n\n\n                                                                                   ‫‪146‬‬\n\f      ‫الشــركة ‪ ........‬جنــده نــص يف الفقــرة (‪ )2‬منــه علــى أن تتكفــل‬\n      ‫الشــركة مبــا قيمتــه ‪ % 75‬مــن تكلفــة تأســيس هاتــف مشــروع‬\n      ‫الشــاليهات و‪ % 25‬يتحملهــا املســتثمر ‪ ........................./‬املدعــي علــى أن‬\n      ‫يــؤول جميــع ذلــك فيمــا بعــد إلــى الشــركة ‪ ،................‬ومــن هــذا النــص‬\n      ‫يتضــح لفضيلتكــم أن املقصــود تأســيس هاتــف يف املشــروع وليــس مــا‬\n      ‫ذكــره املدعــي والفــرق بينهمــا كبيــر وظاهــره فالتأســيس شــيء‬\n      ‫واالســتفادة مــن خدمــة قائمــة شــيء آخــر مختلــف متامــا ال ســيما وأنــه مت‬\n      ‫النــص علــى انتقــال جميــع ذلــك إلــى املدعــى عليــه‪ .‬ثانيا‪/‬مــع مــا ذكرنــاه‬\n      ‫أعــاه فــإن مــا قدمــه املدعــي مــن صــور فواتيــر ال يفيــد بــأن الهواتــف مت‬\n      ‫اســتخدامها للشــاليهات ال ســيما وأنها باســمه الشــخصي والذي يؤكد‬\n      ‫ذلــك أنــه اســتمر يف اســتخدامها إلــى تاريــخ ‪1424/2/10‬ه ـ مــع أنه ســلم‬\n      ‫املوقــع بتاريــخ ‪1419/6/27‬ه ـ مبــا يدحــض  قولــه بــأن هــذه الهواتــف هي‬\n      ‫للشــاليهات‪ .‬ثالثا‪/‬يطلــب املدعــي قيمــة األجهــزة مــع حتفظنــا علــى هــذه‬\n      ‫املطالبــة ويف الوقــت نفســه لــم يلتــزم مبــا نصــت عليــه الفقــرة (‪ )2‬مــن‬\n      ‫احملضــر املشــار إليــه أعــاه والتــي نصــت علــى ( أن يــؤول جميــع ذلــك إلى‬\n      ‫املدعــى عليهــا ) علــى فرضيــة أن قــول املدعــي باالســتفادة مــن هواتــف‬\n      ‫خاصــة بــه هــو املتفــق عليــه مــع املدعــى عليهــا وهــو غيــر صحيــح‪ .‬رابعــا‪/‬‬\n      ‫يطالــب املدعــي يف خطابــه املذكــور أعــاه بإلــزام املدعــى عليهــا بدفــع‬\n      ‫قيمــة اشــتراكات اخلطــن للهاتفــن مــن تاريــخ ‪1418/10/10‬هــ  وحتــى‬\n      ‫تاريــخ ‪1424/2/10‬ه ـ وهــذا جتــاوز للحــق الظاهــر حيــث أن املدعــي‬\n      ‫ســلم املوقــع بتاريــخ ‪1419/6/27‬ه وبالتالــي فليــس لــه احلــق يف املطالبــة‬\n      ‫بقيمــة اشــتراكات ‪ 45‬شــهرا بينمــا املــدة احلقيقيــة ال تتجــاوز ثمانيــة‬\n      ‫أشــهر‪ .‬خامســا‪/‬كيف يصــح للمدعــي املطالبــة بقيمــة اشــتراكات‬\n\n\n‫‪147‬‬\n\f‫شــهرية للهواتــف يف الوقــت الــذي هــو املســتفيد منهــا ســواء علــى فتــرة‬\n‫الثمانيــة أشــهر التــي متثــل املــدة احلقيقيــة التــي بــدأت مــن إدخــال الهواتــف‬\n‫حســب قولــه وانتهــت بتســليمه املوقــع‪ ،‬أو اخلمســة وأربعــن شــهرا التــي‬\n‫ذكرهــا‪ ،‬ممــا تقــدم يتضــح لكــم أن مطالبــة املدعــي غيــر صحيحــة‬\n‫وتســتند إلــى فهــم املدعــي الــذي يخالــف املســتندات والواقــع‪ ،‬لــذا فــإن‬\n‫موكلتــي تطلــب مــن فضيلتكــم رد مطالبــة املدعــي) أ‪.‬هــ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعــي أجــاب قائــا‪ :‬إن الهــدف هــو إيصــال اخلدمــة الســريعة‬\n‫للمشــروع وقــد مت حتقــق ذلــك وكان وقــت التنفيــذ هــي اخلدمــة املتاحــة‬\n‫ويعتبــر ذلــك مبثابــة التأســيس ولــو لــم يوجــد ذلــك التخــذ طريــق آخــر‪،‬‬\n‫ومحضــر التأســيس لــم يفــرق بــن ثابــت أو هوائــي وأن الهاتفــن منــذ‬\n‫تأسيســهما اســتخدمتها للمشــروع ولــم يتــم اســتخدامهما بصفــة‬\n‫شــخصية ومت االحتفــاظ بالهواتــف ورأينــا إبقائهــا حيــث أن القضيــة‬\n‫منظــورة باحملكمــة وملــا طالــت مت إلغاءهمــا والهاتفــن الوســيلة الوحيدة‬\n‫املســتخدمة يف املشــروع‪ ،‬وســمع ذلــك املدعــى عليــه وقــال مــا ذكــره‬\n‫املدعــي مــن أن اخلدمــة الوحيــدة هــي الهاتــف الهوائــي‪ :‬هــذا غيــر صحيــح‬\n‫حيــث يوجــد خدمــة التأســيس ولــو رأت موكلتــي اســتبدال خدمــة‬\n‫التأســيس بخدمــة أخــرى لنــص عليهــا ومــا ذكــره مــن أنــه اســتخدم‬\n‫الهواتــف حتــى مت إلغائهــا يف عــام ‪1424‬ه ـ هــذا يتناقــض مــع الواقــع ومــع‬\n‫محضــر تســليم املشــروع حيــث ســلم املشــروع يف ‪1419/6/27‬هــ‪،‬‬\n‫وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬إننــي لــم أذكــر أنهــا الوســيلة‬\n‫الوحيــدة وإمنــا هــي الوســيلة املتاحــة الســريعة لالســتفادة مــن املشــروع‬\n‫بصفــة عاجلــة وإن ذلــك يعتبــر مبثابــة التأســيس والهاتفــن لــم يتــم‬\n‫اســتخدامهما بعــد تســليم املشــروع ومت دفــع رســوم االشــتراك فقــط‪،‬‬\n\n\n                                                                                          ‫‪148‬‬\n\f      ‫وأضــاف املدعــى عليــه قائــا‪ :‬أن املدعــي أقــر بــأن هــذه اخلدمــة ليســت‬\n      ‫تأســيس وإمنــا هــي خدمــة بديلــة وهــذا خــاف االتفــاق مــع موكلتــي‪،‬‬\n      ‫ويف جلســة أخــرى لــدي أنــا ‪ .......................‬القاضــي اخللــف باملكتــب‬\n      ‫القضائــي ‪ .....‬وقــد جــرى مناقشــة املدعــي حــول بعــض اإلشــكاالت يف‬\n      ‫القضيــة فأبــدى اســتعداده لإلجابــة عنهــا محــررة ‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر املدعــي ‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــة‬\n      ‫‪ ................‬وقــدم املدعــي أصالــة مذكــرة مكونــة مــن ســبع صفحــات‬\n      ‫مــع عــدد مــن املرفقــات وفيهــا إجابــة عــن بعــض اإلشــكاالت التــي‬\n      ‫طــرأت‪ ،‬وهــذا نصهــا‪( :‬جتــدون أدنــاه أجوبــه لالستفســارات املطروحــة‬\n      ‫علــي مــن قبــل فضيلتكــم باجللســة املنعقــدة يف يــوم ‪1431/12/28‬ه ـ‬\n      ‫لنظــر القضيــة التــي رفعتهــا ضــد الشــركة ‪ ...................‬فقــد ســألني‬\n      ‫فضيلتكــم عــن ســبب طلبــي إيجــار الســنة األولــى وأجــرة الصيانــة‬\n      ‫فأقــول‪ :‬إنــه ال يخفــى علــى فضيلتكــم بــأن عقــدي مــع الشــركة عقــد‬\n      ‫اســتثماري وليــس عقــد ســكني والفــرق بينهمــا ظاهــر فعقــد االســتثمار‬\n      ‫تخويــل بالبحــث عــن مســتأجرين آخريــن (طــرف ثالــث) لالنتفــاع‬\n      ‫باملأجــور وذلــك عــن طريــق الدعايــة والترغيــب والعــرض والتســويق مــع‬\n      ‫توفيــر الصيانــة والتشــغيل وأي إعاقــة تعتــرض خطــة اســتثماره تؤثــر‬\n      ‫ســلبا يف تشــغيله وتكــون ســببا مباشــر يف خســارته‪ ،‬وعليــه فبعدمــا‬\n      ‫وقعــت مــع الشــركة عقــد إيجــار الشــاليهات وقعــت عقــد صيانتهــا‪،‬‬\n      ‫فصــارت بذلــك هــي املســؤولة الوحيــدة عــن أي تقصيــر يحــول دون منفعة‬\n      ‫اســتثمار الشــاليهات وقــد جعــل يف مــدة هذيــن العقديــن مــا يلــي‪/1 :‬‬\n      ‫هبــوط يف أرضيــات وممــرات الشــاليهات وتشــققات يف اجلــدران وحرصا‬\n      ‫منــي علــى ســامة مبنــى املشــروع وســامة مرتاديــه والعاملــن فيــه‬\n\n\n‫‪149‬‬\n\f‫استشــرت يف حالتــه االنشــائية جهــة هندســية متخصصــة وبعــد معاينــة‬\n‫املهندســن للموقــع أثبتــوا حالتــه املعيبــة بتقريرهــم املرفــق لفضيلتكــم‬\n‫صــورة منــه وعلــى ضــوء ذلــك أشــعرت الشــركة بخطــورة ذلــك يف وقــت‬\n‫مبكــر مرفقــا لهــم صــورة مــن التقريــر الهندســي‪ ،‬وبنــاء عليــه كتبــت‬\n‫الشــركة للمقــاول املنفــذ للمشــروع تعتــرف فيــه بخطــورة وضــع‬\n‫الشــاليهات وحتملــه كافــة املســؤولية ولعــل العيــوب اإلنشــائية التــي‬\n‫أثبتتهــا اجلهــة االســتثمارية احملايــدة واخلطــورة التــي اعترفــت بهــا‬\n‫الشــركة للمقــاول املنفــذ همــا الســبب الــذي جعــل الشــركة تفســخ‬\n‫العقــد برغبتهــا لعلمهــم أن العقــد الزم مــا لــم يطــرأ عليــه عــذر مينــع مــن‬\n‫االنتفــاع باملأجــور‪/2 .‬حصــل إهمــال مــن متعهــد الصيانــة (الشــركة‬\n‫‪ )..............‬خلزانــات امليــاه ومضخاتهــا التــي كانــت تفيــض بامليــاه احملالة‬\n‫ليــا وتصــب هــدرا مــارة بطــرق ومشــايات الشــاليهات أهملناهــا بذريعــة‬\n‫أنهــا لــم تكلــف الطاقــم الفنــي بالصيانــة بالعمــل يعــد الــدوام الرســمي‬\n‫ملدينتهــم لأللعــاب‪/3 .‬أهملــت الشــركة صيانــة الزراعــة ورعايــة‬\n‫املســطحات اخلضــراء ونبتــت حــول البحيــرة جــراء اإلهمــال أحــواش‬\n‫موحشــة تخيــف نــزالء الشــاليهات كمــا أهملــت رش املبيــدات احلشــرية‬\n‫حتى صارت الشــاليهات وحدائقها مرتفعا خصبا للقوارض واحلشــرات‪.‬‬\n‫‪/4‬امتنعــت الشــركة عــن صيانــة  وإصــاح أعطــال أجهــزة  االتصــال‬\n‫الهاتفيــة وأجهــزت اســتقبال القنــوات الفضائيــة متذرعــة بأنهــا ال متتلــك‬\n‫األرقــام الســرية لألجهــزة والتــي بدونها يتعذر عمــل أي صيانة‪ ،‬فاملقاول‬\n‫الــذي قامــوا بتعميــده لتنفيــذ أعمــال االتصــاالت هــو وحده الــذي يحتفظ‬\n‫باألرقــام ويرفــض قطعــا اطالعنــا عليهــا وهــذا الرفــض والتعنــت مــن‬\n‫قبــل الشــركة ومــن املقــاول املنفــذ يفــرغ القاعــدة الفقهية مــن مضمونها‬\n\n\n                                                                                       ‫‪150‬‬\n\f       ‫وهــي‪ :‬إلــزام املؤجــر بتمكــن املســتأجر مــن االنتفــاع بالعــن املعقــود‬\n       ‫عليهــا وذلــك بتســليمه العــن ومســتلزماتها حســب العــرف كاملفاتيــح‬\n       ‫واألرقــام ونحوهــا والتــي ال ميكــن حتقيــق االنتفــاع املطلــوب إال بهــا‪،‬‬\n      ‫كمــا ال يخفــى علــى فضيلتكــم أنــه إذا انصرمــت مــدة مــن غيــر متكني ‬\n       ‫املســتأجر مــن االنتفــاع باملعقــود عليــه ال يســتحق املؤجــر شــيئا مــن‬\n       ‫األجــرة ولــو مضــى مــن العقــد مــدة قبــل التمكني وهذا احلكم ينســحب‬\n       ‫علــى مبلغــي إيجــار الشــاليهات وصيانتهــا لعــدم انفــكاك أحدهمــا علــى‬\n       ‫اآلخر‪ ،‬وجاء يف عقد الشــاليهات بند (‪ )18‬يســمح  لشــاغلي الشــاليهات‬\n       ‫بالدخــول ملدينــة األميــر محمــد بــن فهــد ويتــم ربطهــا مــع برامــج تســويقية‬\n       ‫مشــتركة وعمــل حوافــز للســكان يتــم االتفــاق عليهــا مــع مراعــاة‬\n       ‫إمكانية ذكر الشــاليهات يف إعالنات الشــركة الشــيخ‪................... /‬‬\n       ‫وبحضــور مديــر عــام الشــركة الســيد ‪ ..................‬التــزم لــي شــفاهه‬\n       ‫رئيــس مجلــس اإلدارة بتحميــل الشــركة مــا نســبته ‪ % 25‬مــن مصاريــف‬\n       ‫الدعايــة التــي ســوف أصرفهــا علــى الشــاليهات‪ ،‬فــكل هــذا اإلهمــال‬\n       ‫والتقصيــر مــن قبــل الشــركة إخــال بعقــدي التأجيــر والصيانــة‬\n       ‫باإلضافــة للنكــوص عمــا يتــم االلتــزام بــه أثنــاء اجتماعــي بهــم ويف ثنايــا‬\n       ‫مكاتبتــي لهــم فصــارت الشــركة ســببا مباشــرا يف فشــل اســتثماري‬\n       ‫ملشــروع الشــاليهات بــل هــو الســبب املتعمــد والوحيــد ونتيجــة لذلــك تعذر‬\n       ‫احلصــول علــى منفعــة االســتثمار التــي مت التعاقــد‪ ،‬وعليــه تكــون‬\n       ‫الشــركة هــي املتســبب يف خســارتي وهــي الغــارم الوحيــد املبلــغ إليجــار‬\n       ‫والصيانــة‪ ،‬وعــن ســؤال فضيلتكــم عــن صحــة اســتالم الشــركة‬\n       ‫لألجهــزة اإلضافيــة وهــل  وقعــت الشــركة علــى االســتالم‪ ،‬فأقــول‪ :‬نعــم‬\n       ‫لقد اســتلمت الشــركة ‪ ..............‬األجهزة اإلضافية التي قمت بتأمينها‬\n\n\n‫‪151‬‬\n\f‫مــن حســابي اخلــاص ووقــع علــى االســتالم نائــب مديــر عــام الشــركة‬\n‫أ‪ ......../‬وذلــك ضمــن محضــر اســتالم الشــاليهات والــذي جــاء فيــه مــا‬\n‫نصــه‪( :‬وعليــه فقــد اســتلمت الشــركة ‪ ............‬ملراكــز الترفيــه‬\n‫الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة‬\n‫لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر وتعتبــر مــن‬\n‫تاريــخ ‪1419/6/27‬ه ـ املوافــق ‪1998/10/17‬م بحوزتهــم وحتــت‬\n‫ـدي مــا ُيثبــت أن الهواتــف‬ ‫مســئوليتهم)‪ ،‬وعــن ســؤال فضيلتكــم هــل لـ ّ‬\n‫اســتخدمت يف الشــاليهات فأقــول‪ :‬إنــه ال يخفــى علــى فضيلتكــم بــأن‬\n‫شــركة ‪ .....‬هــي القــادرة علــى اإلجابــة علــى هــذا الســؤال إمــا مــن خــال‬\n‫تركيــب اخلدمــة الهاتفيــة باملوقــع أو مــن خــال الفواتيــر ومبــا أنــه لــم‬\n‫تتوفــر آنــذاك فقــد وفــرت خدمــة هاتفيــة هوائيــة كالتــي تســتخدم يف‬\n‫املــزارع واملناطــق البعيــدة عــن املدينــة وبعــد إنهــاء التعاقــد تركــت‬\n‫أجهــزت االتصــال الهوائيــة يف الشــاليهات‪ ،‬أمــا رقمــي الهاتــف التــي‬\n‫باســمي فقــد أبقيتهــا ســارية املفعــول أدفــع لهــا رســوم اشــتراك شــبكة‬\n‫فقــط وكنــت منتظــرا إمــا أن تقــوم الشــركة ‪ ..............‬بنقــل األرقــام‬\n‫باســمها وإمــا أمــر القاضــي بقطــع االشــتراك وقــد مت إيقــاف االشــتراك‬\n‫بتاريــخ ‪1424/3/26‬هــ‪ ،‬وعــن ســؤال فضيلتكــم عــن املخالصــة التــي‬\n‫متــت بــن الطرفــن هــل فيهــا قيــود أم مخالصــة مطلقــة فأقــول إننــي ال‬\n‫أعلــم الفــرق بــن املخالصــة املقيــدة مــن املخالصــة املطلقــة لكنــي ســوف‬\n‫أصــف لفضيلتكــم أدنــاه مراحــل وآليــات املخالصــة التــي متــت بيننــا‬\n‫فيمــا يلــي‪/1 :‬جــاء يف التمهيــد لعقــد اإليجــار مــا نصــه‪( :‬إن الطــرف‬\n‫الثانــي (املســتثمر) لديــه الرغبــة األكيــده يف اســتثمار هــذا املشــروع)‪،‬‬\n‫وجــاء يف البنــد رقــم (‪  )10‬أن أعمــال الصيانــة تقــع علــى عاتــق املســتثمر‬\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫مــع االلتــزام يجــدول صيانــة وقائــي وكفائــه عاليــه مــع التفتيــش‬\n      ‫والتوجيهــات مــن فعــل الطــرف األول‪ ،‬ومثلــه البنــد (‪ )11‬امللــزم بصيانــة‬\n      ‫املســطحات اخلضــراء واحملافظــة علــى نظــام الــري وبركــة الســباحة‬\n      ‫وبعــد عقــد الصيانــة الالحــق لعقــد تأجيــر الشــاليهات انقلبــت شــروط‬\n      ‫الصيانــة علــى الطــرف األول (الشــركة ) فمــا كان يف العقــد  واجبــا‬\n      ‫للطــرف الثانــي صــار حقــا لــه ومــا كان حــق للطــرف األول صــار واجبــا‬\n      ‫عليــه وجــاء يف البنــد (‪( )12‬ويف حالــة وجــود أي عيــوب يف املشــروع‬\n      ‫يتحمــل الطــرف األول إصالحهــا) وبعــد إشــعاري للشــركة خطيــا‬\n      ‫بالعيــوب اإلنشــائية يف املشــروع والتــي أثبتتهــا اجلهــة املختصــة مبوجــب‬\n      ‫التقريــر الهندســي الــذي أرفقتــه لهــم انتهــت حالــة التعاقــد مــع الشــركة‬\n      ‫وهــم يكاتبــون املقــاول املنفــذ للمشــروع حيــث رآه املســؤولون يف‬\n      ‫الشــركة أن عقــد الصيانــة وإثبــات العيــوب اإلنشــائية حمــل ثقيل عليهم‬\n      ‫ال أحتملــه‪ ،‬فتلمســوا املخــارج واحليــل إلنهــاء التعاقــد وصياغــة‬\n      ‫املخالصــات‪/2 .‬كتبــت لــي الشــركة متهيــدا إلنهــاء التعاقــد خطابــا‬\n      ‫يطلبــون فيــه االجتمــاع بــي ليبلغونــي برغبتهــم يف إنهــاء التعاقــد ويف يــوم‬\n      ‫االجتمــاع مت إنهــاء عقــد اإليجــار بنــاء علــى رغبــة الشــركة وكان‬\n      ‫توقيعــي علــى املخالصــة مــن أجــل إيقــاف الضــرر املتمثــل بســريان مفعــول‬\n      ‫العقــد مــع حجــب املنفعــة مــن املأجــور وقعــت بتحفــظ شــديد علــى حفــظ‬\n      ‫حقوقــي فلــو لــم أوقــع لطالبونــي فــورا بقيمــة إيجــار الســنة اجلديــدة‬\n      ‫فأكــون قــد أخليــت بالبنــد (‪ )23‬فقــرة (ب) والتــي تنــص علــى أنــه إذا‬\n      ‫تأخــر الطــرف الثانــي (املســتثمر) عــن ســداد أي دفعــة مســتحقة يكــون‬\n      ‫للطــرف األول (الشــركة) احلــق يف مصــادرة الضمــان‪ ،‬ثــم تــا  هــذا‬\n      ‫االجتمــاع محضــر جــرد موجــودات ومفقــودات وتســليم املوقــع ومــا زالــت‬\n\n\n‫‪153‬‬\n\f  ‫حقوقــي املاليــة والتعويضيــة معلقــة يف ذمــة الشــركة حتــى تاريخــه ومــا‬\n  ‫زالــت الشــركة متاطــل يف تنفيــذ وتفعيــل الشــرط الــذي ينــص علــى‬\n  ‫التــزام الطرفــن‪( :‬بإمتــام التســويات واملطالبــات املاليــة كل فيمــا يخصه‬\n  ‫بعــد التوقيــع مباشــرة علــى محضــر اســتالم الشــاليهات) ممــا ســبق مــن‬\n  ‫وصــف مراحــل املخالصــة يســتطيع فضيلتكــم باالســتنتاج احلكــم علــى‬\n  ‫املخالصــة بأنهــا مطلقــة أم مقيــدة‪ ،‬وبطلــب فضيلتكــم البينــة علــى أن‬\n  ‫الرصيــف البــري داخــل ضمــن العقــد رغــم أن العقــد منحصــر يف ‪60‬‬\n  ‫شــاليه فأقــول أن العقــد منحصــر يف ‪ 60‬دون ذكــر األلعــاب ودون ذكــر‬\n  ‫ملواقــف الســيارات ودون ذكــر للمســجد ونحــو ذلــك لكنهــا كلهــا‬\n  ‫داخلــة ضمنــا يف العقــد مبــا فيهــا الرصيــف البحــري بــل أن البينــة ظاهــرة‬\n  ‫يف تواتر القرائن املشــاهدة واملكتوبة والتي تثبت اســتحقاق االســتفادة‬\n  ‫مــن الرصيــف البحــري فقــد التــزم لــي رئيــس مجلــس إدارة الشــركة‬\n  ‫بوقــت مبكــر والتــزم معــه نائــب املديــر العــام بســرعة تنفيــذ الرصيــف‬\n  ‫البحــري مبوجــب توقيعهــا علــى محضــر اجتمــاع يــوم األحــد املوافــق‬\n  ‫‪1997/10/19‬م الــذي أوصــى املوقعــون عليــه‪( :‬بإعــادة صبيــة املزلقــان‬\n  ‫لوضعهــا الصحيــح برفعهــا وتســوية قاعدتهــا وترتيبهــا) ممــا تعهــد أيضــا‬\n  ‫مديــر عــام الشــركة شــرحا بخــط يــده علــى خطابــي‪( :‬وأقــول خطابــي‬\n  ‫أنــا) قائــا  لقــد مت توجيــه التعليمــات إلــى الســيد‪/‬مدير املشــاريع‬\n  ‫لالتصــال بالشــركات املختصــة بذلــك إلنهــاء اإلجــراءات ملــا يخــص‬\n‫املوضــوع أعــاه ( إجنــاز الرصيــف البحــري ) وســيتم التنفيذ بعد االتفاق  ‬\n  ‫مــع أحدهــم‪ ،‬وهــل كل ذلــك عبــث ومراوغــة أم التــزام وتعهــد مكتــوب‬\n  ‫وموقــع عليــه وبينــة داحضــة‪ ،‬هــذا باإلضافــة إلــى أن الشــركة خصصت‬\n  ‫بابــا واســعا ركبــت منــه حاجــزا حديــدا علقــت عليــه لوحــة كتبــت فيهــا‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫(مزلــق القــوارب املائيــة ) وحبــث حولــه قطعتــن كبيرتــن مــن اخلرســانة‬\n      ‫املســلحة كل هــذه القرائــن والبينــات كانــت أثنــاء معاينــة املشــروع‬\n      ‫وقبــل التوقيــع علــى عقــد االســتثمار‪ ،‬وعليــه فيكــون عــدم تنفيــذ‬\n      ‫الرصيــف إمــا ســلب حلقوقــي أو مــن بــاب تزيــن الســلعة مبــا ليــس فيهــا‬\n      ‫وهــذا غــش متعمــد وال أظنــه يخفــى علــى فضيلتكــم أن الغــش يدخــل‬\n      ‫املكتســبات‪ ،‬أمــا بخصــوص الســؤال عــن مســوغ طلــب التعويــض عــن‬\n      ‫األربــاح املتوقعــة عــن (‪ )9‬ســنوات فــإن املــادة (‪ )23‬فقــرة ه ـ تقــول‪( :‬إن‬\n      ‫الطــرف األول الشــركة احلــق يف فســخ العقــد يف حالــة عــدم قيــام‬\n      ‫الطــرف الثانــي املســتثمر بأعمــال الصيانــة علــى الوجــه املطلــوب‬\n      ‫ومصــادرة الضمانــات بعــد خصــم التلفيــات والضمانــات ومصاريــف‬\n      ‫أخــرى) وبعــد مــا صــارت الشــركة هــي املطالبــة بالصيانــة مبوجــب عقد‬\n      ‫إيجابــي وشــيكات مدفوعــة ولــم تقــم بأعمــال الصيانــة علــى الوجــه‬\n      ‫املطلــوب انقلــب الســحر علــى الســاحر‪ ،‬فصــارت الشــركة هــي الغارمــة‬\n      ‫عــن كل خســارة كانــت هــي املتســبب فيهــا‪ ،‬وعليــه فيلزمهــا دفــع قيمــة‬\n      ‫التلفيــات ومصاريــف أخــرى كمــا جــاء يف العقــد فمــن املصاريــف‬\n      ‫تكلفــة اســتقدامي لطاقــم إداري وفنــي متخصــص مــن اجــل إدارة‬\n      ‫املشــروع تســعة ســنوات متبقيــة يف العقــد‪ ،‬إضافــة إلــى أن مؤسســة‬\n      ‫‪ ....................‬للمفروشــات عرضــت علـ ّـي مليــون ريــال كخلــو وقــد‬\n      ‫رفضــت هــذا املبلــغ يف حينــه لعــدم كفايتــه‪ ،‬فهــذا مســوغ كاف لطلــب‬\n      ‫التعويــض كمــا وقــع علـ ّـي مــن خســائر وفاتنــي مــن أربــاح‪ ،‬ويف اخلتــام‬\n      ‫آمــل أن يســمح لــي فضيلــة الشــيخ أن أحيلــه للمذكــرة املقيــدة بــوارد‬\n      ‫الشــيخ‪ .................../‬رقم ‪ 7024‬وتاريخ ‪1424/4/29‬هـ لعلكم جتدون‬\n      ‫فيهــا إيضــاح للمجمــل أعــاه‪ ،‬هــذا وجتــدون برفقــه صــورة معــه عقــد‬\n\n\n‫‪155‬‬\n\f‫الشــاليه رقــم (‪ )6‬حســب طلبكــم مرفقــا بــه كشــف حســاب مــن‬\n‫الشــركة يثبــت حتصيلكــم حلســابنا مــن املســتأجر قمــة إيجــار الشــاليه‬\n‫ووثائــق تثبــت صحــة إجابتــي علــى استفســارات فضيلتكــم وأحيــط‬\n‫فضيلتكــم كذلــك بــأن خروجنــا مــن الشــاليهات كان بتاريــخ‬\n‫‪1419/6/10‬ه ـ املوافــق ‪1998/10/1‬م‪ ،‬ويف جلســة أخــرى حضــر‬\n‫املدعــي ‪ ............‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .......‬وقــدم‬\n‫مذكــرة مكونــة مــن أربــع صفحــات ســيجري رصدهــا الحقــا ونــص‬\n‫املقصــود منهــا‪( :‬وجوابــا علــى املذكــرة املســلمة لــي بجلســة األحــد‬\n‫‪1432/11/18‬ه ـ ومــا تضمنــه مــن إجابــات املدعــي أورد لفضيلتكــم‬\n‫جــواب موكلتــي علــى النحــو التالــي‪ :‬أوال‪/‬مــا ذكــره املدعي من أســباب‬\n‫تبــرر طلبــه إيجــار الســنة األولــى وأجــرة الصيانــة فهــي غيــر صحيحــة‬\n‫جملــة وتفصيــا ودليــل ذلــك أن املدعــي وافــق علــى إنهــاء العقــد واإلقالــة‬\n‫منــه مبوجــب محضــر تســليم الشــاليهات املــؤرخ يف ‪1998/10/17‬م دون‬\n‫أي حتفــظ أو اســتثناء بــل إن املدعــي أقــر هــذا احملضــر بأنــه ملتــزم‬\n‫بالنواقــص واملفقــودات حيــث ورد يف احملضــر‪ :‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‬\n‫واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات اجلــرد املرفقــة واملوقعــة مــن‬\n‫ممثلــي الطرفــن‪ ،‬وعليــه يكــون اســتكمال النواقــص واملفقــودات إمــا‬\n‫باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة ال تقــل عنهــا جــودة وإن‬\n‫تعــذر ذلــك فيتــم تقييــم  أســعار كل منهمــا حســب مــا جــاء يف بيانــات‬\n‫اســتالمها العــام املاضــي مــع مراعــاة العمــر االفتراضــي حســبما ورد يف‬\n‫العقــد‪ ،‬وبالتالــي فــإن موكلتــي هــي التــي لهــا حقــوق لــدى املدعــي‬\n‫وليــس بالعكــس ويؤكــد ذلــك اخلطابــان الصــادران مــن املدعــي‬\n\n\n                                                                                       ‫‪156‬‬\n\f      ‫املرفقــان رقــم (‪1‬ـ‪ )2‬اخلطــاب األول‪ :‬بتاريــخ ‪1998/12/1‬م أي بعــد إنهــاء‬\n      ‫العقــد وتســليم الشــاليهات بشــهرين والــذي ينــص فيــه علــى مــا يلــي‪:‬‬\n      ‫(يســرنا إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه وفــق خطاباتكــم‬\n      ‫املشــار إليهــا) واخلطــاب الثانــي‪ :‬بتاريــخ ‪1998/12/30‬م والــذي نــص‬\n      ‫فيــه علــى مــا يلــي‪( :‬يبــدو ذلــك بغيــة الوصــول إلــى حلــول مرضيــة مثلهــا‬\n      ‫مثــل املواضيــع األخــرى التــي مت حلهــا كل واحــدة علــى حــدة لــذا‬\n      ‫نفيدكــم مبوافقتنــا علــى مطالبتكــم هــذه حســب خطابيكــم املشــار‬\n      ‫إليهــا واخلاصــة باســتهالك الكهربــاء‪ ،‬وعليــه نأمــل منكــم قيــد املبلــغ‬\n      ‫املوضحــة بعاليــه برفقنــا لصاحلكــم وقــدره ‪225135‬ريــاال باإلضافــة‬\n      ‫إلــى املبالــغ املســتحقة علينــا والتــي ســبق أن وافقنــا عليهــا كتابيــا) ومــن‬\n      ‫هــذا اخلطــاب يتضــح لفضيلتكــم مــا يلــي‪/1 :‬إقــرار املدعــي صراحــة‬\n      ‫بأنــه مت حــل املواضيــع بــن الطرفــن بحلــول مرضيــة ولــم يتبــق شــيء لــم‬\n      ‫يحــل ولــو تبقــى شــيء لــم يحلــه الطرفــان ألســتثناه املدعــي‪/2 .‬أن هــذان‬\n      ‫اخلطابــان تاريخهــا الحــق لتاريــخ إنهــاء العقــد وتســليم الشــاليهات‬\n      ‫وبالتالــي فــا توجــد أي تخوفــات أو ضغــوط علــى املدعــي كمــا يدعــي‬\n      ‫تدفعــه للتعجــل وكتابــة مثــل هــذا اإلقــرار‪/3 .‬أن موكلتــي هــي صاحبــة‬\n      ‫احلــق جتــاه املدعــي وليــس العكــس فهــو يقــول‪( :‬باإلضافــة إلــى املبالــغ‬\n      ‫املســتحقة علينــا والتــي ســبق أن وافقنــا عليهــا )‪/4 .‬مــا تضمنــه هــذان‬\n      ‫اخلطابــان مــن إقــرارات املدعــي ومــا تضمنــه محضــر اســتالم الشــاليهات‬\n      ‫يؤكــد أن املدعــي غيــر محــق يف دعــواه وأن احلــق ملوكلتــي‪ ،‬إضافــة ملــا‬\n      ‫ســبق إيــراده فــإن املدعــي تســلم الشــاليهات كاملــة بــكل جتهيزاتهــا‬\n      ‫وفــق إقــراره املرفقــة صورتــه (رقــم ‪ )3‬ومــن ضمنهــا جهــاز مركــزي‬\n      ‫للهاتــف مــع أربــع خطــوط جــوال ماركــة أي تــي تــي  مــع التوصيــات‬\n\n\n‫‪157‬‬\n\f‫والتجهيــزات وأجهــزة التحكــم مــع عــدد ‪ 92‬جهــاز هاتــف ماركــة أي‬\n‫تــي تــي مــع شــريحة هاتــف نقــال رقــم ‪( ...............‬ص ‪ 2‬فقــرة ‪ 5‬مــن‬\n‫املرفــق ) ومــع مــا تقــدم ال يــزال املدعــي يصــر علــى أن موكلتــي أخلــت‬\n‫بالتزاماتهــا يف العقــد الــذي وافــق علــى إنهائــه بــإرادة حــرة‪ ،‬ثانيــا‪:‬‬\n‫بخصــوص اســتالم موكلتــي لألجهــزة اإلضافيــة مــن عدمــه لــم يتضــح‬\n‫مــا املقصــود باألجهــزة اإلضافيــة فــإذا كان املقصــود النواقــص‬\n‫واملفقــودات فــإن موكلتــي لــم تســتلمها إطالقــا ودليــل ذلــك هــو مســتند‬\n‫املدعــي الــذي أورده ولــم يكملــه‪ ،‬ألنــه يدينــه حيــث جــاء يف محضــر‬\n‫اســتالم الشــاليهات الــذي اســتند إليــه املدعــي‪( :‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‬\n‫واملــواد فقــط اخلاصــة بالصيانــة وفــق بيانــات اجلــرد املرفقــة واملوقعــة مــن‬\n‫ممثلــي الطرفــن وعليــه يكــون اســتكمال النواقــص واملفقــودات إمــا‬\n‫باســتبدالها بنفــس النوعيــة أو بأخــرى مماثلــة ال تقــل عنهــا جــودة وإن‬\n‫تعــذر ذلــك فيتــم تقييــم أســعار كل منهــا حســب مــا جــاء يف بيانــات‬\n‫اســتالمها العــام املاضــي مــع مراعــاة العمــر االفتراضــي حســب مــا جــاء‬\n‫يف العقــد)‪ ،‬واملقصــود ببيــان اســتالمها العــام املاضــي هــو املرفــق رقــم‬\n‫(‪ )3‬بهــذه املذكــرة أمــا إن كان املقصــود باألجهــزة اإلضافيــة أشــياء‬\n‫أخــرى فــإن موكلتــي تطلــب بينــة املدعــي علــى تســليمها لهــا‪ .‬ثالثــا‪/‬‬\n‫بخصــوص الهواتــف وهــل اســتخدمت يف الشــاليهات‪ ،‬أقــر املدعــي بأنــه‬\n‫وفــر خدمــة هاتفيــة هوائيــة ومعلــوم أن الهاتــف الهوائــي هــو اســتفادة مــن‬\n‫خدمــة قائمــة وليســت تأســيس كمــا ال يخفــى علــى نظــر فضيلتكــم أن‬\n‫اخلدمــة الهوائيــة التــي ذكرهــا املدعــي (يف ضبــط إحــدى اجللســات‬\n‫الســابقة أقــر بأنــه اســتخدم جهــاز ســيناو) غيــر نظاميــة و ال يوجــد لــدى‬\n\n\n                                                                                       ‫‪158‬‬\n\f        ‫املدعــي مــا يفيــد مبوافقــة موكلتــي علــى هــذه اخلدمــة‪ ،‬كمــا أقــر‬\n        ‫املدعــي بــأن الهاتــف باســمه ولــم يقــدم مــا يثبــت أنــه مت تركيبــه يف‬\n        ‫الشــاليهات ومنعــا لإلطالــة يف هــذه النقطــة أحيــل نظــر فضيلتكــم إلــى‬\n      ‫مذكرتــي املقدمــة بجلســة ‪1429/5/30‬ه ـ مرفــق صورتهــا رقــم ‪  4‬‬\n        ‫وألفــت نظــر فضيلتكــم إلــى أن املدعــي أقــر بأنــه اســتلم أجهــزة هاتــف‬\n        ‫وشــريحة جــوال الســتخدامها يف الشــاليهات مرفــق رقــم ‪ .3‬رابعــا‪/‬‬\n        ‫بخصــوص املخالصــة بــن الطرفــن وهــل هــي مطلقــة أم مقيــدة‪ ،‬فإننــي‬\n        ‫أكتفــي مبــا أوردتــه يف الفقــرة أوال مــن هــذه املذكــرة والتــي تبــن أن‬\n        ‫العالقــة التعاقديــة مــع املدعــي انتهــت مبوجــب تلــك املخالصــة و تبقــى يف‬\n        ‫ذمتــه مــا نصــت عليــه‪ ،‬وأمــا قولــه بأنــه وقّ ــع املخالصــة إليقــاف الضــرر‬\n        ‫الــذي يدعيــه وأنــه وقــع بتحفــظ شــديد علــى حفــظ حقوقــه‪ ،‬فغيــر‬\n        ‫صحيــح وتناقضــه يف إقراراتــه يف خطابيــه الذيــن أشــرت إليهــا يف الفقرة‬\n        ‫أوال مــن هــذه املذكــرة‪ .‬خامســا‪/‬بخصوص طلــب فضيلتكــم البينــة‬\n        ‫مــن املدعــي علــى أن الرصيــف البحــري داخــل ضمــن العقــد رغــم أنــه‬\n        ‫منحصــر يف الســتني شــاليه‪ ،‬مــع األخــذ مبــا ذكرتــه يف أوال مــن هــذه‬\n        ‫املذكــرة‪ ،‬فــإن املدعــي يدعــي أن الرصيــف البحــري داخــل ضمــن‬\n        ‫العقــد‪ ،‬وقــد طلبتــم فضيلتكــم منــه البينــة علــى ذلــك ولــم يقدمهــا؛ ألنــه‬\n        ‫ال توجــد لديــه بينــة‪ ،‬وهــذا هــو الصحيــح فالرصيــف البحــري ليــس‬\n        ‫ضمــن العقــد وقــد أقــر املدعــي بذلــك يف خطابــه الــذي اســتند إليــه‬\n        ‫املرفــق رقــم (‪ )5‬حيــث قــال‪ ...( :‬وعدمتونــا باســتكمال املنزلــق البحــري‬\n        ‫‪...‬الــخ) فــا يخــرج األمــر عــن وعــد والوعــد كمــا هــو معلــوم غيــر ملــزم‬\n        ‫كمــا أن الوعــد بالتنفيــذ معلــق باالتفــاق مــع أحدهــم وليــس ناجــزا‪.‬‬\n        ‫سادســا‪/‬بخصوص مســوغ طلــب املدعــي التعويــض عــن األربــاح املتوقعــة‬\n\n\n‫‪159‬‬\n\f‫عــن تســع ســنوات‪ ،‬كمــا أنــه توقــع أن تكــون هنــاك أربــاح فإنــه توقــع‬\n‫أن تكــون هنــاك خســائر نتيجــة لعــدم قدرتــه علــى إدارة املشــروع‬\n‫بطريقــة اســتثمارية ناجحــة وهــذا التوقــع هــو الــذي دفعــه إلنهــاء العقــد‬\n‫وتســليم الشــاليهات‪ ،‬وكمــا أوردت يف أوال مــن هــذه املذكــرة فــإن‬\n‫إنهــاءه للعقــد ال يجعــل لــه احلــق يف املطالبــة بشــيء الســيما مــع إقراراتــه‬\n‫أن بذمتــه حقــوق ملوكلتــي كمــا ســبق إيضاحــه‪ .‬ســابعا‪/‬ملوكلتي يف‬\n‫ذمــة املدعــي مبالــغ إجماليهــا ‪( 1360802,62‬مائــة وســتة وثالثــون ألفــا‬\n‫وثمامنائــة وريــاالن واثنــان وســتون هللــه) مفصلــة علــى النحــو التالــي‪/1 :‬‬\n‫فواتيــر هاتــف جــوال الشــاليهات املســتحق ‪ 2505,82‬ريــال حســب العقد‪.‬‬\n‫‪/2‬املنصــرف مــن املخــزون لصيانــة الشــاليهات املســتحق ‪ 4939,34‬ريــال‬\n‫حســب العقــد‪/3 .‬قيمــة املســتهلك مــن الكهربــاء املســتحق ‪78899,33‬‬\n‫حســب العقــد ‪/4‬قيمــة املســتهلك مــن امليــاه املســتحق ‪ 73688,63‬ريــال‬\n‫حســب العقــد اإلجمالــي ‪ 160033,12‬ريــال يطــرح منــه املســدد مــن‬\n‫فواتيــر الهاتــف ‪ 1683‬ريــال وقيمــة إيجــار ســنوي مــن قبــل الشــركة‬\n‫الســعودية ‪ 39500‬ريــال صــايف املســتحق ‪ 11885012‬ريــال تضــاف‬\n‫املصاريــف التاليــة عنــد االســتالم نواقــص وتالــف عنــد اســتالم‬\n‫الشــاليهات ‪ 15900‬ريــال وقيمــة مــواد صيانــة الزمــة إلصــاح بعــض‬\n‫التلــف ‪ 1240‬ريــال وقيمــة إصــاح أســرة ‪ 81250‬ريــال إجمالــي املســتحق‬\n‫‪ 3680262‬ريــال وحيــث أن املدعــي يقــر بــأن يف ذمتــه حقــوق ماليــة‬\n‫ملوكلتــي‪ ،‬فــإن موكلتــي تطلــب مــن فضيلتكــم مــا يلــي‪/1 :‬احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي‪/2 .‬احلكــم بإلــزام املدعــي دفــع مــا‬\n‫بذمتــه ملوكلتــي مــن مســتحقات ماليــة إجماليهــا ‪ 120000‬مائــة‬\n‫وعشــرون ألــف ريــال‪/3 .‬احلكــم بإلــزام املدعــي دفــع أجــرة احملامــاة‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫وقدرهــا مائــة وعشــرون ألــف ريــال الشــركة ‪ ..............‬أ‪.‬ه ـ عنــد هــذا‬\n      ‫املوضــع رفعــت اجللســة مــع إفهــام املدعــي بإحضــار جوابــه على مــا ذكره‬\n      ‫املدعــى عليــه وكالــة بخصــوص اخلطــاب الصــادر مــن املدعــي املــؤرخ يف‬\n      ‫‪1998/12/30‬م‪ ،‬ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى‬\n      ‫عليــه وقــدم املدعــي مذكــرة نصهــا كالتالــي‪ :‬أوال‪/‬حــن لــم يســتطع‬\n      ‫محامــي الشــركة أن يفنــد مــا جــاء مبذكراتــي حــاول جاهــدا بــأن‬\n      ‫يشــطب الدعــوى مــن أساســها وذلــك بتجاهــل القــرار األخيــر الصــادر‬\n      ‫مــن مجلــس القضــاء األعلــى بهيئتــه الدائمــة رقــم ‪/2/97‬س يف‬\n      ‫‪1430/2/13‬ه ـ األمــر الــذي بســببه قــد يتأخــر البــت يف هــذه القضيــة‪.‬‬\n      ‫ثانيــا‪ /‬أن مبــررات طلــب قيمــة إيجــار الســنة األولــى وقيمة أجــرة الصيانة‬\n      ‫ليســت متوقفــة علــى إنهــاء العقــد وال علــى اإلقالــة منــه وال علــى محضــر‬\n      ‫التســليم الشــاليهات بــل حــق ثبــت بتعــذر حصــول منفعــة االســتثمار‬\n      ‫املنفعــة التــي مــن اجلهــا مت التعاقــد وتعــذر حصولهــا بســبب العيــوب‬\n      ‫اإلنشــائية واملعماريــة التــي ظهــرت يف املشــروع يف بدايــة التشــغيل والتــي‬\n      ‫شــهدت بهــا جهــة هندســية محايــدة واعتــرف بخطورتهــا نائــب مديــر‬\n      ‫عــام الشــركة بخطابــه املــؤرخ يف ‪1998/2/25‬م املوجــه للمقــاول منفــذ‬\n      ‫املشــروع أضــف علــى ذلــك رفــض الشــركة إلعمــال الصيانــة امللتزمــة‬\n      ‫بهــا مبوجــب عقــد موقــع مــن رئيــس مجلــس إدارة الشــركة ودعــم‬\n      ‫اســتالمهم ألجــرة الصيانــة مبوجــب شــيكات موثقــة باإلضافــة إلــى‬\n      ‫رفــض اجنــاز الرصيــف البحــري وغيــر ذلــك مــن عوائــق اســتثمار‬\n      ‫الشــاليهات‪/3 .‬أن العبــارة التــي وردت بخطابــي املوجهــة للشــركة‬\n      ‫بتاريــخ ‪1998/12/1‬م ونصهــا‪( :‬لــذا يســرنا   إفادتكــم مبوافقتنــا‬\n      ‫مطالباتكــم هــذه ‪ )..‬إمنــا هــي تفعيــل وتطبيــق ملــا ورد يف محضــر تســليم‬\n\n\n‫‪161‬‬\n\f‫الشــاليهات والــذي نصــه‪( :‬أمــا مــن حيــث النواحــي املاليــة فســوف تتــم‬\n‫التســويات املطالبــات املاليــة مــن الطرفــن كل فيمــا يخــص) فقــد وفيت‬\n‫وأبــرأت ذمتــي ممــا يخصهــم أمــا مــا يخصنــي وهــي حقوقي التــي بذمتهم‬\n‫فبعــد إنكارهــم لبعضهــا واملماطلــة يف دفــع بعضهــا اآلخــر أقمــت عليهــم‬\n‫هــذه الدعــوى‪ ،‬وأمــا خطابــي املوحــد للشــركة بتاريــخ ‪1998/12/30‬م‬\n‫فهــو خــاص مبوضــوع اســتهالك الكهربــاء فقــط واملقصــود بعبــارة‪:‬‬\n‫(املواضيــع األخــرى التــي مت حلهــا كل علــى حــدة) إشــارة إلــى االتفاقــات‬\n‫معهــم والتوصــل لتحديــد قيمــة املفقــودات والتالــف مــن التجهيــزات‬\n‫واألســرة ومــواد الصيانــة املفصلــة بخطابــي املــؤرخ يف ‪1998/12/1‬م‬\n‫وبنــاء عليــه يتضــح لفضيلتكــم بــأن محضــر تســليم الشــاليهات مــا هــو‬\n‫إال تســليم للموقــع بجميــع محتوياتــه‪ :‬أوال‪/‬علــى أن تتــم التســويات املاليــة‬\n‫الحقــا ولــم يســتحق إال مــا يخصنــي مــن حقــوق وتعويضــات مــا زالــت‬\n‫حتــت نظــر فضيلتكــم رابعــا‪/‬إن التجهيــزات اإلضافيــة التــي أمنتهــا‬\n‫للشــاليهات مــن حســابي اخلــاص ســبق وأن أدرجتهــا ببيــان مفصــل مرفــق‬\n‫بصــور مــن فواتيــر الشــراء رفعتهــا بخطــاب وجهتــه لفضيلــة عضــو العامة‬\n‫بالدمام‪/‬الشــيخ ‪ ..................‬وهــو مســجل بــوارد احملكمــة رقــم‬\n‫‪ 27/25284‬يف ‪1427/12/4‬ه ـ وأمــا البينــة علــى اســتالم الشــركة‬\n‫لهــذه األجهــزة فهــي مــا جــاء مبحضــر اســتالم الشــاليهات املــؤرخ يف‬\n‫‪1419/6/27‬ه ـ واملوقــع منــي ومــن نائــب مديــر عــام الشــركة ونصــه‪:‬‬\n‫(وعليــه فقــد اســتلمت الشــركة ‪ ..................‬الشــاليهات بكامــل‬\n‫مرفقاتهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة لألغــراض والتجهيــزات‬\n‫املســتلمة مــن قبــل املســتثمر)‪ .‬خامســا‪/‬وأما بخصــوص الهاتــف فلــو‬\n‫كانــت اخلدمــة الهاتفيــة متوفــرة مبوقــع الشــاليهات وقــت التعاقــد لــزال‬\n\n\n                                                                                    ‫‪162‬‬\n\f      ‫اإلشــكال وملــا كلفتنــي الشــركة بالبحــث عــن حلــول مناســبة وملــا‬\n      ‫التزمــت لــي الشــركة بتحمــل مــا نســبته ‪% 75‬مــن تأســيس هاتــف هوائي‬\n      ‫(ســيناو) حيــث كان حينئــذ هــو احلــل األمثــل واملســتخدم للتواصــل مــع‬\n      ‫القــرى واملــزارع واملناطــق النائيــة وقــد ركــب الفنيــون طرفيــة أجهــزة‬\n      ‫الهواتــف يف مكتــب االســتقبال وركبــوا لواقطهــا (االناتــل) فوق ســطح‬\n      ‫املكتــب ثــم ســلمتها للشــركة مــن ضمــن االجهــزة اإلضافيــة‪ ،‬كمــا‬\n      ‫نــص علــى ذلــك محضــر تســليم الشــاليهات واســتالم الشــركة لهــا دليــل‬\n      ‫وبينــة علــى موافقتهــا باســتخدام الهاتــف الهوائــي واالســتفادة مــن هــذه‬\n      ‫اخلدمــة املؤمنــة ولــم أقــم بفصــل احلــرارة عــن الهواتــف إال بعــد فتــرة مــن‬\n      ‫إنهــاء التعاقــد علــى أمــل أن تنقلهــا الشــركة باســمها وتدفــع لــي نســبة‬\n      ‫التأســيس التــي التزمــت بهــا‪ .‬سادســا‪/‬أن الوعــد بإجنــاز الرصيــف‬\n      ‫البحــري ملــزم وناجــز؛ ألنــه وعــد موثــق ومكتــوب صــدرت بــه تعليمــات‬\n      ‫إداريــة مــن نائــب مديــر عــام الشــركة ملديــر املشــاريع بإنهــاء إجــراءات‬\n      ‫إجنــاز الرصيــف البحــري لكــن هــذه التعليمــات لــم تنفــذ إال يــوم ســلمت‬\n      ‫الشــاليهات للشــركة  فبــد التســليم صــار الوعــد اخللــف بقــدرة قــادر‬\n      ‫ملزمــا وناجــزا) أ‪.‬ه ـ وحضــر يف هــذه األثنــاء املدعــى عليــه ‪ ...‬وجــرى‬\n      ‫تســليمه صــورة مــن املذكــرة وطلــب اإلمهــال للــرد‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر الطرفــان ثــم قــدم املدعــى عليــه ‪ .....................‬مذكــرة جوابيــة‬\n      ‫علــى مذكــرة املدعــي املقدمــة يف جلســة ‪1432/12/3‬ه ـ ونصهــا‬\n      ‫كالتالــي‪/1 :‬أقــر املدعــي يف الفقــرة (‪ )2‬مــن مذكرتــه بإنهــاء العقــد‬\n      ‫واإلقالــة منــه وأن ذلــك لــم يكــن معلقــا بشــرط أو قيــد‪/2 .‬لــم يقــدم‬\n      ‫املدعــي جوابــا مالقيــا ومقابــا  ملــا أقــر بــه يف خطابــه املــؤرخ يف‬\n      ‫‪1998/12/30‬م مــن أن جميــع املواضيــع األخــرى مت حلهــا كل علــى‬\n\n\n‫‪163‬‬\n\f‫حــدة ولــم يتبــق ســوى موضــوع فواتيــر الكهربــاء الــذي وافــق يف اخلطــاب‬\n‫نفســه علــى حتمــل قيمــة تلــك الفواتيــر وتقييــد قيمتهــا علــى حســابه لــدى‬\n‫موكلتــي‪ /3 .‬ال عــذر ملــن أقــر واإلقــرار ملــزم لصاحبــه وخطــاب املدعــي‬\n‫يف ‪1998/12/30‬م والــذي جــاء بعــد إنهــاء العقــد وتســليم املوقــع‬\n‫ملوكلتــي وأن جميــع املواضيــع األخــرى مت حلهــا كل علــى حــده‪/4 .‬‬\n‫املدعــي أصالــة األخ ‪.................‬هــو الــذي كتــب اخلطــاب أعــاه وهــو‬\n‫الــذي يكتــب معظــم مذكراتــه املقدمــة لفضيلتكــم وهــو معلــم لغــة‬\n‫عربيــة ملــدة تزيــد عــن الثالثــن عامــا ويعــي ويــدرك معانــي الكلمــات‬\n‫ومقاصدهــا وليــس رجــا عاميــا‪ ،‬وبالتالــي فــإن محاولتــه تبريــر إقــراره‬\n‫تبريــرا ال يحتملــه النــص يف غيــر محلــه ملــا تقــدم وحيــث أن املدعــي أنهــى‬\n‫العقــد وقبــل اإلقالــة منــه دون شــرط أو قيــد وفــق مــا أوضحتــه ومــا‬\n‫قدمتــه مــن خطابــات صــادرة منــه حيــث أن املدعــي يقــر بــأن يف ذمتــه‬\n‫حقــوق ماليــة ملوكلتــي فــإن موكلتــي تطلــب مــن فضيلتكــم مــا يلــي‪:‬‬\n‫‪/1‬احلكــم بصــرف النظــر عــن دعــوى املدعــي‪ /2 .‬احلكــم بإلــزام‬\n‫املدعــي دفــع مــا بذمتــه ملوكلتــي مــن مســتحقات ماليــة إجماليهــا‬\n‫(‪)1360802062‬ريــال‪/3 .‬احلكــم بإلــزام املدعــي دفــع أجــرة احملامــاة‬\n‫وقدرهــا (‪ )120000‬مائــة وعشــرون ألــف ريــال) أ‪.‬هــ  ويف جلســة أخــرى‬\n‫افتتحــت اجللســة الســاعة التاســعة والنصــف وفيهــا حضــر املدعــي‬\n‫‪ .............‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .......................‬وقــد‬\n‫قــدم املدعــي مذكــرة رد علــى مــا جــاء يف مذكــرة املدعــى عليــه وكالة‬\n‫ونصهــا كالتالــي (( إشــارة إلــى جلســة يــوم ‪1432/11/23‬ه ـ والــذي‬\n‫طلبتــم فيهــا فضيلتكــم منــي إيضاح ـ ًا مكتوب ـ ًا ملــا ورد باخلطابــن‬\n‫املوجهــن للشــركة ‪ ................‬واملــؤرخ أحدهمــا يف ‪1419/08/12‬ه ـ‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫واآلخــر يف ‪1419/9/12‬ه عليــه فإنــي أقــدم لفضيلتكــم اإليضــاح‬\n      ‫التالــي ‪ -1 :‬أن التســويات املاليــة املتبادلــة بينــي وبــن الشــركة واملشــار‬\n      ‫إليهــا بخطابــي املــؤرخ يف ‪1419/08/12‬ه ـ وهــي قيمــة مــا اتفقنــا عليــه‬\n      ‫مــن تعويــض للتالــف و املفقــود مــن جتهيــزات الشــاليهات وهــي متثــل قيمــة‬\n      ‫أشــياء محــددة ومنصــوص عليهــا صراحــة ومقيــدة بقولــي ( لــذا يســرنا‬\n      ‫إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه ) أقــول ( هــذه ) أي أنهــا‬\n      ‫قيمــة لألشــياء احملــددة واملنصــوص عليهــا يف اخلطــاب املشــار إليــه‬\n      ‫وليســت اتفاق ـ ًا علــى كل شــي معلــق ‪ - 2‬كمــا أن التســويات املاليــة‬\n      ‫املشــار إليهــا بخطابــي املــؤرخ ‪1419/09/12‬هـ وهي متثل قيمة اســتهالك‬\n      ‫كهربــاء فهــذه القيمــة محــددة عليهــا صراحــة ومقيــدة بقولــي ( لــذا‬\n      ‫يســرنا إفادتكــم مبوافقتنــا علــى مطالبتكــم هــذه ( أقول هذه ) حســب‬\n      ‫خطابكــم املشــار إليهمــا واخلاصــة باســتهالك الكهربــاء ) نعــم إنهــا‬\n      ‫قيمــة خاصــة باســتهالك الكهربــاء وليســت تنــاز ًال عــن حقوقــي الثابتــة‬\n      ‫يف ذمــة الشــركة ويف دفاترهــا أمــا عبــارة ( وذلــك بغيــة الوصــول إلــى‬\n      ‫حلــول مرضيــة مثلهــا مثــل املواضيــع األخــرى التــي مت حلهــا كل علــى‬\n      ‫حــده ) فمعناهــا أن قبــول االتفــاق علــى قيمــة اســتهالك الكهربــاء مثلــه‬\n      ‫مثــل قبــول االتفــاق الســابق لــه وهــو تقديــر قيمــة التالــف واملفقــود‬\n      ‫والنواقــص مــن التجهيــزات فــكل حــل مــن هــذه احللــول مت علــى حــده أن‬\n      ‫مقصــود بعبــارة ( التــي مت حلهــا كل علــى حــده ) وتفســيرها يطلــب منــي‬\n      ‫أنــا وليــس مــن غيــري فأنــا الــذي كتبتهــا وأعــي مــا أقــول متامـ ًا واألمــور‬\n      ‫مبقاصدهــا وبســياقها محــل االتفــاق وأنــا الــذي مــا زلــت اعتــرف بأنــي‬\n      ‫قــد توصلــت مــع الشــركة علــى حــل بعــض اجلزئيــات وهــي مبثابــة آليــة‬\n      ‫لتنفيــذ مــا اتفقــت عليــه مــع الشــركة مبحضــر تســليم الشــاليهات ونصه‬\n\n\n‫‪165‬‬\n\f‫( أمــا مــن حيــث النواحــي املاليــة فســوف تتــم التســويات واملطالبــات بــن‬\n‫الطرفــن كل فيمــا يخصــه ) فاحللــول التــي وردت باخلطابــن أمنــا هــي‬\n‫تســويات ماليــة تخــص الشــركة امــا مــا يخصنــي مــن حقــوق بذمــة‬\n‫الشــركة فهــو مــا أنكــرت الشــركة بعضــه ومــا طلبــت بالبعــض اآلخــر‬\n‫األمــر الــذي دفعنــي للتقــدمي للمحكمــة مطالب ـ ًا بحقوقــي وهــي مثبتــة‬\n‫بدفاتــر الضبــط لــدى فضيلتكــم منــذ اثنــا عشــر عامـ ًا فاحلــق ال يســقط‬\n‫بالتقــادم كمــا ال يخفــى عليكــم فالعبــارات املتبادلــة بينــي وبــن‬\n‫ا قــد قبلــت‬   ‫الشــركة ال تــدل ال مــن قريــب وال مــن بعيــد علــى أنــي مث ـ ً‬\n‫بخطــورة الوضــع اإلنشــائي للشــاليهات وال علــى أنــي تنازلــت عــن حقــي‬\n‫الثابــت برصيــف بحــري دامــت مماطلــة الشــركة يف إجنــازه حتــى نهايــة‬\n‫الســنة األولــى مــن العقــد وال علــى أنــي مذعــن للشــركة التــي وقعــت‬\n‫معــي عقــد الصيانــة واســتلمت أجرتهــا مبوجــب شــيكات موثقــة ثــم‬\n‫رفضــت تنفيذهــا بــل حتــى تاريــخ اليــوم وهــي مــا زالــت تعتبرنــي  ظامل ـ ًا‬\n‫وجــور ًا أنــا املســئول عــن تنفيــذ الصيانــة وغيــر ذلــك أن خطــورة الوضــع‬\n‫اإلنشــائي للشــاليهات واملماطلــة يف إجنــاز الرصيــف البحــري ورفــض‬\n‫الصيانــة كل واحــد منهــا كفيــل يعتــذر حصــول منفعــة االســتثمار التــي‬\n‫مــن أجلهــا مت التعاقــد فتعــذر منفعــة االســتثمار ال يلغــي معــه كمــا أفهــم‬\n‫مصــروف الكهربــاء حيــث أنــه خــاص بطــرف ثالــث ( ‪ ) ....‬ال يعتــرف‬\n‫باخلــاف القائــم بــن املالــك واملســتأجر فــإن رأي فضيلتكــم أن‬\n‫الشــركة الســعودية ملراكــز الترفيــه ال يســتحق شــرع ًا قيمــة اســتهالك‬\n‫تبعــا لتعــذر املنفعــة فأمتنــى ذلــك واملوضــوع بــن أيدكــم ‪ - 3‬وأخيــر ًا أن‬\n‫محامــي الشــركة قــد كــذب علــي يف مذكرتــه املؤرخــة يف‬\n‫‪1432/11/27‬ه ـ وقولنــي مــا لــم اقلــه وذلــك حينمــا أدعــى مــا نصــه (‬\n\n\n                                                                                      ‫‪166‬‬\n\f       ‫يتضــح لفضيلتكــم مــا يلــي ‪ - 1 :‬إقــرار املدعــي صراحــة بأنــه مت حلــه‬\n       ‫املواضيــع بــن الطرفــن بحلــول مرضيــة ولــم يبــق شــيء لــم يحلــه ) فأنــا‬\n      ‫لــم اقــل عبــارة ( ولــم يبــق شــيء لــم يحــل ) واحللــول التــي متــت بــن الطرفني ‬\n       ‫بحلــول مرضيــة إمنــا هــي املشــار إليهــا أعــاه كمــا وأنــه يف املذكــرة‬\n       ‫نفســها ســبق أن حــاول شــطب القضيــة مــن أساســها وذلــك بتجاهــل‬\n       ‫القــرار األخيــر القاضــي باســتئنافها ثــم أدعــى كذب ـ ًا يف مذكرتــه‬\n       ‫املؤرخــة يف ‪1432/12/23‬ه ـ ( أننــي معلــم لغــة عربيــة ملــدة تزيــد عــن‬\n       ‫الثالثــن عامـ ًا ) وهــذه مــن تلقــاء نفســه بــل ومحــض افتــراء )) أ‪.‬ه ـ وبــرد‬\n       ‫ذلــك علــى املدعــى عليــه وكالــة قــال أو ًال ‪ -‬مــا ورد يف الفقرتــن األولــى‬\n       ‫والثانيــة مــن مذكــرة املدعــي ليــس فيــه جديــد بنقــض مــا ســبق أن أقــر‬\n       ‫بــه املدعــي بانتهــاء جميــع املواضيــع وحلهــا واألصــل أنــه ال عــذر لــم أقــر‬\n       ‫كمــا أن الســكوت عــن البيــان يف معــرض احلاجــة لبيــان بيانــه وقــول‬\n       ‫املدعــي أن خطابيــه يتعلقــان بالكهربــاء غيــر صحيــح فــكل منهمــا‬\n       ‫مذيــل بعبــارة حســابي لديكــم أو مطالباتكــم لــدي اجتاهــي ومــا أورده‬\n       ‫املدعــي يف هاتــن الفقرتــن كالم مرســل ال يخــرج عمــا ســبق أن ذكره‬\n       ‫يف اجللســتني املاضيتــن أمــا مــا ورد يف الفقــرة الثالثــة فجوابـ ًا علــى أنــي‬\n       ‫كذبــت علــى املدعــي يف مســألة إقــراره فإنــي أنــزه مجلــس القضــاء مــن‬\n       ‫الــرد عــن هــذه اإلســاءة ولعــل فهــم املدعــي قصــر بــه عــن إدراك معنــى‬\n       ‫عبارتــي أمــا كونــه معلــم لغــة عربيــة فســبق أن أقــر بهــا يف مجلــس‬\n       ‫القضــاء هــذا مــا لــدي ثــم جــرى ســؤال الطرفــن هــل لديهمــا زيــادة علــى‬\n       ‫مــا ذكــراه فقــاال ليــس لدينــا ســوى مــا ذكرنــاه يف هــذه اجللســة‬\n       ‫واجللســات الســابقة ورفعــت اجللســة لتأمــل جميــع مــا ســبق ضبطــه ويف‬\n       ‫جلســة أخــرى افتتحــت اجللســة الســاعة ‪  10 : 31‬وفيهــا حضــر املدعــي‬\n\n\n‫‪167‬‬\n\f‫‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .........‬وجــرى ســؤال‬\n‫املدعــي ‪ .............‬عمــا ذكــره املدعــى عليــه وكالــة يف أحــد اجللســات‬\n‫بخصــوص الشــاليه رقــم ‪  6‬وأن الشــاليه لــم يســلم للمســتأجر مــن بدايــة‬\n‫العقــد لذلــك فقــد جــرى حســاب األجــرة لتكــون تســعة وثالثــون الــف‬\n‫وخمســمائة ريــال فقــال املدعــي هــذا الــكالم غيــر صحيــح فالعقــد‬\n‫يثبــت أن اســتالم املســتأجر للشــاليه كان يف نفــس تاريــخ العقــد (‬\n‫اعتبــار ًا مــن جاهزيتــه لالســتخدام ) وســوف أحضــر مــا يثبــت ذلــك ثــم‬\n‫جــرى ســؤال املدعــي عمــا جــاء يف مذكــرة املدعــى عليه وكالــة املؤرخة‬\n‫يف ‪143/11/27‬هـ يف الفقرة السابعة واملتضمنة أن الشركة ‪...............‬‬\n‫تطالبــه مببلــغ مائــة وســتة وثالثــون ألــف وثمامنائــة وريــاالن واثنــان وســتون‬\n‫هللــه فقــال أقــر بــأن يف ذمتــي للشــركة املدعــى عليهــا مبلــغ خمســون‬\n‫ألــف ريــال وهــذا املبلــغ يشــمل جميــع تكاليــف الكهربــاء واملــاء و‬\n‫املفقــودات والنواقــص وبينتــي علــى ذلــك املخالصــة املوقعــة مــن رئيــس‬\n‫مجلــس اإلدارة والعضــو املنتــدب والتــي تثبــت أن يف ذمتــي مبلــغ خمســون‬\n‫ألــف ريــال فقــط وهنــاك مخالصــة أخــرى موقعــة مــن رئيــس مجلــس‬\n‫اإلدارة تتضمــن تفصيــل املبلــغ املذكــور يف املخالصــة األولــى أقدمهــا‬\n‫لفضيلتكــم وقــد جــرى اإلطــاع منــا علــى املخالصتــن فوجــدت األولــى‬\n‫محررة على مطبوعات الشركة ‪......‬برقم ‪ 99/99‬يف ‪1419/11/01‬هـ‬\n‫املوافــق ‪1999/02/17‬م وعنوانهــا مخالصــة نهائيــة ونصهــا كالتالــي‬\n‫((إشــارة إلــى العقــد بــن الطرفــن ‪ - 1‬الشــركة ‪ ( ..............‬طــرف أول)‬\n‫‪ - 2‬واألســتاذ ‪ ( ................. /‬طــرف ثانــي ) الســتثمار شــاليهات ‪...‬‬\n‫وحيــث انتهــى العقــد بتاريــخ ‪ /1‬أكتوبــر ‪1998 /‬م وحيــث هنــاك مبالــغ‬\n‫مطلوبــة للشــركة لــم يتــم تســديدها مــن قبــل األســتاذ ‪ ..............‬فقــد مت‬\n\n\n                                                                                        ‫‪168‬‬\n\f       ‫االتفــاق بتاريخــه علــى عمــل هــذه املخالصــة النهائيــة والتــي يقــوم‬\n       ‫مبوجبهــا األســتاذ ‪ ............‬بدفــع مبلــغ ( ‪ 50.000‬ريــال ) خمســون الــف‬\n       ‫ا قــام املذكــور بتســديد هــذا املبلــغ مبوجــب الشــيك رقــم‬            ‫ريــال وفع ـ ً‬\n       ‫(بــدون ) وتاريــخ ( بــدون ) مســحوب علــى البنــك ( بــدون ) وبذلــك لــم يعــد‬\n       ‫ال‬\n        ‫ألي مــن الطرفــن احلــق يف مطالبــة الطــرف اآلخــر حاضــر ًا أو مســتقب ً‬\n       ‫بــأي مبالــغ أخــرى ويعتبــر هــذا املبلــغ مبثابــة مخالصــة نهائيــة بــن‬\n       ‫الطرفــن املذكوريــن فيمــا يخــص العقــد املذكــور أعــاه )) أ‪.‬ه ـ‬\n       ‫‪ ...............‬رئيــس مجلــس اإلدارة والعضــو املنتــدب توقيعــه وختــم‬\n       ‫الشــركة ‪ ....................‬و‪ ....................‬مســتثمر الشــاليهات بــدون توقيــع‬\n       ‫كمــا  جــرى اإلطــاع منــا علــى املخالصــة الثانيــة فوجدتهــا  محــررة‬\n       ‫علــى مطبوعــات الشــركة ‪ ...........‬برقــم ‪ 99/99‬يف ‪1419/11/01‬ه ـ‬\n       ‫املوافــق ‪1999/02/17‬م وعنوانهــا مخالصــة نهائيــة ونصهــا كالتالــي‬\n       ‫((إشــارة إلــى العقــد بــن الطرفــن ‪ - 1‬الشــركة ‪( ..................‬طــرف‬\n       ‫أول) ‪ - 2‬واألستاذ ‪ ( .......... /‬طرف ثاني ) الستثمار شاليهات ‪..............‬‬\n       ‫وحيــث انتهــى العقــد بتاريــخ ‪ /1‬أكتوبــر ‪1998 /‬م وحيــث هنــاك مبالــغ‬\n       ‫مطلوبــة للشــركة لــم يتــم تســديدها مــن قبــل األســتاذ ‪ ...................‬فقــد‬\n       ‫مت االتفــاق بتاريخــه علــى عمــل هــذه املخالصــة النهائيــة والتــي يقــوم‬\n       ‫مبوجبهــا األســتاذ ‪ ..................‬بدفــع مبلــغ ( ‪ 50.000‬ريــال ) خمســون‬\n       ‫ألــف ريــال ‪ 15.900 ( - 1 :‬ريــال ) قيمــة املفقــودات ‪ 1420 ( - 2‬ريــال )‬\n       ‫الصيانــة  ‪ 812 ( - 3‬ريــال ) إصــاح األســرة ‪ 22.513 ( - 4‬ريــال )‬\n       ‫ا قــام‬ ‫اســتهالك الكهربــاء ‪ 9355 ( - 5‬ريــال ) اســتهالك املــاء  وفع ـ ً‬\n       ‫املذكــور بتســديد هــذا املبلــغ مبوجــب الشــيك رقــم ( بــدون ) وتاريــخ‬\n      ‫(بــدون ) مســحوب علــى البنــك ( بــدون ) وبذلــك لــم يعد ألي من الطرفني ‬\n\n\n‫‪169‬‬\n\f‫ال بــأي مبالــغ أخــرى‬ ‫احلــق يف مطالبــة الطــرف اآلخــر حاضــر ًا أو مســتقب ً‬\n‫ويعتبــر هــذا املبلــغ مبثابــة مخالصــة نهائيــة بــن الطرفــن املذكوريــن‬\n‫فيمــا يخــص العقــد املذكــور أعــاه )) أ‪.‬ه ـ ‪ ...................‬رئيــس مجلــس‬\n‫اإلدارة والعضــو املنتــدب توقيعــه  و ‪ ...................‬مســتثمر الشــاليهات‬\n‫بــدون توقيــع ثــم جــرى ســؤال املدعــى عليــه وكالــة عــن البيــان املقــدم من‬\n‫قبــل املدعــي بخصــوص التجهيــزات اإلضافيــة والتــي يطالــب بهــا‬\n‫الشــركة املدعــى عليهــا مببلــغ ســتة عشــر الــف وثالثمائــة وتســعة‬\n‫وتســعون ريــال كمــا جــرى ســؤاله عــن املبلــغ الــذي أقــر بــه املدعــي‬\n‫وقــدره خمســون ألــف ريــال لصالــح الشــركة املدعــى عليهــا فقــال اطلــب‬\n‫إمهالــي لإلعــداد اجلــواب وقــد جــرى تســليمه صــور مــن البيــان املتضمــن‬\n‫التجهيــزات اإلضافيــة واملخالصتــان املقدمتــان مــن املدعــي ثــم قــال‬\n‫املدعــى عليــه وكالــة اطلــب قبــل رفــع اجللســة توجيــه ســؤال للمدعــي هــل‬\n‫املخالصــة التــي قدمهــا يف هــذه اجللســة ال يقــر فيهــا إال بلــزوم ذمتــه مبلــغ‬\n‫اخلمســون الــف ريــال مــع أن الصيــاغ يثبــت مــن أولــه إلــى آخــره أنــه ليــس‬\n‫ال بــن الطرفــن فجرى‬      ‫لــه حــق وتعتبــر منهيــة للمطالبــة حاضــر ًا ومســتقب ً‬\n‫توجيــه ذلــك للمدعــي فقــال  أن الشــركة ‪ ..............‬هــي مــن أعــدت‬\n‫املخالصــة وعلــى مطبوعاتهــم وكان صياغتهــا لصاحلهــم ومت توقيعهــم‬\n‫ا أقــر باخلمســن الــف ريــال وهــي يف ذمتــي وأنــا لــم أوقــع‬  ‫عليهــا وأنــا فعـ ً‬\n‫هــذه املخالصــة والســبب إنكارهــم وبخســهم حلقوقــي وقــد أعــدو‬\n‫املخالصــة وأنــا معهــم يف الشــركة ‪ .................‬فقالــو لــي وقــع ولكنــي‬\n‫رفضــت ألنهــم أنكــروا حقوقــي وأخــذت صــورة مــن املخالصــة األولــى‬\n‫والثانيــة وغــادرت الشــركة علمـ ًا بــأن التفصيــل املذكــور يف املخالصــة‬\n‫الثانيــة أنــا مــن طلبــت إضافتــه يف املخالصــة حتــى نعــرف تفصيــل جميــع‬\n\n\n                                                                                          ‫‪170‬‬\n\f      ‫املطلــوب منــي وعنــد هــذا املوضــع رفعــت اجللســة مــع إفهــام املدعــى عليــه‬\n      ‫وكالــة بإحضــار املطلــوب منــه ويف يــوم جلســة أخــرى وفيهــا حضــر‬\n      ‫املدعــي ‪................‬وحضــر حلضــوره ‪ ...............‬الوكيــل الشــرعي عــن‬\n      ‫الشــركة ‪ ..............‬للترفيــه وبســؤال املدعــى عليــه وكالــة عــن جوابــه‬\n      ‫علــى مــا ورد يف اجللســة الســابقة فقــدم مذكــرة مــن ثــاث صفحــات‬\n      ‫محــرره علــى مطبوعــات شــركة ‪ ..............‬و‪ .............‬محامــون‬\n      ‫ومستشــارون مؤرخــه يف ‪1433/6/3‬ه ونصهــا كالتالــي ( جواب ـ ًا علــى‬\n      ‫مــا دار يف جلســة الثالثــاء ‪1433/4/27‬ه ـ ومــا مت ضبطــه أود أن أبــن‬\n      ‫لفضيلتكــم مــا يلــي‪ :‬أوالً‪ :‬بيــان التجهيــزات اإلضافيــة املقــدم مــن‬\n      ‫املدعــي‪-1.‬ورد يف مقدمــة البيــان (إشــارة إلــى العقــد ‪.......‬وقــد أقــر‬\n      ‫الســيد ‪ .........‬بتحمــل كافــة النواقــص وبيانها)‪،‬وبالتالــي فــإن هــذا‬\n      ‫البيــان يتحــدث عــن نواقــص التــزم املدعــي باســتكمالها‪-2.‬الصفحة‬\n      ‫الثانيــة مــن البيــان مت إدراجهــا ضمــن البيــان وليســت مــن ضمنــه يف‬\n      ‫األصــل وهــذا واضــح مــن اختــاف اخلــط وطريقــة احلقول‪-3.‬الصفحــة‬\n      ‫الثالثــة مــن البيــان تضمنــت مالحظــات إضافيــة بنواقــص يجــب‬\n      ‫اســتكمالها مــن املدعــي وهــذا منصــوص عليــه‪ ،‬وبالتالــي فــإن هــذا‬\n      ‫البيــان يتحــدث عــن نواقــص علــى املدعــي فقط‪-4.‬الفواتيــر التــي أرفقهــا‬\n      ‫املدعــي تضمنــت مشــتريات ال عالقــة لهــا بالشــاليهات كاألدوات‬\n      ‫واألجهــزة األساســية مطلق ـاً( ســياكل‪ ،‬أحذيــة تزحلــق‪ ،‬آلــة حاســبة‪،‬‬\n      ‫طاولــة تنــس ومســتلزماتها‪ ،‬حامــل ملفــات‪ ،‬ملفــات عالقــي‪ ،‬موقــد‬\n      ‫طبــخ أمريكــي لــزوم موظفــي املدعي‪...‬الخ)‪-5.‬التجهيــزات التــي يطالب‬\n      ‫بهــا املدعــي مكتوبــة يف البيــان بخــط اليــد‪ ،‬كمــا أن أقيامهمــا مبالــغ‬\n      ‫فيها(ســلطانية صغيــرة بخمســة عشــر ريال)‪-6.‬هــذا البيــان املقــدم مــن‬\n\n\n‫‪171‬‬\n\f‫املدعــي ال يظهــر فيــه توقيــع أي مــن الطرفــن كمــا أنــه صــورة وليــس‬\n‫أصــل وال يوجــد مــا يفيــد باســتالم موكلتــي ملــا يدعــي بــه املدعــي‪-7.‬‬\n‫املدعــي كمــا هــو معــروف يعمــل يف نشــاط الشــقق املفروشــة وقــد‬\n‫تكــون هــذه املشــتريات تخــص تلــك األنشــطة‪-8.‬األصل أن املدعــي‬\n‫ملتــزم باســتكمال نواقــص مبوجــب محضــر اســتالم الشــاليهات املــؤرخ‬\n‫يف ‪1998/10/17‬م‪،‬حيــث ورد فيه(هــذا وقــد مت اجلــرد بالفعــل خــال‬\n‫اليومــن املشــار إليهمــا أعــاه وتبينــت بعــض النواقــص واملفقــودات مــن‬\n‫جتهيــزات الشــاليهات وقــد مت إدراجهــا بالبيانــات املرفقة(لــم أرفــق‬\n‫صــورة احملضــر منع ـ ًا لتكــرار املرفقات)‪-9.‬محضــر االجتمــاع املوقــع‬\n‫بتاريــخ ‪1998/8/26‬م (املرفــق رقم‪)1‬املوقــع مــن املدعــي نــص صراحــة‬\n‫على موافقة املدعي تســليم الشــاليهات ولم يذكر أن له أي مســتحقات‬\n‫أو خالفــه‪ .‬ثانيـاً‪ :‬املخالصتــان النهائيتــان املقدمــة مــن املدعــي يف اجللســة‬\n‫الســابقة‪-1.‬أقر املدعــي بأنــه مديــن ملوكلتــي مببلــغ خمســن ألــف ريــال‬\n‫مبوجــب هاتــن املخالصتني‪-2.‬ذكــر املدعــي أنــه كان موجــود ًا عنــد‬\n‫إعــداد املخالصــة األولــى يف مقــر موكلتــي وأنــه لــم يوقــع عليهــا كونهــا‬\n‫لــم تتضمــن حقوقــه‪ ،‬ثــم أقــر بأنــه تســلمها وغــادر الشــركة ثــم عــاد‬\n‫وطلــب مــن موكلتــي إضافــة التفصيــل الــوارد يف املخالصــة الثانية‪،‬ومــع‬\n‫ذلــك لــم يطلــب إدراج حقوقــه التــي يزعم‪،‬والقاعــدة الفقهيــة تقــول(أن‬\n‫الســكوت عــن البيــان يف معــرض احلاجــة لبيــان بيــان) فكونــه تســلم‬\n‫املخالصــة األولــى وطلــب صياغــة أخــرى بالتفصيــل الــذي نــص عليــه دون‬\n‫أن يذكــر حقوقــه التــي يزعــم فهــذا يــدل علــى عــدم صحــة قولــه وأن‬\n‫احلقيقــة أن ال حقــوق له‪-3.‬يؤكــد ذلــك مــا أقــر بــه املدعــي يف خطابيــه‬\n‫املؤرخني يف ‪ 1998/12/1‬والثاني يف ‪ 1998/12/30‬حيث أن التفصيل‬\n\n\n                                                                                     ‫‪172‬‬\n\f      ‫يف املخالصــة الثانيــة يطابــق مــا أقــر بــه يف خطابــه املــؤرخ يف‬\n      ‫‪1998/12/30‬م مــن أنــه ليــس لــه حقــوق كمــا يزعم‪-4.‬زعــم املدعــي‬\n      ‫بــأن اخلطابــان أعــاه كان يقصــد منهمــا إنهــاء موضــوع الكهربــاء‬\n      ‫فقط‪،‬وجــاءت املخالصتــان بعــد شــهرين ونصــف مــن اخلطابــن ومــع ذلك‬\n      ‫لــم يطلــب مــن موكلتــي ذكــر حقوقــه املزعومــة يف الوقــت الــذي أصــر‬\n      ‫علــى ذكــر تفصيــل مســتحقات موكلتــي بذمتــه يف املخالصــة الثانيــة‬\n      ‫حســب إقراره‪-5.‬العالقــة بــن موكلتــي واملدعــي محصــورة فقــط يف‬\n      ‫موضــوع الشــاليهات وال توجــد أي أعمــال بينهما‪،‬وحينمــا يقــول بأنــه مت‬\n      ‫حــل املواضيــع األخــرى كل علــى حــده فإنــه يقصــد الناشــئة عــن عالقتــه‬\n      ‫مــع موكلتــي‪ ،‬وهــذا اإلقــرار منــه ليــس عامـ ًا بــل هــو مخصــص يف كل‬\n      ‫موضــوع مــع موكلتــي ‪-6.‬قــول املدعــي(كل علــى حــده )هــو تفصيــل‬\n      ‫وحتديــد وليــس فيــه عمــوم مطلقاً‪.‬فهــو يصــرح بــأن جميــع املواضيــع‬\n      ‫األخــرى مــا عــدا موضــوع خطابيه(الكهربــاء) مت حلهــا كل علــى حــده‪.‬‬\n      ‫‪-7‬إذا كان املدعــي يدعــي بــأن هنــاك أعمــا ًال ومواضيــع أخــرى مــع‬\n      ‫موكلتــي خــاف موضــوع الشــاليهات فعليــه إقامــة دعــوى مســتقلة‬\n      ‫به‪،‬أمــا املواضيــع املتعلقــة بالشــاليهات فقــد مت حــل كل موضــوع منهــا‬\n      ‫علــى حــده كمــا هــو إقراره‪-8.‬جميــع اخلطابــات املوجهــة مــن املدعــي‬\n      ‫إلــى موكلتــي قبــل وبعــد محضــر اســتالم الشــاليهات ال يوجــد فيهــا أي‬\n      ‫ذكــر ملــا يزعمــه مــن حقوق‪،‬أمــا العبــارة التــي يتمســك بهــا املدعــي‬\n      ‫الــواردة يف محضــر اســتالم الشــاليهات ونصها(وعليــه فقــد اســتلمت‬\n      ‫الشــركة ‪.....‬املســتكملة مــن املســتثمر‪)....‬فإنها ضــده وليســت‬\n      ‫له‪،‬فكلمــة مســتكملة تعنــي أن هنــاك نقــص مت اســتكمال بعضــه‬\n      ‫والبعــض اآلخــر لــم يســتكمل‪،‬ويؤكد هــذا مــا ورد قبــل ذلك(‪...‬وتبينت‬\n\n\n‫‪173‬‬\n\f‫بعــض النواقــص واملفقودات‪...‬الــخ)‪ ،‬وبعــده (‪...‬ولــم يعــد للمســتثمر أي‬\n‫عالقــة بالشــاليهات مــا عــدا النواقــص واملفقــودات مــن التجهيــزات‪...‬‬\n‫الخ)‪-9.‬جميــع مــا ذكرتــه يف هــذه املذكــرة ومــا ســبق ذكرتــه مــن أدلة‬\n‫وقرائــن يؤكــد أن املدعــي ســلم الشــاليهات وليــس لــه أي مطالبــات‬\n‫ســواء يف محضــر تســليم الشــاليهات أو احملضــر املرفــق رقم(‪)1‬ومــا‬\n‫أورده مــن دفــع هــو غيــر صحيح‪.‬ملــا تقــدم ومــا ســبق إيــراده يف مذكراتــي‬\n‫الســابقة فــإن موكلتــي تطلــب مــن فضيلتكم‪-1:‬احلكــم بــرد دعــوى‬\n‫املدعــي لعــدم صحتها‪-2.‬احلكــم بإلزامــه بدفــع مــا بذمتــه ملوكلتــي‬\n‫وهــي  مبلــغ ‪(136.802.62‬مائــة وســتة وثالثــون ألف ـ ًا وثمامنائــة وريــاالن‪.‬‬\n‫‪-3‬احلكــم بإلزامــه بدفــع أجــرة احملامــاة وقدرهــا ‪(120.000‬مائــة‬\n‫وعشــرون ألــف ريــال)‪ .‬وفــق اهلل اجلميــع للحــق والعمــل بــه هــذا مــا لــدي‬\n‫ورفعــت اجللســة للــرد علــى املذكــرة ويف جلســة أخــرى وفيهــا حضــر‬\n‫‪ ................‬وحضــر حلضــوره املدعــى عليــه وكالــه ‪ ...............‬وقــد قــدم‬\n‫املدعــي مذكرتــه والتــي تعــذر كتابتهــا يف اجللســة الســابقة ونصهــا‬\n‫كالتالــي (اشــارة الــى مذكــرة وكيــل الشــركة ‪ ................‬املقدمــه‬\n            ‫لفضيلتكم يف جلسه يوم ‪ 1433/6/3‬هـ أود ايضاح مايلي‪-:‬‬\n‫أوالً‪ :‬جــاء يف املذكــرة كالم حــول جتهيــزات الشــاليهات ‪ ،‬وفيــه خلــط‬\n‫وتداخــل بــن مــا للشــركة ومــا عليهــا‪ .‬ولعــل معــد املذكــرة لــم يســتوعب‬\n‫تفاصيــل القضيــة التــي يدافــع عنهــا وكيــل الشــركة ‪ ،‬فلإليضــاح‬\n    ‫وتبســيط هــذه اجلزئيــة اقــول ‪ :‬ان جتهيــزات الشــاليهات هــي نوعــان‪:‬‬\n‫النــوع االول‪ :‬أدوات واغــراض اشــترتها الشــركة وأمنتهــا مــن حســابها‬\n‫لتجهيــز الشــاليهات وقمــت انــا بإســتالمها يف بدايــة التعاقــد وبعــد‬\n‫فســخ العقــد مــن قبــل الشــركة وتســليمها يف نهايــة التعاقــد مت جــرد‬\n\n\n                                                                                       ‫‪174‬‬\n\f      ‫تلــك التجهيــزات فوجــد يف بعضهــا نقــص ويف البعــض األخــر تلــف فتــم‬\n      ‫تقديــر قيمــة الناقــص والتألــف منهــا مببلــغ خمســة عشــر ألفـ ًا وتســعمائة‬\n                                ‫‪ 15900‬ريــال ســجلته يف ذمتــي حلســاب الشــركة‬\n      ‫النــوع الثانــي ‪ :‬أدوات ناقصــة كانــت حتتــاج إليهــا الشــاليهات وهــي‬\n      ‫مبثابــة اســتكمال جتهيــزات ضروريــه لــم تقــم الشــركة أصــا ‬\n      ‫بتأمينهــا فقمــت بتأمينهــا مــن حســابي اخلــاص مببلــغ إجمالــي قــدرة ســتة‬\n      ‫عشــر الف ـ ًا وثالثمائــة وتســعه وتســعون ‪ 16399‬ريــال وذلــك يف الشــهور‬\n      ‫األولــى مــن العقــد وعنــد تســليم الشــاليهات بعــد فســخ العقــد اســتلمتها‬\n      ‫الشــركة منــي ضمــن كامــل التجهيــزات املنصــوص عليهــا مبحضــر‬\n      ‫تســليم الشــاليهات ونصــه ( وعليــه فقــد اســتلمت الشــركة ‪.................‬‬\n      ‫الشــاليهات بكامــل مرافقهــا وملحقاتهــا وجتهيزاتهــا باإلضافــة‬\n      ‫لألغــراض والتجهيــزات املســتكملة مــن قبــل املســتثمر ) وهــي مازالــت‬\n      ‫مــن ضمــن حقوقــي التــي بذمــة الشــركة وممــا يجــب إيضاخــه أيضــا‬\n      ‫ان مســئولي الشــركة هــم الذيــن اعــدوا بيانــات التجهيــزات الناقصــة‬\n      ‫والتجهيــزات الزائــدة اثنــاء اجلــرد فمــا كان فيهــا زائــدا عمــا اســتلمته‬\n      ‫ا خاصـ ًا بــه ثــم طلبــوا بعــد ذلــك‬\n                                            ‫مــن الشــركة افــردوا لــه يف البيــان حقـ ً‬\n      ‫منــي اســعارها مبوجــب الفواتيــر التــي تتوفــر لــدي ومــا ليســت فاتورتــه‬\n      ‫عنــدي رجعــوا اليهــا مبلــف الشــاليهات الــذي بحوزتهــم واي صنــف لــم‬\n      ‫يعثــروا لــه علــى فاتــورة ( كالســلطانيه مثــا ) حــددوا قيمتهــا بنفــس‬\n      ‫الســعر الــذي هــم أمنوهــا بــه يف بدايــة التجهيــز حســب مــاورد بخانتــه‬\n      ‫وســجلوه‪ .‬فــإن كان وكيــل الشــركة يــرى ان ســعر الســلطانيه مبالــغ‬\n      ‫فيــه فليرجــع لبيــان موكلتــه ‪ ،‬أمــا التشــكيك يف مصداقيــة البيانــات‬\n      ‫واختــاف اخلــط كمــا يزعــم فإنــي ال أظنــه يجهــل الفــرق بــن صيغــة (‬\n\n\n‫‪175‬‬\n\f‫وقــد اقــر الســيد ‪ )........ /‬وصيغــة (أقــر انــا ‪ )..........‬حيــث االولــى وهــي‬\n‫الصيغــة املكتوبــه تؤكــد للمطلــع علــى البيانــات ان مســئولي الشــركه‬\n‫هــم مــن قامــوا بإعــداد البيانــات ‪ ،‬وليــس انــا‪ .‬وهــم مــن جتاهــل التوقيــع‬\n‫عليهــا اوالً‪ .‬فــإن كان وكيــل الشــركة اليعتــرف ببيانــات التجهيــزات‬\n‫الزائــدة اص ـاً‪ .‬فعليــة تبع ـ ًا لذلــك ان ال يطالــب بقيمــة التجهيــزات‬\n‫الناقصــة وذلــك لعــدم التوقيــع‪ .‬ثاني ـ ًا ‪ :‬ان محضــر االجتمــاع بتاريــخ‬\n‫‪1998/8/26‬م املوقــع مــن الطرفــن نــص صراحــة علــى أن فســخ العقــد‬\n‫مت (بنــاء علــى رغبــة الشــركة) املشــروطة (مبــا تضمنتــه املراســات)‬\n‫الس ــابقة لتوقيــع احملض ــر [ مرفــق رقــم ‪ ]1‬ومــن ضمــن املراســات ايضـ ًا‬\n‫‪ .1‬خطــاب عــدم االنتفــاع باملأجــور نتيجــة لوجــود عيــوب إنشــائية‬\n‫ومعماريــة يف املشــروع واملثبتــة بتقريــر هندســي اعترفــت بهــا الشــركة‬\n‫وأكــدت خطورتهــا بخطابهــا املوجــة للمقــاول املنفــذ للمشــروع [ مرفــق‬\n                                                                           ‫رقــم ‪.]2‬‬\n‫‪.2‬خطاباتــي املتعــدده للشــركة بتحميلهــم املســئولية كاملــة نتيجــة‬\n‫إلهمــال أعمــال الصيانــه ‪ ،‬وجتاهــل العنايــة بالزراعــة [ مرفــق رقــم ‪]3‬‬\n‫رغــم انهــم قبضــوا اجرتهــا بشــيكات مدفوعــه مقدمـ ًا عنــد بدايــة كل‬\n‫شــهر فأنــا ال اطالــب الشــركة باجــرة الصيانــه لذاتهــا فقــط بــل اطالبهم‬\n              ‫ايض ـ ًا بأثــر االهمــال والتجاهــل اللذيــن تســببا يف خســارتي‪.‬‬\n‫‪.3‬خطاباتــي للشــركة املطالبــة بإجنــاز الرصيــف البحــري [ مرفــق رقــم‬\n                                                                       ‫‪ 4‬ورقــم ‪.]5‬‬\n‫‪.4‬خطابــي للشــركه بطلــب االرقــام الســريه ألجهــزة االتصــاالت‬\n‫الهاتفيــه وأجهــزة اســتقبال القنــوات الفضائيــة التــي تكثــر اعطالهــا‬\n‫والتــي الميكــن اصالحهــا إال مبعرفــة االرقــام الســرية لهــا والتــي هــي‬\n\n\n                                                                                        ‫‪176‬‬\n\f      ‫بحوزتهــم وعنــد وجــود أي عطــل يحتــاج االمــر الــى وقــت ليــس بالقصيــر‬\n                                                    ‫لالتصــال باملتعهــد ثــم االصــاح‪.‬‬\n      ‫فضيلــة القاضــي‪ :‬إن الشــركة ‪ ..............‬أجرتنــي مرفق ـ ًا ســياحي ًا ‪،‬‬\n      ‫وبعدمــا قبضــت وضمنــت كامــل اجرتــه ‪ ،‬عطلــت صيانتــه‪ ،‬وأهملــت‬\n      ‫زراعتــه ‪ ،‬ومنعــت عنــي ارقــام تشــغيل واصــاح اجهزتــه لفتــرات متقطعــة‬\n                                                                        ‫[مرفــق رقــم ‪.]6‬‬\n      ‫ثالث ـاً‪ :‬أمــا إشــارة وكيــل الشــركة الــى مــا جــاء بخطابــي املوجــه‬\n      ‫للشــركة بتاريــخ ‪1998/12/1‬م وخطابــي املــؤرخ يف ‪1998/12/30‬م‬\n      ‫‪ ،‬فــإن ســياقهما يؤكــد لفضيلتكــم أنهمــا خاصــان مبعاجلــة موضــوع‬\n      ‫التجهيــزات الناقصــة ‪ ،‬واســتهالك الكهربــاء ‪ ،‬ومنع ـ ًا لإلطالــة‬\n      ‫والتكــرار فإنــي احيــل فضيلتكــم مشــكور ًا الــى مذكرتــي الســابقة‬\n                                                           ‫املؤرخــة يف ‪1433/1/2‬هــ‪.‬‬\n      ‫رابعـ ًا ‪ :‬مــا يدعيــه وكيــل الشــركة بــأن (الســكوت عــن البيــان ‪ -‬بعــد‬\n      ‫اطالعــي علــى صياغتهــم للمخالصــة ؟ بيــان ) فأقــول أن احلــال وقتهــا لــم‬\n      ‫يكــن ســكوت ًا بــل كان رد ًا منــي للصياغــة التــي هــي لصالــح طــرف‬\n      ‫واحــد دون اعتبــار للطــرف االخــر ‪ ،‬وحيــث ان االمــر بهــذا الشــكل‬\n      ‫ال يحتمــل‪ .‬نتيجــة جحودهــم ونكرانهــم لكامــل حقوقــي حتــى مــا هــو‬\n      ‫منهــا ثابــت لديهــم وقتهــا فضلــت االنســحاب واخلــروج من الشــركة ألنهم‬\n      ‫وبهــذه الصفــة التعســفية املماثلــة ملــا ســبق ال جــدوى مــن التفاهــم معهــم او‬\n      ‫االذعــان ملطالبهــم‪ ،‬والتوســل لهــم وعندهــا فضلــت اللجــوء للقضــاء ولــم‬\n      ‫يكــن آنــذاك وكيــل الشــركة حينهــا حاضــر ًا حتــى يصــف املوقــف‬\n      ‫بالســكوت او االذعــان وهــو يعلــم بــأن عــدم توقيعــي علــى مــا يســميه‬\n      ‫مخالصــة إمنــا هــو اعتــراض علــى جتاهلهــم حقوقــي وامنــا توقيعهــم عليهــا‬\n\n\n‫‪177‬‬\n\f‫هــو حتديــد وتثبيــت حلقوقهــم قبلــي بخمســن الــف ‪ 50000‬ريــال وهــذا‬\n‫املبلــغ هــو مجمــوع مــا مت التفاهــم حولــه ودراســته كل علــى حــده ومت‬\n‫تثبيتــه ســابق ًا بنــد ًا بنــداً‪ ،‬وبعــد ذلــك االنــكار حلقوقــي الثابتــة يف ذمــة‬\n‫الشــركة جلــأت الــى القضــاء طالب ـ ًا انتــزاع حقوقــي مــن الشــركة‬\n                                     ‫‪ .......................‬وهــي محــددة كمــا يلــي‪:‬‬\n‫‪ .1‬مبلــغ مليــون ‪ 1.000.000‬ريــال مدفــوع مقدم ـ ًا اســتلمته الشــركة‬\n                      ‫منــي كإيجــار لســنه واحــده وحجبــت عنــي املنفعــة‪.‬‬\n‫‪ .2‬مبلــغ إثنــان وعشــرون الــف وســبعمائة واربعــه وســبعون ‪ 22774‬ريــال‬\n‫مدفــوع مقدم ـ ًا ايض ـ ًا لــكل شــهر اســتلمتها الشــركة منــي كأجــرة‬\n‫صيانــه لــم تقــم بهــا ‪ ،‬ومازالــت تنكــر املســئولية بتحمل اعمــال الصيانة‪.‬‬\n‫‪ .3‬مبلــغ تســعه وتســعون الــف وثمامنائــه وخمســه عشــر ‪99815‬ريــال‬\n‫قيمــة مشــتريات وإصالحــات ‪ ،‬وحســابات مقيــده يف دفاتــر الشــركة‬\n                                                                            ‫لصاحلنــا‪.‬‬\n‫‪ .4‬مبلــغ مليــون وثالثمائــة وخمســون الــف ‪ 1350000‬ريــال تعويــض جــراء‬\n‫فســخ عقــد الشــاليهات ‪ ،‬وحجــب املنفعــة املتوخــاة مــن اســتثمار املشــروع‬\n‫للتســع ســنوات املتبقيــة يف العقــد مبعــدل ربــح ‪ %15‬مــن قيمــة االيجــار‪. .‬‬\n‫مبلــغ مائتــان واربعــون الــف ‪ 240000‬ريــال أجــرة وأتعــاب وكيــل شــرعي‬\n‫قــام مبتابعــة وحضــور جلســات هــذه القضيــة ملــدة تزيــد عــن ثالثــة عشــر‬\n                                                                                  ‫عاماً‪.‬‬\n‫وفقكــم اهلل ‪ ،‬وفهمكــم حلكمــه ‪ ،‬والســام عليكــم ورحمــه اهلل‬\n                                                                   ‫وبركاتــه‪ .‬أ‪.‬ه ـ‬\n‫وبســؤال املدعــى عليــه وكالــه عــن جوابــه علــى املذكــرة فقــال أكتفــي‬\n‫مبــا قدمتــه ســابقا بنــاء عليــه فقــد رفعــت اجللســة لتأمــل جميــع مــا ســبق‬\n\n\n                                                                                           ‫‪178‬‬\n\f      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي ‪ ...............‬وحضــر حلضــوره‬\n      ‫املدعــى عليــه وكالــه ‪ ..............‬وبعــد ســماع الدعــوى واإلجابــة وجميــع‬\n      ‫مــا ســبق فقــد تقــدم املدعــي ‪ ......................‬بدعــوى للمطالبــة بإعــادة‬\n      ‫إيجــار الســنة األولــى مبلــغ ‪ 1000000‬ريــال‪ ،‬وقيمــة الصيانــة مبلــغ‬\n      ‫‪ 22774‬ريــال‪ ،‬ومطالبــات متفرقــة متعلقــة بالعقــد بقيمــة ‪ 99815‬ريــال‪،‬‬\n      ‫واملطالبــة بالتعويــض عــن األربــاح املتوقعــة عــن تســع ســنوات‪ ،‬وبعــد‬\n      ‫مــداوالت متعــددة ويف اجللســة املؤرخــة يف ‪ 1433/04/27‬اســتند املدعــي‬\n      ‫يف إثبــات مــا يف ذمتــه للشــركة املدعــى عليهــا مــن مبالــغ ماليــة علــى‬\n      ‫الوثيقــة احملــررة بتاريــخ ‪1419/11/01‬ه ـ وعنوانهــا (مخالصــة نهائيــة)‪،‬‬\n      ‫حيــث ورد يف املخالصــة مــا نصــه‪( :‬فقــد مت االتفــاق بتاريخــه علــى عمــل‬\n      ‫هــذه املخالصــة النهائيــة والتــي يقــوم مبوجبهــا أ‪ ....................../‬بدفــع‬\n      ‫(ويعتبــر هــذا‬\n                   ‫مبلــغ ‪ 50000‬ريــال(‪ ،‬كمــا تضمنــت الوثيقــة مــا نصــه‪ُ :‬‬\n      ‫املبلــغ مبثابــة مخالصــة بــن الطرفــن)‪ ،‬ثــم يف نفــس اجللســة ذكــر‬\n      ‫املدعــي أنــه طلــب تعديــل ورقــة املخالصــة لتفصيــل مــا عليــه مــن أمــوال‪،‬‬\n      ‫وقــد جــرى حتريرهــا بتاريــخ ‪1419/11/01‬هــ‪ ،‬وبتأمــل ذلــك  وجــدت‬\n      ‫ـزء وتــرك جــزء‪ ،‬مــع أن مبلــغ‬     ‫أن املدعــي أخــذ مــن هاتــن املخالصتــن جـ ً‬\n      ‫اخلمســن ألــف ريــال خــرج يف املخالصتــن مخــرج االتفــاق ولــم يكــن‬\n      ‫إقــرار ًا مجــرد ًا مــن املدعــي أو إقــرارا مــن الشــركة املدعــى عليهــا‬\n       ‫قبــل إبــرام املخالصــة ‪ ،‬ومعلــوم أن االتفــاق كلٌ ال يتجــزأ‪ ،‬إذ كيـ َ‬\n      ‫ـف‬\n      ‫ُي َوافـ ُـق أحــد طــريف النــزاع علــى أخــذ مــا يريــد مــن املخالصــة وتــرك مــا ال‬\n      ‫خصمــه وال يلتــزم‬\n                     ‫َ‬                   ‫يريــد‪ ،‬وكيــف يســتند أحدهمــا علــى شــي ٍء ُ‬\n                               ‫ويلــزم بــه‬\n      ‫هــو مبــا فيــه إلــزام لــه‪ ،‬ويعضــد هــذا االســتنتاج انضمــام قرينــة أخــرى‬\n      ‫وهــي خطــاب حــرره املدعــي بتاريــخ ‪1419/09/12‬ه ـ املتضمــن معاجلــة‬\n\n\n‫‪179‬‬\n\f‫موضــوع اســتهالك الكهربــاء حيــث تضمــن يف آخــره مــا نصــه‪( :‬رغبــة‬\n‫منــا يف إنهــاء موضــوع الكهربــاء بغــض النظــر عــن هــذه األخطــاء وذلــك‬\n‫بغيــة الوصــول إلــى حلــول مرضيــة مثلهــا مثــل املواضيــع األخــرى التــي مت‬\n‫حلهــا كل علــى حــده)‪ ،‬وقــد ورد يف املــادة ‪ 155‬مــن نظــام املرافعــات‬\n‫الشــرعية‪( :‬يجــوز للقاضــي أن يســتنتج قرينــة‪ ،‬أو أكثــر مــن وقائــع‬\n‫الدعــوى‪ ،‬أو ُمناقشــة اخلصــوم أو الشــهود؛ لتكــون ُمســتند ًا حلُكمِ ــه‬\n‫ا ناقص ـ ًا ثبــت لديــه ليكـ ِّـون بهمــا مع ـ ًا اقتناعــه‬‫أو ُليكمِ ــل ِبهــا دلي ـ ً‬\n‫بثبــوت احلــق إلصــدار ا ُحلكــم)‪ ،‬وهــو مــا قــرره أهــل العلــم رحمهــم اهلل‬\n‫حيــث يقــول ابــن رجــب احلنبلــي رحمــه اهلل يف جامــع العلــوم واحلكــم‬\n‫ص ‪( :316‬وقــد كان شــريح وإيــاس بــن معاويــة يحكمــان يف األمــوال‬\n‫املتنــازع فيهــا مبجــرد القرائــن الدالــة علــى صــدق أحــد املتداعيــن ‪..‬‬\n‫وكان يقضــي بنحــو ذلــك أبــو بكــر الشــامي مــن الشــافعية ورجــح قولــه‬\n‫ـدي أن يف‬  ‫ابــن عقيــل مــن أصحابنــا)‪ ،‬بنــاء علــى مــا ســبق فلــم يثبــت لـ ّ‬\n‫ذمــة الشــركة املدعــى عليهــا حــق مالــي للمدعــي وصرفــت النظــر عــن‬\n‫ـدي أن يف ذمــة املدعــي ‪....................‬‬\n                                           ‫مطالبتــه لعــدم اســتحقاقه‪ ،‬وثبــت لـ ّ‬\n‫مبلــغ ‪ 50000‬ريــال وألزمتــه بدفعهــا حــا ًال للشــركة ‪ ،...................‬وبــه‬\n‫حكمــت‪ ،‬وبعــرض ذلــك علــى الطرفــن قــرر املدعــي عليــه وكالــة‬\n‫قناعتــه أمــا املدعــي فقــرر عــدم القناعــة وجــرى إفهامــه أن عليــه مراجعــة‬\n‫احملكمــة خــال عشــرة أيــام الســتالم نســخة مــن احلكــم ثــم تبــدأ املــدة‬\n‫االعتراضيــة وأن عليــه تقــدمي الئحتــه خــال ثالثــن يومــا فــإذا لــم يقــدم‬\n‫اعتراضــه خــال هــذه املــدة ســقط حقــه يف طلــب االســتئناف واكتســب‬\n‫احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/21‬هــ‪.‬‬\n\n\n                                                                                           ‫‪180‬‬\n\f        ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n        ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n        ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n        ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪341437809‬‬\n      ‫وتاريــخ ‪1434/7/12‬ه واملقيــدة لــدى احملكمــة برقــم ‪  341724906‬‬\n        ‫وتاريــخ ‪1434/7/17‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n        ‫باحملكمــة الشــيخ د‪ ........................‬املسـ ّـجل برقــم ‪ 3416698‬وتاريــخ‬\n        ‫‪1434/1/19‬ه ـ اخلــاص بدعــوى‪ ..................../‬ضد‪/‬الشــركة‬\n        ‫‪ ....................‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه‬\n        ‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحة‬\n        ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                                  ‫حــرر يف ‪1434/9/22‬هــ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":125,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"98894f9b092143dfc7828fa6f593f2bd0da199a2ef4cbf20de54865c5bd8b4de","normalized_text_hash":"95a597e754195a414213ed6d4ab369de421926b339d5507e57210e38ebf09ea3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p125-3416698"},{"id":"8a7488c8-82b6-5c9b-a968-b9d9bfac2f2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بقيمة األجرة احلال منها واملتأخر -إقرار املدعى عليه بعدم السداد -تعديل الطلبات بإضافة فسخ العقد -سجن املدعى عليه يف قضايا حقوقيه وعجزه عن السداد -احلكم بسداد قيمة األجرة وتسليم العن محل اإلجارة .","document_number":"34224021","case_number":"34224021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"إجارة -مطالبة بقيمة األجرة احلال منها واملتأخر -إقرار املدعى عليه بعدم السداد -تعديل الطلبات بإضافة فسخ العقد -سجن املدعى عليه يف قضايا حقوقيه وعجزه عن السداد -احلكم بسداد قيمة األجرة وتسليم العن محل اإلجارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/27 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34224021 :‬‬\n                   ‫َر ْق ُم الدعوى‪34224021 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34274920‬تاريخه‪1434/7/22 :‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة بقيمــة األجــرة احلــال منهــا واملتأخــر ‪ -‬إقــرار املدعــى‬\n‫عليــه بعــدم الســداد ‪ -‬تعديــل الطلبــات بإضافــة فســخ العقــد ‪ -‬ســجن‬\n‫املدعــى عليــه يف قضايــا حقوقيــه وعجــزه عــن الســداد ‪ -‬احلكــم بســداد‬\n                              ‫قيمــة األجــرة وتســليم العــن محــل اإلجــارة ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                             ‫تســبيب احلكــم‬\n\n\n\n\n‫ادعــى املدعــى ضــد املدعــى عليــه انــه اســتأجر منــه عقــار ًا مــدة خمــس‬\n‫ســنوات باجــره ســنويه معلومــه املقــدار علــى ان تدفــع على ثــاث دفعات‪-‬‬\n‫مت ســداد قيمــة الدفعــه االولــى ‪ -‬والثانيــه منقوصــه عشــرة االف ‪ -‬ولــم‬\n‫يســلم الدفعــة الثالثــه علم ـ ًا بانهــا حالــة عليــه ‪ -‬طلــب املدعــي احلكــم‬\n                                                    ‫بدفــع املتبقــي مــن األجــرة‪.‬‬\n‫يف جلســه اخــرى حضــر الطرفــان واقــر املدعــى عليــه مبــا ذكــره املدعى‬\n‫جملــة وتفصيــا واكــد انــه يف ذمتــه مبلــغ ‪ 37000‬ريــال وال مانــع لديــه‬\n‫مــن ســدادها‪ -‬عــدل املدعــى عــن طلباتــه باالضافــه لســداد احلــال مــن‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫القيمــة االيجاريــه بطلــب االخــاء الفــوري ملماطلتــه وملخالفتــه مقتضــى‬\n      ‫عقــد االيجــار  ثــم عــرض االخــاء علــى املدعــى عليــه ولــم يقــره وبالتالــي‬\n      ‫والقــرار املدعــى عليــه مبــا يف ذمتــه مــن القيمــة االيجاريــه احلالــه وعــدم‬\n      ‫ســداده اياهــا طيلــة الفتــرة املاضيــه وملقتضــى العقــد الــذي يوجــب‬\n      ‫فســخه دفع ـ ًا للضــرر الواقــع علــى املالــك ‪ -‬ولكــون املدعــى عليــه لــم‬\n      ‫يحضــر ملجلــس احلكــم إال بعــد ان مت ســجنه يف عــدة قضايــا حقوقيــه‬\n      ‫اخــرى ممــا يــدل علــى عجــزه بالوفــاء بالعقــد حكــم عليــه بــان يســلم‬\n      ‫للمدعــى مبلــغ ‪ 37000‬ريــال وان يســلم العمــارة محــل الدعــوى فــور ًا دون‬\n      ‫تأخيــر‪ -‬قنــع املدعــى باحلكــم ولــم يقنــع املدعــى عليــه ‪ -‬صــدق احلكــم‬\n                                                         ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 3362412‬وتاريــخ‬\n      ‫‪1433/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33161638‬وتاريــخ‬\n      ‫‪1433/1/24‬ه ـ واملتعلقــة بدعــوى ‪ ......................‬ضــد ‪...........................‬‬\n      ‫يف أجــرة عقــار  حضــر ‪ .....................‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .................‬الوكيــل عــن ‪ ...................‬بالوكالــة رقــم‬\n      ‫‪ 51370‬يف ‪1431/8/20‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة والتــي‬\n        ‫تخــول لــه ( املداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا وإقامــة‬\n        ‫البينــة والدفــع وقبــول احلكــم واإلعتــراض عليــه ‪ ) ..‬ولــم يحضــر املدعــى‬\n      ‫عليــه وقــررت ســماع الدعــوى غيابيـ ًا ‪ .‬وبســؤال وكيــل املدعي عن دعواه  ‬\n‫‪209‬‬\n\f‫ا ‪:‬أدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم  ‬              ‫أدعــى قائ ـ ً‬\n  ‫‪ ..............................‬بأنــه اســتأجر مــن موكلــي عقــاره الكائــن يف ‪...‬‬\n‫مــدة خمــس ســنوات تبــدأ يف ‪1432/1/1‬ه ـ وتنتهــي يف ‪1436/12/30‬هـ  ‬\n  ‫وهــو عبــارة عــن عمــارة ســكينة مملوكــة لــه مبوجــب الصــك رقــم ‪...‬‬\n  ‫يف ‪1431/9/18‬ه ـ بأجــرة ســنوي ًة قدرهــا مئتــان وعشــرون ألــف ريــال‬\n  ‫علــى دفعــات ثــاث الدفعــة األولــى ثمانــن الــف ريــال ســلمها ملوكلــي‪،‬‬\n  ‫والدفعــة الثانيــة ســبعني الــف ريــال ســلم منهــا ملوكلــي ســتني ألــف ريــال‬\n  ‫وبقــي منهــا عشــرة آالف ريــال‪ ،‬لــم تســلم حتــى اآلن‪ ،‬والدفعــة الثالثــة‬\n  ‫ســبعني ألــف ريــال لــم يســلمها ملوكلــي حتــى االن‪ ،‬علمـ ًا أنهــا حالــة مــن‬\n  ‫تاريــخ ‪1432/09/20‬ه ـ أطلــب احلكــم علــى املدعــى عليــه بدفــع املتبقــي‬\n  ‫مــن اإليجــار وقــدره ثمانــن ألــف ريــال ‪ .‬هــذه دعواي ‪ .‬وقررت رفع اجللســة‬\n  ‫لتبليــغ املدعــى عليــة أصالــة مبوعدها‪ ،‬وأفهمــت وكيل املدعي بإحضار‬\n  ‫مســتنداته (صــك العقــار‪ ،‬وعقــد اإليجــار) ويف جلســة  أخــرى أحضــر‬\n‫املدعــي وكالــة ‪ ....................‬بالســجل املدنــي رقــم ………………  ‬\n  ‫بوكالتــه عــن ‪ ..............‬وجــرى الالطــاع علــى أصــل صــك العقــار‬\n  ‫رقــم … يف ‪1431/9/18‬ه ـ ومت اإلطــاع عليــه فوجــد يتضمــن متلــك‬\n  ‫املدعــي للعقــار املذكــور‪ ،‬كمــا مت اإلطــاع علــى أصــل عقــد اإليجــار‬\n  ‫ووجــد يتضمــن ‪ ( :‬أنــه مت يف يــوم الســبت ‪1431/12/28‬ه ـ التعاقــد‬\n  ‫بــن الطــرف األول ‪( ...............‬املؤجــر)‪ ،‬والطــرف الثانــي ‪.....................‬‬\n  ‫(املســتأجر) علــى تأجيــر الطــرف األول للطــرف الثانــي العقــار املدعــى‬\n  ‫بــه للطــرف الثانــي‪ ،‬بايجــار ســنوي وقــدره مائتــان وعشــرون ألــف ريــال‪،‬‬\n  ‫تدفــع علــى النحــو التالــي ‪ :‬أو ًال ‪ :‬ثمانــن ألــف ريــال عنــد توقيــع العقــد‪،‬‬\n  ‫وتدفــع يف الســنوات الالحقــة للســنة األولــى يف األول مــن شــهر محــرم‬\n\n\n                                                                                             ‫‪210‬‬\n\f        ‫مــن كل عــام ‪ .‬ثاني ـ ًا ‪ :‬ســبعون ألــف ريــال يف األول مــن شــهر جمــادى‬\n        ‫األول مــن كل عــام ‪ .‬ثالث ـ ًا ‪ :‬ســبعون ألــف ريــال يف يــوم عشــرين مــن‬\n        ‫شــهر رمضــان مــن كل عــام ) أ‪.‬هــ  طلبــت مــن املدعــي وكالــة إحضــار‬\n        ‫األصيــل للجلســة القادمــة ألداء اليمــن ‪.‬ويف جلســة أخــرى حضــر املدعــي‬\n        ‫وكالــة ‪ ......................‬ولــم يحضــر املدعــى عليــه ويف  جلســة أخــرى‬\n        ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــي أصالــة ألداء اليمــن كمــا‬\n        ‫لــم يحضــر املدعــى عليــه ولــم جنــد يف املعاملــة مايفيــد تبلغــه ورفعــت‬\n        ‫اجللســة ويف جلســة اخــرى حضــر وكيــل املدعــي ولــم يحضــر املدعــى‬\n        ‫عليــه كمــا لــم يحضــر املدعــي اصالــة ورفعــت اجللســة ويف جلســة أخــرى‬\n        ‫حضــر املدعــى وكالــة ولــم يحضــر املدعــى عليــه ورفعــت اجللســة  ويف‬\n        ‫جلســة أخــرى لــم يحضــر الطرفــان وشــطبت الدعــوى ويف جلســة أخــرى‬\n        ‫حضــر الطرفــان وبعــرض الدعــوى علــى املدعــى عليــه قــال أريــد مهلــة‬\n        ‫للــرد علــى هــذه الدعــوى يف اجللســة القادمــة ورفعــت اجللســة  حضــر‬\n        ‫املدعــي أصالــة ولــم يحضــر املدعــى عليــه ويف جلســة أخــرى   حضــر‬\n        ‫أصالــة ‪ ....................‬ســعودي بالســجل املدنــي رقــم ‪.........................‬‬\n        ‫كمــا حضــر حلضــوره املدعــى عليــه ‪ ...................‬ســعودي بالســجل‬\n        ‫املدنــي رقــم ‪ ...........................‬وبعــرض الدعــوى علــى املدعــى عليــه‬\n        ‫ا ‪ :‬مــا ذكــره املدعــي كلــه صحيــح جملــة وتفصيــا ‪،‬‬               ‫أجــاب قائ ـ ً‬\n        ‫فقــد اســتأجرت منــه العمــارة الواقعــة يف حــي ‪ ...‬يف املدينــة املنــورة جــوار‬\n        ‫مســجد ‪ ، ...‬واملكونــة مــن أربعــة طوابــق واململوكــه للمدعــي بالصــك‬\n        ‫الصــادر مــن كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪ ..............‬يف‬\n      ‫‪1431/09/18‬ه ـ ‪ ،‬منــذ ‪1432/01/01‬ه ـ ولــم أســدده ســوى دفعتــن  ‬\n        ‫فقــط ‪ ،‬وبقــي لــه يف ذمتــي الدفعــة األخيــرة مــن عــام ‪1432‬ه ـ وقدرهــا‬\n\n\n‫‪211‬‬\n\f  ‫ســبعون ألف ريال ‪ ،‬وكذلك لم أســدده من إيجار عامي ‪1433‬و ‪1434‬‬\n  ‫ه ـ وال ريــا ًال واحــد ًا ‪ ،‬علمـ ًا أنــه قــد حلــت علــي دفعتــان مــن عــام ‪1434‬ه ـ‬\n  ‫فقــط  ‪ ،‬ومجمــوع مــا تبقــى لــه يف ذمتــي ثالثمائــة وســبعون ألــف ريــال‬\n  ‫‪ ،‬وال مانــع لــدي مــن تســديده هــذا املبلــغ إذا تيســرت أمــوري ‪ ،‬وأطلــب‬\n  ‫منــه إمهالــي حتــى تتيســر أمــوري ‪ .‬هكــذا أجــاب‪ .‬وبعــرض جوابــه علــى‬\n  ‫ا ‪ :‬ماذكــره املدعــى عليــه يف جوابــه فهــو‬         ‫املدعــي أصالــة أجــاب قائ ـ ً‬\n  ‫صحيــح ‪ ،‬وهــو املبلــغ الــذي أدعــى بــه فقــط ‪ ،‬وغيــر موافــق علــى إمهالــه‬\n  ‫وأطلــب احلكــم عليــه بهــذا املبلــغ ‪ ،‬كمــا أطلــب احلكــم عليــه باإلخــاء‬\n  ‫الفــوري ملاطلتــه ومخالفتــه مقتضــى العقــد بعــدم تســليمي اإليجــارات‬\n  ‫‪ ،‬والتــي أقــر بهــا لديكــم يف هــذه اجللســة ‪ .‬هكــذا أجــاب ‪ .‬وبعــرض‬\n  ‫ا ‪ :‬أنــا غيــر مســتعد باإلخــاء‬     ‫اإلخــاء علــى املدعــى عليــه أجــاب قائ ـ ً‬\n  ‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة ‪ ،‬وإلقــرار‬       ‫‪ .‬هكــذا أجــاب ‪ .‬بنـ ً‬\n  ‫املدعــى عليــه بــأن يف ذمتــه للمدعــي مبلــغ قــدره ثالثمائــة وســبعون ألــف‬\n  ‫ريــال لــم يســددها مــن اإليجــارات ‪ ،‬وإلقــرار املدعــى عليــه بعــدم الســداد‬\n  ‫طيلــة الفتــرة املاضيــة حتــى وصلــت املديونيــة إلــى املبلــغ الــذي أقربــه يف‬\n  ‫هــذه اجللســة ‪ ،‬وكل هــذا يعــد مخالفــة صريحــة ملقتضــى العقــد ويوجــب‬\n  ‫الفســخ دفعــا للضــرر الواقــع علــى املالــك ‪ ،‬وألن املدعــى عليــه لــم يحضــر‬\n  ‫ملجلــس احلكــم إال بعــد أن ســجن يف قضايــا حقوقيــة أخــرى ‪ ،‬ممــا‬\n  ‫يــدل علــى عجــزه عــن الوفــاء بالعقــد ؛ فقــد حكمــت علــى املدعــى عليــه‬\n‫‪ .....................‬بــأن يســلم للمدعــي ‪ ..................‬مبلــغ ثالثمائــة وســبعني ‬\n  ‫ألــف ريــال ‪ ،‬كمــا حكمــت عليــه بــأن يســلم العمــارة  محــل الدعــوى‬\n‫ذات الصــك الصــادر كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪  ........‬‬\n  ‫يف ‪1431/09/18‬هــ   فــور ًا مــن غيــر تأخيــر ‪ .‬وبعــرض احلكــم علــى‬\n\n\n                                                                                             ‫‪212‬‬\n\f      ‫املدعــى عليــه قــرر عــدم القناعــة باحلكــم ؛ فأفهــم بــان لــه مهلــة ثالثــن‬\n      ‫يومــا مــن اســتالمه احلكــم ليقــدم الئحتــه االعتراضيــة ‪ ،‬وأنــه إن لــم‬\n      ‫يعتــرض خاللهــا فسيســقط حقــه يف االعتــراض ‪ ،‬كمــا أفهــم باحلضــور‬\n      ‫احلضــور يــوم االثنــن ‪1434/5/27‬ه ـ الســاعة العاشــر الســتالم نســخة‬\n      ‫احلكــم ‪ ،‬وأنــه إن لــم يحضــر الســتالم الصــك فــإن املــدة ستحتســب‬\n      ‫عليــه مــن هــذا التاريــخ ففهــم ذلــك ‪ ،‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/05/25‬هــ‪..‬‬\n      ‫احلمــد هلل وحــده‪ :‬وبعــد رفــع كامــل أوراق املعاملــة إلــى محكمــة‬\n      ‫اإلســتئناف عــادت وقــد مت تصديــق احلكــم مبوجــب قــرار الدائــرة‬\n      ‫احلقوقيــة األولــى رقــم ‪ 34274920‬يف ‪1434/7/22‬ه ـ املظهــر علــى صك‬\n      ‫احلكــم رقــم ‪ 34224021‬يف ‪1434/5/27‬ه ـ ‪ .‬وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/3‬ه‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم‬\n      ‫‪ 33/161638‬وتاريــخ ‪1434/7/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ..........................‬القاضــي باحملكمــة العامــة باملدينــة‬\n      ‫املنــورة واملســجل بعــدد ‪ 34224021‬وتاريــخ ‪1434/5/27‬هـ ـ واملتضمــن‬\n      ‫دعــوى‪ .......................... /‬ضــد‪ ........................... /‬واحملكــوم فيــه مبــا‬\n      ‫دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينا محمد‬\n                                                         ‫وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b4e1a41bfbe32c85789f3653519b4942a9630f1e315ac44f53423599c3ecf58","normalized_text_hash":"06a23ef68d769beef60a58c19aebafd9d8214155df597d833079a82fb8e7014f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p208-34224021"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
